/**
 * @param {number} left
 * @param {number} right
 * @return {string}
 */
var abbreviateProduct = function(left, right) {
    // Compute the exact product with BigInt (at most 10^4 multiplications,
    // product has at most ~36k digits, which is cheap to build and stringify)
    let prod = 1n;
    for (let i = left; i <= right; i++) {
        prod *= BigInt(i);
    }

    let s = prod.toString();

    // Count and strip trailing zeros
    let c = 0;
    let end = s.length - 1;
    while (end >= 0 && s[end] === '0') {
        c++;
        end--;
    }
    s = s.substring(0, end + 1);

    const d = s.length;
    if (d <= 10) {
        return s + 'e' + c;
    }
    // First 5 digits + "..." + last 5 digits
    return s.substring(0, 5) + '...' + s.substring(d - 5) + 'e' + c;
};

/**
 * @param {number} left
 * @param {number} right
 * @return {string}
 */
var abbreviateProduct = function(left, right) {
    // Count factors of 2 and 5
    let cnt2 = 0, cnt5 = 0;
    for (let i = left; i <= right; i++) {
        let n = i;
        while (n % 2 === 0) { n /= 2; cnt2++; }
        n = i;
        while (n % 5 === 0) { n /= 5; cnt5++; }
    }
    let C = Math.min(cnt2, cnt5);

    // Compute full product using BigInt to check if total digits <= 10
    // But product can be huge; still, compute to know d
    let prod = 1n;
    let big = false;
    for (let i = left; i <= right; i++) {
        prod *= BigInt(i);
        // if prod already huge, we can stop exact tracking but we still need trailing removal
    }
    // remove trailing zeros
    let s = prod.toString();
    let idx = s.length;
    while (idx > 0 && s[idx-1] === '0') idx--;
    let stripped = s.substring(0, idx);
    // trailing zero count is s.length - idx, which equals C

    if (stripped.length <= 10) {
        return stripped + "e" + C;
    }

    let last5 = stripped.substring(stripped.length - 5);
    let first5 = stripped.substring(0, 5);
    return first5 + "..." + last5 + "e" + C;
};

