var abbreviateProduct = function(left, right) {
    let c2 = 0, c5 = 0;
    for (let i = left; i <= right; i++) {
        let n = i;
        while (n % 2 === 0) { c2++; n /= 2; }
        n = i;
        while (n % 5 === 0) { c5++; n /= 5; }
    }
    const C = Math.min(c2, c5);
    let r2 = C, r5 = C;
    const MOD = 1e10;
    let suf = 1;
    let big = false;
    let pre = 1.0;
    for (let i = left; i <= right; i++) {
        pre *= i;
        while (pre >= 1e13) pre /= 10;
        let n = i;
        while (r2 > 0 && n % 2 === 0) { n /= 2; r2--; }
        while (r5 > 0 && n % 5 === 0) { n /= 5; r5--; }
        suf = suf * n;
        if (suf >= MOD) {
            big = true;
            suf %= MOD;
        }
    }
    if (!big) {
        return String(suf) + "e" + C;
    }
    while (pre >= 1e5) pre /= 10;
    const p = Math.floor(pre);
    const s = String(suf % 100000).padStart(5, '0');
    return String(p) + "..." + s + "e" + C;
};

function abbreviateProduct(left: number, right: number): string {
    let product = 1n;

    for (let value = left; value <= right; value++) {
        product *= BigInt(value);
    }

    const digits = product.toString();
    let end = digits.length;

    while (digits[end - 1] === "0") {
        end--;
    }

    const zeros = digits.length - end;

    if (end <= 10) {
        return `${digits.slice(0, end)}e${zeros}`;
