            String fp = t.substring(i);
            if (ip.length() > 1 && ip.charAt(0) == '0') continue;
            if (!fp.isEmpty() && fp.charAt(fp.length() - 1) == '0') continue;
            out.add(fp.isEmpty() ? ip : ip + "." + fp);
        }
        return out;
    }
}

class Solution {
    public List<String> ambiguousCoordinates(String s) {
        String digits = s.substring(1, s.length() - 1);
        List<String> ans = new ArrayList<>();
        int n = digits.length();
        for (int i = 1; i < n; i++) {
            List<String> lefts = generate(digits.substring(0, i));
            List<String> rights = generate(digits.substring(i));
            for (String l : lefts) {
                for (String r : rights) {
                    ans.add("(" + l + ", " + r + ")");
                }
            }
        }
        return ans;
    }

    private List<String> generate(String num) {
        List<String> res = new ArrayList<>();
        int m = num.length();
        if (num.charAt(0) != '0' || m == 1) {
            res.add(num);
        }
        for (int i = 1; i < m; i++) {
            String ip = num.substring(0, i);
            String fp = num.substring(i);
            if ((ip.charAt(0) != '0' || ip.length() == 1) && fp.charAt(fp.length() - 1) != '0') {
                res.add(ip + "." + fp);
            }
        }
        return res;
    }
}

