var numFactoredBinaryTrees = function(arr) {
    const MOD = 1000000007n;
    arr.sort((a, b) => a - b);

    const index = new Map();
    for (let i = 0; i < arr.length; i++) {
        index.set(arr[i], i);
    }

    const dp = new Array(arr.length).fill(1n);
    let answer = 0n;

    for (let i = 0; i < arr.length; i++) {
        for (let j = 0; j < i; j++) {
            if (arr[i] % arr[j] === 0) {
                const k = arr[i] / arr[j];
                if (index.has(k)) {
                    const idx = index.get(k);
                    dp[i] = (dp[i] + dp[j] * dp[idx]) % MOD;
                }
            }
        }
        answer = (answer + dp[i]) % MOD;
    }

    return Number(answer);
};

