/**
 * @param {number[][]} grid
 * @param {number[][]} hits
 * @return {number[]}
 */
var hitBricks = function(grid, hits) {
    const R = grid.length, C = grid[0].length;
    const N = R * C;
    const parent = new Array(N + 1);
    const sz = new Array(N + 1);
    for (let i = 0; i <= N; i++) {
        parent[i] = i;
        sz[i] = i === N ? 0 : 1;
    }
    const find = (x) => {
        if (parent[x] !== x) parent[x] = find(parent[x]);
        return parent[x];
    };
    const union = (x, y) => {
        let px = find(x), py = find(y);
        if (px === py) return;
        if (sz[px] < sz[py]) {
            parent[px] = py;
            sz[py] += sz[px];
        } else {
            parent[py] = px;
            sz[px] += sz[py];
        }
    };
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    const connect = (i, j) => {
        const id = i * C + j;
        if (i === 0) union(id, N);
        for (const [di, dj] of dirs) {
            const ni = i + di, nj = j + dj;
            if (ni >= 0 && ni < R && nj >= 0 && nj < C && grid[ni][nj] === 1) {
                union(id, ni * C + nj);
            }
        }
    };
    for (const [x, y] of hits) grid[x][y]--;
    for (let i = 0; i < R; i++) {
        for (let j = 0; j < C; j++) {
            if (grid[i][j] === 1) connect(i, j);
        }
    }
    const result = new Array(hits.length);
    for (let k = hits.length - 1; k >= 0; k--) {
        const [x, y] = hits[k];
        grid[x][y]++;
        if (grid[x][y] !== 1) {
            result[k] = 0;
            continue;
        }
        const before = sz[find(N)];
        connect(x, y);
        const after = sz[find(N)];
        result[k] = Math.max(0, after - before - 1);
    }
    return result;
};

/**
 * @param {number[][]} grid
 * @param {number[][]} hits
 * @return {number[]}
 */
var hitBricks = function(grid, hits) {
    const m = grid.length, n = grid[0].length;
    // copy grid and remove all hits
    const g = grid.map(row => row.slice());
    for (const [r, c] of hits) {
        g[r][c] = 0;
    }

    const top = m * n; // virtual node for top
    const parent = new Array(m * n + 1);
    const size = new Array(m * n + 1).fill(1);
    for (let i = 0; i <= m * n; i++) parent[i] = i;

    const find = (x) => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };
    const union = (a, b) => {
        const ra = find(a), rb = find(b);
        if (ra === rb) return;
        parent[ra] = rb;
        size[rb] += size[ra];
    };

    const idx = (r, c) => r * n + c;
    const dirs = [[0,1],[0,-1],[1,0],[-1,0]];

    // build union-find for final grid
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (g[r][c] === 1) {
                if (r === 0) union(idx(r,c), top);
                for (const [dr, dc] of dirs) {
                    const nr = r + dr, nc = c + dc;
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n && g[nr][nc] === 1) {
                        union(idx(r,c), idx(nr,nc));
                    }
                }
            }
        }
    }

    const result = new Array(hits.length).fill(0);

    for (let i = hits.length - 1; i >= 0; i--) {
        const [r, c] = hits[i];
        if (grid[r][c] === 0) {
            result[i] = 0;
            continue;
        }
        // before adding
        const prevTop = size[find(top)];

        g[r][c] = 1;
        if (r === 0) union(idx(r,c), top);
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && g[nr][nc] === 1) {
                union(idx(r,c), idx(nr,nc));
            }
        }

        const newTop = size[find(top)];
        // bricks that became stable = newTop - prevTop - 1 (the added brick itself)
        const fallen = Math.max(0, newTop - prevTop - 1);
        result[i] = fallen;
    }

    return result;
};

