        if (size[ra] < size[rb]) { const t = ra; ra = rb; rb = t; }
        parent[rb] = ra;
        size[ra] += size[rb];
    };
    const g: number[][] = grid.map(r => r.slice());
    const had: boolean[] = [];
    for (const [r, c] of hits) {
        if (g[r][c] === 1) {
            had.push(true);
            g[r][c] = 0;
        } else had.push(false);
    }
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (g[i][j] === 1) {
                if (i === 0) union(j, top);
                if (i > 0 && g[i - 1][j] === 1) union(i * n + j, (i - 1) * n + j);
                if (j > 0 && g[i][j - 1] === 1) union(i * n + j, i * n + j - 1);
            }
        }
    }
    const res: number[] = new Array(hits.length).fill(0);
    for (let k = hits.length - 1; k >= 0; k--) {
        if (!had[k]) continue;
        const [r, c] = hits[k];
        const before = size[find(top)];
        g[r][c] = 1;
        const id = r * n + c;
        if (r === 0) union(id, top);
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && g[nr][nc] === 1) {
                union(id, nr * n + nc);
            }
        }
        const after = size[find(top)];
        res[k] = Math.max(0, after - before - 1);
    }
    return res;
};

function hitBricks(grid: number[][], hits: number[][]): number[] {
    const m = grid.length;
    const n = grid[0].length;
    const N = m * n;
    const TOP = N;

    const parent: number[] = new Array(N + 1);
    for (let i = 0; i <= N; i++) parent[i] = i;
    const size: number[] = new Array(N + 1).fill(1);
    size[TOP] = 0;

    const find = (x: number): number => {
        let root = x;
        while (parent[root] !== root) root = parent[root];
        while (parent[x] !== root) {
            const next = parent[x];
            parent[x] = root;
            x = next;
        }
        return root;
    };

    const union = (a: number, b: number): void => {
        const ra = find(a);
        const rb = find(b);
        if (ra === rb) return;
        if (size[ra] < size[rb]) {
            parent[ra] = rb;
            size[rb] += size[ra];
        } else {
            parent[rb] = ra;
            size[ra] += size[rb];
        }
    };

    const idx = (r: number, c: number): number => r * n + c;

    const g: number[][] = grid.map(row => row.slice());
    for (const [r, c] of hits) {
        if (g[r][c] === 1) g[r][c] = 2;
    }

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (g[r][c] !== 1) continue;
            if (r === 0) union(idx(r, c), TOP);
            if (r > 0 && g[r - 1][c] === 1) union(idx(r, c), idx(r - 1, c));
            if (c > 0 && g[r][c - 1] === 1) union(idx(r, c), idx(r, c - 1));
        }
    }

    const dirs: number[][] = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    const result: number[] = new Array(hits.length).fill(0);

    for (let i = hits.length - 1; i >= 0; i--) {
        const r = hits[i][0];
        const c = hits[i][1];
        if (grid[r][c] === 0) continue;
        const oldTopSize = size[find(TOP)];
        g[r][c] = 1;
        for (const [dr, dc] of dirs) {
            const nr = r + dr;
            const nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && g[nr][nc] === 1) {
                union(idx(r, c), idx(nr, nc));
            }
        }
        if (r === 0) union(idx(r, c), TOP);
        const root = find(idx(r, c));
        if (root === find(TOP)) {
            result[i] = size[root] - oldTopSize - 1;
        }
    }

    return result;
}

function hitBricks(grid: number[][], hits: number[][]): number[] {
    const m = grid.length;
    const n = grid[0].length;
    const total = m * n;
    const roof = total;

    const parent: number[] = new Array(total + 1);
    const size: number[] = new Array(total + 1).fill(0);
    for (let i = 0; i <= total; i++) {
        parent[i] = i;
    }

    const hitBrick: boolean[] = new Array(hits.length).fill(false);

    // Remove all hit bricks initially
    for (let i = 0; i < hits.length; i++) {
        const r = hits[i][0];
        const c = hits[i][1];
        if (grid[r][c] === 1) {
            hitBrick[i] = true;
            grid[r][c] = 0;
        }
    }

    const find = (x: number): number => {
        let r = x;
        while (parent[r] !== r) {
            r = parent[r];
        }
        while (parent[x] !== x) {
            const p = parent[x];
            parent[x] = r;
            x = p;
        }
        return r;
    };

    const union = (a: number, b: number): void => {
        let ra = find(a);
        let rb = find(b);
        if (ra === rb) return;
        if (size[ra] < size[rb]) {
            const tmp = ra;
            ra = rb;
            rb = tmp;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
    };

    // Initialize remaining bricks
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] === 1) {
                size[r * n + c] = 1;
            }
        }
    }

    // Build connected components
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] !== 1) continue;
            const id = r * n + c;
            if (r === 0) union(id, roof);
            if (r + 1 < m && grid[r + 1][c] === 1) {
                union(id, (r + 1) * n + c);
            }
            if (c + 1 < n && grid[r][c + 1] === 1) {
                union(id, r * n + c + 1);
            }
        }
    }

    const ans: number[] = new Array(hits.length).fill(0);
    const dirs: [number, number][] = [[-1, 0], [0, -1], [1, 0], [0, 1]];

    // Process hits in reverse
    for (let i = hits.length - 1; i >= 0; i--) {
        if (!hitBrick[i]) continue;
        const r = hits[i][0];
        const c = hits[i][1];
        const oldSize = size[find(roof)];

        grid[r][c] = 1;
        const id = r * n + c;
        parent[id] = id;
        size[id] = 1;

        if (r === 0) union(id, roof);
        for (const [dr, dc] of dirs) {
            const nr = r + dr;
            const nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] === 1) {
                union(id, nr * n + nc);
            }
        }

        const newSize = size[find(roof)];
        ans[i] = Math.max(0, newSize - oldSize - 1);
    }

    return ans;
}

function hitBricks(grid: number[][], hits: number[][]): number[] {
    const m = grid.length;
    const n = grid[0].length;
    const roof = m * n;
    const total = roof + 1;

    const parent = new Int32Array(total);
    const size = new Int32Array(total);

    for (let i = 0; i < total; i++) {
        parent[i] = i;
        size[i] = 1;
    }

    const find = (x: number): number => {
        let root = x;

        while (parent[root] !== root) {
            root = parent[root];
        }

        while (parent[x] !== x) {
            const next = parent[x];
            parent[x] = root;
            x = next;
        }

        return root;
    };

    const union = (a: number, b: number): void => {
        let rootA = find(a);
        let rootB = find(b);

        if (rootA === rootB) return;

        if (size[rootA] < size[rootB]) {
            const temp = rootA;
            rootA = rootB;
            rootB = temp;
        }

        parent[rootB] = rootA;
        size[rootA] += size[rootB];
    };

    const removed = new Array<boolean>(hits.length).fill(false);

    for (let i = 0; i < hits.length; i++) {
        const [row, col] = hits[i];

        if (grid[row][col] === 1) {
            removed[i] = true;
            grid[row][col] = 0;
        }
    }

    const id = (row: number, col: number): number => row * n + col;

    for (let row = 0; row < m; row++) {
        for (let col = 0; col < n; col++) {
            if (grid[row][col] === 0) continue;

            const current = id(row, col);

            if (row === 0) {
                union(current, roof);
            }
            if (row > 0 && grid[row - 1][col] === 1) {
                union(current, id(row - 1, col));
            }
            if (col > 0 && grid[row][col - 1] === 1) {
                union(current, id(row, col - 1));
            }
        }
    }

    const result = new Array<number>(hits.length).fill(0);
    const directions = [
        [-1, 0],
        [1, 0],
        [0, -1],
        [0, 1]
    ];

    for (let i = hits.length - 1; i >= 0; i--) {
        if (!removed[i]) continue;

        const [row, col] = hits[i];
        const before = size[find(roof)];
        const current = id(row, col);

        grid[row][col] = 1;

        if (row === 0) {
            union(current, roof);
        }

        for (const [dr, dc] of directions) {
            const nextRow = row + dr;
            const nextCol = col + dc;

            if (
                nextRow >= 0 &&
                nextRow < m &&
                nextCol >= 0 &&
                nextCol < n &&
                grid[nextRow][nextCol] === 1
            ) {
                union(current, id(nextRow, nextCol));
            }
        }

        const after = size[find(roof)];
        result[i] = Math.max(0, after - before - 1);
    }

    return result;
}

function hitBricks(grid: number[][], hits: number[][]): number[] {
    const m = grid.length, n = grid[0].length;
    const TOP = m * n;
    const parent = new Array(m * n + 1);
    const size = new Array(m * n + 1).fill(1);
    for (let i = 0; i <= m * n; i++) parent[i] = i;

    function find(x: number): number {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    function union(a: number, b: number): void {
        const ra = find(a), rb = find(b);
        if (ra === rb) return;
        parent[ra] = rb;
        size[rb] += size[ra];
    }

    // copy grid and remove hits
    const g: number[][] = grid.map(row => row.slice());
    for (const [r, c] of hits) {
        g[r][c] -= 1;
    }

    const idx = (r: number, c: number) => r * n + c;
    const dirs = [[0,1],[0,-1],[1,0],[-1,0]];

    // build union-find on remaining grid
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (g[r][c] === 1) {
                if (r === 0) union(idx(r,c), TOP);
                for (const [dr, dc] of dirs) {
                    const nr = r + dr, nc = c + dc;
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n && g[nr][nc] === 1) {
                        union(idx(r,c), idx(nr,nc));
                    }
                }
            }
        }
    }

    const result = new Array(hits.length).fill(0);

    for (let i = hits.length - 1; i >= 0; i--) {
        const [r, c] = hits[i];
        g[r][c] += 1;
        if (g[r][c] !== 1) {
            // no brick was originally there
            continue;
        }
        const prevTop = size[find(TOP)];
        if (r === 0) union(idx(r,c), TOP);
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && g[nr][nc] === 1) {
                union(idx(r,c), idx(nr,nc));
            }
        }
        const newTop = size[find(TOP)];
        result[i] = Math.max(0, newTop - prevTop - 1);
    }

    return result;
};

