function hitBricks(grid: number[][], hits: number[][]): number[] {
    const m = grid.length;
    const n = grid[0].length;
    const totalCells = m * n;
    const TOP = totalCells;

    const parent = new Int32Array(totalCells + 1);
    const size = new Int32Array(totalCells + 1);

    for (let i = 0; i <= totalCells; i++) {
        parent[i] = i;
        size[i] = 1;
    }
    size[TOP] = 0;

    function find(i: number): number {
        let root = i;
        while (root !== parent[root]) {
            root = parent[root];
        }
        let curr = i;
        while (curr !== root) {
            const nxt = parent[curr];
            parent[curr] = root;
            curr = nxt;
        }
        return root;
    }

    function union(i: number, j: number): void {
        const rootI = find(i);
        const rootJ = find(j);
        if (rootI !== rootJ) {
            parent[rootI] = rootJ;
            size[rootJ] += size[rootI];
        }
    }

    const hitBrick = new Uint8Array(hits.length);
    for (let k = 0; k < hits.length; k++) {
        const [r, c] = hits[k];
        if (grid[r][c] === 1) {
            hitBrick[k] = 1;
            grid[r][c] = 0;
        }
    }

    const getIndex = (r: number, c: number): number => r * n + c;

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] === 1) {
                const idx = getIndex(r, c);
                if (r === 0) {
                    union(idx, TOP);
                }
                if (r > 0 && grid[r - 1][c] === 1) {
                    union(idx, getIndex(r - 1, c));
                }
                if (c > 0 && grid[r][c - 1] === 1) {
                    union(idx, getIndex(r, c - 1));
                }
            }
        }
    }

    const dr = [-1, 1, 0, 0];
    const dc = [0, 0, -1, 1];
    const result = new Array(hits.length).fill(0);

    for (let k = hits.length - 1; k >= 0; k--) {
        if (!hitBrick[k]) {
            continue;
        }

        const [r, c] = hits[k];
        const prevTopSize = size[find(TOP)];

        grid[r][c] = 1;
        const idx = getIndex(r, c);

        if (r === 0) {
            union(idx, TOP);
        }

        for (let d = 0; d < 4; d++) {
            const nr = r + dr[d];
            const nc = c + dc[d];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] === 1) {
                union(idx, getIndex(nr, nc));
            }
        }

        const currTopSize = size[find(TOP)];
        result[k] = Math.max(0, currTopSize - prevTopSize - 1);
    }

    return result;
}

function hitBricks(grid: number[][], hits: number[][]): number[] {
    const m = grid.length, n = grid[0].length;
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
    const idx = (r: number, c: number) => r * n + c;
    const size = m * n;
    const parent = new Int32Array(size + 1);
    const compSize = new Int32Array(size + 1);

    for (let i = 0; i <= size; i++) parent[i] = i;

    const find = (x: number): number => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    const union = (a: number, b: number): void => {
        let ra = find(a), rb = find(b);
        if (ra === rb) return;
        if (compSize[ra] < compSize[rb]) {
            const t = ra; ra = rb; rb = t;
        }
        parent[rb] = ra;
        compSize[ra] += compSize[rb];
    };

    const top = size;

    const copy = grid.map(row => row.slice());
    for (const [r, c] of hits) {
        if (copy[r][c] === 1) copy[r][c] = 0;
    }

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (copy[r][c] !== 1) continue;
            const id = idx(r, c);
            compSize[id] = 1;
            if (r === 0) union(id, top);
            if (r > 0 && copy[r - 1][c] === 1) union(id, idx(r - 1, c));
            if (c > 0 && copy[r][c - 1] === 1) union(id, idx(r, c - 1));
        }
    }

    const ans = new Array(hits.length).fill(0);

    for (let k = hits.length - 1; k >= 0; k--) {
        const [r, c] = hits[k];
        if (grid[r][c] === 0) continue;

        const before = compSize[find(top)];
        const id = idx(r, c);
        copy[r][c] = 1;
        parent[id] = id;
        compSize[id] = 1;

        if (r === 0) union(id, top);
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
            if (copy[nr][nc] === 1) union(id, idx(nr, nc));
        }

        const after = compSize[find(top)];
        ans[k] = Math.max(0, after - before - 1);
    }

    return ans;
};

function hitBricks(grid: number[][], hits: number[][]): number[] {
    const m = grid.length;
    const n = grid[0].length;
    const roof = m * n;
    const parent: number[] = new Array(m * n + 1);
    const sz: number[] = new Array(m * n + 1).fill(1);
    for (let i = 0; i <= m * n; i++) parent[i] = i;
    sz[roof] = 0;

    const find = (x: number): number => {
        if (parent[x] !== x) parent[x] = find(parent[x]);
        return parent[x];
    };

    const union = (x: number, y: number): void => {
        let px = find(x);
        let py = find(y);
        if (px === py) return;
        if (sz[px] < sz[py]) {
            parent[px] = py;
            sz[py] += sz[px];
        } else {
            parent[py] = px;
            sz[px] += sz[py];
        }
    };

    const dirs = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    const index = (i: number, j: number) => i * n + j;

    for (const [r, c] of hits) {
        grid[r][c]--;
    }

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 1) {
                if (i === 0) union(index(i, j), roof);
                for (const [di, dj] of dirs) {
                    const ni = i + di, nj = j + dj;
                    if (ni >= 0 && ni < m && nj >= 0 && nj < n && grid[ni][nj] === 1) {
                        union(index(i, j), index(ni, nj));
                    }
                }
            }
        }
    }

    const res: number[] = new Array(hits.length).fill(0);
    for (let k = hits.length - 1; k >= 0; k--) {
        const [r, c] = hits[k];
        grid[r][c]++;
        if (grid[r][c] !== 1) continue;
        const old = sz[find(roof)];
        const id = index(r, c);
        if (r === 0) union(id, roof);
        for (const [di, dj] of dirs) {
            const ni = r + di, nj = c + dj;
            if (ni >= 0 && ni < m && nj >= 0 && nj < n && grid[ni][nj] === 1) {
                union(id, index(ni, nj));
            }
        }
        const neu = sz[find(roof)];
        res[k] = Math.max(0, neu - old - 1);
    }
    return res;
}

class Solution {
public:
    vector<int> p, sz;
    int find(int x) {
        while (p[x] != x) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        p[a] = b;
        sz[b] += sz[a];
    }
    vector<int> hitBricks(vector<vector<int>>& grid, vector<vector<int>>& hits) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> g = grid;
        int k = hits.size();
        vector<char> had(k, 0);
        for (int i = 0; i < k; i++) {
            int x = hits[i][0], y = hits[i][1];
            if (g[x][y] == 1) {
                had[i] = 1;
                g[x][y] = 0;
            }
        }
        int top = m * n;
        p.assign(m * n + 1, 0);
        sz.assign(m * n + 1, 1);
        for (int i = 0; i <= m * n; i++) p[i] = i;
        int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (!g[i][j]) continue;
                if (i == 0) unite(i * n + j, top);
                if (i > 0 && g[i - 1][j]) unite(i * n + j, (i - 1) * n + j);
                if (j > 0 && g[i][j - 1]) unite(i * n + j, i * n + j - 1);
            }
        }
        vector<int> res(k, 0);
        for (int t = k - 1; t >= 0; t--) {
            if (!had[t]) continue;
            int x = hits[t][0], y = hits[t][1];
            int before = sz[find(top)];
            g[x][y] = 1;
            if (x == 0) unite(x * n + y, top);
            for (int d = 0; d < 4; d++) {
                int nx = x + dx[d], ny = y + dy[d];
                if (nx < 0 || ny < 0 || nx >= m || ny >= n || !g[nx][ny]) continue;
                unite(x * n + y, nx * n + ny);
            }
            int after = sz[find(top)];
            res[t] = max(0, after - before - 1);
        }
        return res;
    }
};

