class Solution {
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int roof = m * n;
        int[] result = new int[hits.length];
        boolean[] removed = new boolean[hits.length];

        for (int i = 0; i < hits.length; i++) {
            int row = hits[i][0];
            int col = hits[i][1];

            if (grid[row][col] == 1) {
                removed[i] = true;
                grid[row][col] = 0;
            }
        }

        UnionFind uf = new UnionFind(m * n + 1);
        int[][] directions = {{1, 0}, {0, 1}};

        for (int row = 0; row < m; row++) {
            for (int col = 0; col < n; col++) {
                if (grid[row][col] == 0) {
                    continue;
                }

                int index = row * n + col;
                if (row == 0) {
                    uf.union(index, roof);
                }

                for (int[] direction : directions) {
                    int nextRow = row + direction[0];
                    int nextCol = col + direction[1];

                    if (nextRow < m && nextCol < n
                            && grid[nextRow][nextCol] == 1) {
                        uf.union(index, nextRow * n + nextCol);
                    }
                }
            }
        }

        int[][] neighbors = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
        };

        for (int i = hits.length - 1; i >= 0; i--) {
            if (!removed[i]) {
                continue;
            }

            int row = hits[i][0];
            int col = hits[i][1];
            int before = uf.componentSize(roof);

            grid[row][col] = 1;
            int index = row * n + col;

            if (row == 0) {
                uf.union(index, roof);
            }

            for (int[] neighbor : neighbors) {
                int nextRow = row + neighbor[0];
                int nextCol = col + neighbor[1];

                if (nextRow >= 0 && nextRow < m
                        && nextCol >= 0 && nextCol < n
                        && grid[nextRow][nextCol] == 1) {
                    uf.union(index, nextRow * n + nextCol);
                }
            }

            int after = uf.componentSize(roof);
            result[i] = Math.max(0, after - before - 1);
        }

        return result;
    }

    private static class UnionFind {
        private final int[] parent;
        private final int[] size;

        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];

            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int node) {
            if (parent[node] != node) {
                parent[node] = find(parent[node]);
            }
            return parent[node];
        }

        void union(int first, int second) {
            int rootFirst = find(first);
            int rootSecond = find(second);

            if (rootFirst == rootSecond) {
                return;
            }

            if (size[rootFirst] < size[rootSecond]) {
                int temp = rootFirst;
                rootFirst = rootSecond;
                rootSecond = temp;
            }

            parent[rootSecond] = rootFirst;
            size[rootFirst] += size[rootSecond];
        }

        int componentSize(int node) {
            return size[find(node)];
        }
    }
}

class Solution {
    private int[] parent;
    private int[] size;

    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length, n = grid[0].length;
        int top = m * n;
        parent = new int[top + 1];
        size = new int[top + 1];
        for (int i = 0; i <= top; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        // Mark hit bricks as 2 (originally present but will be erased)
        for (int[] hit : hits) {
            if (grid[hit[0]][hit[1]] == 1) {
                grid[hit[0]][hit[1]] = 2;
            }
        }

        // Build union-find over remaining bricks
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int idx = i * n + j;
                    if (i == 0) union(idx, top);
                    if (i + 1 < m && grid[i + 1][j] == 1) union(idx, (i + 1) * n + j);
                    if (j + 1 < n && grid[i][j + 1] == 1) union(idx, i * n + j + 1);
                }
            }
        }

        int[] result = new int[hits.length];
        for (int k = hits.length - 1; k >= 0; k--) {
            int r = hits[k][0], c = hits[k][1];
            if (grid[r][c] != 2) continue; // no brick was erased by this hit
            grid[r][c] = 1; // restore the brick
            int idx = r * n + c;
            int before = size[find(top)];
            if (r == 0) union(idx, top);
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                    union(idx, nr * n + nc);
                }
            }
            int after = size[find(top)];
            result[k] = Math.max(0, after - before - 1);
        }

        return result;
    }

    private int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    private void union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (size[ra] < size[rb]) {
            parent[ra] = rb;
            size[rb] += size[ra];
        } else {
            parent[rb] = ra;
            size[ra] += size[rb];
        }
    }
}

class Solution {
    private int m, n;
    private int[] parent, size;

    public int[] hitBricks(int[][] grid, int[][] hits) {
        m = grid.length;
        n = grid[0].length;
        int total = m * n;
        int roof = total;

        int[][] g = new int[m][n];
        for (int i = 0; i < m; i++) {
            System.arraycopy(grid[i], 0, g[i], 0, n);
        }

        for (int[] h : hits) {
            int r = h[0], c = h[1];
            if (g[r][c] == 1) g[r][c] = 0;
        }

        parent = new int[total + 1];
        size = new int[total + 1];
        for (int i = 0; i <= total; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        for (int c = 0; c < n; c++) {
            if (g[0][c] == 1) union(idx(0, c), roof);
        }
        for (int r = 1; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (g[r][c] == 1) {
                    if (g[r - 1][c] == 1) union(idx(r, c), idx(r - 1, c));
                    if (c > 0 && g[r][c - 1] == 1) union(idx(r, c), idx(r, c - 1));
                }
            }
        }

        int k = hits.length;
        int[] ans = new int[k];
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};

        for (int i = k - 1; i >= 0; i--) {
            int r = hits[i][0], c = hits[i][1];
            if (grid[r][c] == 0) {
                ans[i] = 0;
                continue;
            }

            int before = roofSize();
            int id = idx(r, c);
            g[r][c] = 1;

            if (r == 0) union(id, roof);
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && g[nr][nc] == 1) {
                    union(id, idx(nr, nc));
                }
            }

            int after = roofSize();
            ans[i] = Math.max(0, after - before - 1);
        }

        return ans;
    }

    private int idx(int r, int c) {
        return r * n + c;
    }

    private int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    private void union(int a, int b) {
        int pa = find(a), pb = find(b);
        if (pa == pb) return;
        if (size[pa] < size[pb]) {
            int t = pa; pa = pb; pb = t;
        }
        parent[pb] = pa;
        size[pa] += size[pb];
    }

    private int roofSize() {
        return size[find(m * n)];
    }
}

