        int N = m * n;
        DSU dsu = new DSU(N + 1);
        int top = N;
        dsu.size[top] = 0;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (g[r][c] == 1) {
                    int idx = r * n + c;
                    if (r == 0) {
                        dsu.union(idx, top);
                    }
                    for (int d = 0; d < 4; d++) {
