                        int nc = c + dc[d];
                        if (nr >= 0 && nr < m && nc >= 0 && nc < n && g[nr][nc] == 1) {
                            dsu.union(idx, nr * n + nc);
                        }
                    }
                }
            }
        }

        int[] ans = new int[h];
        for (int i = h - 1; i >= 0; i--) {
            if (!wasBrick[i]) {
                ans[i] = 0;
                continue;
            }
            int r = hits[i][0];
            int c = hits[i][1];
            int idx = r * n + c;
            int before = dsu.getSize(top);
            g[r][c] = 1;
            if (r == 0) {
