        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0) {
                    continue;
                }

                int index = r * n + c;
                if (r == 0) {
                    dsu.union(index, roof);
                }
                if (r > 0 && grid[r - 1][c] == 1) {
                    dsu.union(index, (r - 1) * n + c);
                }
                if (c > 0 && grid[r][c - 1] == 1) {
                    dsu.union(index, r * n + c - 1);
                }
            }
        }

        int[] result = new int[hits.length];

        for (int i = hits.length - 1; i >= 0; i--) {
            if (!existed[i]) {
                continue;
