var countMaxOrSubsets = function(nums) {
    let maxOr = 0;
    for (const num of nums) {
        maxOr |= num;
    }

    function dfs(index, currentOr) {
        if (currentOr === maxOr) {
            return 1 << (nums.length - index);
        }
        if (index === nums.length) {
            return 0;
        }
        return dfs(index + 1, currentOr | nums[index]) + dfs(index + 1, currentOr);
    }

    return dfs(0, 0);
};

