        final long MOD = 1_000_000_007L;
        // dp counts for strings ending in each vowel (start with length 1)
        long a = 1, e = 1, i = 1, o = 1, u = 1;
        for (int len = 2; len <= n; len++) {
            // a can follow e, i, u
            long na = (e + i + u) % MOD;
            // e can follow a, i
            long ne = (a + i) % MOD;
            // i can follow e, o
            long ni = (e + o) % MOD;
            // o can follow i
            long no = i;
            // u can follow i, o
            long nu = (i + o) % MOD;
            a = na;
            e = ne;
            i = ni;
            o = no;
            u = nu;
        }
        long ans = (a + e + i + o + u) % MOD;
        return (int) ans;
    }
}

