    public boolean isCousins(TreeNode root, int x, int y) {
        java.util.Queue<TreeNode> queue = new java.util.ArrayDeque<>();
        java.util.Map<Integer, TreeNode> parents = new java.util.HashMap<>();

        queue.offer(root);
        parents.put(root.val, null);

        while (!queue.isEmpty()) {
            int size = queue.size();
            TreeNode parentX = null;
            TreeNode parentY = null;
            boolean foundX = false;
            boolean foundY = false;

            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();

                if (node.val == x) {
                    foundX = true;
                    parentX = parents.get(node.val);
                }
                if (node.val == y) {
                    foundY = true;
                    parentY = parents.get(node.val);
                }

                if (node.left != null) {
                    queue.offer(node.left);
                    parents.put(node.left.val, node);
                }
                if (node.right != null) {
                    queue.offer(node.right);
                    parents.put(node.right.val, node);
                }
            }

            if (foundX || foundY) {
                return foundX && foundY && parentX != parentY;
            }
        }

        return false;
    }
}

