    string evaluate(string s, vector<vector<string>>& knowledge) {
        unordered_map<string, string> mp;
        mp.reserve(knowledge.size() * 2);
        for (const auto& pair : knowledge) {
            mp[pair[0]] = pair[1];
        }

        string result;
        result.reserve(s.size());

        int i = 0;
        while (i < (int)s.size()) {
            if (s[i] == '(') {
                int j = i + 1;
                while (s[j] != ')') {
                    ++j;
                }

                string key = s.substr(i + 1, j - i - 1);
                auto it = mp.find(key);
                if (it != mp.end()) {
                    result += it->second;
                } else {
                    result += '?';
                }

                i = j + 1;
            } else {
                result += s[i];
                ++i;
            }
        }

        return result;
    }
};

