 * @param {number[]} nums
 * @param {number} key
 * @param {number} k
 * @return {number[]}
 */
var findKDistantIndices = function(nums, key, k) {
    const n = nums.length;
    const result = [];
    let lastAdded = -1;

    for (let j = 0; j < n; j++) {
        if (nums[j] === key) {
            const start = Math.max(0, j - k);
            const end = Math.min(n - 1, j + k);

            for (let i = Math.max(start, lastAdded + 1); i <= end; i++) {
                result.push(i);
                lastAdded = i;
            }
        }
    }

    return result;
};

