function findKDistantIndices(nums: number[], key: number, k: number): number[] {
    const n = nums.length;
    const diff = new Array<number>(n + 1).fill(0);

    for (let j = 0; j < n; j++) {
        if (nums[j] === key) {
            const left = Math.max(0, j - k);
            const right = Math.min(n - 1, j + k);
            diff[left]++;
            diff[right + 1]--;
        }
    }

    const result: number[] = [];
    let active = 0;

    for (let i = 0; i < n; i++) {
        active += diff[i];
        if (active > 0) {
            result.push(i);
        }
    }

    return result;
}

