/**
 * @param {number} m
 * @param {number} k
 */
var MKAverage = function(m, k) {
    this.m = m;
    this.k = k;
    this.queue = [];
    this.MAX = 100001;
    this.cnt = new Array(this.MAX + 1).fill(0);
    this.sum = new Array(this.MAX + 1).fill(0);
    this.total = 0; // total count in tree
    this.totalSum = 0;
};

MKAverage.prototype._update = function(i, dc, ds) {
    for (; i <= this.MAX; i += i & (-i)) {
        this.cnt[i] += dc;
        this.sum[i] += ds;
    }
};

// returns {cnt, sum} of values <= i
MKAverage.prototype._query = function(i) {
    let c = 0, s = 0;
    for (; i > 0; i -= i & (-i)) {
        c += this.cnt[i];
        s += this.sum[i];
    }
    return [c, s];
};

// find smallest value v such that prefix count >= target
MKAverage.prototype._kth = function(target) {
    let pos = 0;
    let c = 0;
    let LOG = 17;
    for (let pw = 1 << LOG; pw > 0; pw >>= 1) {
        let next = pos + pw;
        if (next <= this.MAX && c + this.cnt[next] < target) {
            pos = next;
            c += this.cnt[next];
        }
    }
    return pos + 1;
};

/** 
 * @param {number} num
 * @return {void}
 */
MKAverage.prototype.addElement = function(num) {
    this.queue.push(num);
    this._update(num, 1, num);
    this.total++;
    this.totalSum += num;
    if (this.queue.length > this.m) {
        let old = this.queue.shift();
        this._update(old, -1, -old);
        this.total--;
        this.totalSum -= old;
    }
};

/**
 * @return {number}
 */
MKAverage.prototype.calculateMKAverage = function() {
    if (this.queue.length < this.m) return -1;
    // remove smallest k and largest k
    // sum of smallest k:
    let k = this.k;
    // find the value at position k (kth smallest)
    let vk = this._kth(k);
    let [ck, sk] = this._query(vk);
    // sum of smallest k: we have ck elements <= vk, ck >= k
    // sum including vk occurrences; need exactly k smallest
    let smallSum;
    {
        // elements strictly below vk
        let below = this._query(vk - 1);
        let belowCnt = below[0], belowSum = below[1];
        let need = k - belowCnt; // occurrences of vk to include
        smallSum = belowSum + need * vk;
    }
    // largest k: position total-k+1 .. total
    let m = this.m;
    let vk2 = this._kth(m - k + 1); // value at position m-k+1 (first of largest k)
    let largeSum;
    {
        // elements strictly above vk2
        let below2 = this._query(vk2); // count <= vk2
        let aboveCnt = this.total - below2[0];
        let aboveSum = this.totalSum - below2[1];
        let need = k - aboveCnt; // occurrences of vk2 to include in largest
        largeSum = aboveSum + need * vk2;
    }
    let middleSum = this.totalSum - smallSum - largeSum;
    let middleCnt = m - 2 * k;
    return Math.floor(middleSum / middleCnt);
};

/**
 * @param {number} m
 * @param {number} k
 */
var MKAverage = function(m, k) {
    this.m = m;
    this.k = k;
    this.N = 100001;
    this.cnt = new Int32Array(this.N + 1);
    this.sum = new Float64Array(this.N + 1);
    this.queue = [];
    this.head = 0;
    this.total = 0;
    this.LOG = 1;
    while ((1 << this.LOG) <= this.N) this.LOG++;
};

MKAverage.prototype._update = function(idx, dc, ds) {
    for (let i = idx; i <= this.N; i += i & (-i)) {
        this.cnt[i] += dc;
        this.sum[i] += ds;
    }
};

// sum of the smallest `k` elements currently in window
MKAverage.prototype._smallestSum = function(k) {
    if (k <= 0) return 0;
    let pos = 0, c = 0, s = 0;
    for (let b = this.LOG; b >= 0; b--) {
        const np = pos + (1 << b);
        if (np <= this.N && c + this.cnt[np] < k) {
            pos = np;
            c += this.cnt[np];
            s += this.sum[np];
        }
    }
    const remaining = k - c;
    return s + remaining * (pos + 1);
};

/** 
 * @param {number} num
 * @return {void}
 */
MKAverage.prototype.addElement = function(num) {
    this.queue.push(num);
    this._update(num, 1, num);
    this.total += num;
    if (this.queue.length - this.head > this.m) {
        const old = this.queue[this.head++];
        this._update(old, -1, -old);
        this.total -= old;
        if (this.head > 100000) {
            this.queue = this.queue.slice(this.head);
            this.head = 0;
        }
    }
};

/**
 * @return {number}
 */
MKAverage.prototype.calculateMKAverage = function() {
    if (this.queue.length - this.head < this.m) return -1;
    const small = this._smallestSum(this.k);
    const upToMK = this._smallestSum(this.m - this.k);
    const mid = upToMK - small;
    return Math.floor(mid / (this.m - 2 * this.k));
