            mid.erase(mid.begin());
            sum_mid -= val;
            left.insert(val);
        } else if (left.size() > k) {
            int val = *left.rbegin();
            left.erase(std::prev(left.end()));
            mid.insert(val);
            sum_mid += val;
        }

        // Rebalance right and mid
        if (right.size() < k) {
            int val = *mid.rbegin();
            mid.erase(std::prev(mid.end()));
            sum_mid -= val;
            right.insert(val);
        } else if (right.size() > k) {
            int val = *right.begin();
            right.erase(right.begin());
            mid.insert(val);
            sum_mid += val;
        }
    }

    int calculateMKAverage() {
