        q.offer(num);

        if (sizeLow == 0 || num <= low.lastKey()) {
            add(low, num);
            sizeLow++;
        } else if (sizeHigh == 0 || num >= high.firstKey()) {
            add(high, num);
            sizeHigh++;
        } else {
            add(mid, num);
            sizeMid++;
            sumMid += num;
        }

        if (q.size() > m) {
            int old = q.poll();
            if (remove(low, old)) {
                sizeLow--;
            } else if (remove(high, old)) {
                sizeHigh--;
            } else {
                remove(mid, old);
                sizeMid--;
                sumMid -= old;
            }
        }

        rebalance();
    }

    public int calculateMKAverage() {
        if (q.size() < m) return -1;
        return (int) (sumMid / (m - 2L * k));
    }

    private void rebalance() {
        while (sizeLow > k) {
            int x = pollLast(low);
            sizeLow--;
            add(mid, x);
            sizeMid++;
            sumMid += x;
        }
        while (sizeLow < k && sizeMid > 0) {
            int x = pollFirst(mid);
            sizeMid--;
            sumMid -= x;
            add(low, x);
            sizeLow++;
        }

        while (sizeHigh > k) {
            int x = pollFirst(high);
            sizeHigh--;
            add(mid, x);
            sizeMid++;
            sumMid += x;
        }
        while (sizeHigh < k && sizeMid > 0) {
            int x = pollLast(mid);
            sizeMid--;
            sumMid -= x;
            add(high, x);
            sizeHigh++;
        }

        while (sizeLow > 0 && sizeHigh > 0 && !low.isEmpty() && !high.isEmpty() && low.lastKey() > high.firstKey()) {
            int a = pollLast(low);
            int b = pollFirst(high);
            add(mid, a);
            add(mid, b);
            sizeLow--;
            sizeHigh--;
            sizeMid += 2;
            sumMid += a + b;

            int x = pollFirst(mid);
            sizeMid--;
            sumMid -= x;
            add(low, x);
            sizeLow++;

            x = pollLast(mid);
            sizeMid--;
            sumMid -= x;
            add(high, x);
            sizeHigh++;
        }
    }

    private void add(TreeMap<Integer, Integer> map, int x) {
        map.put(x, map.getOrDefault(x, 0) + 1);
    }

    private boolean remove(TreeMap<Integer, Integer> map, int x) {
        Integer cnt = map.get(x);
        if (cnt == null) return false;
        if (cnt == 1) map.remove(x);
        else map.put(x, cnt - 1);
        return true;
    }

    private int pollFirst(TreeMap<Integer, Integer> map) {
        int x = map.firstKey();
        remove(map, x);
        return x;
    }

    private int pollLast(TreeMap<Integer, Integer> map) {
        int x = map.lastKey();
        remove(map, x);
        return x;
    }
}

