        long lessSum = querySum(value - 1);
        int need = cnt - lessCount;

        return lessSum + (long) need * value;
    }
}

import java.util.*;

class MKAverage {
    int m, k;
    Deque<Integer> window = new ArrayDeque<>();
    TreeMap<Integer,Integer> low = new TreeMap<>(), mid = new TreeMap<>(), high = new TreeMap<>();
    int lowSize = 0, highSize = 0;
    long midSum = 0;

    public MKAverage(int m, int k) {
        this.m = m;
        this.k = k;
    }

    private void add(TreeMap<Integer,Integer> map, int num) {
        map.merge(num, 1, Integer::sum);
    }
    private void remove(TreeMap<Integer,Integer> map, int num) {
        int c = map.get(num);
        if (c == 1) map.remove(num);
        else map.put(num, c-1);
    }

    public void addElement(int num) {
        window.addLast(num);
        // insert num into structure
        if (lowSize < k) {
            add(low, num); lowSize++;
        } else if (!low.isEmpty() && num < low.lastKey()) {
            add(low, num); lowSize++;
        } else if (highSize < k) {
            add(high, num); highSize++;
        } else if (!high.isEmpty() && num > high.firstKey()) {
            add(high, num); highSize++;
        } else {
            add(mid, num); midSum += num;
        }
        rebalance();

        if (window.size() > m) {
            int old = window.removeFirst();
            removeElement(old);
            rebalance();
        }
    }

    private void removeElement(int num) {
        if (low.containsKey(num)) {
            remove(low, num); lowSize--;
        } else if (high.containsKey(num) && num >= high.firstKey() && (mid.isEmpty() || num > mid.lastKey())) {
            // ambiguous; prefer checking mid first properly
            remove(high, num); highSize--;
        } else if (mid.containsKey(num)) {
            remove(mid, num); midSum -= num;
        } else {
            remove(high, num); highSize--;
        }
    }

    private void rebalance() {
        // ensure low has exactly k (if enough elements), high has exactly k
        // move between low->mid, mid->low, mid->high, high->mid
        while (lowSize > k) {
            int key = low.lastKey();
            remove(low, key); lowSize--;
            add(mid, key); midSum += key;
        }
        while (lowSize < k && !mid.isEmpty()) {
            int key = mid.firstKey();
            remove(mid, key); midSum -= key;
            add(low, key); lowSize++;
        }
        while (highSize > k) {
            int key = high.firstKey();
            remove(high, key); highSize--;
            add(mid, key); midSum += key;
        }
        while (highSize < k && !mid.isEmpty()) {
            int key = mid.lastKey();
            remove(mid, key); midSum -= key;
            add(high, key); highSize++;
        }
        // ensure low elements <= mid <= high
        while (!low.isEmpty() && !mid.isEmpty() && low.lastKey() > mid.firstKey()) {
            int a = low.lastKey(), b = mid.firstKey();
            remove(low, a); add(low, b);
            remove(mid, b); add(mid, a);
            midSum += a - b;
        }
        while (!high.isEmpty() && !mid.isEmpty() && high.firstKey() < mid.lastKey()) {
            int a = high.firstKey(), b = mid.lastKey();
            remove(high, a); add(high, b);
            remove(mid, b); add(mid, a);
            midSum += a - b;
        }
    }

    public int calculateMKAverage() {
        if (window.size() < m) return -1;
        int cnt = m - 2*k;
        return (int)(midSum / cnt);
    }
}

class MKAverage {
    private static final int MAX_VAL = 100000;
    private final int m;
    private final int k;
    private final int[] countTree;
    private final long[] sumTree;
    private final int[] stream;
    private int size;
    private int head;

    public MKAverage(int m, int k) {
        this.m = m;
        this.k = k;
        this.countTree = new int[MAX_VAL + 1];
        this.sumTree = new long[MAX_VAL + 1];
        this.stream = new int[m];
        this.size = 0;
        this.head = 0;
    }

    private void update(int val, int delta) {
        long deltaSum = (long) val * delta;
        for (int i = val; i <= MAX_VAL; i += i & -i) {
            countTree[i] += delta;
            sumTree[i] += deltaSum;
        }
    }

    private long getSumOfSmallest(int r) {
        if (r == 0) return 0;
        int idx = 0;
        int currentCount = 0;
        long currentSum = 0;

        for (int step = 1 << 16; step > 0; step >>= 1) {
            if (idx + step <= MAX_VAL && currentCount + countTree[idx + step] <= r) {
                idx += step;
                currentCount += countTree[idx];
                currentSum += sumTree[idx];
            }
        }

        if (currentCount < r) {
            currentSum += (long) (r - currentCount) * (idx + 1);
        }
        return currentSum;
    }

    public void addElement(int num) {
        if (size == m) {
            int oldNum = stream[head];
            update(oldNum, -1);
        } else {
            size++;
        }

        stream[head] = num;
        head = (head + 1) % m;
        update(num, 1);
    }

    public int calculateMKAverage() {
        if (size < m) {
            return -1;
        }
        long sumSmallestMK = getSumOfSmallest(m - k);
        long sumSmallestK = getSumOfSmallest(k);
        return (int) ((sumSmallestMK - sumSmallestK) / (m - 2 * k));
    }
}

