    // dp[i][k] = 1 if stone i is reachable with the last jump being k units.
    // Reaching stone index i with jump k requires k <= i <= n - 1.
    const dp = new Array(n);
    for (let i = 0; i < n; i++) dp[i] = new Uint8Array(n + 1);
