            for (let nextJump = jump - 1; nextJump <= jump + 1; nextJump++) {
                if (nextJump <= 0) {
                    continue;
                }

                const nextPosition = position + nextJump;
                const nextIndex = indexByPosition.get(nextPosition);

                if (nextIndex !== undefined) {
                    dp[nextIndex].add(nextJump);
                }
            }
        }
    }

    return dp[n - 1].size > 0;
}

class Solution {
