class Solution {
    public boolean canCross(int[] stones) {
        int n = stones.length;
        if (n == 1) return true;

        // Pruning: to land on stone i, the landing jump size is at most i
        // (first jump is 1, each jump grows by at most 1, at most i jumps used).
        // So the gap between consecutive stones i-1 and i cannot exceed i.
        for (int i = 1; i < n; i++) {
            if (stones[i] - stones[i - 1] > i) return false;
        }

        Map<Integer, Set<Integer>> dp = new HashMap<>();
        for (int pos : stones) {
            dp.put(pos, new HashSet<>());
        }
        // Frog starts at position 0; treat initial last jump as 0 so first jump must be 1.
        dp.get(0).add(0);

        int last = stones[n - 1];
        for (int pos : stones) {
            for (int k : dp.get(pos)) {
                for (int step = k - 1; step <= k + 1; step++) {
                    if (step <= 0) continue;
                    long target = (long) pos + step;
                    if (target > last) continue;
                    Set<Integer> next = dp.get((int) target);
                    if (next != null) {
                        next.add(step);
                    }
                }
            }
        }

        return !dp.get(last).isEmpty();
    }
}

