/**
 * @param {number[][]} grid
 * @return {number}
 */
var largestMagicSquare = function(grid) {
    const m = grid.length;
    const n = grid[0].length;

    const rowPrefix = Array.from({ length: m }, () => Array(n + 1).fill(0));
    const colPrefix = Array.from({ length: m + 1 }, () => Array(n).fill(0));
    const diagPrefix = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));
    const antiDiagPrefix = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            rowPrefix[i][j + 1] = rowPrefix[i][j] + grid[i][j];
            colPrefix[i + 1][j] = colPrefix[i][j] + grid[i][j];
            diagPrefix[i + 1][j + 1] = diagPrefix[i][j] + grid[i][j];
        }
    }

    for (let i = 0; i < m; i++) {
        for (let j = n - 1; j >= 0; j--) {
            antiDiagPrefix[i + 1][j] = antiDiagPrefix[i][j + 1] + grid[i][j];
        }
    }

    const maxSize = Math.min(m, n);

    for (let k = maxSize; k >= 1; k--) {
        for (let r = 0; r + k <= m; r++) {
            for (let c = 0; c + k <= n; c++) {
                const target = diagPrefix[r + k][c + k] - diagPrefix[r][c];
                const antiDiagSum = antiDiagPrefix[r + k][c] - antiDiagPrefix[r][c + k];

                if (antiDiagSum !== target) continue;

                let isMagic = true;

                for (let i = r; i < r + k; i++) {
                    const rowSum = rowPrefix[i][c + k] - rowPrefix[i][c];
                    if (rowSum !== target) {
                        isMagic = false;
                        break;
                    }
                }

                if (!isMagic) continue;

                for (let j = c; j < c + k; j++) {
                    const colSum = colPrefix[r + k][j] - colPrefix[r][j];
                    if (colSum !== target) {
                        isMagic = false;
                        break;
                    }
                }

                if (isMagic) return k;
            }
        }
    }

    return 1;
};

/**
 * @param {number[][]} grid
 * @return {number}
 */
var largestMagicSquare = function(grid) {
    const m = grid.length;
    const n = grid[0].length;

    const rowSum = Array.from({ length: m }, () => new Int32Array(n + 1));
    const colSum = Array.from({ length: m + 1 }, () => new Int32Array(n));

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            rowSum[r][c + 1] = rowSum[r][c] + grid[r][c];
            colSum[r + 1][c] = colSum[r][c] + grid[r][c];
        }
    }

    const maxK = Math.min(m, n);

    for (let k = maxK; k >= 2; k--) {
        for (let r = 0; r <= m - k; r++) {
            for (let c = 0; c <= n - k; c++) {
                const target = rowSum[r][c + k] - rowSum[r][c];
                let isMagic = true;

                // Check remaining rows
                for (let i = 1; i < k; i++) {
                    if (rowSum[r + i][c + k] - rowSum[r + i][c] !== target) {
                        isMagic = false;
                        break;
                    }
                }
                if (!isMagic) continue;

                // Check columns
                for (let j = 0; j < k; j++) {
                    if (colSum[r + k][c + j] - colSum[r][c + j] !== target) {
                        isMagic = false;
                        break;
                    }
                }
                if (!isMagic) continue;

                // Check main diagonal
                let d1 = 0;
                for (let d = 0; d < k; d++) {
                    d1 += grid[r + d][c + d];
                }
                if (d1 !== target) continue;

                // Check anti-diagonal
                let d2 = 0;
                for (let d = 0; d < k; d++) {
                    d2 += grid[r + d][c + k - 1 - d];
                }
                if (d2 !== target) continue;

                return k;
            }
        }
    }

    return 1;
};

var largestMagicSquare = function(grid) {
    const m = grid.length, n = grid[0].length;
    const row = Array.from({length: m + 1}, () => new Array(n + 2).fill(0));
    const col = Array.from({length: m + 2}, () => new Array(n + 1).fill(0));
    const d1 = Array.from({length: m + 2}, () => new Array(n + 2).fill(0));
    const d2 = Array.from({length: m + 2}, () => new Array(n + 2).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            const v = grid[i][j];
            row[i][j + 1] = row[i][j] + v;
            col[i + 1][j] = col[i][j] + v;
            d1[i + 1][j + 1] = d1[i][j] + v;
            d2[i + 1][j] = d2[i][j + 1] + v;
        }
    }
    for (let k = Math.min(m, n); k >= 2; k--) {
        for (let i = 0; i + k <= m; i++) {
            for (let j = 0; j + k <= n; j++) {
                const t = d1[i + k][j + k] - d1[i][j];
                if (d2[i + k][j] - d2[i][j + k] !== t) continue;
                let ok = true;
                for (let r = i; r < i + k && ok; r++) {
                    if (row[r][j + k] - row[r][j] !== t) ok = false;
                }
                for (let c = j; c < j + k && ok; c++) {
                    if (col[i + k][c] - col[i][c] !== t) ok = false;
                }
                if (ok) return k;
            }
        }
    }
    return 1;
};

