class Solution {
    public int lengthOfLIS(int[] nums) {
        // tails[i] = smallest possible tail value of an increasing subsequence of length i+1
        int[] tails = new int[nums.length];
        int size = 0;

        for (int num : nums) {
            // Binary search for the leftmost position where tails[pos] >= num (lower bound)
            int lo = 0, hi = size;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (tails[mid] < num) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            tails[lo] = num;
            if (lo == size) {
                size++;
            }
        }

        return size;
    }
}

