#include <vector>
#include <unordered_map>
#include <algorithm>
#include <numeric>
using namespace std;

class Solution {
public:
    int maxPoints(vector<vector<int>>& points) {
        int n = points.size();
        if (n <= 2) return n;

        int best = 1;

        for (int i = 0; i < n; ++i) {
            // Pruning: even if all remaining points (including i) are collinear,
            // we can get at most (n - i) points; skip if it can't beat current best.
            if (best >= n - i) break;

            unordered_map<long long, int> slopeCount;
            int localMax = 0;

            for (int j = i + 1; j < n; ++j) {
                long long dx = points[j][0] - points[i][0];
                long long dy = points[j][1] - points[i][1];

                long long g = std::gcd(dx, dy);
                dx /= g;
                dy /= g;

                // Normalize direction so that lines are represented uniquely
                if (dx < 0) {
                    dx = -dx;
                    dy = -dy;
                } else if (dx == 0 && dy < 0) {
                    dy = -dy;  // vertical line -> (0, 1)
                }

                // Encode (dx, dy) into a single key:
                // dx in [0, 20000], dy in [-20000, 20000]
                long long key = dx * 40001LL + (dy + 20000);
                localMax = max(localMax, ++slopeCount[key]);
            }

            best = max(best, localMax + 1);
        }

        return best;
    }
};

