 * @param {number[]} nums
 * @return {number}
 */
var maxScore = function(nums) {
    const m = nums.length;
    const gcd = (a, b) => { while (b) { [a, b] = [b, a % b]; } return a; };
    const dp = new Array(1 << m).fill(-1);
    dp[0] = 0;
    const bits = mask => {
        let c = 0;
        while (mask) { c += mask & 1; mask >>= 1; }
        return c;
    };
    let best = 0;
    for (let mask = 0; mask < (1 << m); mask++) {
        if (dp[mask] < 0) continue;
        const cnt = bits(mask);
        const op = cnt / 2 + 1;
        for (let i = 0; i < m; i++) {
            if (mask & (1 << i)) continue;
            for (let j = i + 1; j < m; j++) {
                if (mask & (1 << j)) continue;
                const nm = mask | (1 << i) | (1 << j);
                const val = dp[mask] + op * gcd(nums[i], nums[j]);
                if (val > dp[nm]) {
                    dp[nm] = val;
                    if (val > best) best = val;
                }
            }
        }
    }
    return best;
};

