var maxScore = function(nums) {
    const m = nums.length;
    const maxMask = 1 << m;

    // Helper function for GCD
    const gcd = (a, b) => {
        while (b !== 0) {
            let temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    };

    // Precompute GCDs
    const gcdTable = Array.from({ length: m }, () => new Int32Array(m));
    for (let i = 0; i < m; i++) {
        for (let j = i + 1; j < m; j++) {
            gcdTable[i][j] = gcd(nums[i], nums[j]);
        }
    }

    // dp[mask] stores the maximum score using elements in mask
    const dp = new Int32Array(maxMask);

    // Helper to count set bits
    const popcount = new Int8Array(maxMask);
    for (let mask = 1; mask < maxMask; mask++) {
        popcount[mask] = popcount[mask >> 1] + (mask & 1);
    }

    for (let mask = 0; mask < maxMask; mask++) {
        const count = popcount[mask];
        if ((count & 1) !== 0) continue;

        const op = (count >> 1) + 1;

        for (let i = 0; i < m; i++) {
            if ((mask & (1 << i)) !== 0) continue;
            for (let j = i + 1; j < m; j++) {
                if ((mask & (1 << j)) !== 0) continue;

                const nextMask = mask | (1 << i) | (1 << j);
                const score = dp[mask] + op * gcdTable[i][j];
                if (score > dp[nextMask]) {
                    dp[nextMask] = score;
                }
            }
        }
    }

    return dp[maxMask - 1];
};

var maxScore = function(nums) {
    const m = nums.length;
    const full = 1 << m;
    const dp = new Array(full).fill(-1);
    dp[0] = 0;

    const gcd = (a, b) => {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };

    const gcdCache = Array.from({ length: m }, () => new Array(m).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = i + 1; j < m; j++) {
            gcdCache[i][j] = gcd(nums[i], nums[j]);
        }
    }

    for (let mask = 0; mask < full; mask++) {
        if (dp[mask] === -1) continue;

        let used = 0;
        for (let i = 0; i < m; i++) {
            if (mask & (1 << i)) used++;
        }

        if (used % 2 !== 0) continue;

        const operation = used / 2 + 1;

