        if (i === n) return 0;
        const key = (i << 18) | mask;
        const cached = memo.get(key);
        if (cached !== undefined) return cached;

        let best = 0;
        for (let slot = 0; slot < numSlots; slot++) {
            const p1 = slot * 2;
            const p2 = slot * 2 + 1;
            if (((mask >> p1) & 1) === 0) {
