class Solution {
public:
    int maximumANDSum(vector<int>& nums, int numSlots) {
        int totalPositions = 2 * numSlots;
        int limit = 1 << totalPositions;
        vector<int> dp(limit, -1);
        dp[0] = 0;

        for (int mask = 0; mask < limit; ++mask) {
            if (dp[mask] == -1) continue;

            int index = __builtin_popcount(mask);
            if (index == (int)nums.size()) continue;

            for (int pos = 0; pos < totalPositions; ++pos) {
                if ((mask & (1 << pos)) == 0) {
                    int slot = pos / 2 + 1;
                    int nextMask = mask | (1 << pos);
                    dp[nextMask] = max(
                        dp[nextMask],
                        dp[mask] + (nums[index] & slot)
                    );
                }
            }
        }

        int answer = 0;
        for (int mask = 0; mask < limit; ++mask) {
            if (__builtin_popcount(mask) == (int)nums.size()) {
                answer = max(answer, dp[mask]);
            }
        }

        return answer;
    }
};

