            if (used > n) continue;
            int idx = used - 1;
            int best = 0;
            for (int slot = 0; slot < numSlots; slot++) {
                int bit1 = 1 << (2 * slot);
                int bit2 = 1 << (2 * slot + 1);
                if ((mask & bit1) != 0) {
                    int prev = mask ^ bit1;
                    best = Math.max(best, dp[prev] + (nums[idx] & (slot + 1)));
                }
                if ((mask & bit2) != 0) {
                    int prev = mask ^ bit2;
                    best = Math.max(best, dp[prev] + (nums[idx] & (slot + 1)));
                }
            }
            dp[mask] = best;
        }
        int ans = 0;
        for (int mask = 0; mask < m; mask++) {
            if (Integer.bitCount(mask) == n) ans = Math.max(ans, dp[mask]);
        }
        return ans;
    }
