/**
 * @param {number[][]} students
 * @param {number[][]} mentors
 * @return {number}
 */
var maxCompatibilitySum = function(students, mentors) {
    const m = students.length;
    const n = students[0].length;

    // Precompute compatibility score between each student and each mentor
    const score = Array.from({ length: m }, () => new Array(m).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < m; j++) {
            let s = 0;
            for (let k = 0; k < n; k++) {
                if (students[i][k] === mentors[j][k]) s++;
            }
            score[i][j] = s;
        }
    }

    const full = 1 << m;
    // dp[mask] = max score where mask = set of mentors used,
    // students 0..popcount(mask)-1 are assigned
    const dp = new Array(full).fill(0);

    for (let mask = 0; mask < full; mask++) {
        // count of assigned students = popcount(mask)
        let i = 0;
        for (let b = 0; b < m; b++) {
            if (mask & (1 << b)) i++;
        }
        if (i === m) continue; // all students assigned
        for (let j = 0; j < m; j++) {
            if (!(mask & (1 << j))) {
                const nMask = mask | (1 << j);
                const cand = dp[mask] + score[i][j];
                if (cand > dp[nMask]) dp[nMask] = cand;
            }
        }
    }

    return dp[full - 1];
};

/**
 * @param {number[][]} students
 * @param {number[][]} mentors
 * @return {number}
 */
var maxCompatibilitySum = function(students, mentors) {
    const m = students.length;
    const n = students[0].length;

    const score = Array.from({ length: m }, () => new Array(m).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < m; j++) {
            let match = 0;
            for (let k = 0; k < n; k++) {
                if (students[i][k] === mentors[j][k]) {
                    match++;
                }
            }
            score[i][j] = match;
        }
    }

    const dp = new Array(1 << m).fill(0);

    for (let mask = 0; mask < (1 << m); mask++) {
        let i = 0;
        let temp = mask;
        while (temp > 0) {
            i += temp & 1;
            temp >>= 1;
        }

        if (i >= m) continue;

        for (let j = 0; j < m; j++) {
            if ((mask & (1 << j)) === 0) {
                const nextMask = mask | (1 << j);
                dp[nextMask] = Math.max(dp[nextMask], dp[mask] + score[i][j]);
            }
        }
    }

    return dp[(1 << m) - 1];
};

