                for (int k = 0; k < n; k++) {
                    if (students[i][k] == mentors[j][k]) s++;
                }
                score[i][j] = s;
            }
        }
        int[] dp = new int[1 << m];
        for (int mask = 0; mask < (1 << m); mask++) {
            int i = Integer.bitCount(mask);
            if (i >= m) continue;
            for (int j = 0; j < m; j++) {
                if ((mask & (1 << j)) == 0) {
                    int nmask = mask | (1 << j);
                    dp[nmask] = Math.max(dp[nmask], dp[mask] + score[i][j]);
                }
            }
        }
        return dp[(1 << m) - 1];
    }
}

class Solution {
    public int maxCompatibilitySum(int[][] students, int[][] mentors) {
        int m = students.length;
        int n = students[0].length;

        // Precompute compatibility score between each student and mentor
        int[][] score = new int[m][m];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                int s = 0;
                for (int k = 0; k < n; k++) {
                    if (students[i][k] == mentors[j][k]) {
                        s++;
                    }
                }
                score[i][j] = s;
            }
        }

        // Bitmask DP: dp[mask] = max score sum when mentors in 'mask' are assigned
        // to the first popcount(mask) students.
        int size = 1 << m;
        int[] dp = new int[size];

        for (int mask = 0; mask < size; mask++) {
            int i = Integer.bitCount(mask); // next student to assign
            if (i >= m) continue;
            for (int j = 0; j < m; j++) {
                if ((mask & (1 << j)) == 0) {
                    int newMask = mask | (1 << j);
                    int candidate = dp[mask] + score[i][j];
                    if (candidate > dp[newMask]) {
                        dp[newMask] = candidate;
                    }
                }
            }
        }

        return dp[size - 1];
    }
}

