        if ((freqCount.get(1) || 0) === 1) {
            // check rest all same
            const otherFreqCount = freqCount.get(maxFreq) || 0;
            // sum check: numbers with freq maxFreq * maxFreq + 1 == len
            if (maxFreq * otherFreqCount + 1 === len) {
                ans = len;
                continue;
            }
        }
        // Case 3: one element has freq maxFreq, rest have freq maxFreq-1
        if ((freqCount.get(maxFreq) || 0) === 1) {
            const prev = maxFreq - 1;
            const prevCount = freqCount.get(prev) || 0;
            if (prev * prevCount + maxFreq === len) {
                ans = len;
                continue;
            }
        }
    }

    return ans;
};

