        if (distToX > k) continue;

        let maxOtherDist = k - distToX;

        // Case 1: go first to x and then only one direction for remaining steps
        // Interval [l, r] containing startPos and x, possibly extending on one side.
        // We enumerate achievable intervals by considering turning points.
    }

    // Sliding window over all contiguous fruit positions that can be visited.
    let l = 0;
    let sum = 0;
