            const need = Math.min(
                2 * Math.abs(startPos - leftPos) + Math.abs(startPos - rightPos),
                2 * Math.abs(startPos - rightPos) + Math.abs(startPos - leftPos)
            );
            // But that still doesn't represent the minimal steps correctly for all cases.
            // Replace with direct formula below.
            break;
        }
    }

    // Correct approach: enumerate windows and compute minimum steps to cover interval [a,b].
    l = 0;
    sum = 0;
    for (let r = 0; r < n; r++) {
        sum += fruits[r][1];
        while (l <= r) {
            const a = positions[l];
            const b = positions[r];
            let need: number;
            if (b <= startPos) {
                need = startPos - a;
            } else if (a >= startPos) {
                need = b - startPos;
            } else {
