/**
 * @param {number} n
 * @param {number[]} batteries
 * @return {number}
 */
var maxRunTime = function(n, batteries) {
    let sum = 0n;
    for (const b of batteries) sum += BigInt(b);
    const N = BigInt(n);
    let lo = 1n, hi = sum / N;
    const canRun = (t) => {
        let total = 0n;
        for (const b of batteries) {
            const bb = BigInt(b);
            total += bb < t ? bb : t;
        }
        return total >= t * N;
    };
    while (lo < hi) {
        const mid = (lo + hi + 1n) / 2n;
        if (canRun(mid)) lo = mid;
        else hi = mid - 1n;
    }
    return Number(lo);
};

/**
 * @param {number} n
 * @param {number[]} batteries
 * @return {number}
 */
var maxRunTime = function(n, batteries) {
    let total = 0;
    for (const b of batteries) total += b;

    let left = 0;
    let right = Math.floor(total / n);

    const canRun = (time) => {
        let power = 0;
        const need = time * n;

        for (const b of batteries) {
            power += Math.min(b, time);
            if (power >= need) return true;
        }

        return false;
    };

    while (left < right) {
        const mid = Math.floor((left + right + 1) / 2);

        if (canRun(mid)) {
            left = mid;
        } else {
            right = mid - 1;
        }
    }

    return left;
};

