var maxRunTime = function(n, batteries) {
    let totalEnergy = 0n;
    for (const b of batteries) {
        totalEnergy += BigInt(b);
    }

    const bigN = BigInt(n);
    let low = 1n;
    let high = totalEnergy / bigN;
    let ans = 0n;

    while (low <= high) {
        const mid = (low + high) / 2n;

        let currentEnergy = 0n;
        for (const b of batteries) {
            const bigB = BigInt(b);
            currentEnergy += bigB < mid ? bigB : mid;
        }

        if (currentEnergy >= mid * bigN) {
            ans = mid;
            low = mid + 1n;
        } else {
            high = mid - 1n;
        }
    }

    return Number(ans);
};

