class Solution {
public:
    long long maxRunTime(int n, vector<int>& batteries) {
        long long sum = 0;
        for (int x : batteries) sum += x;

        sort(batteries.begin(), batteries.end());

        int m = (int)batteries.size();
        long long k = n;

        // Remove batteries that are too large to be part of the equalized pool.
        while (m > 0 && batteries[m - 1] > sum / k) {
            sum -= batteries[m - 1];
            --m;
            --k;
        }

        return sum / k;
    }
};

