function maxStudents(seats: string[][]): number {
    const m = seats.length;
    const n = seats[0].length;

    // broken[r] has the c-th bit set if seats[r][c] is '#'
    const broken: number[] = new Array(m).fill(0);
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (seats[r][c] === '#') {
                broken[r] |= (1 << c);
            }
        }
    }

    // Helper to count bits
    function countBits(x: number): number {
        let count = 0;
        while (x > 0) {
            count += x & 1;
            x >>= 1;
        }
        return count;
    }

    // dp[mask] = max students up to previous row with `mask`
    let dp = new Map<number, number>();
    dp.set(0, 0);

    for (let r = 0; r < m; r++) {
        const nextDp = new Map<number, number>();
        const validMasks: number[] = [];

        for (let mask = 0; mask < (1 << n); mask++) {
            // Cannot sit in broken seats
            if ((mask & broken[r]) !== 0) continue;
            // No adjacent students in the same row
            if ((mask & (mask >> 1)) !== 0) continue;
            validMasks.push(mask);
        }

        for (const currMask of validMasks) {
            const students = countBits(currMask);
            let maxPrev = -1;

            for (const [prevMask, prevCount] of dp.entries()) {
                // Check upper-left and upper-right
                if ((currMask & (prevMask >> 1)) !== 0) continue;
                if ((currMask & (prevMask << 1)) !== 0) continue;

                if (prevCount > maxPrev) {
                    maxPrev = prevCount;
                }
            }

            if (maxPrev !== -1) {
                nextDp.set(currMask, maxPrev + students);
            }
        }

        dp = nextDp;
    }

    let ans = 0;
    for (const val of dp.values()) {
        if (val > ans) {
            ans = val;
        }
    }

    return ans;
};

function maxStudents(seats: string[][]): number {
    const m = seats.length;
    const n = seats[0].length;
    const N = 1 << n;
    const avail: number[] = new Array(m).fill(0);
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (seats[i][j] === '.') avail[i] |= (1 << j);
        }
    }
    const pop: number[] = new Array(N).fill(0);
    for (let i = 1; i < N; i++) {
        pop[i] = pop[i >> 1] + (i & 1);
    }
    let dp: number[] = new Array(N).fill(-Infinity);
    dp[0] = 0;
    for (let r = 0; r < m; r++) {
        const ndp: number[] = new Array(N).fill(-Infinity);
        for (let pmask = 0; pmask < N; pmask++) {
            if (dp[pmask] === -Infinity) continue;
            for (let mask = 0; mask < N; mask++) {
                if ((mask & ~avail[r]) !== 0) continue;
                if ((mask & (mask << 1)) !== 0) continue;
                if (((mask << 1) & pmask) !== 0 || ((mask >> 1) & pmask) !== 0) continue;
                ndp[mask] = Math.max(ndp[mask], dp[pmask] + pop[mask]);
            }
        }
        dp = ndp;
    }
    let ans = 0;
    for (let v of dp) ans = Math.max(ans, v);
    return ans;
}

function maxStudents(seats: string[][]): number {
    const m = seats.length;
    const n = seats[0].length;
    const full = 1 << n;

    // valid seat mask per row
    const rowMask: number[] = [];
    for (let i = 0; i < m; i++) {
        let mask = 0;
        for (let j = 0; j < n; j++) {
            if (seats[i][j].trim() === '.') mask |= (1 << j);
        }
        rowMask.push(mask);
    }

    const popcount = (x: number): number => {
        let c = 0;
        while (x) { x &= x - 1; c++; }
        return c;
    };

    // dp[mask] = max students up to current row with current row's mask
    let dp = new Array<number>(full).fill(-1);
    dp[0] = 0;

    for (let i = 0; i < m; i++) {
        const ndp = new Array<number>(full).fill(-1);
        for (let cur = 0; cur < full; cur++) {
            if ((cur & rowMask[i]) !== cur) continue;
            if (cur & (cur << 1)) continue;
            const cnt = popcount(cur);
            for (let prev = 0; prev < full; prev++) {
                if (dp[prev] < 0) continue;
                if (cur & (prev << 1)) continue;
                if (cur & (prev >> 1)) continue;
                const val = dp[prev] + cnt;
                if (val > ndp[cur]) ndp[cur] = val;
            }
        }
        dp = ndp;
    }

    let ans = 0;
    for (let mask = 0; mask < full; mask++) {
        if (dp[mask] > ans) ans = dp[mask];
    }
    return ans;
};

function maxStudents(seats: string[][]): number {
    const m = seats.length;
    const n = seats[0].length;
    const full = 1 << n;

    // Bitmask of available seats per row
    const valid: number[] = new Array(m).fill(0);
    for (let i = 0; i < m; i++) {
        let v = 0;
        for (let j = 0; j < n; j++) {
            if (seats[i][j] === '.') v |= 1 << j;
        }
        valid[i] = v;
    }

    const popcount = (x: number): number => {
        let c = 0;
        while (x) {
            x &= x - 1;
            c++;
        }
        return c;
    };

    // A row arrangement is valid if it only uses available seats
    // and no two students sit adjacent horizontally.
    const ok = (mask: number, row: number): boolean =>
        (mask & valid[row]) === mask && (mask & (mask << 1)) === 0;

    // dp[mask] = max students up to current row, current row arranged as `mask`
    let dp = new Array<number>(full).fill(-1);
    for (let mask = 0; mask < full; mask++) {
        if (ok(mask, 0)) dp[mask] = popcount(mask);
    }

    for (let i = 1; i < m; i++) {
        const ndp = new Array<number>(full).fill(-1);
        for (let mask = 0; mask < full; mask++) {
            if (!ok(mask, i)) continue;
            const cnt = popcount(mask);
            let best = -1;
            for (let p = 0; p < full; p++) {
                if (dp[p] < 0) continue;
                // No student in current row may sit diagonally (upper-left / upper-right)
                // to a student in previous row.
                if ((mask & (p << 1)) !== 0) continue;
                if ((mask & (p >> 1)) !== 0) continue;
                const val = dp[p] + cnt;
                if (val > best) best = val;
            }
            ndp[mask] = best;
        }
        dp = ndp;
    }

    let ans = 0;
    for (const v of dp) if (v > ans) ans = v;
    return ans;
}

