class Solution {
public:
    int maxStudents(vector<vector<char>>& seats) {
        int m = seats.size(), n = seats[0].size();
        int S = 1 << n;
        vector<int> dp(S, -1);
        dp[0] = 0;
        for (int i = 0; i < m; i++) {
            int bad = 0;
            for (int j = 0; j < n; j++) if (seats[i][j] == '#') bad |= (1 << j);
            vector<int> nd(S, -1);
            for (int cur = 0; cur < S; cur++) {
                if (cur & bad) continue;
                if (cur & (cur >> 1)) continue;
                int pc = __builtin_popcount(cur);
                for (int prev = 0; prev < S; prev++) {
                    if (dp[prev] < 0) continue;
                    if (cur & (prev << 1)) continue;
                    if (cur & (prev >> 1)) continue;
                    nd[cur] = max(nd[cur], dp[prev] + pc);
                }
            }
            dp = nd;
        }
        int ans = 0;
        for (int v : dp) ans = max(ans, v);
        return ans;
    }
};

class Solution {
public:
    int maxStudents(vector<vector<char>>& seats) {
        int m = seats.size();
        int n = seats[0].size();

        vector<int> valid_seats(m, 0);
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (seats[i][j] == '.') {
                    valid_seats[i] |= (1 << j);
                }
            }
        }

        int total_masks = 1 << n;
        vector<int> dp(total_masks, -1);
        dp[0] = 0; // Base state before row 0

        for (int r = 0; r < m; ++r) {
            vector<int> next_dp(total_masks, -1);

            for (int curr_mask = 0; curr_mask < total_masks; ++curr_mask) {
                // Must only sit in available seats
                if ((curr_mask & ~valid_seats[r]) != 0) continue;
                // No two students adjacent in the same row
                if ((curr_mask & (curr_mask << 1)) != 0) continue;

                int students_in_curr = __builtin_popcount(curr_mask);

                for (int prev_mask = 0; prev_mask < total_masks; ++prev_mask) {
                    if (dp[prev_mask] == -1) continue;
                    // No student in upper-left
                    if ((curr_mask & (prev_mask << 1)) != 0) continue;
                    // No student in upper-right
                    if ((curr_mask & (prev_mask >> 1)) != 0) continue;

                    next_dp[curr_mask] = max(next_dp[curr_mask], dp[prev_mask] + students_in_curr);
                }
            }
            dp = move(next_dp);
        }

        int ans = 0;
        for (int val : dp) {
            ans = max(ans, val);
        }
        return ans;
    }
};

class Solution {
    public int maxStudents(char[][] seats) {
        int rows = seats.length;
        int cols = seats[0].length;
        int limit = 1 << cols;

        int[] available = new int[rows];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (seats[r][c] == '.') {
                    available[r] |= 1 << c;
                }
            }
        }

        int[] previous = new int[limit];
        java.util.Arrays.fill(previous, -1);
        previous[0] = 0;

        for (int r = 0; r < rows; r++) {
            int[] current = new int[limit];
            java.util.Arrays.fill(current, -1);

            for (int mask = 0; mask < limit; mask++) {
                if ((mask & ~available[r]) != 0 || (mask & (mask << 1)) != 0) {
                    continue;
                }

                int students = Integer.bitCount(mask);

                for (int prevMask = 0; prevMask < limit; prevMask++) {
                    if (previous[prevMask] < 0) {
                        continue;
                    }
                    if ((mask & (prevMask << 1)) != 0
                            || (mask & (prevMask >> 1)) != 0) {
                        continue;
                    }

                    current[mask] = Math.max(
                            current[mask],
                            previous[prevMask] + students
                    );
                }
            }

            previous = current;
        }

        int answer = 0;
        for (int value : previous) {
            answer = Math.max(answer, value);
        }
        return answer;
    }
}

class Solution {
    public int maxStudents(char[][] seats) {
        int m = seats.length, n = seats[0].length;
        int maxMask = 1 << n;
        int[][] dp = new int[m][maxMask];
        for (int[] row : dp) java.util.Arrays.fill(row, -1);

        int[] validMasks = new int[m];
        for (int i = 0; i < m; i++) {
            int mask = 0;
            for (int j = 0; j < n; j++) {
                if (seats[i][j] == '.') mask |= 1 << j;
            }
            validMasks[i] = mask;
        }

        for (int mask = 0; mask < maxMask; mask++) {
            if ((mask & (mask << 1)) == 0 && (mask & ~validMasks[0]) == 0) {
                dp[0][mask] = Integer.bitCount(mask);
            }
        }

        for (int i = 1; i < m; i++) {
            for (int mask = 0; mask < maxMask; mask++) {
                if ((mask & (mask << 1)) != 0) continue;
                if ((mask & ~validMasks[i]) != 0) continue;
                int cnt = Integer.bitCount(mask);
                for (int pmask = 0; pmask < maxMask; pmask++) {
                    if (dp[i - 1][pmask] < 0) continue;
                    if ((mask & (pmask << 1)) != 0) continue;
                    if ((mask & (pmask >> 1)) != 0) continue;
                    dp[i][mask] = Math.max(dp[i][mask], dp[i - 1][pmask] + cnt);
                }
            }
        }

        int ans = 0;
        for (int mask = 0; mask < maxMask; mask++) ans = Math.max(ans, dp[m - 1][mask]);
        return ans;
    }
}

class Solution {
    public int maxStudents(char[][] seats) {
        int m = seats.length;
        int n = seats[0].length;
        int totalMasks = 1 << n;

        int[] available = new int[m];
        for (int i = 0; i < m; i++) {
            int mask = 0;
            for (int j = 0; j < n; j++) {
                if (seats[i][j] == '.') {
                    mask |= 1 << j;
                }
            }
            available[i] = mask;
        }

        int[] count = new int[totalMasks];
        for (int mask = 0; mask < totalMasks; mask++) {
            count[mask] = Integer.bitCount(mask);
        }

        int[] prev = new int[totalMasks];
        int[] curr = new int[totalMasks];
        java.util.Arrays.fill(prev, -1);
        prev[0] = 0;

        for (int row = 0; row < m; row++) {
            java.util.Arrays.fill(curr, -1);

            for (int mask = 0; mask < totalMasks; mask++) {
                if ((mask & ~available[row]) != 0) {
                    continue;
                }
                if ((mask & (mask << 1)) != 0) {
                    continue;
                }

                for (int prevMask = 0; prevMask < totalMasks; prevMask++) {
                    if (prev[prevMask] == -1) {
                        continue;
                    }
                    if ((mask & (prevMask << 1)) != 0) {
                        continue;
                    }
                    if ((mask & (prevMask >> 1)) != 0) {
                        continue;
                    }

                    curr[mask] = Math.max(curr[mask], prev[prevMask] + count[mask]);
                }
            }

            int[] temp = prev;
            prev = curr;
            curr = temp;
        }

        int answer = 0;
        for (int value : prev) {
            answer = Math.max(answer, value);
