class Solution {
    public int maxStudents(char[][] seats) {
        int m = seats.length;
        int n = seats[0].length;
        int full = 1 << n;

        int[] avail = new int[m];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (seats[i][j] == '.') {
                    avail[i] |= (1 << j);
                }
            }
        }

        int[] dp = new int[full];
        for (int i = 0; i < m; i++) {
            int[] ndp = new int[full];
            for (int mask = 0; mask < full; mask++) {
                if ((mask & ~avail[i]) != 0 || (mask & (mask << 1)) != 0) {
                    ndp[mask] = -1;
                    continue;
                }
                int bits = Integer.bitCount(mask);
                if (i == 0) {
                    ndp[mask] = bits;
                } else {
                    int best = -1;
                    for (int prev = 0; prev < full; prev++) {
                        if (dp[prev] < 0) continue;
                        if ((mask & (prev << 1)) != 0 || (mask & (prev >> 1)) != 0) continue;
                        if (dp[prev] > best) best = dp[prev];
                    }
                    ndp[mask] = best >= 0 ? best + bits : -1;
                }
            }
            dp = ndp;
        }

        int ans = 0;
        for (int v : dp) {
            if (v > ans) ans = v;
        }
        return ans;
    }
}

class Solution {
    public int maxStudents(char[][] seats) {
        int m = seats.length, n = seats[0].length;
        int[] valid = new int[m];
        for (int i = 0; i < m; i++) {
            int mask = 0;
            for (int j = 0; j < n; j++) {
                if (seats[i][j] == '.') mask |= (1 << j);
            }
            valid[i] = mask;
        }
        int full = 1 << n;
        int[] prev = new int[full];
        for (int i = 0; i < full; i++) prev[i] = -1;
        prev[0] = 0;
        for (int i = 0; i < m; i++) {
            int[] cur = new int[full];
            for (int j = 0; j < full; j++) cur[j] = -1;
            for (int state = 0; state < full; state++) {
                // valid seating
                if ((state & valid[i]) != state) continue;
                if ((state & (state << 1)) != 0) continue;
                for (int p = 0; p < full; p++) {
                    if (prev[p] < 0) continue;
                    if ((state & (p << 1)) != 0) continue;
                    if ((state & (p >> 1)) != 0) continue;
                    int cnt = prev[p] + Integer.bitCount(state);
                    if (cnt > cur[state]) cur[state] = cnt;
                }
            }
            prev = cur;
        }
        int ans = 0;
        for (int j = 0; j < full; j++) ans = Math.max(ans, prev[j]);
        return ans;
    }
}

