import java.util.Arrays;

class Solution {
    public int maxStudents(char[][] seats) {
        int m = seats.length;
        int n = seats[0].length;
        int N = 1 << n;

        int[] pop = new int[N];
        for (int mask = 1; mask < N; mask++) {
            pop[mask] = pop[mask >> 1] + (mask & 1);
        }

        int[] available = new int[m];
        for (int i = 0; i < m; i++) {
            int rowMask = 0;
            for (int j = 0; j < n; j++) {
                if (seats[i][j] == '.') {
                    rowMask |= 1 << j;
                }
            }
            available[i] = rowMask;
        }

        int[] dp = new int[N];
        Arrays.fill(dp, -1);

        for (int mask = 0; mask < N; mask++) {
            if ((mask & ~available[0]) == 0 && (mask & (mask << 1)) == 0) {
                dp[mask] = pop[mask];
            }
        }

        for (int r = 1; r < m; r++) {
            int[] next = new int[N];
            Arrays.fill(next, -1);

            for (int cur = 0; cur < N; cur++) {
                if ((cur & ~available[r]) != 0) continue;
                if ((cur & (cur << 1)) != 0) continue;

                int best = -1;
                for (int prev = 0; prev < N; prev++) {
                    if (dp[prev] == -1) continue;
                    if (((cur << 1) & prev) == 0 && ((cur >> 1) & prev) == 0) {
                        best = Math.max(best, dp[prev] + pop[cur]);
                    }
                }
                next[cur] = best;
            }

            dp = next;
        }

        int answer = 0;
        for (int value : dp) {
            answer = Math.max(answer, value);
        }
        return answer;
    }
}

class Solution {
    public int maxStudents(char[][] seats) {
        int m = seats.length;
        int n = seats[0].length;
        int[][] dp = new int[m + 1][1 << n];
        for (int i = 0; i <= m; i++) {
            for (int j = 0; j < (1 << n); j++) {
                dp[i][j] = -1;
            }
        }
        dp[0][0] = 0;
        for (int i = 1; i <= m; i++) {
            char[] row = seats[i - 1];
            for (int prev = 0; prev < (1 << n); prev++) {
                if (dp[i - 1][prev] == -1) continue;
                for (int curr = 0; curr < (1 << n); curr++) {
                    if ((curr & (curr << 1)) != 0) continue;
                    boolean ok = true;
                    for (int j = 0; j < n; j++) {
                        if ((curr & (1 << j)) != 0 && row[j] == '#') {
                            ok = false;
                            break;
                        }
                    }
                    if (!ok) continue;
                    if ((curr & (prev << 1)) != 0 || (curr & (prev >> 1)) != 0) continue;
                    dp[i][curr] = Math.max(dp[i][curr], dp[i - 1][prev] + Integer.bitCount(curr));
                }
            }
        }
        int ans = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            ans = Math.max(ans, dp[m][mask]);
        }
        return ans;
    }
}

