import java.util.Arrays;

class Solution {
    public int maxStudents(char[][] seats) {
        int m = seats.length;
        int n = seats[0].length;

        int[] broken = new int[m];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (seats[i][j] == '#') {
                    broken[i] |= (1 << j);
                }
            }
        }

        int states = 1 << n;
        int[] dp = new int[states];
        Arrays.fill(dp, -1);
        dp[0] = 0;

        for (int i = 0; i < m; i++) {
            int[] nextDp = new int[states];
            Arrays.fill(nextDp, -1);

            for (int mask = 0; mask < states; mask++) {
                // Check if mask has adjacent students
                if ((mask & (mask >> 1)) != 0) continue;
                // Check if mask uses broken seats
                if ((mask & broken[i]) != 0) continue;

                int count = Integer.bitCount(mask);

                for (int prevMask = 0; prevMask < states; prevMask++) {
                    if (dp[prevMask] == -1) continue;
                    // Check upper-left and upper-right
                    if ((mask & (prevMask >> 1)) != 0) continue;
                    if ((mask & (prevMask << 1)) != 0) continue;

                    nextDp[mask] = Math.max(nextDp[mask], dp[prevMask] + count);
                }
            }

            dp = nextDp;
        }

        int maxStudents = 0;
        for (int val : dp) {
            maxStudents = Math.max(maxStudents, val);
        }

        return maxStudents;
    }
}

/**
 * @param {number[]} nums
 * @param {number} firstLen
 * @param {number} secondLen
 * @return {number}
 */
var maxSumTwoNoOverlap = function(nums, firstLen, secondLen) {
    const n = nums.length;

    // prefix[i] = sum of nums[0..i-1]
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + nums[i];
    }

    // Best total when an L-length subarray lies entirely before an S-length subarray.
    const bestWithOrder = (L, S) => {
        // maxLeft[i]: best sum of an L-length subarray within nums[0..i-1]
        const maxLeft = new Array(n + 1).fill(-Infinity);
        for (let i = L; i <= n; i++) {
            maxLeft[i] = Math.max(maxLeft[i - 1], prefix[i] - prefix[i - L]);
        }
        // maxRight[i]: best sum of an S-length subarray within nums[i..n-1]
        const maxRight = new Array(n + 1).fill(-Infinity);
        for (let i = n - S; i >= 0; i--) {
            maxRight[i] = Math.max(maxRight[i + 1], prefix[i + S] - prefix[i]);
        }
        // Split point i: L-subarray in nums[0..i-1], S-subarray in nums[i..n-1]
        let best = -Infinity;
        for (let i = L; i <= n - S; i++) {
            best = Math.max(best, maxLeft[i] + maxRight[i]);
        }
        return best;
    };

    return Math.max(
        bestWithOrder(firstLen, secondLen),
        bestWithOrder(secondLen, firstLen)
    );
};

/**
 * @param {number[]} nums
 * @param {number} firstLen
 * @param {number} secondLen
 * @return {number}
 */
var maxSumTwoNoOverlap = function(nums, firstLen, secondLen) {
    const n = nums.length;
    const P = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];
    const f = (L, M) => {
        let maxL = 0, res = 0;
        for (let i = L + M; i <= n; i++) {
            maxL = Math.max(maxL, P[i - M] - P[i - M - L]);
            res = Math.max(res, maxL + P[i] - P[i - M]);
        }
        return res;
    };
    return Math.max(f(firstLen, secondLen), f(secondLen, firstLen));
};

/**
 * @param {number[]} nums
 * @param {number} firstLen
 * @param {number} secondLen
 * @return {number}
 */
var maxSumTwoNoOverlap = function(nums, firstLen, secondLen) {
    const n = nums.length;
    const pref = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        pref[i + 1] = pref[i] + nums[i];
    }

    const helper = (L, M) => {
        let maxL = 0;
        let ans = 0;
        for (let i = L + M; i <= n; i++) {
            maxL = Math.max(maxL, pref[i - M] - pref[i - M - L]);
            ans = Math.max(ans, maxL + (pref[i] - pref[i - M]));
        }
