class Solution {
public:
    int maxSumTwoNoOverlap(vector<int>& nums, int firstLen, int secondLen) {
        int n = nums.size();
        vector<int> prefix(n + 1, 0);
        for (int i = 0; i < n; ++i) prefix[i + 1] = prefix[i] + nums[i];

        // leftMax[j] = max sum of a subarray of length secondLen ending at index <= j
        vector<int> leftMax(n, INT_MIN);
        for (int j = 0; j < n; ++j) {
            if (j >= secondLen - 1)
                leftMax[j] = prefix[j + 1] - prefix[j + 1 - secondLen];
            if (j > 0)
                leftMax[j] = max(leftMax[j], leftMax[j - 1]);
        }

        // rightMax[j] = max sum of a subarray of length secondLen starting at index >= j
        vector<int> rightMax(n, INT_MIN);
        for (int j = n - 1; j >= 0; --j) {
            if (j + secondLen <= n)
                rightMax[j] = prefix[j + secondLen] - prefix[j];
            if (j + 1 < n)
                rightMax[j] = max(rightMax[j], rightMax[j + 1]);
        }

        int ans = INT_MIN;
        for (int i = firstLen - 1; i < n; ++i) {
            int s1 = prefix[i + 1] - prefix[i + 1 - firstLen];
            // secondLen subarray entirely to the left of [i-firstLen+1, i]
            if (i - firstLen >= secondLen - 1)
                ans = max(ans, s1 + leftMax[i - firstLen]);
            // secondLen subarray entirely to the right of [i-firstLen+1, i]
            if (i + 1 + secondLen <= n)
                ans = max(ans, s1 + rightMax[i + 1]);
        }
        return ans;
    }
};

