            pref[i + 1] = pref[i] + nums[i];
        }

        auto helper = [&](int L, int M) {
            int maxL = 0;
            int ans = 0;
            for (int i = L + M; i <= n; ++i) {
                maxL = max(maxL, pref[i - M] - pref[i - M - L]);
                ans = max(ans, maxL + pref[i] - pref[i - M]);
            }
            return ans;
        };

        return max(helper(firstLen, secondLen), helper(secondLen, firstLen));
    }
};

