                        maxSumOrdered(nums, secondLen, firstLen));
    }

    // Maximum sum where a subarray of length lenA comes entirely before
    // a subarray of length lenB (both non-overlapping).
    private int maxSumOrdered(int[] nums, int lenA, int lenB) {
        int n = nums.length;
        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        int ans = 0;
        int bestA = 0; // best sum of a lenA subarray ending at index <= i - lenB
        for (int i = lenA + lenB - 1; i < n; i++) {
            // lenA subarray ending exactly at index i - lenB: [i - lenB - lenA + 1, i - lenB]
            bestA = Math.max(bestA, prefix[i - lenB + 1] - prefix[i - lenB - lenA + 1]);
            // lenB subarray ending at index i: [i - lenB + 1, i]
            int sumB = prefix[i + 1] - prefix[i - lenB + 1];
            ans = Math.max(ans, bestA + sumB);
        }
        return ans;
    }
}

