/**
 * @param {number[]} flowers
 * @param {number} newFlowers
 * @param {number} target
 * @param {number} full
 * @param {number} partial
 * @return {number}
 */
var maximumBeauty = function(flowers, newFlowers, target, full, partial) {
    const n = flowers.length;
    // Cap flowers at target
    let arr = flowers.map(f => Math.min(f, target));
    arr.sort((a, b) => a - b);

    let inc = [];
    let c0 = 0;
    for (let f of arr) {
        if (f < target) inc.push(f);
        else c0++;
    }

    // If all gardens are already complete
    if (inc.length === 0) {
        return n * full;
    }

    const m = inc.length;
    const pref = new Array(m + 1).fill(0);
    for (let i = 0; i < m; i++) {
        pref[i + 1] = pref[i] + inc[i];
    }

    // Precompute countLess[x] = number of elements in inc < x
    const countLess = new Array(target + 1).fill(0);
    let idx = 0;
    for (let x = 0; x <= target; x++) {
        while (idx < m && inc[idx] < x) idx++;
        countLess[x] = idx;
    }

    let ans = 0;
    let cost = 0;

    // Helper to find maximum possible minimum for first cnt incomplete gardens with rem flowers
    function maxMin(cnt, rem) {
        if (cnt === 0) return 0;
        let low = 0, high = target - 1;
        while (low < high) {
            let mid = Math.floor((low + high + 1) / 2);
            let p = Math.min(cnt, countLess[mid]);
            let c = mid * p - pref[p];
            if (c <= rem) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }

    // Try completing k largest incomplete gardens
    for (let k = 0; k <= m; k++) {
        if (k > 0) {
            cost += target - inc[m - k];
        }
        if (cost > newFlowers) break;
        let rem = newFlowers - cost;
        let cnt = m - k;
        let minVal = maxMin(cnt, rem);
        let beauty = (c0 + k) * full + minVal * partial;
        if (beauty > ans) ans = beauty;
    }

    return ans;
};

/**
 * @param {number[]} flowers
 * @param {number} newFlowers
 * @param {number} target
 * @param {number} full
 * @param {number} partial
 * @return {number}
 */
var maximumBeauty = function(flowers, newFlowers, target, full, partial) {
    const n = flowers.length;
    const f = new Float64Array(n);
    for (let i = 0; i < n; i++) f[i] = Math.min(flowers[i], target);
    f.sort();
    if (f[0] === target) return n * full;
    const pre = new Float64Array(n + 1);
    for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + f[i];
    let cnt = 0;
    while (cnt < n && f[n - 1 - cnt] === target) cnt++;
    let best = 0;
    let cost = 0;
    let p = n - cnt;
    for (let i = n - cnt; i >= 0; i--) {
        if (i < n - cnt) {
            cost += target - f[i];
        }
        if (cost > newFlowers) break;
        if (i === 0) {
            best = Math.max(best, n * full);
            break;
        }
        const rem = newFlowers - cost;
        if (p > i) p = i;
        while (p > 1 && f[p - 1] * p - pre[p] > rem) p--;
        const level = Math.min(target - 1, Math.floor((rem + pre[p]) / p));
        best = Math.max(best, (n - i) * full + level * partial);
    }
    return best;
};

/**
 * @param {number[]} flowers
 * @param {number} newFlowers
 * @param {number} target
 * @param {number} full
 * @param {number} partial
 * @return {number}
 */
var maximumBeauty = function(flowers, newFlowers, target, full, partial) {
    const arr = [];
    let alreadyFull = 0;

    for (const f of flowers) {
        if (f >= target) alreadyFull++;
        else arr.push(f);
    }

    const m = arr.length;
    if (m === 0) return alreadyFull * full;

    arr.sort((a, b) => a - b);

    const prefix = new Array(m + 1).fill(0);
    for (let i = 0; i < m; i++) {
        prefix[i + 1] = prefix[i] + arr[i];
    }

    const upperBound = (right, value) => {
        let left = 0;
        while (left < right) {
            const mid = (left + right) >> 1;
            if (arr[mid] <= value) left = mid + 1;
            else right = mid;
        }
        return left;
    };

    const bestPartial = (len, budget) => {
        let left = arr[0];
        let right = target - 1;
        let ans = arr[0];

        while (left <= right) {
            const mid = Math.floor((left + right) / 2);
            const count = upperBound(len, mid);
            const cost = mid * count - prefix[count];

            if (cost <= budget) {
                ans = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return ans;
    };

    let answer = 0;

    for (let madeFull = 0; madeFull <= m; madeFull++) {
        const suffixSum = prefix[m] - prefix[m - madeFull];
        const costToFull = madeFull * target - suffixSum;

        if (costToFull > newFlowers) break;

        const remaining = newFlowers - costToFull;
        const incompleteCount = m - madeFull;

        let beauty = (alreadyFull + madeFull) * full;

        if (incompleteCount > 0) {
            beauty += bestPartial(incompleteCount, remaining) * partial;
        }

        answer = Math.max(answer, beauty);
    }

    return answer;
};

/**
 * @param {number[]} flowers
 * @param {number} newFlowers
 * @param {number} target
 * @param {number} full
 * @param {number} partial
 * @return {number}
 */
var maximumBeauty = function(flowers, newFlowers, target, full, partial) {
    const n = flowers.length;
    const f = flowers.slice().sort((a, b) => b - a); // descending

    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + f[i];
    const totalSum = prefix[n];

    // t = number of gardens already complete
    let t = 0;
    while (t < n && f[t] >= target) t++;

    // cntGe[L] = count of gardens with value >= L
    const size = Math.max(f[0], target) + 2;
    const cnt = new Array(size).fill(0);
    for (let i = 0; i < n; i++) cnt[f[i]]++;
    const cntGe = new Array(size).fill(0);
    for (let v = size - 2; v >= 0; v--) cntGe[v] = cntGe[v + 1] + cnt[v];

    let ans = 0;

    for (let k = t; k <= n; k++) {
        // cost to bring top k gardens to target (indices t..k-1 need planting)
        const costK = (k - t) * target - (prefix[k] - prefix[t]);
        if (costK > newFlowers) break; // costK is non-decreasing in k
        const rem = newFlowers - costK;

        if (k === n) {
            if (n * full > ans) ans = n * full;
            break;
        }

        // maximize L in [0, target-1] with cost to raise f[k..n-1] to L <= rem
        let lo = 0, hi = target - 1, best = 0;
        while (lo <= hi) {
            const L = (lo + hi) >> 1;
            let j = cntGe[L]; // first global index with f[j] < L
            if (j < k) j = k;
            const cost = (n - j) * L - (totalSum - prefix[j]);
            if (cost <= rem) {
                best = L;
                lo = L + 1;
            } else {
                hi = L - 1;
            }
        }

        const beauty = k * full + best * partial;
        if (beauty > ans) ans = beauty;
    }

    return ans;
};

/**
 * @param {number[]} flowers
 * @param {number} newFlowers
 * @param {number} target
 * @param {number} full
 * @param {number} partial
 * @return {number}
 */
var maximumBeauty = function(flowers, newFlowers, target, full, partial) {
    const n = flowers.length;
    const fl = flowers.map(f => Math.min(f, target)).sort((a, b) => a - b);
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + fl[i];
    }
    let p = n;
    for (let i = 0; i < n; i++) {
        if (fl[i] === target) {
            p = i;
            break;
        }
    }
    let ans = 0;
    for (let m = 0; m <= p; m++) {
        const cost = (n - m) * target - (prefix[n] - prefix[m]);
        if (cost > newFlowers) continue;
        const rem = newFlowers - cost;
        if (m === 0) {
            ans = Math.max(ans, n * full);
            continue;
        }
        let lo = 0, hi = target - 1, bestx = 0;
        while (lo <= hi) {
            const mid = Math.floor((lo + hi) / 2);
            let l = 0, r = m;
            while (l < r) {
                const md = Math.floor((l + r) / 2);
                if (fl[md] < mid) l = md + 1;
                else r = md;
            }
            const pos = l;
            const cst = mid * pos - prefix[pos];
            if (cst <= rem) {
                bestx = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        ans = Math.max(ans, (n - m) * full + bestx * partial);
    }
    return ans;
};

function maximumBeauty(flowers: number[], newFlowers: number, target: number, full: number, partial: number): number {
    const n = flowers.length;
    const a = flowers.map(v => Math.min(v, target)).sort((x, y) => x - y);
    const prefix: number[] = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + a[i];
    const total = prefix[n];
    let best = 0;
    // i = number of incomplete gardens (prefix of length i)
    for (let i = 0; i <= n; i++) {
        if (i > 0 && a[i - 1] >= target) break;
        // cost to complete gardens i..n-1
        const cost = (n - i) * target - (total - prefix[i]);
        if (cost > newFlowers) continue;
        const remaining = newFlowers - cost;
        if (i === 0) {
            best = Math.max(best, n * full);
            continue;
        }
        // find largest p in [1, i] with a[p-1]*p - prefix[p] <= remaining
        let lo = 1, hi = i;
        while (lo < hi) {
            const mid = (lo + hi + 1) >> 1;
            const c = a[mid - 1] * mid - prefix[mid];
            if (c <= remaining) lo = mid; else hi = mid - 1;
        }
        const p = lo;
        const m = Math.min(target - 1, Math.floor((remaining + prefix[p]) / p));
        const beauty = (n - i) * full + m * partial;
        if (beauty > best) best = beauty;
    }
    return best;
};

function maximumBeauty(flowers: number[], newFlowers: number, target: number, full: number, partial: number): number {
    const n = flowers.length;
    flowers.sort((a, b) => a - b);

    let below = 0;
    while (below < n && flowers[below] < target) {
        below++;
    }

    const already = n - below;
    const m = below;
    const pref = new Array(m + 1).fill(0);

    for (let i = 0; i < m; i++) {
        pref[i + 1] = pref[i] + flowers[i];
    }

    let ans = 0;

    for (let c = 0; c <= m; c++) {
        const i = m - c;
        const sumSuffix = pref[m] - pref[i];
        const costComplete = c * target - sumSuffix;

        if (costComplete > newFlowers) {
            break;
        }

        const remaining = newFlowers - costComplete;
        const completeTotal = already + c;

        if (i === 0) {
            ans = Math.max(ans, completeTotal * full);
        } else {
            let lo = 0;
            let hi = target - 1;
            let best = 0;

            while (lo <= hi) {
                const mid = Math.floor((lo + hi) / 2);

                let left = 0;
                let right = i;
                while (left < right) {
                    const mid2 = Math.floor((left + right) / 2);
                    if (flowers[mid2] < mid) {
                        left = mid2 + 1;
                    } else {
                        right = mid2;
                    }
                }

                const p = left;
                const cost = mid * p - pref[p];

                if (cost <= remaining) {
                    best = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }

            ans = Math.max(ans, completeTotal * full + best * partial);
        }
    }

    return ans;
}

function maximumBeauty(flowers: number[], newFlowers: number, target: number, full: number, partial: number): number {
    flowers.sort((a, b) => a - b);

    let incompleteCount = 0;
    while (incompleteCount < flowers.length && flowers[incompleteCount] < target) {
        incompleteCount++;
    }

    const prefix: number[] = new Array(incompleteCount + 1).fill(0);
    for (let i = 0; i < incompleteCount; i++) {
        prefix[i + 1] = prefix[i] + flowers[i];
    }

    let answer = 0;
    let completionCost = 0;

    for (let completed = 0; completed <= incompleteCount; completed++) {
        if (completionCost > newFlowers) break;

        const remaining = incompleteCount - completed;
        let beauty = (flowers.length - remaining) * full;

        if (remaining > 0) {
            const budget = newFlowers - completionCost;

            let left = 0;
            let right = remaining - 1;
            let index = 0;

            while (left <= right) {
                const mid = Math.floor((left + right) / 2);
                const cost = flowers[mid] * (mid + 1) - prefix[mid + 1];

                if (cost <= budget) {
                    index = mid;
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }

            const levelingCost =
                flowers[index] * (index + 1) - prefix[index + 1];

            const minimum = Math.min(
                target - 1,
                flowers[index] +
                    Math.floor((budget - levelingCost) / (index + 1))
            );

            beauty += minimum * partial;
        }

        answer = Math.max(answer, beauty);

        if (completed < incompleteCount) {
            completionCost += target - flowers[incompleteCount - 1 - completed];
        }
    }

    return answer;
}

function maximumBeauty(flowers: number[], newFlowers: number, target: number, full: number, partial: number): number {
    const n = flowers.length;
    const f = flowers.slice().sort((a, b) => a - b);

    // prefix sums of sorted values
    const pre: number[] = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + f[i];

    // suf[i] = flowers needed to bring gardens i..n-1 up to target
    const suf: number[] = new Array(n + 1).fill(0);
    for (let i = n - 1; i >= 0; i--) {
        const need = target - f[i];
        suf[i] = suf[i + 1] + (need > 0 ? need : 0);
    }

    // gardens with value < target occupy positions [0, lo)
    let lo = 0;
    while (lo < n && f[lo] < target) lo++;

    // lbArr[v] = number of gardens with value < v (for v in [0, target-1])
    const lbArr = new Int32Array(target);
    let ptr = 0;
    for (let v = 0; v < target; v++) {
        while (ptr < n && f[ptr] < v) ptr++;
        lbArr[v] = ptr;
    }

    // cost to raise the minimum of the first m gardens to value v
    const raiseCost = (m: number, v: number): number => {
        const p = Math.min(lbArr[v], m);
        return v * p - pre[p];
    };

    let ans = 0;

    // k = number of complete gardens (the k largest ones); k >= n - lo is required,
    // since gardens already >= target are always complete
    for (let k = n - lo; k <= n; k++) {
        const cost = suf[n - k];
        if (cost > newFlowers) break; // completing more gardens only costs more
        if (k === n) {
            // all gardens complete -> no incomplete minimum
            if (n * full > ans) ans = n * full;
            continue;
        }
        const m = n - k;
        const budget = newFlowers - cost;
        // maximize the minimum of the first m gardens, capped at target - 1
        let l = f[0];
        let r = target - 1;
        while (l < r) {
            const mid = (l + r + 1) >> 1;
            if (raiseCost(m, mid) <= budget) l = mid;
            else r = mid - 1;
        }
        const cand = k * full + l * partial;
        if (cand > ans) ans = cand;
    }

    return ans;
}

function maximumBeauty(flowers: number[], newFlowers: number, target: number, full: number, partial: number): number {
    const n = flowers.length;
    flowers.sort((a, b) => a - b);

    for (let i = 0; i < n; i++) {
        if (flowers[i] > target) {
            flowers[i] = target;
        }
    }

    const pref = new Float64Array(n + 1);
    for (let i = 0; i < n; i++) {
        pref[i + 1] = pref[i] + flowers[i];
    }

    let count = 0;
    while (count < n && flowers[count] < target) {
        count++;
    }

    let maxBeauty = 0;

    for (let m = 0; m <= count; m++) {
        const costComplete = (n - m) * target - (pref[n] - pref[m]);
        if (costComplete > newFlowers) {
            continue;
        }

        if (m === 0) {
            const beauty = n * full;
            if (beauty > maxBeauty) {
                maxBeauty = beauty;
            }
            continue;
        }

        const rem = newFlowers - costComplete;

        let low = 0;
        let high = m - 1;
        while (low < high) {
            const mid = (low + high + 1) >> 1;
            const cost = (mid + 1) * flowers[mid] - pref[mid + 1];
            if (cost <= rem) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }

        const p = low;
        const costP = (p + 1) * flowers[p] - pref[p + 1];
        const extra = Math.floor((rem - costP) / (p + 1));
        const v = Math.min(target - 1, flowers[p] + extra);

        const beauty = (n - m) * full + v * partial;
        if (beauty > maxBeauty) {
            maxBeauty = beauty;
        }
    }

    return maxBeauty;
}

function maximumBeauty(flowers: number[], newFlowers: number, target: number, full: number, partial: number): number {
    const n = flowers.length;
    const f = flowers.map(x => Math.min(x, target)).sort((a, b) => a - b);
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + f[i];
    let numComplete = 0;
    for (let i = n - 1; i >= 0 && f[i] === target; i--) numComplete++;
    let best = 0;
    let r = newFlowers;
    for (let k = numComplete; k <= n; k++) {
        if (k > numComplete) {
            r -= target - f[n - k];
        }
        if (r < 0) break;
        const m = n - k;
        if (m === 0) {
            best = Math.max(best, n * full);
            continue;
        }
        let lo = 1, hi = m;
        while (lo < hi) {
            const mid = (lo + hi + 1) >> 1;
            const cost = f[mid - 1] * mid - prefix[mid];
            if (cost <= r) lo = mid; else hi = mid - 1;
        }
        const j = lo;
        const val = Math.min(target - 1, Math.floor((prefix[j] + r) / j));
        best = Math.max(best, k * full + val * partial);
    }
    return best;
};

function maximumBeauty(flowers: number[], newFlowers: number, target: number, full: number, partial: number): number {
    const n = flowers.length;
    const arr = flowers.map(value => Math.min(value, target));
    arr.sort((a, b) => a - b);

    const prefix = new Array<number>(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + arr[i];
    }

    let baseComplete = 0;
    while (baseComplete < n && arr[baseComplete] >= target) {
        baseComplete++;
    }

    const getPartialLevel = (count: number, budget: number): number => {
        let low = 0;
        let high = target - 1;

        while (low <= high) {
            const level = Math.floor((low + high) / 2);

            let left = 0;
            let right = count;
            while (left < right) {
                const mid = Math.floor((left + right) / 2);
                if (arr[mid] <= level) {
                    left = mid + 1;
                } else {
                    right = mid;
                }
            }

            const needed = level * left - prefix[left];

            if (needed <= budget) {
                low = level + 1;
            } else {
                high = level - 1;
            }
        }

        return high;
    };

    let answer = 0;
    let completeCost = 0;

    for (let complete = baseComplete; complete <= n; complete++) {
        if (complete > baseComplete) {
            completeCost += target - arr[n - complete];
        }

        if (completeCost > newFlowers) {
            break;
        }

        const incomplete = n - complete;
        let beauty = complete * full;

        if (incomplete > 0) {
            const level = getPartialLevel(incomplete, newFlowers - completeCost);
            beauty += level * partial;
        }

        answer = Math.max(answer, beauty);
    }

    return answer;
}

function maximumBeauty(flowers: number[], newFlowers: number, target: number, full: number, partial: number): number {
    const incomplete: number[] = [];
    let alreadyFull = 0;

    for (const f of flowers) {
        if (f >= target) alreadyFull++;
        else incomplete.push(f);
    }

    incomplete.sort((a, b) => a - b);

    const m = incomplete.length;
    const prefix: number[] = new Array(m + 1).fill(0);

    for (let i = 0; i < m; i++) {
        prefix[i + 1] = prefix[i] + incomplete[i];
    }

    const lowerBound = (len: number, value: number): number => {
        let left = 0;
        let right = len;

        while (left < right) {
            const mid = Math.floor((left + right) / 2);
            if (incomplete[mid] < value) left = mid + 1;
            else right = mid;
        }

        return left;
    };

    const getBestPartial = (len: number, budget: number): number => {
        if (len === 0) return 0;

        let left = 0;
        let right = target - 1;
        let best = 0;

        while (left <= right) {
            const mid = Math.floor((left + right) / 2);
            const idx = lowerBound(len, mid);
            const cost = mid * idx - prefix[idx];

            if (cost <= budget) {
                best = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return best;
    };

    let answer = 0;
    let completeCost = 0;

    for (let madeFull = 0; madeFull <= m; madeFull++) {
        if (completeCost > newFlowers) break;

        const remainingIncomplete = m - madeFull;
        const remainingFlowers = newFlowers - completeCost;

        const partialValue = getBestPartial(remainingIncomplete, remainingFlowers);
        const beauty = (alreadyFull + madeFull) * full + partialValue * partial;

        answer = Math.max(answer, beauty);

        if (madeFull < m) {
            completeCost += target - incomplete[m - 1 - madeFull];
        }
    }

    return answer;
};

function maximumBeauty(flowers: number[], newFlowers: number, target: number, full: number, partial: number): number {
    flowers.sort((a, b) => a - b);

    const n = flowers.length;
    let incomplete = n;
    while (incomplete > 0 && flowers[incomplete - 1] >= target) {
        incomplete--;
    }

    const prefix = new Array<number>(incomplete + 1).fill(0);
    for (let i = 0; i < incomplete; i++) {
        prefix[i + 1] = prefix[i] + flowers[i];
    }

    let remaining = newFlowers;
    let answer = 0;

    // Complete the largest incomplete gardens first.
    for (let count = incomplete; count >= 0; count--) {
        if (remaining < 0) break;

        if (count === 0) {
            answer = Math.max(answer, n * full);
            break;
        }

        // Find the largest prefix that can be raised to its largest value.
        let low = 1;
        let high = count;
        while (low < high) {
            const mid = Math.floor((low + high + 1) / 2);
            const cost = flowers[mid - 1] * mid - prefix[mid];

            if (cost <= remaining) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }

        const minimum = Math.min(
            target - 1,
            Math.floor((remaining + prefix[low]) / low)
        );

        answer = Math.max(
            answer,
            (n - count) * full + minimum * partial
        );

        remaining -= target - flowers[count - 1];
    }

    return answer;
};

function maximumBeauty(flowers: number[], newFlowers: number, target: number, full: number, partial: number): number {
    const n = flowers.length;
    const f = flowers.map(x => Math.min(x, target));
    f.sort((a, b) => a - b);

    // prefix sums
    const prefix: number[] = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + f[i];

    // cost to make gardens [i..n-1] complete (each raised to target)
    // costComplete[i] = sum over j>=i of (target - f[j])
    const totalSum = prefix[n];

    let ans = 0;

    // helper: given first m gardens (indices 0..m-1) and budget b,
    // find max possible minimum among them (capped below target)
    // f sorted ascending. Use two-pointer over budget as m increases? 
    // We'll iterate k from n down to 0. Let complete count = n - k where we complete suffix.
    // Actually let numComplete go from 0 to n. Complete the last numComplete gardens.

    // Precompute for prefix of length m, function to get best min given budget.
    // We'll do it with a pointer that only moves forward as budget grows... but budget changes non-monotonically.
    // Instead, for each split point, binary search the min value.

    // Cost to raise prefix [0..m-1] all to at least value v (v <= target):
    // find index j = first position with f[j] >= v, then cost = v*j - prefix[j]
    // We can binary search v.

    // suffix complete cost
    // costToComplete of gardens from index i (all to target)
    const costComplete: number[] = new Array(n + 1).fill(0);
    for (let i = n - 1; i >= 0; i--) {
        costComplete[i] = costComplete[i + 1] + (target - f[i]);
    }

    // If all gardens already complete
    // numComplete = number of complete gardens; we complete gardens from index (n - numComplete) to n-1
    for (let numComplete = 0; numComplete <= n; numComplete++) {
        const startComplete = n - numComplete;
        const cost = costComplete[startComplete];
        if (cost > newFlowers) continue; // can't complete these
        // but the gardens we're completing must not already be complete requirement... 
        // gardens from startComplete need raising to target. Those before are incomplete.
        let remaining = newFlowers - cost;

        const m = startComplete; // number of incomplete gardens (prefix 0..m-1)
        let minBeauty = 0;
        if (m === 0) {
            // no incomplete gardens
            minBeauty = 0;
        } else {
            // we want max v in [f[0], target-1] such that cost to raise prefix to v <= remaining
            // But also these gardens must stay incomplete? They can be at most target-1 to count as incomplete.
            // If f[0] already >= target that shouldn't happen since we didn't complete them... but capped values < target unless originally >= target.
            // If f[m-1] >= target, that garden is already complete; then min could be... 
            // Actually if a prefix garden already has f == target it's complete, then min of incomplete = 0 only if all incomplete... handle via binary search cap at target-1? 
            // Let's binary search v in range [f[0], target] but result min capped at target-1 for "incomplete".
            let lo = f[0], hi = target - 1;
            // if f[0] >= target, all these are actually target -> they are complete. Then minBeauty stays... 
            if (f[0] >= target) {
                // all incomplete gardens are actually at target => complete, min incomplete = 0
                minBeauty = 0;
            } else {
                let best = f[0];
                while (lo <= hi) {
                    const mid = Math.floor((lo + hi) / 2);
                    // first index j in [0,m) with f[j] >= mid
                    let l2 = 0, r2 = m;
                    while (l2 < r2) {
                        const md = Math.floor((l2 + r2) / 2);
                        if (f[md] >= mid) r2 = md; else l2 = md + 1;
                    }
                    const j = l2;
                    const c = mid * j - prefix[j];
                    if (c <= remaining) {
                        best = mid;
                        lo = mid + 1;
                    } else {
                        hi = mid - 1;
                    }
                }
                minBeauty = best;
            }
        }

        const beauty = numComplete * full + minBeauty * partial;
        ans = Math.max(ans, beauty);
    }

    return ans;
};

function maximumBeauty(flowers: number[], newFlowers: number, target: number, full: number, partial: number): number {
    const n = flowers.length;
    const a = flowers.map(x => Math.min(x, target)).sort((x, y) => x - y);
    const prefix: number[] = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + a[i];
    let best = 0;
    let cost = 0;
    for (let j = 0; j <= n; j++) {
        if (j > 0) cost += target - a[n - j];
        if (cost > newFlowers) break;
        const m = n - j;
        if (m === 0) {
            best = Math.max(best, n * full);
            continue;
        }
        if (a[0] >= target) continue;
        const rem = newFlowers - cost;
        let lo = 1, hi = m;
        while (lo < hi) {
            const mid = (lo + hi + 1) >> 1;
            if (a[mid - 1] * mid - prefix[mid] <= rem) lo = mid;
            else hi = mid - 1;
        }
        const k = lo;
        let L = Math.floor((rem + prefix[k]) / k);
        if (L > target - 1) L = target - 1;
        best = Math.max(best, j * full + L * partial);
    }
    return best;
};

function maximumBeauty(flowers: number[], newFlowers: number, target: number, full: number, partial: number): number {
    const incomplete: number[] = [];
    let already = 0;
    for (const f of flowers) {
        if (f >= target) {
            already++;
        } else {
            incomplete.push(f);
        }
    }
    incomplete.sort((a, b) => a - b);
    const m = incomplete.length;
    const prefix: number[] = new Array(m + 1).fill(0);
    for (let i = 0; i < m; i++) {
        prefix[i + 1] = prefix[i] + incomplete[i];
    }
    let ans = 0;
    let costX = 0;
    for (let x = 0; x <= m; x++) {
        if (x > 0) {
            costX += target - incomplete[m - x];
        }
        if (costX > newFlowers) {
            break;
        }
        const rem = newFlowers - costX;
        const r = m - x;
        let h = 0;
        if (r > 0) {
            let left = 0;
            let right = target - 1;
            while (left <= right) {
                const mid = Math.floor((left + right) / 2);
                let lo = 0;
                let hi = r;
                while (lo < hi) {
                    const md = Math.floor((lo + hi) / 2);
                    if (incomplete[md] < mid) {
                        lo = md + 1;
                    } else {
                        hi = md;
                    }
                }
                const k = lo;
                const cost = k * mid - prefix[k];
                if (cost <= rem) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }
            h = right;
        }
        const beauty = (already + x) * full + h * partial;
        if (beauty > ans) {
            ans = beauty;
        }
    }
    return ans;
}

class Solution {
public:
    long long maximumBeauty(vector<int>& flowers, long long newFlowers, int target, int full, int partial) {
        int n = flowers.size();
        sort(flowers.begin(), flowers.end());
        vector<long long> f(n);
        for (int i = 0; i < n; i++) f[i] = min((long long)flowers[i], (long long)target);

        // prefix sums
        vector<long long> pre(n+1, 0);
        for (int i = 0; i < n; i++) pre[i+1] = pre[i] + f[i];

        // cost to complete the largest c gardens (indices n-c..n-1)
        // suffix cost of making garden j complete = target - f[j]
        // costComplete[c] = sum over last c gardens of (target - f[j])
        // Since sorted, largest values are cheapest to complete.

        long long ans = 0;

        // For a given number of complete gardens c (0..n), the first n-c gardens are incomplete.
        // We need to maximize min of first n-c gardens with remaining budget.
        // Precompute suffix cost to complete.
        vector<long long> suffCost(n+1, 0); // suffCost[i] = cost to complete gardens i..n-1
        for (int i = n-1; i >= 0; i--) suffCost[i] = suffCost[i+1] + (target - f[i]);

        // helper: for first m gardens (m = n-c), given budget, max achievable minimum (capped at target-1)
        // f is sorted ascending. We use two-pointer over c.

        for (int c = 0; c <= n; c++) {
            int m = n - c; // incomplete gardens are 0..m-1
            long long budget = newFlowers - suffCost[m]; // cost to complete last c
            if (budget < 0) break; // increasing c only increases cost, so break

            long long incompleteBeauty = 0;
            if (m > 0) {
                // maximize minimum of first m gardens, each < target (max target-1)
                // find largest x in [0, target-1] such that cost to raise all first m to x <= budget
                // cost = x*k - pre[k] where k = number of gardens with f < x among first m
                // binary search on x
                long long lo = f[0], hi = target - 1;
                // if f[0] already >= target-1... all incomplete are already at their capped values; min could be f[0]
                if (lo > hi) {
                    // all first m gardens have f value = target (impossible since incomplete)
                    incompleteBeauty = 0; // shouldn't happen for incomplete
                } else {
                    long long best = 0;
                    while (lo <= hi) {
                        long long x = (lo + hi) / 2;
                        // count in first m with f < x -> upper_bound
                        int k = upper_bound(f.begin(), f.begin()+m, x-1) - f.begin();
                        // actually gardens with value < x
                        // k = number with f[i] < x
                        long long cost = x * k - pre[k];
                        if (cost <= budget) {
                            best = x;
                            lo = x + 1;
                        } else {
                            hi = x - 1;
                        }
                    }
                    incompleteBeauty = best * (long long)partial;
                }
            }

            long long totalBeauty = (long long)c * full + incompleteBeauty;
            ans = max(ans, totalBeauty);
        }

        return ans;
    }
};

class Solution {
public:
    long long maximumBeauty(vector<int>& flowers, long long newFlowers, int target, int full, int partial) {
        sort(flowers.begin(), flowers.end());

        int n = flowers.size();
        int incomplete = lower_bound(flowers.begin(), flowers.end(), target) - flowers.begin();

        vector<long long> prefix(incomplete + 1, 0);
        for (int i = 0; i < incomplete; ++i) {
            prefix[i + 1] = prefix[i] + flowers[i];
        }

        long long answer = 0;
        int alreadyComplete = n - incomplete;

        for (int madeComplete = 0; madeComplete <= incomplete; ++madeComplete) {
            long long completionCost =
                1LL * madeComplete * target -
                (prefix[incomplete] - prefix[incomplete - madeComplete]);

            if (completionCost > newFlowers) break;

            int remaining = incomplete - madeComplete;
            long long beauty = 1LL * (alreadyComplete + madeComplete) * full;

            if (remaining > 0) {
                long long available = newFlowers - completionCost;
                int low = 0, high = target - 1, bestMinimum = 0;

                while (low <= high) {
                    int middle = low + (high - low) / 2;
                    int count = upper_bound(
                        flowers.begin(), flowers.begin() + remaining, middle
                    ) - flowers.begin();

                    long long cost = 1LL * middle * count - prefix[count];

                    if (cost <= available) {
                        bestMinimum = middle;
                        low = middle + 1;
                    } else {
                        high = middle - 1;
                    }
                }

                beauty += 1LL * bestMinimum * partial;
            }

            answer = max(answer, beauty);
        }

        return answer;
    }
};

