        for (int f : flowers) {
            if (f >= target) complete++;
            else a.push_back(f);
        }
        sort(a.begin(), a.end());
        int m = a.size();
        vector<long long> pre(m + 1, 0);
        for (int i = 0; i < m; i++) pre[i + 1] = pre[i] + a[i];
        long long ans = 0;
        for (int k = 0; k <= m; k++) {
            long long cost = (long long)k * target - (pre[m] - pre[m - k]);
            if (cost > newFlowers) break;
            long long r = newFlowers - cost;
            int n = m - k;
            long long part = 0;
            if (n > 0) {
                long long left = 0, right = target - 1, best = 0;
                while (left <= right) {
                    long long mid = left + (right - left) / 2;
                    auto it = lower_bound(a.begin(), a.begin() + n, mid);
                    int pos = it - a.begin();
                    long long cst = (long long)pos * mid - pre[pos];
                    if (cst <= r) {
                        best = mid;
                        left = mid + 1;
                    } else {
                        right = mid - 1;
                    }
                }
                part = best;
            }
            ans = max(ans, (long long)(complete + k) * full + part * partial);
        }
        return ans;
    }
};

