import java.util.Arrays;

class Solution {
    public long maximumBeauty(int[] flowers, long newFlowers, int target, int full, int partial) {
        int n = flowers.length;
        Arrays.sort(flowers);
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + flowers[i];
        }

        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (flowers[mid] >= target) hi = mid;
            else lo = mid + 1;
        }
        int t = lo; // gardens [t, n-1] already have >= target flowers

        if (t == 0) {
            return (long) n * full;
        }

        int[] ub = new int[target + 1]; // ub[m] = first index with flowers[i] >= m
        int p = 0;
        for (int m = 0; m <= target; m++) {
            while (p < n && flowers[p] < m) p++;
            ub[m] = p;
        }

        long ans = 0;
        int startK = n - t;

        for (int k = startK; k <= n; k++) {
            int start = n - k; // incomplete gardens are indices [0, start-1]
            long cost;
            if (start >= t) {
                cost = 0;
            } else {
                cost = (long) (t - start) * target - (prefix[t] - prefix[start]);
            }
            if (cost > newFlowers) break;
            if (k == n) {
                long cand = (long) n * full;
                if (cand > ans) ans = cand;
                break;
            }
            long rem = newFlowers - cost;
            int mLo = 0, mHi = target - 1;
            while (mLo < mHi) {
                int mid = (mLo + mHi + 1) >>> 1;
                int q = ub[mid];
                if (q > start) q = start;
                long g = (long) q * mid - prefix[q];
                if (g <= rem) mLo = mid;
                else mHi = mid - 1;
            }
            long cand = (long) k * full + (long) mLo * partial;
            if (cand > ans) ans = cand;
        }
        return ans;
    }
}

class Solution {
    public long maximumBeauty(int[] flowers, long newFlowers, int target, int full, int partial) {
        java.util.Arrays.sort(flowers);
        int n = flowers.length;

        int incomplete = n;
        while (incomplete > 0 && flowers[incomplete - 1] >= target) {
            incomplete--;
        }

        if (incomplete == 0) {
            return (long) n * full;
        }

        long[] prefix = new long[incomplete + 1];
        for (int i = 0; i < incomplete; i++) {
            prefix[i + 1] = prefix[i] + flowers[i];
        }

        long answer = 0;
        long remainingFlowers = newFlowers;

        // Complete the largest incomplete gardens first.
        for (int remaining = incomplete; remaining >= 0; remaining--) {
            if (remainingFlowers < 0) {
                break;
            }

            long beauty = (long) (n - remaining) * full;
            if (remaining == 0) {
                answer = Math.max(answer, beauty);
                break;
            }

            // Find the largest prefix that can be leveled to its maximum.
            int low = 1;
            int high = remaining;
            while (low < high) {
                int mid = low + (high - low + 1) / 2;
                long cost = (long) flowers[mid - 1] * mid - prefix[mid];

                if (cost <= remainingFlowers) {
                    low = mid;
                } else {
                    high = mid - 1;
                }
            }

            long minimum = Math.min(
                target - 1L,
                (remainingFlowers + prefix[low]) / low
            );

            answer = Math.max(answer, beauty + minimum * partial);
            remainingFlowers -= target - flowers[remaining - 1];
        }

        return answer;
    }
}

class Solution {
    public long maximumBeauty(int[] flowers, long newFlowers, int target, int full, int partial) {
        int n = flowers.length;
        int m = 0;
        int ready = 0;

        for (int f : flowers) {
            if (f >= target) {
                ready++;
            } else {
                m++;
            }
        }

        int[] a = new int[m];
        int idx = 0;
        for (int f : flowers) {
            if (f < target) {
                a[idx++] = f;
            }
        }

        java.util.Arrays.sort(a);

        long[] pref = new long[m + 1];
        for (int i = 0; i < m; i++) {
            pref[i + 1] = pref[i] + a[i];
        }

        long ans = 0;

        for (int p = m; p >= 0; p--) {
            int completedFromA = m - p;
            long costComplete = (long) completedFromA * target - (pref[m] - pref[p]);

            if (costComplete > newFlowers) {
                break;
            }

            long remaining = newFlowers - costComplete;
            long beauty;

            if (p == 0) {
                beauty = (long) n * full;
            } else {
                int low = 0, high = target - 1;

                while (low < high) {
                    int mid = (low + high + 1) >>> 1;
                    long cost = costToRaise(a, pref, p, mid);

                    if (cost <= remaining) {
                        low = mid;
                    } else {
                        high = mid - 1;
                    }
                }

                beauty = (long) (ready + completedFromA) * full + (long) low * partial;
            }

            ans = Math.max(ans, beauty);
        }

        return ans;
    }

    private long costToRaise(int[] a, long[] pref, int p, int v) {
        int lo = 0, hi = a.length;

        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] < v) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }

        int idx = Math.min(lo, p);
        return (long) idx * v - pref[idx];
    }
}

