class Solution {
    public long maximumBeauty(int[] flowers, long newFlowers, int target, int full, int partial) {
        int n = flowers.length;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = Math.min(flowers[i], target);
        Arrays.sort(a);
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + a[i];
        long best = 0;
        for (int k = 0; k <= n; k++) {
            long cost = (long) k * target - (pre[n] - pre[n - k]);
            if (cost > newFlowers) continue;
            long rem = newFlowers - cost;
            int m = n - k;
            if (m == 0) {
                best = Math.max(best, (long) n * full);
                continue;
            }
            if (a[m - 1] >= target) continue;
            int lo = 0, hi = m - 1;
            while (lo < hi) {
                int mid = (lo + hi + 1) >>> 1;
                long c = a[mid] * (mid + 1) - pre[mid + 1];
                if (c <= rem) lo = mid;
                else hi = mid - 1;
            }
            long level = Math.min((long) target - 1, (rem + pre[lo + 1]) / (lo + 1));
            best = Math.max(best, (long) k * full + level * partial);
        }
        return best;
    }
}

import java.util.Arrays;

class Solution {
    public long maximumBeauty(int[] flowers, long newFlowers, int target, int full, int partial) {
        int n = flowers.length;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = Math.min(flowers[i], target);
        }
        Arrays.sort(a);

        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + a[i];
        }

        long ans = 0;

        for (int i = 0; i <= n; i++) {
            // Cost to make suffix flowers[i...n-1] complete
            long cost = (long) (n - i) * target - (pref[n] - pref[i]);
            if (cost > newFlowers) {
                continue;
            }

            if (i == 0) {
                ans = Math.max(ans, (long) n * full);
                continue;
            }

            // If a[i - 1] is already target, it cannot be considered incomplete
            if (a[i - 1] == target) {
                continue;
            }

            long remaining = newFlowers - cost;

            // Binary search for the maximum minimum value among a[0...i-1]
            long low = a[0];
            long high = target - 1;
            long bestMin = a[0];

            while (low <= high) {
                long mid = low + (high - low) / 2;
                int idx = upperBound(a, i - 1, mid);
                long needed = (long) idx * mid - pref[idx];

                if (needed <= remaining) {
                    bestMin = mid;
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }

            long currentBeauty = (long) (n - i) * full + bestMin * partial;
            ans = Math.max(ans, currentBeauty);
        }

        return ans;
    }

    private int upperBound(long[] a, int r, long val) {
        int low = 0, high = r, ans = 0;
        while (low <= high) {
            int mid = (low + high) >>> 1;
            if (a[mid] <= val) {
                ans = mid + 1;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
}

