    for (const r of sorted) {
        const visited = new Array<boolean>(n).fill(false);
        visited[r] = true; // removed
        const queue: number[] = [];
        for (const s of initial) {
            if (s === r) continue;
            visited[s] = true;
            queue.push(s);
        }
        let count = queue.length;
        let head = 0;
        while (head < queue.length) {
            const u = queue[head++];
            const row = graph[u];
            for (let v = 0; v < n; v++) {
                if (row[v] === 1 && !visited[v]) {
                    visited[v] = true;
                    count++;
                    queue.push(v);
                }
            }
        }
        if (count < bestCount) {
            bestCount = count;
            best = r;
        }
    }
    return best;
}

function minMalwareSpread(graph: number[][], initial: number[]): number {
    const n = graph.length;
    const isInitial = new Array<boolean>(n).fill(false);
    for (const v of initial) isInitial[v] = true;

    // Union-Find over clean (non-initial) nodes only.
    const parent = new Array<number>(n);
    for (let i = 0; i < n; i++) parent[i] = i;
    const size = new Array<number>(n).fill(1);

    const find = (x: number): number => {
        let root = x;
        while (parent[root] !== root) root = parent[root];
        while (parent[x] !== root) {
            const next = parent[x];
            parent[x] = root;
            x = next;
        }
        return root;
    };

    for (let i = 0; i < n; i++) {
        if (isInitial[i]) continue;
        for (let j = i + 1; j < n; j++) {
            if (graph[i][j] === 1 && !isInitial[j]) {
                const ri = find(i);
                const rj = find(j);
                if (ri !== rj) {
                    parent[ri] = rj;
                    size[rj] += size[ri];
                }
            }
        }
    }

    // For each clean component root, count how many DISTINCT initial nodes touch it.
    const adjCount = new Map<number, number>();
    const adjOwner = new Map<number, number>();
    for (const v of initial) {
        const roots = new Set<number>();
        for (let u = 0; u < n; u++) {
            if (graph[v][u] === 1 && !isInitial[u]) {
                roots.add(find(u));
            }
        }
        for (const r of roots) {
            adjCount.set(r, (adjCount.get(r) || 0) + 1);
            adjOwner.set(r, v);
        }
    }

    // savings[v] = total size of clean components whose ONLY adjacent initial node is v.
    // Removing v keeps exactly those components clean (plus v itself, constant for all v).
    const savings = new Map<number, number>();
    for (const v of initial) savings.set(v, 0);
    for (const [r, c] of adjCount) {
        if (c === 1) {
            const v = adjOwner.get(r)!;
            savings.set(v, (savings.get(v) || 0) + size[r]);
        }
    }

    // Maximize savings; tie-break by smallest node index.
    let best = -1;
    let bestSavings = -1;
    const sorted = [...initial].sort((a, b) => a - b);
    for (const v of sorted) {
        const s = savings.get(v) || 0;
        if (s > bestSavings) {
            bestSavings = s;
            best = v;
        }
    }
    return best;
}

function minMalwareSpread(graph: number[][], initial: number[]): number {
    const n = graph.length;
    const infected = new Array<boolean>(n).fill(false);

    for (const node of initial) {
        infected[node] = true;
    }

    const parent = Array.from({ length: n }, (_, i) => i);
    const size = new Array<number>(n).fill(1);

    const find = (x: number): number => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    const union = (a: number, b: number): void => {
        let rootA = find(a);
        let rootB = find(b);

        if (rootA === rootB) return;

        if (size[rootA] < size[rootB]) {
            [rootA, rootB] = [rootB, rootA];
        }

        parent[rootB] = rootA;
        size[rootA] += size[rootB];
    };

    for (let i = 0; i < n; i++) {
        if (infected[i]) continue;

        for (let j = i + 1; j < n; j++) {
            if (!infected[j] && graph[i][j] === 1) {
                union(i, j);
            }
        }
    }

    const sourceCount = new Array<number>(n).fill(0);
    const owner = new Array<number>(n).fill(-1);

    for (const source of initial) {
        const components = new Set<number>();

        for (let node = 0; node < n; node++) {
            if (!infected[node] && graph[source][node] === 1) {
                components.add(find(node));
            }
        }

        for (const root of components) {
            sourceCount[root]++;
            owner[root] = source;
        }
    }

    const saved = new Array<number>(n).fill(0);

    for (let node = 0; node < n; node++) {
        if (!infected[node] && find(node) === node && sourceCount[node] === 1) {
            saved[owner[node]] += size[node];
        }
    }

    let answer = initial[0];

    for (const source of initial) {
        if (
            saved[source] > saved[answer] ||
            (saved[source] === saved[answer] && source < answer)
        ) {
            answer = source;
        }
    }

    return answer;
}

function minMalwareSpread(graph: number[][], initial: number[]): number {
    const n = graph.length;
    const isInitial = new Array<boolean>(n).fill(false);

    for (const node of initial) {
        isInitial[node] = true;
    }

    const visited = new Array<boolean>(n).fill(false);
    const saved = new Array<number>(n).fill(0);

    for (let start = 0; start < n; start++) {
        if (isInitial[start] || visited[start]) continue;

        const queue: number[] = [start];
        visited[start] = true;
        let head = 0;
        let size = 0;
        const sources = new Set<number>();

        while (head < queue.length) {
            const node = queue[head++];
            size++;

            for (let next = 0; next < n; next++) {
                if (graph[node][next] === 0) continue;

                if (isInitial[next]) {
                    sources.add(next);
                } else if (!visited[next]) {
                    visited[next] = true;
                    queue.push(next);
                }
            }
        }

        if (sources.size === 1) {
            const source = sources.values().next().value as number;
            saved[source] += size;
        }
    }

    let answer = initial[0];
    for (const node of initial) {
        if (
            saved[node] > saved[answer] ||
            (saved[node] === saved[answer] && node < answer)
        ) {
            answer = node;
        }
    }

    return answer;
};

