    }
};

class Solution {
    vector<int> parent, sz;
    int find(int x){
        while(parent[x] != x){
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    void unite(int a, int b){
        a = find(a); b = find(b);
        if(a == b) return;
        if(sz[a] < sz[b]) swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
    }
public:
    int minMalwareSpread(vector<vector<int>>& graph, vector<int>& initial) {
        int n = graph.size();
        int m = initial.size();
        vector<char> infected(n, 0);
        for(int u : initial) infected[u] = 1;

        parent.resize(n);
        sz.assign(n, 1);
        iota(parent.begin(), parent.end(), 0);

        // Union only non-infected nodes
        for(int i = 0; i < n; i++){
            if(infected[i]) continue;
            for(int j = i + 1; j < n; j++){
                if(graph[i][j] && !infected[j]) unite(i, j);
            }
        }

        // For each component root, record which initial nodes are adjacent to it
        vector<set<int>> adj(n);
        for(int k = 0; k < m; k++){
            int u = initial[k];
            for(int v = 0; v < n; v++){
                if(graph[u][v] && !infected[v]) adj[find(v)].insert(k);
            }
        }

        // Savings for initial node k = total size of components adjacent only to k
        vector<int> save(m, 0);
        for(int r = 0; r < n; r++){
            if(adj[r].size() == 1){
                save[*adj[r].begin()] += sz[r];
            }
        }

        // Pick max savings, tie-break by smallest node index
        vector<int> order(m);
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b){ return initial[a] < initial[b]; });

        int best = order[0];
        for(int t = 1; t < m; t++){
            if(save[order[t]] > save[best]) best = order[t];
        }
        return initial[best];
    }
};

