class Solution {
    public int minMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.length;
        boolean[] infected = new boolean[n];
        for (int u : initial) infected[u] = true;

        int[] parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        // Union-find over clean nodes only: components of the graph
        // with all initially infected nodes (and their edges) removed.
        for (int i = 0; i < n; i++) {
            if (infected[i]) continue;
            for (int j = i + 1; j < n; j++) {
                if (graph[i][j] == 1 && !infected[j]) {
                    int ri = find(parent, i);
                    int rj = find(parent, j);
                    if (ri != rj) parent[ri] = rj;
                }
            }
        }

        // Size of each clean component.
        int[] compSize = new int[n];
        for (int i = 0; i < n; i++) {
            if (!infected[i]) compSize[find(parent, i)]++;
        }

        // For each clean component, count distinct initially infected
        // nodes adjacent to it; remember the node for the singleton case.
        int[] cnt = new int[n];
        int[] lastInf = new int[n];
        int[] stamp = new int[n];
        int iter = 0;
        for (int u : initial) {
            iter++;
            for (int v = 0; v < n; v++) {
                if (graph[u][v] == 1 && !infected[v]) {
                    int r = find(parent, v);
                    if (stamp[r] != iter) {
                        stamp[r] = iter;
                        cnt[r]++;
                        lastInf[r] = u;
                    }
                }
            }
        }

        // Removing u saves exactly the clean components whose only
        // adjacent infected node is u.
        int[] savings = new int[n];
        for (int r = 0; r < n; r++) {
            if (cnt[r] == 1) {
                savings[lastInf[r]] += compSize[r];
            }
        }

        // Max savings == min M(initial); tie -> smallest index.
        int best = -1;
        int bestSav = -1;
        for (int u : initial) {
            if (savings[u] > bestSav || (savings[u] == bestSav && u < best)) {
                bestSav = savings[u];
                best = u;
            }
        }
        return best;
    }

    private int find(int[] parent, int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
}

class Solution {
    public int minMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.length;
        boolean[] infected = new boolean[n];
        for (int node : initial) {
            infected[node] = true;
        }

        boolean[] visited = new boolean[n];
        int[] saved = new int[n];
        int[] queue = new int[n];

        // Find components consisting only of initially uninfected nodes.
        for (int start = 0; start < n; start++) {
            if (infected[start] || visited[start]) {
                continue;
            }

            int head = 0;
            int tail = 0;
            queue[tail++] = start;
            visited[start] = true;

            // -1: no infected neighbor; -2: multiple infected neighbors.
            int owner = -1;

            while (head < tail) {
                int node = queue[head++];

                for (int neighbor = 0; neighbor < n; neighbor++) {
                    if (graph[node][neighbor] == 0) {
                        continue;
                    }

                    if (infected[neighbor]) {
                        if (owner == -1) {
                            owner = neighbor;
                        } else if (owner != neighbor) {
                            owner = -2;
                        }
                    } else if (!visited[neighbor]) {
                        visited[neighbor] = true;
                        queue[tail++] = neighbor;
                    }
                }
            }

            // Removing the sole infection source saves this entire component.
            if (owner >= 0) {
                saved[owner] += tail;
            }
        }

        int answer = initial[0];
        for (int node : initial) {
            if (saved[node] > saved[answer]
                    || (saved[node] == saved[answer] && node < answer)) {
                answer = node;
            }
        }

        return answer;
    }
}

