    int minAreaRect(vector<vector<int>>& points) {
        map<int, vector<int>> cols;
        for (const auto& p : points) {
            cols[p[0]].push_back(p[1]);
        }

        for (auto& [x, ys] : cols) {
            sort(ys.begin(), ys.end());
        }

        int ans = INT_MAX;
        vector<int> xs;
        for (const auto& [x, ys] : cols) {
            xs.push_back(x);
        }

        for (int i = 0; i < (int)xs.size(); ++i) {
            for (int j = i + 1; j < (int)xs.size(); ++j) {
                int x1 = xs[i];
                int x2 = xs[j];
                const auto& ys1 = cols[x1];
                const auto& ys2 = cols[x2];

                int p = 0, q = 0;
                int prevY = -1;
                int minDiff = INT_MAX;

                while (p < (int)ys1.size() && q < (int)ys2.size()) {
                    if (ys1[p] == ys2[q]) {
                        if (prevY != -1) {
                            minDiff = min(minDiff, ys1[p] - prevY);
                        }
                        prevY = ys1[p];
                        ++p;
                        ++q;
                    } else if (ys1[p] < ys2[q]) {
                        ++p;
                    } else {
                        ++q;
                    }
                }

                if (minDiff != INT_MAX) {
                    ans = min(ans, (x2 - x1) * minDiff);
                }
            }
        }

        return ans == INT_MAX ? 0 : ans;
    }
};

class Solution {
    public int minAreaRect(int[][] points) {
        java.util.HashSet<Long> set = new java.util.HashSet<>();

        for (int[] point : points) {
            long key = ((long) point[0] << 32) | (point[1] & 0xffffffffL);
            set.add(key);
        }

        int minArea = Integer.MAX_VALUE;

        for (int i = 0; i < points.length; i++) {
            for (int j = i + 1; j < points.length; j++) {
                int x1 = points[i][0];
                int y1 = points[i][1];
                int x2 = points[j][0];
                int y2 = points[j][1];

                if (x1 == x2 || y1 == y2) {
                    continue;
                }

                long corner1 = ((long) x1 << 32) | (y2 & 0xffffffffL);
                long corner2 = ((long) x2 << 32) | (y1 & 0xffffffffL);

                if (set.contains(corner1) && set.contains(corner2)) {
                    int area = Math.abs(x1 - x2) * Math.abs(y1 - y2);
                    minArea = Math.min(minArea, area);
                }
            }
        }

        return minArea == Integer.MAX_VALUE ? 0 : minArea;
    }
}

