class Solution {
    public int minAreaRect(int[][] points) {
        TreeMap<Integer, List<Integer>> cols = new TreeMap<>();
        for (int[] p : points) {
            cols.computeIfAbsent(p[0], k -> new ArrayList<>()).add(p[1]);
        }
        Map<Long, Integer> lastX = new HashMap<>();
        long best = Long.MAX_VALUE;
        for (Map.Entry<Integer, List<Integer>> e : cols.entrySet()) {
            int x = e.getKey();
            List<Integer> ys = e.getValue();
            Collections.sort(ys);
            int n = ys.size();
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    int y1 = ys.get(i), y2 = ys.get(j);
                    long key = ((long) y1) * 50000L + y2;
                    Integer px = lastX.get(key);
                    if (px != null) {
                        long area = (long) (x - px) * (y2 - y1);
                        if (area < best) best = area;
                    }
                    lastX.put(key, x);
                }
            }
        }
        return best == Long.MAX_VALUE ? 0 : (int) best;
    }
}

