 */
var minCost = function(maxTime, edges, passingFees) {
    const n = passingFees.length;
    const INF = Infinity;
    // dp[t * n + node] = min cost to be at 'node' after exactly 't' minutes
    const dp = new Float64Array((maxTime + 1) * n).fill(INF);
    dp[0] = passingFees[0]; // start at city 0 at time 0, pay its fee

    const m = edges.length;
    const us = new Int32Array(m);
    const vs = new Int32Array(m);
    const ws = new Int32Array(m);
    for (let i = 0; i < m; i++) {
        us[i] = edges[i][0];
        vs[i] = edges[i][1];
        ws[i] = edges[i][2];
    }

    for (let t = 0; t < maxTime; t++) {
        const base = t * n;
        for (let i = 0; i < m; i++) {
            const nt = t + ws[i];
            if (nt > maxTime) continue;
            const nbase = nt * n;
            const u = us[i], v = vs[i];

            const cu = dp[base + u];
            if (cu !== INF) {
                const c = cu + passingFees[v];
                if (c < dp[nbase + v]) dp[nbase + v] = c;
            }
            const cv = dp[base + v];
            if (cv !== INF) {
                const c = cv + passingFees[u];
                if (c < dp[nbase + u]) dp[nbase + u] = c;
            }
        }
    }

    let ans = INF;
    const dest = n - 1;
    for (let t = 0; t <= maxTime; t++) {
        const c = dp[t * n + dest];
        if (c < ans) ans = c;
    }
    return ans === INF ? -1 : ans;
};

