function minCost(maxTime: number, edges: number[][], passingFees: number[]): number {
    const n = passingFees.length;
    const m = edges.length;
    const INF = Infinity;

    // Sort edges by travel time (ascending) so each edge becomes usable
    // from time t = w onward; a pointer tracks the usable prefix.
    const sorted = edges.slice().sort((a, b) => a[2] - b[2]);
    const eu = new Int32Array(m);
    const ev = new Int32Array(m);
    const ew = new Int32Array(m);
    for (let i = 0; i < m; i++) {
        eu[i] = sorted[i][0];
        ev[i] = sorted[i][1];
        ew[i] = sorted[i][2];
    }

    // dp[t * n + i] = minimum cost to be at city i at exactly time t.
    const dp = new Float64Array((maxTime + 1) * n);
    dp.fill(INF);
    dp[0] = passingFees[0]; // start at city 0 at time 0, paying its fee

    let ptr = 0;
    for (let t = 1; t <= maxTime; t++) {
        while (ptr < m && ew[ptr] <= t) ptr++;
        const base = t * n;
        for (let e = 0; e < ptr; e++) {
            const w = ew[e];
            const prevBase = (t - w) * n;
            const u = eu[e];
            const v = ev[e];
            const pu = dp[prevBase + u];
            if (pu !== INF) {
                const cand = pu + passingFees[v];
                if (cand < dp[base + v]) dp[base + v] = cand;
            }
            const pv = dp[prevBase + v];
            if (pv !== INF) {
                const cand = pv + passingFees[u];
                if (cand < dp[base + u]) dp[base + u] = cand;
            }
        }
    }

    let ans = INF;
    const dest = n - 1;
    for (let t = 0; t <= maxTime; t++) {
        const c = dp[t * n + dest];
        if (c < ans) ans = c;
    }
    return ans === INF ? -1 : ans;
}

