function minCost(maxTime: number, edges: number[][], passingFees: number[]): number {
    const n = passingFees.length;
    const graph: Array<Array<[number, number]>> = Array.from({ length: n }, () => []);
    for (const [u, v, t] of edges) {
        graph[u].push([v, t]);
        graph[v].push([u, t]);
    }

    const INF = Number.POSITIVE_INFINITY;
    const dist: number[][] = Array.from({ length: n }, () => Array(maxTime + 1).fill(INF));
    dist[0][0] = passingFees[0];

    class MinHeap {
        data: Array<[number, number, number]> = [];
        push(x: [number, number, number]) {
            const a = this.data;
            a.push(x);
            let i = a.length - 1;
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (a[p][0] <= a[i][0]) break;
                [a[p], a[i]] = [a[i], a[p]];
                i = p;
            }
        }
        pop(): [number, number, number] | undefined {
            const a = this.data;
            if (a.length === 0) return undefined;
            const top = a[0];
            const last = a.pop()!;
            if (a.length > 0) {
                a[0] = last;
                let i = 0;
                while (true) {
                    let smallest = i;
                    const l = i * 2 + 1;
                    const r = l + 1;
                    if (l < a.length && a[l][0] < a[smallest][0]) smallest = l;
                    if (r < a.length && a[r][0] < a[smallest][0]) smallest = r;
                    if (smallest === i) break;
                    [a[i], a[smallest]] = [a[smallest], a[i]];
                    i = smallest;
                }
            }
            return top;
        }
        size() {
            return this.data.length;
        }
    }

    const heap = new MinHeap();
    heap.push([passingFees[0], 0, 0]); // [cost, time, node]

    while (heap.size() > 0) {
        const cur = heap.pop()!;
        const [cost, time, node] = cur;
        if (cost !== dist[node][time]) continue;
        if (node === n - 1) return cost;

        for (const [next, t] of graph[node]) {
            const nt = time + t;
            if (nt > maxTime) continue;
            const nc = cost + passingFees[next];
            if (nc < dist[next][nt]) {
                dist[next][nt] = nc;
                heap.push([nc, nt, next]);
            }
        }
    }

    return -1;
};

function minCost(maxTime: number, edges: number[][], passingFees: number[]): number {
    const n = passingFees.length;
    const dp = new Float64Array((maxTime + 1) * n);
    dp.fill(Infinity);
    dp[0] = passingFees[0];

    let answer = Infinity;

    for (let time = 0; time <= maxTime; time++) {
        const offset = time * n;

        for (const [u, v, travelTime] of edges) {
            const nextTime = time + travelTime;
            if (nextTime > maxTime) continue;

            const nextOffset = nextTime * n;
            const costAtU = dp[offset + u];
            const costAtV = dp[offset + v];

            if (costAtU !== Infinity) {
                const nextCost = costAtU + passingFees[v];
                if (nextCost < dp[nextOffset + v]) {
                    dp[nextOffset + v] = nextCost;
                    if (v === n - 1) answer = Math.min(answer, nextCost);
                }
            }

            if (costAtV !== Infinity) {
                const nextCost = costAtV + passingFees[u];
                if (nextCost < dp[nextOffset + u]) {
                    dp[nextOffset + u] = nextCost;
                    if (u === n - 1) answer = Math.min(answer, nextCost);
                }
            }
        }
    }

    return answer === Infinity ? -1 : answer;
}

function minCost(maxTime: number, edges: number[][], passingFees: number[]): number {
