        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (g[i][j] == 1 && !vis[i][j]) {
                    c++;
                    int sp = 0;
                    stack[sp++] = i * n + j;
                    vis[i][j] = true;
                    while (sp > 0) {
                        int cur = stack[--sp];
                        int x = cur / n, y = cur % n;
                        for (int d = 0; d < 4; d++) {
                            int nx = x + dx[d], ny = y + dy[d];
                            if (nx >= 0 && ny >= 0 && nx < m && ny < n && g[nx][ny] == 1 && !vis[nx][ny]) {
                                vis[nx][ny] = true;
                                stack[sp++] = nx * n + ny;
                            }
                        }
                    }
                }
            }
        }
        return c;
    }

    public int minDays(int[][] grid) {
        m = grid.length;
        n = grid[0].length;
        if (count(grid) != 1) return 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    grid[i][j] = 0;
                    int c = count(grid);
                    grid[i][j] = 1;
                    if (c != 1) return 1;
                }
            }
        }
        return 2;
    }
}

class Solution {
    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    public int minDays(int[][] grid) {
        if (countIslands(grid) != 1) {
            return 0;
        }

        for (int row = 0; row < grid.length; row++) {
            for (int col = 0; col < grid[0].length; col++) {
                if (grid[row][col] == 0) {
                    continue;
                }

                grid[row][col] = 0;
                boolean disconnected = countIslands(grid) != 1;
                grid[row][col] = 1;

                if (disconnected) {
                    return 1;
                }
            }
        }

        return 2;
    }

    private int countIslands(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        int islands = 0;

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (grid[row][col] == 1 && !visited[row][col]) {
                    islands++;
                    if (islands > 1) {
                        return islands;
                    }
                    dfs(grid, row, col, visited);
                }
            }
        }

        return islands;
    }

    private void dfs(int[][] grid, int row, int col, boolean[][] visited) {
        visited[row][col] = true;

        for (int[] direction : DIRECTIONS) {
            int nextRow = row + direction[0];
            int nextCol = col + direction[1];

            if (nextRow >= 0 && nextRow < grid.length
                    && nextCol >= 0 && nextCol < grid[0].length
                    && grid[nextRow][nextCol] == 1
                    && !visited[nextRow][nextCol]) {
                dfs(grid, nextRow, nextCol, visited);
            }
        }
    }
}

class Solution {
    public int minDays(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int land = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) land++;
            }
        }

        if (land == 0) return 0;
        if (countIslands(grid) != 1) return 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    grid[i][j] = 0;
                    if (countIslands(grid) != 1) {
                        grid[i][j] = 1;
                        return 1;
                    }
                    grid[i][j] = 1;
                }
            }
        }
        return 2;
    }

    private int countIslands(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        boolean[][] vis = new boolean[m][n];
        int islands = 0;
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1 && !vis[i][j]) {
                    islands++;
                    if (islands > 1) return islands;
                    java.util.ArrayDeque<int[]> q = new java.util.ArrayDeque<>();
                    q.add(new int[]{i, j});
                    vis[i][j] = true;
                    while (!q.isEmpty()) {
                        int[] cur = q.poll();
                        for (int k = 0; k < 4; k++) {
                            int ni = cur[0] + dr[k], nj = cur[1] + dc[k];
                            if (ni >= 0 && ni < m && nj >= 0 && nj < n && grid[ni][nj] == 1 && !vis[ni][nj]) {
                                vis[ni][nj] = true;
                                q.add(new int[]{ni, nj});
                            }
                        }
                    }
                }
            }
        }
        return islands;
    }
}

