class Solution {
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public int minDays(int[][] grid) {
        if (countIslands(grid) != 1) {
            return 0;
        }

        int m = grid.length;
        int n = grid[0].length;

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0) {
                    continue;
                }

                grid[r][c] = 0;
                boolean disconnected = countIslands(grid) != 1;
                grid[r][c] = 1;

                if (disconnected) {
                    return 1;
                }
            }
        }

        // Any finite 4-connected grid island can be disconnected in at most 2 days.
        return 2;
    }

    private int countIslands(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        boolean[] visited = new boolean[m * n];
        int[] queue = new int[m * n];
        int islands = 0;

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                int start = r * n + c;
                if (grid[r][c] == 0 || visited[start]) {
                    continue;
                }

                if (++islands == 2) {
                    return 2;
                }

                int head = 0;
                int tail = 0;
                queue[tail++] = start;
                visited[start] = true;

                while (head < tail) {
                    int cell = queue[head++];
                    int row = cell / n;
                    int col = cell % n;

                    for (int d = 0; d < 4; d++) {
                        int nr = row + DR[d];
                        int nc = col + DC[d];

                        if (nr < 0 || nr >= m || nc < 0 || nc >= n) {
                            continue;
                        }

                        int next = nr * n + nc;
                        if (grid[nr][nc] == 1 && !visited[next]) {
                            visited[next] = true;
                            queue[tail++] = next;
                        }
                    }
                }
            }
        }

        return islands;
    }
}

