var minSwaps = function(s) {
    let open = 0, unmatched = 0;
    const n = s.length;
    for (let i = 0; i < n; i++) {
        if (s.charCodeAt(i) === 91) {
            open++;
        } else if (open > 0) {
            open--;
        } else {
            unmatched++;
        }
    }
    return Math.ceil(unmatched / 2);
};

