 */
var minSwaps = function(s) {
    let extra = 0;
    let maxExtra = 0;
    for (const c of s) {
        if (c === ']') extra++;
        else extra--;
        if (extra > maxExtra) maxExtra = extra;
    }
    return Math.floor((maxExtra + 1) / 2);
};

