/**
 * @param {number[]} tasks
 * @param {number} sessionTime
 * @return {number}
 */
var minSessions = function(tasks, sessionTime) {
    const n = tasks.length;
    const full = (1 << n) - 1;
    const INF = 1e9;
    const dp = new Array(1 << n).fill(INF);
    dp[0] = 1 * 16 + 0;
    for (let m = 0; m < full; m++) {
        if (dp[m] === INF) continue;
        const s = dp[m] >> 4, t = dp[m] & 15;
        for (let i = 0; i < n; i++) {
            if (m & (1 << i)) continue;
            const nm = m | (1 << i);
            let val;
            if (t + tasks[i] <= sessionTime) val = s * 16 + t + tasks[i];
            else val = (s + 1) * 16 + tasks[i];
            if (val < dp[nm]) dp[nm] = val;
        }
    }
    return dp[full] >> 4;
};

/**
 * @param {number[]} tasks
 * @param {number} sessionTime
 * @return {number}
 */
var minSessions = function(tasks, sessionTime) {
    const n = tasks.length;
    const totalMasks = 1 << n;

    const dpSessions = new Array(totalMasks).fill(Infinity);
    const dpUsed = new Array(totalMasks).fill(Infinity);

    dpSessions[0] = 1;
    dpUsed[0] = 0;

    for (let mask = 0; mask < totalMasks; mask++) {
        if (dpSessions[mask] === Infinity) continue;

        for (let i = 0; i < n; i++) {
            if ((mask & (1 << i)) !== 0) continue;

            const nextMask = mask | (1 << i);
            let nextSessions = dpSessions[mask];
            let nextUsed = dpUsed[mask] + tasks[i];

            if (nextUsed > sessionTime) {
                nextSessions++;
                nextUsed = tasks[i];
            }

            if (
                nextSessions < dpSessions[nextMask] ||
                (nextSessions === dpSessions[nextMask] && nextUsed < dpUsed[nextMask])
            ) {
                dpSessions[nextMask] = nextSessions;
                dpUsed[nextMask] = nextUsed;
            }
        }
    }

    return dpSessions[totalMasks - 1];
};

/**
 * @param {number[]} tasks
 * @param {number} sessionTime
 * @return {number}
 */
var minSessions = function(tasks, sessionTime) {
    const n = tasks.length;
    const full = (1 << n) - 1;
    // sum[mask] = total time of tasks in mask
    const sum = new Array(1 << n).fill(0);
    for (let mask = 1; mask <= full; mask++) {
        const low = mask & (-mask);
        const idx = Math.log2(low);
        sum[mask] = sum[mask ^ low] + tasks[idx];
    }
    // dp[mask] = min sessions to finish tasks in mask
    const dp = new Array(1 << n).fill(Infinity);
    dp[0] = 0;
    for (let mask = 1; mask <= full; mask++) {
        // iterate over submasks that form one session (fit in sessionTime)
        for (let sub = mask; sub > 0; sub = (sub - 1) & mask) {
            if (sum[sub] <= sessionTime) {
                dp[mask] = Math.min(dp[mask], dp[mask ^ sub] + 1);
            }
        }
    }
    return dp[full];
};

/**
 * @param {number[]} tasks
 * @param {number} sessionTime
 * @return {number}
 */
var minSessions = function(tasks, sessionTime) {
    const n = tasks.length;
    const totalMasks = 1 << n;
    const dpSessions = new Array(totalMasks).fill(Infinity);
    const dpRem = new Array(totalMasks).fill(-1);
    dpSessions[0] = 0;
    dpRem[0] = 0;

    for (let mask = 0; mask < totalMasks; mask++) {
        if (dpSessions[mask] === Infinity) continue;
        const s = dpSessions[mask];
        const rem = dpRem[mask];
        for (let i = 0; i < n; i++) {
            if (mask & (1 << i)) continue;
            const t = tasks[i];
            let ns, nrem;
            if (rem >= t) {
                ns = s;
                nrem = rem - t;
            } else {
                ns = s + 1;
                nrem = sessionTime - t;
            }
            const nmask = mask | (1 << i);
            if (ns < dpSessions[nmask] || (ns === dpSessions[nmask] && nrem > dpRem[nmask])) {
                dpSessions[nmask] = ns;
                dpRem[nmask] = nrem;
            }
        }
    }

    return dpSessions[totalMasks - 1];
};

/**
 * @param {number[]} tasks
 * @param {number} sessionTime
 * @return {number}
 */
var minSessions = function(tasks, sessionTime) {
    const n = tasks.length;
    const total = 1 << n;

    // Precompute the sum of tasks for every bitmask
    const sum = new Array(total).fill(0);
    for (let mask = 1; mask < total; mask++) {
        const lb = mask & (-mask);
        const idx = 31 - Math.clz32(lb);
        sum[mask] = sum[mask ^ lb] + tasks[idx];
    }

    const INF = Number.MAX_SAFE_INTEGER;
    // dp[mask] = minimum number of sessions to finish the set of tasks in mask
    const dp = new Array(total).fill(INF);
    dp[0] = 0;

    for (let mask = 1; mask < total; mask++) {
        // If all tasks in this mask fit in one session, that's optimal
        if (sum[mask] <= sessionTime) {
            dp[mask] = 1;
            continue;
        }
        // Enumerate submasks containing the lowest set bit as the last session
        const lb = mask & (-mask);
        const rest = mask ^ lb;
        let best = INF;
        for (let sub = rest; ; sub = (sub - 1) & rest) {
            const session = sub | lb;
            if (sum[session] <= sessionTime) {
                const val = dp[mask ^ session] + 1;
                if (val < best) best = val;
            }
            if (sub === 0) break;
        }
        dp[mask] = best;
    }

    return dp[total - 1];
};

/**
 * @param {number[]} tasks
 * @param {number} sessionTime
 * @return {number}
 */
var minSessions = function(tasks, sessionTime) {
    const n = tasks.length;
    const totalMasks = 1 << n;
    const dp = new Int32Array(totalMasks).fill(1e9);

    // dp[mask] = (sessions << 5) | time
    dp[0] = (1 << 5) | 0;

    for (let mask = 0; mask < totalMasks; mask++) {
        const curr = dp[mask];
        const sess = curr >> 5;
        const time = curr & 31;

        for (let i = 0; i < n; i++) {
            if ((mask & (1 << i)) === 0) {
                const nextMask = mask | (1 << i);
                let cand;
                if (time + tasks[i] <= sessionTime) {
                    cand = (sess << 5) | (time + tasks[i]);
                } else {
                    cand = ((sess + 1) << 5) | tasks[i];
                }
                if (cand < dp[nextMask]) {
                    dp[nextMask] = cand;
                }
            }
        }
    }

    return dp[totalMasks - 1] >> 5;
};

