                ns = s + 1;
                nt = tasks[i];
            }
            const v = ns * 100 + nt;
            const nm = mask | (1 << i);
            if (v < dp[nm]) dp[nm] = v;
        }
    }
    return Math.floor(dp[full] / 100);
