function minSessions(tasks: number[], sessionTime: number): number {
    const n = tasks.length;
    const size = 1 << n;
    const INF = Number.MAX_SAFE_INTEGER;

    // sessions[mask]: min number of sessions used for tasks in mask
    // used[mask]: time already used in the currently open (last) session
    const sessions = new Array<number>(size).fill(INF);
    const used = new Array<number>(size).fill(0);

    sessions[0] = 0;
    used[0] = sessionTime; // "full" open session so the first task starts a new one

    for (let mask = 0; mask < size; mask++) {
        const s = sessions[mask];
        if (s === INF) continue;
        const t = used[mask];

        for (let i = 0; i < n; i++) {
            const bit = 1 << i;
            if (mask & bit) continue;

            const nmask = mask | bit;
            let ns = s;
            let nt = t + tasks[i];
            if (nt > sessionTime) {
                // task doesn't fit in the open session -> start a new session
                ns = s + 1;
                nt = tasks[i];
            }

            if (ns < sessions[nmask] || (ns === sessions[nmask] && nt < used[nmask])) {
                sessions[nmask] = ns;
                used[nmask] = nt;
            }
        }
    }

    return sessions[size - 1];
}

