class Solution {
public:
    int minSessions(vector<int>& tasks, int sessionTime) {
        int n = tasks.size();
        int full = (1 << n) - 1;
        // precompute whether a subset fits in one session
        vector<bool> fits(1 << n, false);
        for (int mask = 0; mask <= full; mask++) {
            int sum = 0;
            for (int i = 0; i < n; i++)
                if (mask & (1 << i)) sum += tasks[i];
            fits[mask] = (sum <= sessionTime);
        }
        vector<int> dp(1 << n, INT_MAX);
        dp[0] = 0;
        for (int mask = 1; mask <= full; mask++) {
            // enumerate submasks
            for (int sub = mask; sub > 0; sub = (sub - 1) & mask) {
                if (fits[sub] && dp[mask ^ sub] != INT_MAX) {
                    dp[mask] = min(dp[mask], dp[mask ^ sub] + 1);
                }
            }
        }
        return dp[full];
    }
};

class Solution {
    public int minSessions(int[] tasks, int sessionTime) {
        int n = tasks.length;
        int full = 1 << n;
        // cost[mask] = 1 if tasks in mask fit in one session
        boolean[] fits = new boolean[full];
        for (int mask = 0; mask < full; mask++) {
            int sum = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) sum += tasks[i];
            }
            fits[mask] = sum <= sessionTime;
        }
        int[] dp = new int[full];
        java.util.Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;
        for (int mask = 1; mask < full; mask++) {
            // iterate submasks
            for (int sub = mask; sub > 0; sub = (sub - 1) & mask) {
                if (fits[sub] && dp[mask ^ sub] != Integer.MAX_VALUE) {
                    dp[mask] = Math.min(dp[mask], dp[mask ^ sub] + 1);
                }
            }
        }
        return dp[full - 1];
    }
}

class Solution {
    public int minSessions(int[] tasks, int sessionTime) {
        int n = tasks.length;
        int totalMasks = 1 << n;

        int[] sum = new int[totalMasks];
        for (int mask = 1; mask < totalMasks; mask++) {
            int lsb = mask & -mask;
            int idx = Integer.numberOfTrailingZeros(lsb);
            sum[mask] = sum[mask ^ lsb] + tasks[idx];
        }

        int[] dp = new int[totalMasks];
        for (int i = 1; i < totalMasks; i++) {
            dp[i] = n;
        }

        for (int mask = 1; mask < totalMasks; mask++) {
            if (sum[mask] <= sessionTime) {
                dp[mask] = 1;
                continue;
            }

            for (int sub = mask; sub > 0; sub = (sub - 1) & mask) {
                if (sum[sub] <= sessionTime) {
                    dp[mask] = Math.min(dp[mask], dp[mask ^ sub] + 1);
                }
            }
        }

        return dp[totalMasks - 1];
    }
}

class Solution {
    public int minSessions(int[] tasks, int sessionTime) {
        int n = tasks.length;
        int full = (1 << n) - 1;
        int[] dp = new int[1 << n];
        java.util.Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 100;
        for (int mask = 0; mask < full; mask++) {
            if (dp[mask] == Integer.MAX_VALUE) continue;
            int s = dp[mask] / 100;
            int t = dp[mask] % 100;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                int ns, nt;
                if (t + tasks[i] <= sessionTime) {
                    ns = s;
                    nt = t + tasks[i];
                } else {
                    ns = s + 1;
                    nt = tasks[i];
                }
                int v = ns * 100 + nt;
                int nm = mask | (1 << i);
                if (v < dp[nm]) dp[nm] = v;
            }
        }
        return dp[full] / 100;
    }
}

import java.util.Arrays;

class Solution {
    public int minSessions(int[] tasks, int sessionTime) {
        int n = tasks.length;
        int full = (1 << n) - 1;
        // dp[mask] = pair (sessions[mask], remaining[mask]):
        // minimum number of sessions to complete tasks in mask,
        // and the maximum remaining time in the currently open session.
        int[] sessions = new int[1 << n];
        int[] remaining = new int[1 << n];
        Arrays.fill(sessions, Integer.MAX_VALUE);
        sessions[0] = 0;
        remaining[0] = 0;

        for (int mask = 0; mask < full; mask++) {
            if (sessions[mask] == Integer.MAX_VALUE) continue;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                int next = mask | (1 << i);
                int ns, nr;
                if (tasks[i] <= remaining[mask]) {
                    // Task fits into the currently open session.
                    ns = sessions[mask];
                    nr = remaining[mask] - tasks[i];
                } else {
                    // Need to open a new session for this task.
                    ns = sessions[mask] + 1;
                    nr = sessionTime - tasks[i];
                }
                if (ns < sessions[next] || (ns == sessions[next] && nr > remaining[next])) {
                    sessions[next] = ns;
                    remaining[next] = nr;
                }
            }
        }
        return sessions[full];
    }
}

import java.util.Arrays;

class Solution {
    public int minSessions(int[] tasks, int sessionTime) {
        int n = tasks.length;
        int totalStates = 1 << n;

        int[] dpSessions = new int[totalStates];
        int[] dpTime = new int[totalStates];

        Arrays.fill(dpSessions, Integer.MAX_VALUE);
        Arrays.fill(dpTime, Integer.MAX_VALUE);

        dpSessions[0] = 1;
        dpTime[0] = 0;

        for (int mask = 0; mask < totalStates; mask++) {
            if (dpSessions[mask] == Integer.MAX_VALUE) continue;

            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) {
                    int nextMask = mask | (1 << i);
                    int newSessions = dpSessions[mask];
                    int newTime;

                    if (dpTime[mask] + tasks[i] <= sessionTime) {
                        newTime = dpTime[mask] + tasks[i];
                    } else {
                        newSessions++;
                        newTime = tasks[i];
                    }

                    if (newSessions < dpSessions[nextMask] || 
                       (newSessions == dpSessions[nextMask] && newTime < dpTime[nextMask])) {
                        dpSessions[nextMask] = newSessions;
                        dpTime[nextMask] = newTime;
                    }
                }
            }
        }

        return dpSessions[totalStates - 1];
    }
}

class Solution {
    public int minSessions(int[] tasks, int sessionTime) {
        int n = tasks.length;
        int m = 1 << n;
        int[] sum = new int[m];
        for (int mask = 1; mask < m; mask++) {
            int bit = Integer.numberOfTrailingZeros(mask);
            sum[mask] = sum[mask ^ (1 << bit)] + tasks[bit];
        }

        int[] dp = new int[m];
        final int INF = 1 << 30;
        for (int i = 1; i < m; i++) dp[i] = INF;
        dp[0] = 0;

        for (int mask = 1; mask < m; mask++) {
            for (int sub = mask; sub > 0; sub = (sub - 1) & mask) {
                if (sum[sub] <= sessionTime) {
                    dp[mask] = Math.min(dp[mask], dp[mask ^ sub] + 1);
                }
            }
        }
        return dp[m - 1];
    }
}

class Solution {
    public int minSessions(int[] tasks, int sessionTime) {
        int n = tasks.length;
        int full = 1 << n;
        int[] sess = new int[full];
        int[] rem = new int[full];
        java.util.Arrays.fill(sess, Integer.MAX_VALUE);
        sess[0] = 1;
        rem[0] = sessionTime;
        for (int mask = 0; mask < full; mask++) {
            if (sess[mask] == Integer.MAX_VALUE) continue;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                int nm = mask | (1 << i);
                int ns, nr;
                if (rem[mask] >= tasks[i]) {
                    ns = sess[mask];
                    nr = rem[mask] - tasks[i];
                } else {
                    ns = sess[mask] + 1;
                    nr = sessionTime - tasks[i];
                }
                if (ns < sess[nm] || (ns == sess[nm] && nr > rem[nm])) {
                    sess[nm] = ns;
                    rem[nm] = nr;
                }
            }
        }
        return sess[full - 1];
    }
}

class Solution {
    public int minSessions(int[] tasks, int sessionTime) {
        int n = tasks.length;
        int totalMasks = 1 << n;
        int[] sessions = new int[totalMasks];
        int[] usedTime = new int[totalMasks];

        java.util.Arrays.fill(sessions, n + 1);
        java.util.Arrays.fill(usedTime, sessionTime + 1);

        sessions[0] = 1;
        usedTime[0] = 0;

        for (int mask = 0; mask < totalMasks; mask++) {
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    continue;
                }

                int nextMask = mask | (1 << i);
                int nextSessions = sessions[mask];
                int nextUsedTime;

                if (usedTime[mask] + tasks[i] <= sessionTime) {
                    nextUsedTime = usedTime[mask] + tasks[i];
                } else {
                    nextSessions++;
                    nextUsedTime = tasks[i];
                }

                if (nextSessions < sessions[nextMask]
                        || (nextSessions == sessions[nextMask]
                        && nextUsedTime < usedTime[nextMask])) {
                    sessions[nextMask] = nextSessions;
                    usedTime[nextMask] = nextUsedTime;
                }
            }
        }

        return sessions[totalMasks - 1];
    }
}

