var minSubsequence = function(nums) {
    nums.sort((a, b) => b - a);

    const total = nums.reduce((sum, num) => sum + num, 0);
    const result = [];
    let currentSum = 0;

    for (const num of nums) {
        result.push(num);
        currentSum += num;

        if (currentSum > total - currentSum) {
            break;
        }
    }

    return result;
};

