class Solution {
public:
    vector<int> minSubsequence(vector<int>& nums) {
        sort(nums.begin(), nums.end(), greater<int>());
        int total = 0;
        for (int x : nums) total += x;

        vector<int> ans;
        int cur = 0;
        for (int x : nums) {
            ans.push_back(x);
            cur += x;
            if (cur > total - cur) break;
        }
        return ans;
    }
};

