        java.util.Arrays.fill(ans, -1);
        java.util.Deque<Integer> stack = new java.util.ArrayDeque<>(); // indices

        for (int i = 0; i < 2 * n; i++) {
            int idx = i % n;
            while (!stack.isEmpty() && nums[stack.peek()] < nums[idx]) {
                ans[stack.pop()] = nums[idx];
            }
            if (i < n) stack.push(idx);
        }

        return ans;
    }
}

