var nextBeautifulNumber = function(n) {
    const set = new Set();
    const counts = new Array(8).fill(0);

    // Generate every unique arrangement of the currently chosen digits.
    // Each root-to-leaf path corresponds to exactly one digit string.
    const build = (num, len) => {
        if (len === 0) {
            set.add(num);
            return;
        }
        for (let d = 1; d <= 7; d++) {
            if (counts[d] > 0) {
                counts[d]--;
                build(num * 10 + d, len - 1);
                counts[d]++;
            }
        }
    };

    // Pick a subset of digits {1..7}; digit d is used exactly d times.
    // Total length capped at 7 digits: the smallest 7-digit balanced number
    // is 1224444, which already exceeds the maximum possible n = 10^6.
    const choose = (d, total) => {
        if (d > 7) {
            if (total > 0) build(0, total);
            return;
        }
        choose(d + 1, total); // skip digit d
        if (total + d <= 7) {
            counts[d] = d;
            choose(d + 1, total + d); // use digit d exactly d times
            counts[d] = 0;
        }
    };

    choose(1, 0);

    const list = Array.from(set).sort((a, b) => a - b);

    // Binary search: smallest balanced number strictly greater than n.
    let lo = 0, hi = list.length - 1, ans = list[list.length - 1];
    while (lo <= hi) {
        const mid = (lo + hi) >> 1;
        if (list[mid] > n) {
            ans = list[mid];
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }
    return ans;
};

