class Solution {
public:
    int daysBetweenDates(string date1, string date2) {
        return abs(toDays(date1) - toDays(date2));
    }

private:
    static bool isLeap(int y) {
        return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
    }

    static int toDays(const string& date) {
        int y = stoi(date.substr(0, 4));
        int m = stoi(date.substr(5, 2));
        int d = stoi(date.substr(8, 2));

        static const int cum[12] = {0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334};

        // Days for all complete years before y (using Gregorian leap rule)
        int days = 365 * (y - 1) + (y - 1) / 4 - (y - 1) / 100 + (y - 1) / 400;

        // Days for complete months in current year + day of month
        days += cum[m - 1] + d;

        // Account for Feb 29 of a leap year if we've passed February
        if (m > 2 && isLeap(y)) days += 1;

        return days;
    }
};

