 * @param {number[]} nums
 * @return {number}
 */
var numOfWays = function(nums) {
    const n = nums.length;
    const MOD_NUM = 1000000007;
    const MOD = 1000000007n;

    const comb = Array.from({ length: n + 1 }, () => Array(n + 1).fill(0));
    for (let i = 0; i <= n; i++) {
        comb[i][0] = 1;
        comb[i][i] = 1;
        for (let j = 1; j < i; j++) {
            let val = comb[i - 1][j - 1] + comb[i - 1][j];
            if (val >= MOD_NUM) val -= MOD_NUM;
            comb[i][j] = val;
        }
    }

    const dfs = (arr) => {
        const len = arr.length;
        if (len <= 2) return 1n;

        const root = arr[0];
        const left = [];
        const right = [];

        for (let i = 1; i < len; i++) {
            if (arr[i] < root) left.push(arr[i]);
            else right.push(arr[i]);
        }

        const leftWays = dfs(left);
        const rightWays = dfs(right);
        const chooseWays = BigInt(comb[len - 1][left.length]);

        return (((chooseWays * leftWays) % MOD) * rightWays) % MOD;
    };

    return Number((dfs(nums) - 1n + MOD) % MOD);
};

