            if (arr[i] < root) {
                left.push(arr[i]);
            } else {
                right.push(arr[i]);
            }
        }

        const leftWays = dfs(left);
        const rightWays = dfs(right);

        let result = (BigInt(leftWays) * BigInt(rightWays)) % MODBI;
        result = (result * BigInt(comb[arr.length - 1][left.length])) % MODBI;

        return Number(result);
    };

    const ways = dfs(nums);
    return (ways - 1 + MOD) % MOD;
};

