var numOfWays = function(nums) {
    const MOD = 1000000007n;
    const n = nums.length;
    const N = n + 1;
    const C = new Int32Array(N * N);
    for (let i = 0; i <= n; i++) {
        C[i * N] = 1;
        for (let j = 1; j <= i; j++) {
            C[i * N + j] = (C[(i - 1) * N + j - 1] + C[(i - 1) * N + j]) % 1000000007;
        }
    }
    const ways = (arr) => {
        if (arr.length <= 2) return 1n;
        const root = arr[0];
        const left = [], right = [];
        for (let i = 1; i < arr.length; i++) {
            if (arr[i] < root) left.push(arr[i]); else right.push(arr[i]);
        }
        const total = arr.length - 1;
        let res = BigInt(C[total * N + left.length]);
        res = res * ways(left) % MOD;
        res = res * ways(right) % MOD;
        return res;
    };
    return Number((ways(nums) - 1n + MOD) % MOD);
};

var numOfWays = function(nums) {
    const MOD = 1000000007;
    const n = nums.length;

    const C = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(0));
    for (let i = 0; i <= n; i++) {
        C[i][0] = 1;
        for (let j = 1; j <= i; j++) {
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
        }
    }

    function mul(a, b) {
        const a1 = Math.floor(a / 32768);
        const a0 = a - a1 * 32768;
        return ((a1 * b % MOD) * 32768 + a0 * b) % MOD;
    }

    function count(arr) {
        const m = arr.length;
        if (m <= 2) return 1;
        const root = arr[0];
        let lSize = 0;
        for (let i = 1; i < m; i++) {
            if (arr[i] < root) lSize++;
        }
        const left = new Array(lSize);
        const right = new Array(m - 1 - lSize);
        let li = 0, ri = 0;
        for (let i = 1; i < m; i++) {
            if (arr[i] < root) left[li++] = arr[i];
            else right[ri++] = arr[i];
        }
        return mul(C[m - 1][lSize], mul(count(left), count(right)));
    }

    return (count(nums) - 1 + MOD) % MOD;
};

