    private long dfs(int[] arr, int len) {
        if (len <= 1) {
            return 1;
        }

        int root = arr[0];
        int[] left = new int[len - 1];
        int[] right = new int[len - 1];
        int lc = 0;
        int rc = 0;

        for (int i = 1; i < len; i++) {
            if (arr[i] < root) {
                left[lc++] = arr[i];
            } else {
                right[rc++] = arr[i];
            }
        }

