        for (Map.Entry<Long, Long> ae : aFreq.entrySet()) {
            long sq = ae.getKey() * ae.getKey();
            long ways = 0;
            for (Map.Entry<Long, Long> e : freq.entrySet()) {
                long v = e.getKey();
                if (sq % v != 0) continue;
                long c = sq / v;
                if (c == v) {
                    long cnt = e.getValue();
                    ways += cnt * (cnt - 1) / 2;
                } else if (c > v) {
                    Long cc = freq.get(c);
                    if (cc != null) {
                        ways += e.getValue() * cc;
                    }
                }
            }
            total += ways * ae.getValue();
        }
        return total;
    }
}

class Solution {
    public int numTriplets(int[] nums1, int[] nums2) {
        long result = countTriplets(nums1, nums2) + countTriplets(nums2, nums1);
        return (int) result;
    }

    private long countTriplets(int[] squaredNumbers, int[] factors) {
        java.util.Map<Long, Integer> squareFrequency = new java.util.HashMap<>();

        for (int number : squaredNumbers) {
            long square = (long) number * number;
            squareFrequency.merge(square, 1, Integer::sum);
        }

        long count = 0;

        for (int j = 0; j < factors.length; j++) {
            for (int k = j + 1; k < factors.length; k++) {
                long product = (long) factors[j] * factors[k];
                count += squareFrequency.getOrDefault(product, 0);
            }
        }

        return count;
    }
}

class Solution {
    public int numTriplets(int[] nums1, int[] nums2) {
        return count(nums1, nums2) + count(nums2, nums1);
    }

    private int count(int[] a, int[] b) {
        int res = 0;
        for (int i = 0; i < a.length; i++) {
            long sq = (long) a[i] * a[i];
            for (int j = 0; j < b.length; j++) {
                for (int k = j + 1; k < b.length; k++) {
                    if ((long) b[j] * b[k] == sq) res++;
                }
            }
        }
        return res;
    }
}

