        for (int mask = 0; mask < size; mask++) {
            if (dp[mask] == -1) {
                continue;
            }

            for (int i = 0; i < nums.length; i++) {
                int bit = 1 << i;
                if ((mask & bit) == 0 && dp[mask] + nums[i] <= target) {
                    dp[mask | bit] = (dp[mask] + nums[i]) % target;
                }
            }
        }

        return dp[size - 1] == 0;
    }
}

class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int n = nums.length;
        int sum = 0;
        for (int num : nums) {
            sum += num;
        }
        if (sum % k != 0) {
            return false;
        }
        int target = sum / k;
        int[] sums = new int[1 << n];
        for (int mask = 1; mask < (1 << n); mask++) {
            int i = Integer.numberOfTrailingZeros(mask);
            sums[mask] = sums[mask ^ (1 << i)] + nums[i];
        }
        boolean[] dp = new boolean[1 << n];
        dp[0] = true;
        for (int mask = 0; mask < (1 << n); mask++) {
            if (!dp[mask]) {
                continue;
            }
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) {
                    if (sums[mask] % target + nums[i] <= target) {
                        dp[mask | (1 << i)] = true;
                    }
                }
            }
        }
        return dp[(1 << n) - 1];
    }
}

var maxSizeSlices = function(slices) {
    const m = slices.length;
    const n = Math.floor(m / 3);

    const maxPick = (arr, k) => {
        const len = arr.length;
        const NEG = -1e9;
        const dp = Array.from({ length: len + 1 }, () => new Array(k + 1).fill(NEG));

        for (let i = 0; i <= len; i++) {
            dp[i][0] = 0;
        }

        for (let i = 1; i <= len; i++) {
            const limit = Math.min(k, Math.floor((i + 1) / 2));
            for (let j = 1; j <= limit; j++) {
                dp[i][j] = dp[i - 1][j];

                if (i >= 2) {
                    dp[i][j] = Math.max(dp[i][j], dp[i - 2][j - 1] + arr[i - 1]);
                } else if (j === 1) {
                    dp[i][j] = Math.max(dp[i][j], arr[0]);
                }
            }
        }

        return dp[len][k];
    };

    return Math.max(
        maxPick(slices.slice(0, m - 1), n),
        maxPick(slices.slice(1), n)
    );
};

