var maxSizeSlices = function(slices) {
    const m = slices.length;
    const n = m / 3;

    // Max sum of exactly k pairwise non-adjacent elements in a linear array.
    const bestLinear = (arr, k) => {
        const len = arr.length;
        // dp[j][i] = max sum picking exactly j non-adjacent elements from arr[0..i-1]
        const dp = Array.from({ length: k + 1 }, () => new Array(len + 1).fill(-Infinity));
        for (let i = 0; i <= len; i++) dp[0][i] = 0;
        for (let j = 1; j <= k; j++) {
            for (let i = 1; i <= len; i++) {
                let take = -Infinity;
                if (i >= 2) {
                    take = dp[j - 1][i - 2] + arr[i - 1];
                } else if (j === 1) {
                    take = arr[0];
                }
                dp[j][i] = Math.max(dp[j][i - 1], take);
            }
        }
        return dp[k][len];
    };

    // Picking a slice removes it and both neighbors, so the picked slices
    // form an independent set of size n on the circle. Slices 0 and m-1 are
    // adjacent, so at least one of them is never picked: try both linear cases.
    return Math.max(
        bestLinear(slices.slice(0, m - 1), n),
        bestLinear(slices.slice(1), n)
    );
};

