    const bestLinear = (arr: number[]): number => {
        const len = arr.length;
        const NEG = -Infinity;
        let dpPrev2 = new Array<number>(n + 1).fill(NEG); // dp[i-2][*]
        let dpPrev1 = new Array<number>(n + 1).fill(NEG); // dp[i-1][*]
        dpPrev2[0] = 0;
        dpPrev1[0] = 0;
        dpPrev1[1] = arr[0];
