            const dpCur = new Array<number>(n + 1).fill(NEG);
            const v = arr[i - 1];
            for (let j = 0; j <= n; j++) {
                let bestVal = dpPrev1[j];
                if (j > 0) {
                    const take = dpPrev2[j - 1] + v;
                    if (take > bestVal) bestVal = take;
                }
                dpCur[j] = bestVal;
            }
            dpPrev2 = dpPrev1;
            dpPrev1 = dpCur;
        }
        return dpPrev1[n];
    };

    return Math.max(
        bestLinear(slices.slice(0, m - 1)),
        bestLinear(slices.slice(1))
    );
