        int len = hi - lo + 1;
        int NEG = -1000000000;
        int[][] dp = new int[len + 2][n + 1];
        for (int i = 0; i < len + 2; i++) {
            for (int j = 1; j <= n; j++) dp[i][j] = NEG;
            dp[i][0] = 0;
        }
        for (int i = 1; i <= len; i++) {
            int v = s[lo + i - 1];
            for (int j = 1; j <= n; j++) {
                int best = dp[i][j];
                int prev = dp[i - 1][j - 1];
                if (prev > NEG / 2) best = Math.max(best, prev + v);
                dp[i + 1][j] = best;
            }
        }
        return dp[len + 1][n];
    }
