        return Math.max(solve(slices, 0, n - 2, k), solve(slices, 1, n - 1, k));
    }

    private int solve(int[] slices, int start, int end, int k) {
        int len = end - start + 1;
        int[][] dp = new int[len + 1][k + 1];

        for (int i = 1; i <= len; i++) {
            int val = slices[start + i - 1];
            for (int j = 1; j <= k; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], (i >= 2 ? dp[i - 2][j - 1] : 0) + val);
            }
        }
        return dp[len][k];
    }
