/**
 * @param {string[]} grid
 * @return {number}
 */
var regionsBySlashes = function(grid) {
    const n = grid.length;
    const size = n * 3;
    const g = Array.from({ length: size }, () => new Uint8Array(size));

    // Upscale each 1x1 cell to 3x3
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            const char = grid[i][j];
            const r = i * 3;
            const c = j * 3;

            if (char === '/') {
                g[r][c + 2] = 1;
                g[r + 1][c + 1] = 1;
                g[r + 2][c] = 1;
            } else if (char === '\\') {
                g[r][c] = 1;
                g[r + 1][c + 1] = 1;
                g[r + 2][c + 2] = 1;
            }
        }
    }

    // Flood fill using BFS to count connected components of 0s
    let regions = 0;
    const dirs = [-1, 0, 1, 0, -1];

    for (let i = 0; i < size; i++) {
        for (let j = 0; j < size; j++) {
            if (g[i][j] === 0) {
                regions++;
                const queue = [i * size + j];
                g[i][j] = 1;

                let head = 0;
                while (head < queue.length) {
                    const curr = queue[head++];
                    const r = Math.floor(curr / size);
                    const c = curr % size;

                    for (let d = 0; d < 4; d++) {
                        const nr = r + dirs[d];
                        const nc = c + dirs[d + 1];

                        if (nr >= 0 && nr < size && nc >= 0 && nc < size && g[nr][nc] === 0) {
                            g[nr][nc] = 1;
                            queue.push(nr * size + nc);
                        }
                    }
                }
            }
        }
    }

    return regions;
};

/**
 * @param {string[]} grid
 * @return {number}
 */
var regionsBySlashes = function(grid) {
    const n = grid.length;
    const total = n * n * 4;
    const parent = new Int32Array(total);
    const rank = new Int32Array(total);

    for (let i = 0; i < total; i++) parent[i] = i;

    let regions = total;

    const find = (x) => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    const union = (a, b) => {
        const rootA = find(a);
        const rootB = find(b);

        if (rootA === rootB) return;

        if (rank[rootA] < rank[rootB]) {
            parent[rootA] = rootB;
        } else if (rank[rootA] > rank[rootB]) {
            parent[rootB] = rootA;
        } else {
            parent[rootB] = rootA;
            rank[rootA]++;
        }

        regions--;
    };

    const index = (r, c, part) => {
        return (r * n + c) * 4 + part;
    };

    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            const ch = grid[r][c];

            const top = index(r, c, 0);
            const right = index(r, c, 1);
            const bottom = index(r, c, 2);
            const left = index(r, c, 3);

            if (ch === ' ') {
                union(top, right);
                union(right, bottom);
                union(bottom, left);
            } else if (ch === '/') {
                union(top, left);
                union(right, bottom);
            } else {
                union(top, right);
                union(bottom, left);
            }

            if (r + 1 < n) {
                union(bottom, index(r + 1, c, 0));
            }

            if (c + 1 < n) {
                union(right, index(r, c + 1, 3));
            }
        }
    }

    return regions;
};

/**
 * @param {string[]} grid
 * @return {number}
 */
var regionsBySlashes = function(grid) {
    const n = grid.length;
    const size = 3 * n;
    const wall = Array.from({ length: size }, () => new Array(size).fill(false));

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            const ch = grid[i][j];
            const r = i * 3;
            const c = j * 3;

            if (ch === '/') {
                wall[r][c + 2] = true;
                wall[r + 1][c + 1] = true;
                wall[r + 2][c] = true;
            } else if (ch === '\\') {
                wall[r][c] = true;
                wall[r + 1][c + 1] = true;
                wall[r + 2][c + 2] = true;
            }
        }
    }

    const visited = Array.from({ length: size }, () => new Array(size).fill(false));
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    let regions = 0;

    for (let i = 0; i < size; i++) {
        for (let j = 0; j < size; j++) {
            if (!wall[i][j] && !visited[i][j]) {
                regions++;
                const queue = [[i, j]];
                visited[i][j] = true;
                let head = 0;

                while (head < queue.length) {
                    const [x, y] = queue[head++];

                    for (const [dx, dy] of dirs) {
                        const nx = x + dx;
                        const ny = y + dy;

                        if (
                            nx >= 0 && nx < size &&
                            ny >= 0 && ny < size &&
                            !wall[nx][ny] &&
                            !visited[nx][ny]
                        ) {
                            visited[nx][ny] = true;
                            queue.push([nx, ny]);
                        }
                    }
                }
            }
        }
    }

    return regions;
};

/**
 * @param {string[]} grid
 * @return {number}
 */
var regionsBySlashes = function(grid) {
    const n = grid.length;
    const p = new Array(n * n * 4);
    for (let i = 0; i < p.length; i++) p[i] = i;
    let count = p.length;
    const find = (x) => {
        while (p[x] !== x) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    };
    const union = (a, b) => {
        a = find(a);
        b = find(b);
        if (a !== b) {
            p[a] = b;
            count--;
        }
    };
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            const base = (i * n + j) * 4;
            const c = grid[i][j];
            if (c === ' ') {
                union(base, base + 1);
                union(base + 1, base + 2);
                union(base + 2, base + 3);
            } else if (c === '/') {
                union(base, base + 3);
                union(base + 1, base + 2);
            } else {
                union(base, base + 1);
                union(base + 2, base + 3);
            }
            if (i + 1 < n) {
                union(base + 2, ((i + 1) * n + j) * 4);
            }
            if (j + 1 < n) {
                union(base + 1, (i * n + j + 1) * 4 + 3);
            }
        }
    }
    return count;
};

/**
