        vector<vector<int>> g(N, vector<int>(N, 0));
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int r = i * 3, c = j * 3;
                if (grid[i][j] == '/') {
                    g[r][c + 2] = 1;
                    g[r + 1][c + 1] = 1;
                    g[r + 2][c] = 1;
                } else if (grid[i][j] == '\\') {
                    g[r][c] = 1;
                    g[r + 1][c + 1] = 1;
                    g[r + 2][c + 2] = 1;
                }
            }
        }
        int ans = 0;
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                if (g[i][j] == 0) {
                    ++ans;
                    dfs(g, i, j, N);
                }
            }
        }
        return ans;
    }
private:
    void dfs(vector<vector<int>>& g, int x, int y, int N) {
        if (x < 0 || x >= N || y < 0 || y >= N || g[x][y] == 1) return;
        g[x][y] = 1;
        dfs(g, x - 1, y, N);
        dfs(g, x + 1, y, N);
        dfs(g, x, y - 1, N);
        dfs(g, x, y + 1, N);
    }
};

