class Solution {
public:
    int regionsBySlashes(vector<string>& grid) {
        int n = grid.size();
        int regions = 4 * n * n;
        vector<int> parent(regions), size(regions, 1);
        iota(parent.begin(), parent.end(), 0);

        auto find = [&](int x) {
            while (x != parent[x]) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        };

        auto unite = [&](int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return;
            if (size[a] < size[b]) swap(a, b);
            parent[b] = a;
            size[a] += size[b];
            --regions;
        };

        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < n; ++c) {
                // Each cell has four triangles: top, right, bottom, left.
                int base = 4 * (r * n + c);

                if (grid[r][c] != '/') {
                    unite(base, base + 1);
                    unite(base + 2, base + 3);
                }
                if (grid[r][c] != '\\') {
                    unite(base, base + 3);
                    unite(base + 1, base + 2);
                }

                if (r + 1 < n)
                    unite(base + 2, base + 4 * n);
                if (c + 1 < n)
                    unite(base + 1, base + 7);
            }
        }

        return regions;
    }
};

class Solution {
    public int regionsBySlashes(String[] grid) {
        int n = grid.length;
        int m = n * 3;
        boolean[][] blocked = new boolean[m][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                char c = grid[i].charAt(j);
                int r = i * 3;
                int col = j * 3;
                if (c == '/') {
                    blocked[r][col + 2] = true;
                    blocked[r + 1][col + 1] = true;
                    blocked[r + 2][col] = true;
                } else if (c == '\\') {
                    blocked[r][col] = true;
                    blocked[r + 1][col + 1] = true;
                    blocked[r + 2][col + 2] = true;
                }
            }
        }

        boolean[][] visited = new boolean[m][m];
        int regions = 0;
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};
        int[] queue = new int[m * m];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                if (blocked[i][j] || visited[i][j]) {
                    continue;
                }

                regions++;
                int head = 0, tail = 0;
                queue[tail++] = i * m + j;
                visited[i][j] = true;

                while (head < tail) {
                    int cur = queue[head++];
                    int r = cur / m;
                    int c = cur % m;

                    for (int d = 0; d < 4; d++) {
                        int nr = r + dr[d];
                        int nc = c + dc[d];
                        if (nr >= 0 && nr < m && nc >= 0 && nc < m
                                && !blocked[nr][nc] && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            queue[tail++] = nr * m + nc;
                        }
                    }
                }
            }
        }

        return regions;
    }
}

