class Solution {
    public int regionsBySlashes(String[] grid) {
        int n = grid.length;
        int size = 4 * n * n;
        int[] parent = new int[size];
        int[] rank = new int[size];
        int count = size;
        for (int i = 0; i < size; i++) {
            parent[i] = i;
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int root = 4 * (i * n + j);
                char c = grid[i].charAt(j);
                if (c == '/') {
                    count = union(parent, rank, count, root + 0, root + 3);
                    count = union(parent, rank, count, root + 1, root + 2);
                } else if (c == '\\') {
                    count = union(parent, rank, count, root + 0, root + 1);
                    count = union(parent, rank, count, root + 2, root + 3);
                } else {
                    count = union(parent, rank, count, root + 0, root + 1);
                    count = union(parent, rank, count, root + 1, root + 2);
                    count = union(parent, rank, count, root + 2, root + 3);
                }
                if (j + 1 < n) {
                    int right = 4 * (i * n + j + 1);
                    count = union(parent, rank, count, root + 1, right + 3);
                }
                if (i + 1 < n) {
                    int down = 4 * ((i + 1) * n + j);
                    count = union(parent, rank, count, root + 2, down + 0);
                }
            }
        }
        return count;
    }

    private int find(int[] parent, int x) {
        if (parent[x] != x) {
            parent[x] = find(parent, parent[x]);
        }
        return parent[x];
    }

    private int union(int[] parent, int[] rank, int count, int x, int y) {
        int px = find(parent, x);
        int py = find(parent, y);
        if (px == py) {
            return count;
        }
        if (rank[px] < rank[py]) {
            parent[px] = py;
        } else if (rank[px] > rank[py]) {
            parent[py] = px;
        } else {
            parent[py] = px;
            rank[px]++;
        }
        return count - 1;
    }
}

class Solution {
    public int regionsBySlashes(String[] grid) {
        int n = grid.length;
        int total = 4 * n * n;
        int[] parent = new int[total];
        int[] rank = new int[total];

        for (int i = 0; i < total; i++) {
            parent[i] = i;
        }

        int regions = total;

        for (int row = 0; row < n; row++) {
            for (int col = 0; col < n; col++) {
                // Triangle indices: top, right, bottom, left.
                int base = 4 * (row * n + col);
                char ch = grid[row].charAt(col);

                if (ch != '/') {
                    regions -= union(parent, rank, base, base + 1);
                    regions -= union(parent, rank, base + 2, base + 3);
                }

                if (ch != '\\') {
                    regions -= union(parent, rank, base, base + 3);
                    regions -= union(parent, rank, base + 1, base + 2);
                }

                if (col + 1 < n) {
                    regions -= union(parent, rank, base + 1, base + 7);
                }

                if (row + 1 < n) {
                    regions -= union(parent, rank, base + 2, base + 4 * n);
                }
            }
        }

        return regions;
    }

    private int find(int[] parent, int node) {
        if (parent[node] != node) {
            parent[node] = find(parent, parent[node]);
        }
        return parent[node];
    }

    private int union(int[] parent, int[] rank, int a, int b) {
        int rootA = find(parent, a);
        int rootB = find(parent, b);

        if (rootA == rootB) {
            return 0;
        }

        if (rank[rootA] < rank[rootB]) {
            parent[rootA] = rootB;
        } else if (rank[rootA] > rank[rootB]) {
            parent[rootB] = rootA;
        } else {
            parent[rootB] = rootA;
            rank[rootA]++;
        }

        return 1;
    }
}

