class Solution {
    public int regionsBySlashes(String[] grid) {
        int n = grid.length;
        DSU dsu = new DSU(n * n * 4);

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int base = (i * n + j) * 4;
                char c = grid[i].charAt(j);

                if (c == ' ') {
                    dsu.union(base, base + 1);
                    dsu.union(base + 1, base + 2);
                    dsu.union(base + 2, base + 3);
                } else if (c == '/') {
                    dsu.union(base, base + 3);
                    dsu.union(base + 1, base + 2);
                } else {
                    dsu.union(base, base + 1);
                    dsu.union(base + 2, base + 3);
                }

                if (i + 1 < n) {
                    int below = ((i + 1) * n + j) * 4;
                    dsu.union(base + 2, below);
                }

                if (j + 1 < n) {
                    int right = (i * n + j + 1) * 4;
                    dsu.union(base + 1, right + 3);
                }
            }
        }

        return dsu.count;
    }

    private static class DSU {
        int[] parent;
        int[] rank;
        int count;

        DSU(int size) {
            parent = new int[size];
            rank = new int[size];
            count = size;

            for (int i = 0; i < size; i++) {
                parent[i] = i;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);

            if (rootA == rootB) {
                return;
            }

            if (rank[rootA] < rank[rootB]) {
                parent[rootA] = rootB;
            } else if (rank[rootA] > rank[rootB]) {
                parent[rootB] = rootA;
            } else {
                parent[rootB] = rootA;
                rank[rootA]++;
            }

            count--;
        }
    }
}

