class Solution {
    public int regionsBySlashes(String[] grid) {
        int n = grid.length;
        int m = 3 * n;
        int total = m * m;
        int[] parent = new int[total];
        int[] rank = new int[total];
        for (int i = 0; i < total; i++) parent[i] = i;

        boolean[][] blocked = new boolean[m][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                char c = grid[i].charAt(j);
                if (c == '/') {
                    blocked[3 * i][3 * j + 2] = true;
                    blocked[3 * i + 1][3 * j + 1] = true;
                    blocked[3 * i + 2][3 * j] = true;
                } else if (c == '\\') {
                    blocked[3 * i][3 * j] = true;
                    blocked[3 * i + 1][3 * j + 1] = true;
                    blocked[3 * i + 2][3 * j + 2] = true;
                }
            }
        }

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < m; c++) {
                if (blocked[r][c]) continue;
                int idx = r * m + c;
                if (c + 1 < m && !blocked[r][c + 1]) {
                    union(parent, rank, idx, r * m + c + 1);
                }
                if (r + 1 < m && !blocked[r + 1][c]) {
                    union(parent, rank, idx, (r + 1) * m + c);
                }
            }
        }

        int count = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < m; c++) {
                if (!blocked[r][c] && find(parent, r * m + c) == r * m + c) {
                    count++;
                }
            }
        }
        return count;
    }

    private int find(int[] parent, int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    private void union(int[] parent, int[] rank, int a, int b) {
        int ra = find(parent, a);
        int rb = find(parent, b);
        if (ra == rb) return;
        if (rank[ra] < rank[rb]) {
            int t = ra;
            ra = rb;
            rb = t;
        }
        parent[rb] = ra;
        if (rank[ra] == rank[rb]) rank[ra]++;
    }
}

