class Solution {
public:
    vector<string> removeInvalidParentheses(string s) {
        // Compute minimum removals needed: l = unmatched '(', r = unmatched ')'
        int l = 0, r = 0;
        for (char c : s) {
            if (c == '(') {
                ++l;
            } else if (c == ')') {
                if (l > 0) --l;
                else ++r;
            }
        }
        unordered_set<string> uniqueResults;
        string current;
        current.reserve(s.size());
        dfs(s, 0, l, r, 0, current, uniqueResults);
        return vector<string>(uniqueResults.begin(), uniqueResults.end());
    }

private:
    // Try building every subsequence that removes exactly l '(' and r ')'.
    // Prune when the kept prefix would have more ')' than '(' (open < 0),
    // since such a prefix can never extend to a valid string.
    void dfs(const string& s, int idx, int l, int r, int open,
             string& current, unordered_set<string>& uniqueResults) {
        if (idx == (int)s.size()) {
            if (l == 0 && r == 0 && open == 0) {
                uniqueResults.insert(current);
            }
            return;
        }
        char c = s[idx];
        if (c == '(') {
            // Option 1: keep it
            current.push_back(c);
            dfs(s, idx + 1, l, r, open + 1, current, uniqueResults);
            current.pop_back();
            // Option 2: remove it (if budget remains)
            if (l > 0) {
                dfs(s, idx + 1, l - 1, r, open, current, uniqueResults);
            }
        } else if (c == ')') {
            // Option 1: keep it only if it doesn't break the prefix validity
            if (open > 0) {
                current.push_back(c);
                dfs(s, idx + 1, l, r, open - 1, current, uniqueResults);
                current.pop_back();
            }
            // Option 2: remove it (if budget remains)
            if (r > 0) {
                dfs(s, idx + 1, l, r - 1, open, current, uniqueResults);
            }
        } else {
            // Letters are always kept
            current.push_back(c);
            dfs(s, idx + 1, l, r, open, current, uniqueResults);
            current.pop_back();
        }
    }
};

