                    found = true;
                }

                if (found) continue;

                for (int j = 0; j < curr.size(); j++) {
                    if (curr[j] != '(' && curr[j] != ')') continue;

                    string next = curr.substr(0, j) + curr.substr(j + 1);
                    if (!visited.count(next)) {
