class Solution {
public:
    vector<string> removeInvalidParentheses(string s) {
        int leftRemove = 0, rightRemove = 0;
        for (char c : s) {
            if (c == '(') {
                leftRemove++;
            } else if (c == ')') {
                if (leftRemove > 0) leftRemove--;
                else rightRemove++;
            }
        }

        unordered_set<string> visited;
        vector<string> res;
        int n = (int)s.size();
        int best = -1;

        function<void(int,int,int,int,string&)> dfs = [&](int idx, int open, int lrem, int rrem, string& cur) {
            if (idx == n) {
                if (open == 0 && lrem == 0 && rrem == 0) {
                    if (best == -1 || (int)cur.size() > best) {
                        best = (int)cur.size();
                        res.clear();
                        res.push_back(cur);
                    } else if ((int)cur.size() == best) {
                        res.push_back(cur);
                    }
                }
                return;
            }

            char c = s[idx];
            int remaining = n - idx;
            if ((int)cur.size() + remaining < best) return;

            if (c == '(') {
                if (lrem > 0) {
                    dfs(idx + 1, open, lrem - 1, rrem, cur);
                }
                cur.push_back(c);
                dfs(idx + 1, open + 1, lrem, rrem, cur);
                cur.pop_back();
            } else if (c == ')') {
                if (rrem > 0) {
                    dfs(idx + 1, open, lrem, rrem - 1, cur);
                }
                if (open > 0) {
                    cur.push_back(c);
                    dfs(idx + 1, open - 1, lrem, rrem, cur);
                    cur.pop_back();
                }
            } else {
                cur.push_back(c);
                dfs(idx + 1, open, lrem, rrem, cur);
                cur.pop_back();
            }
        };

        string cur;
        dfs(0, 0, leftRemove, rightRemove, cur);

        unordered_set<string> uniq;
        vector<string> ans;
        for (auto &x : res) {
            if (uniq.insert(x).second) ans.push_back(x);
        }
        if (ans.empty()) ans.push_back("");
        return ans;
    }
};

class Solution {
public:
    vector<string> removeInvalidParentheses(string s) {
        int rmL = 0, rmR = 0;
        for (char c : s) {
            if (c == '(') rmL++;
            else if (c == ')') {
                if (rmL > 0) rmL--;
                else rmR++;
            }
        }
        vector<string> res;
        string cur;
        dfs(s, 0, rmL, rmR, 0, cur, res);
        return res;
    }

private:
    void dfs(const string& s, int idx, int rmL, int rmR, int open, string& cur, vector<string>& res) {
        if (rmL < 0 || rmR < 0 || open < 0) return;
        if (idx == (int)s.size()) {
            if (rmL == 0 && rmR == 0 && open == 0) res.push_back(cur);
            return;
        }
        char c = s[idx];
        if (c == '(') {
            // remove this '(' (only if it's the first in a run of identical chars)
            if (rmL > 0 && (idx == 0 || s[idx - 1] != '(')) {
                // skip consecutive '(' as a block for dedup: remove k of them
                int j = idx;
                while (j < (int)s.size() && s[j] == '(') j++;
                int run = j - idx;
                // choose how many to remove: k from 1..min(run, rmL)
                for (int k = 1; k <= run && k <= rmL; k++) {
                    int keep = run - k;
                    cur.append(keep, '(');
                    dfs(s, j, rmL - k, rmR, open + keep, cur, res);
                    cur.erase(cur.size() - keep);
                }
                // keep all
                cur.append(run, '(');
                dfs(s, j, rmL, rmR, open + run, cur, res);
                cur.erase(cur.size() - run);
            } else if (idx == 0 || s[idx - 1] != '(') {
                int j = idx;
                while (j < (int)s.size() && s[j] == '(') j++;
                int run = j - idx;
                cur.append(run, '(');
                dfs(s, j, rmL, rmR, open + run, cur, res);
                cur.erase(cur.size() - run);
            }
        } else if (c == ')') {
            if (idx == 0 || s[idx - 1] != ')') {
                int j = idx;
                while (j < (int)s.size() && s[j] == ')') j++;
                int run = j - idx;
                for (int k = 0; k <= run && k <= rmR; k++) {
                    int keep = run - k;
                    if (open - keep < 0) continue;
                    cur.append(keep, ')');
                    dfs(s, j, rmL, rmR - k, open - keep, cur, res);
                    cur.erase(cur.size() - keep);
                }
            }
        } else {
            cur.push_back(c);
            dfs(s, idx + 1, rmL, rmR, open, cur, res);
            cur.pop_back();
        }
    }
};

