                    char c = str.charAt(j);
                    if (c != '(' && c != ')') {
                        continue;
                    }
                    String next = str.substring(0, j) + str.substring(j + 1);
                    if (!visited.contains(next)) {
                        visited.add(next);
                        queue.offer(next);
                    }
                }
            }
        }
