import java.util.List;

class Solution {
    public List<String> removeInvalidParentheses(String s) {
        int rmClose = 0; // excess ')' that must be removed
        int rmOpen = 0;  // excess '(' that must be removed
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                rmOpen++;
            } else if (c == ')') {
                if (rmOpen > 0) {
                    rmOpen--;
                } else {
                    rmClose++;
                }
            }
        }
        List<String> result = new ArrayList<>();
        dfs(s, 0, rmClose, rmOpen, 0, false, new StringBuilder(), result);
        return result;
    }

    // prevRemoved: true iff the character at the previous index was removed
    // (used to keep removals canonical within runs of identical parens, avoiding duplicates)
    private void dfs(String s, int idx, int rmClose, int rmOpen, int open,
                     boolean prevRemoved, StringBuilder path, List<String> result) {
        if (idx == s.length()) {
            if (rmClose == 0 && rmOpen == 0 && open == 0) {
                result.add(path.toString());
            }
            return;
        }
        char c = s.charAt(idx);
        int len = path.length();
        if (c == '(') {
            // option 1: remove it (if budget remains and canonical rule allows)
            if (rmOpen > 0 && (idx == 0 || s.charAt(idx - 1) != '(' || prevRemoved)) {
                dfs(s, idx + 1, rmClose, rmOpen - 1, open, true, path, result);
            }
            // option 2: keep it
            path.append(c);
            dfs(s, idx + 1, rmClose, rmOpen, open + 1, false, path, result);
            path.setLength(len);
        } else if (c == ')') {
            // option 1: remove it (if budget remains and canonical rule allows)
            if (rmClose > 0 && (idx == 0 || s.charAt(idx - 1) != ')' || prevRemoved)) {
                dfs(s, idx + 1, rmClose - 1, rmOpen, open, true, path, result);
            }
            // option 2: keep it (only if it doesn't break prefix validity)
            if (open > 0) {
                path.append(c);
                dfs(s, idx + 1, rmClose, rmOpen, open - 1, false, path, result);
                path.setLength(len);
            }
        } else {
            path.append(c);
            dfs(s, idx + 1, rmClose, rmOpen, open, false, path, result);
            path.setLength(len);
        }
    }
}

