 * @param {string} s1
 * @param {string} s2
 * @return {boolean}
 */
var isScramble = function(s1, s2) {
    const memo = new Map();

    const helper = (a, b) => {
        if (a === b) return true;
        if (a.length !== b.length) return false;
        const key = a + '#' + b;
        if (memo.has(key)) return memo.get(key);

        const count = {};
        for (const c of a) count[c] = (count[c] || 0) + 1;
        for (const c of b) {
            if (!count[c]) { memo.set(key, false); return false; }
            count[c]--;
        }

        const n = a.length;
        for (let i = 1; i < n; i++) {
            if (helper(a.slice(0, i), b.slice(0, i)) && helper(a.slice(i), b.slice(i))) {
                memo.set(key, true);
                return true;
            }
            if (helper(a.slice(0, i), b.slice(n - i)) && helper(a.slice(i), b.slice(0, n - i))) {
                memo.set(key, true);
                return true;
            }
        }

        memo.set(key, false);
        return false;
    };

    return helper(s1, s2);
};

