        const len = a.length;
        if (len !== b.length) return false;
        if (len === 1) return a === b;

        const key = a + '#' + b;
        if (memo.has(key)) return memo.get(key);

        if (!sameChars(a, b)) {
            memo.set(key, false);
            return false;
        }

        for (let i = 1; i < len; i++) {
            if (
                solve(a.slice(0, i), b.slice(0, i)) &&
                solve(a.slice(i), b.slice(i))
            ) {
                memo.set(key, true);
                return true;
            }

            if (
                solve(a.slice(0, i), b.slice(len - i)) &&
                solve(a.slice(i), b.slice(0, len - i))
            ) {
                memo.set(key, true);
                return true;
            }
        }

        memo.set(key, false);
        return false;
    };

    return solve(s1, s2);
};

