    if (n !== s2.length) return false;
    if (s1 === s2) return true;
    const memo = new Map<string, boolean>();

    const helper = (i: number, j: number, len: number): boolean => {
        const key = i * 1000 * 100 + j * 100 + len;
        const k = key.toString();
        if (memo.has(k)) return memo.get(k)!;
        const a = s1.substr(i, len);
        const b = s2.substr(j, len);
        if (a === b) {
            memo.set(k, true);
            return true;
        }
        const cnt = new Array(26).fill(0);
        for (let t = 0; t < len; t++) {
            cnt[a.charCodeAt(t) - 97]++;
            cnt[b.charCodeAt(t) - 97]--;
        }
        for (let t = 0; t < 26; t++) {
            if (cnt[t] !== 0) {
                memo.set(k, false);
                return false;
            }
        }
        for (let l = 1; l < len; l++) {
            if (helper(i, j, l) && helper(i + l, j + l, len - l)) {
                memo.set(k, true);
                return true;
            }
            if (helper(i, j + len - l, l) && helper(i + l, j, len - l)) {
                memo.set(k, true);
                return true;
            }
        }
        memo.set(k, false);
        return false;
    };

    return helper(0, 0, n);
};

function isScramble(s1: string, s2: string): boolean {
    const memo = new Map<string, boolean>();

    function helper(a: string, b: string): boolean {
        if (a === b) return true;
        if (a.length !== b.length) return false;
        const key = a + "#" + b;
        if (memo.has(key)) return memo.get(key)!;

        const count = new Array(26).fill(0);
        for (let i = 0; i < a.length; i++) {
            count[a.charCodeAt(i) - 97]++;
            count[b.charCodeAt(i) - 97]--;
        }
        for (const c of count) {
            if (c !== 0) {
                memo.set(key, false);
                return false;
            }
        }

        const n = a.length;
        for (let i = 1; i < n; i++) {
            if (helper(a.slice(0, i), b.slice(0, i)) && helper(a.slice(i), b.slice(i))) {
                memo.set(key, true);
                return true;
            }
            if (helper(a.slice(0, i), b.slice(n - i)) && helper(a.slice(i), b.slice(0, n - i))) {
                memo.set(key, true);
                return true;
            }
        }

        memo.set(key, false);
        return false;
    }

    return helper(s1, s2);
};

function isScramble(s1: string, s2: string): boolean {
    const n = s1.length;
    if (n !== s2.length) return false;

    const prefix1 = Array.from({ length: n + 1 }, () => new Int32Array(26));
    const prefix2 = Array.from({ length: n + 1 }, () => new Int32Array(26));

    for (let i = 0; i < n; i++) {
        prefix1[i + 1].set(prefix1[i]);
        prefix2[i + 1].set(prefix2[i]);

        prefix1[i + 1][s1.charCodeAt(i) - 97]++;
        prefix2[i + 1][s2.charCodeAt(i) - 97]++;
    }

    const memo = new Uint8Array(n * n * (n + 1));

    const sameCharacters = (i: number, j: number, len: number): boolean => {
        for (let c = 0; c < 26; c++) {
            if (
                prefix1[i + len][c] - prefix1[i][c] !==
                prefix2[j + len][c] - prefix2[j][c]
            ) {
                return false;
            }
        }
        return true;
    };

    const index = (i: number, j: number, len: number): number =>
        (i * n + j) * (n + 1) + len;

    const dfs = (i: number, j: number, len: number): boolean => {
        const stateIndex = index(i, j, len);
        if (memo[stateIndex] !== 0) {
            return memo[stateIndex] === 1;
        }

        if (!sameCharacters(i, j, len)) {
            memo[stateIndex] = 2;
            return false;
        }

        if (len === 1) {
            const result = s1[i] === s2[j];
            memo[stateIndex] = result ? 1 : 2;
            return result;
        }

        for (let split = 1; split < len; split++) {
            if (
                (dfs(i, j, split) &&
                    dfs(i + split, j + split, len - split)) ||
                (dfs(i, j + len - split, split) &&
                    dfs(i + split, j, len - split))
            ) {
                memo[stateIndex] = 1;
                return true;
            }
        }

        memo[stateIndex] = 2;
        return false;
    };

    return dfs(0, 0, n);
};

class Solution {
public:
    bool isScramble(string s1, string s2) {
        int n = s1.size();
        vector<vector<vector<bool>>> dp(
            n + 1, vector<vector<bool>>(n, vector<bool>(n, false))
        );

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                dp[1][i][j] = (s1[i] == s2[j]);
            }
        }

        for (int len = 2; len <= n; ++len) {
            for (int i = 0; i + len <= n; ++i) {
                for (int j = 0; j + len <= n; ++j) {
                    for (int split = 1; split < len; ++split) {
                        bool unchanged =
                            dp[split][i][j] &&
                            dp[len - split][i + split][j + split];

                        bool swapped =
                            dp[split][i][j + len - split] &&
                            dp[len - split][i + split][j];

                        if (unchanged || swapped) {
                            dp[len][i][j] = true;
                            break;
                        }
                    }
                }
            }
        }

        return dp[n][0][0];
    }
};

class Solution {
public:
    bool isScramble(string s1, string s2) {
        int n = s1.size();
        if (s1 == s2) return true;

        vector<vector<vector<int>>> memo(n, vector<vector<int>>(n, vector<int>(n + 1, -1)));

        function<bool(int,int,int)> dfs = [&](int i, int j, int len) -> bool {
            int &res = memo[i][j][len];
            if (res != -1) return res;
            if (s1.compare(i, len, s2, j, len) == 0) return res = 1;

            int cnt[26] = {0};
            for (int k = 0; k < len; ++k) {
                cnt[s1[i + k] - 'a']++;
                cnt[s2[j + k] - 'a']--;
            }
            for (int c = 0; c < 26; ++c) {
                if (cnt[c] != 0) return res = 0;
            }

            for (int k = 1; k < len; ++k) {
                if (dfs(i, j, k) && dfs(i + k, j + k, len - k)) return res = 1;
                if (dfs(i, j + len - k, k) && dfs(i + k, j, len - k)) return res = 1;
            }
            return res = 0;
        };

        return dfs(0, 0, n);
    }
};

class Solution {
public:
    bool isScramble(string s1, string s2) {
        int n = s1.size();
        if (s2.size() != (size_t)n) return false;
        vector<vector<vector<char>>> dp(n + 1, vector<vector<char>>(n, vector<char>(n, 0)));
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                dp[1][i][j] = (s1[i] == s2[j]);
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len <= n; i++) {
                for (int j = 0; j + len <= n; j++) {
                    bool ok = false;
                    for (int k = 1; k < len && !ok; k++) {
                        if (dp[k][i][j] && dp[len - k][i + k][j + k]) ok = true;
                        else if (dp[k][i][j + len - k] && dp[len - k][i + k][j]) ok = true;
                    }
                    dp[len][i][j] = ok;
                }
            }
        }
        return dp[n][0][0];
    }
};

