using namespace std;

class Solution {
    int memo[31][31][31];

    bool solve(const string& s1, const string& s2, int i, int j, int len) {
        if (memo[i][j][len] != -1) return memo[i][j][len];

        if (len == 1) {
            return memo[i][j][len] = (s1[i] == s2[j]);
        }

        int count[26] = {0};
        for (int k = 0; k < len; ++k) {
            count[s1[i + k] - 'a']++;
            count[s2[j + k] - 'a']--;
        }
        for (int c = 0; c < 26; ++c) {
            if (count[c] != 0) {
                return memo[i][j][len] = 0;
            }
        }

        for (int k = 1; k < len; ++k) {
            // Case 1: No swap
            if (solve(s1, s2, i, j, k) && solve(s1, s2, i + k, j + k, len - k)) {
                return memo[i][j][len] = 1;
            }
            // Case 2: Swap
            if (solve(s1, s2, i, j + len - k, k) && solve(s1, s2, i + k, j, len - k)) {
                return memo[i][j][len] = 1;
            }
        }

        return memo[i][j][len] = 0;
    }

public:
    bool isScramble(string s1, string s2) {
        int n = s1.length();
        for (int i = 0; i <= n; ++i) {
            for (int j = 0; j <= n; ++j) {
                for (int len = 0; len <= n; ++len) {
                    memo[i][j][len] = -1;
                }
            }
        }
        return solve(s1, s2, 0, 0, n);
    }
};

class Solution {
public:
    unordered_map<string, bool> memo;

    bool isScramble(string s1, string s2) {
        if (s1 == s2) return true;
        if (s1.size() != s2.size()) return false;

        string key = s1 + "#" + s2;
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;

        int cnt[26] = {0};
        for (int i = 0; i < s1.size(); i++) {
            cnt[s1[i]-'a']++;
            cnt[s2[i]-'a']--;
        }
        for (int i = 0; i < 26; i++) {
            if (cnt[i] != 0) {
                memo[key] = false;
                return false;
            }
        }

        int n = s1.size();
        for (int i = 1; i < n; i++) {
            if (isScramble(s1.substr(0, i), s2.substr(0, i)) &&
                isScramble(s1.substr(i), s2.substr(i))) {
                memo[key] = true;
                return true;
            }
            if (isScramble(s1.substr(0, i), s2.substr(n-i)) &&
                isScramble(s1.substr(i), s2.substr(0, n-i))) {
                memo[key] = true;
                return true;
            }
        }

        memo[key] = false;
        return false;
    }
};

class Solution {
public:
    bool isScramble(string s1, string s2) {
        int n = s1.size();
        vector<vector<vector<int>>> memo(n + 1,
            vector<vector<int>>(n, vector<int>(n, -1)));
        return solve(s1, s2, 0, 0, n, memo);
    }

private:
    bool solve(const string& s1, const string& s2, int i, int j, int len,
               vector<vector<vector<int>>>& memo) {
        if (len == 1) return s1[i] == s2[j];
        int& m = memo[len][i][j];
        if (m != -1) return m;

        // If substrings are identical, identity scrambling works.
        if (s1.compare(i, len, s2, j, len) == 0) return m = 1;

        // Pruning: must be anagrams of each other.
        int cnt[26] = {0};
        for (int k = 0; k < len; ++k) {
            ++cnt[s1[i + k] - 'a'];
            --cnt[s2[j + k] - 'a'];
        }
        for (int k = 0; k < 26; ++k) {
            if (cnt[k] != 0) return m = 0;
        }

        for (int split = 1; split < len; ++split) {
            // No swap: left~left and right~right
            if (solve(s1, s2, i, j, split, memo) &&
                solve(s1, s2, i + split, j + split, len - split, memo))
                return m = 1;
            // Swap: left of s1 ~ right of s2, right of s1 ~ left of s2
            if (solve(s1, s2, i, j + len - split, split, memo) &&
                solve(s1, s2, i + split, j, len - split, memo))
                return m = 1;
        }
        return m = 0;
    }
};

class Solution {
public:
    string a, b;
    int n;
    vector<vector<vector<int>>> memo;

    bool dfs(int i, int j, int len) {
        if (memo[i][j][len] != -1) return memo[i][j][len];
        if (len == 1) return memo[i][j][len] = (a[i] == b[j]);

        int cnt[26] = {0};
        for (int k = 0; k < len; ++k) {
            ++cnt[a[i + k] - 'a'];
            --cnt[b[j + k] - 'a'];
        }
        for (int c = 0; c < 26; ++c) {
            if (cnt[c] != 0) return memo[i][j][len] = 0;
        }

        for (int k = 1; k < len; ++k) {
            if (dfs(i, j, k) && dfs(i + k, j + k, len - k))
                return memo[i][j][len] = 1;
            if (dfs(i, j + len - k, k) && dfs(i + k, j, len - k))
                return memo[i][j][len] = 1;
        }

        return memo[i][j][len] = 0;
    }

    bool isScramble(string s1, string s2) {
        if (s1.size() != s2.size()) return false;
        if (s1 == s2) return true;

        a = s1;
        b = s2;
        n = s1.size();
        memo.assign(n, vector<vector<int>>(n, vector<int>(n + 1, -1)));

        return dfs(0, 0, n);
    }
};

