class Solution {
public:
    bool isScramble(string s1, string s2) {
        int n = s1.size();
        if (n != (int)s2.size()) return false;

        vector<vector<vector<int>>> memo(
            n, vector<vector<int>>(n, vector<int>(n + 1, -1))
        );

        function<bool(int, int, int)> solve = [&](int i, int j, int len) -> bool {
            int &res = memo[i][j][len];
            if (res != -1) return res;

            if (s1.compare(i, len, s2, j, len) == 0)
                return res = true;

            int cnt[26] = {};
            for (int k = 0; k < len; ++k) {
                ++cnt[s1[i + k] - 'a'];
                --cnt[s2[j + k] - 'a'];
            }

            for (int c = 0; c < 26; ++c) {
                if (cnt[c] != 0)
                    return res = false;
            }

            for (int cut = 1; cut < len; ++cut) {
                if (solve(i, j, cut) &&
                    solve(i + cut, j + cut, len - cut)) {
                    return res = true;
                }

                if (solve(i, j + len - cut, cut) &&
                    solve(i + cut, j, len - cut)) {
                    return res = true;
                }
            }

            return res = false;
        };

        return solve(0, 0, n);
    }
};

class Solution {
    String a, b;
    byte[][][] memo;

    public boolean isScramble(String s1, String s2) {
        a = s1;
        b = s2;
        int n = s1.length();
        memo = new byte[n + 1][n][n];
        return solve(0, 0, n);
    }

    boolean solve(int i, int j, int len) {
        if (memo[len][i][j] != 0) return memo[len][i][j] == 1;
        boolean res = false;
        if (a.regionMatches(i, b, j, len)) {
            res = true;
        } else {
            int[] cnt = new int[26];
            for (int t = 0; t < len; t++) {
                cnt[a.charAt(i + t) - 'a']++;
                cnt[b.charAt(j + t) - 'a']--;
            }
            boolean ok = true;
            for (int c : cnt) if (c != 0) { ok = false; break; }
            if (ok) {
                for (int k = 1; k < len && !res; k++) {
                    if (solve(i, j, k) && solve(i + k, j + k, len - k)) res = true;
                    else if (solve(i, j + len - k, k) && solve(i + k, j, len - k)) res = true;
                }
            }
        }
        memo[len][i][j] = (byte) (res ? 1 : 2);
        return res;
    }
}

class Solution {
    private char[] a;
    private char[] b;
    private Boolean[][][] memo;

    public boolean isScramble(String s1, String s2) {
        if (s1.length() != s2.length()) return false;
        a = s1.toCharArray();
        b = s2.toCharArray();
        int n = a.length;
        memo = new Boolean[n][n][n + 1];
        return dfs(0, 0, n);
    }

    private boolean dfs(int i, int j, int len) {
        if (memo[i][j][len] != null) return memo[i][j][len];

        if (len == 1) {
            boolean result = a[i] == b[j];
            memo[i][j][len] = result;
            return result;
        }

        int[] count = new int[26];
        for (int p = 0; p < len; p++) {
            count[a[i + p] - 'a']++;
            count[b[j + p] - 'a']--;
        }
        for (int c : count) {
            if (c != 0) {
                memo[i][j][len] = false;
                return false;
            }
        }

        for (int k = 1; k < len; k++) {
            if (dfs(i, j, k) && dfs(i + k, j + k, len - k)) {
                memo[i][j][len] = true;
                return true;
            }
            if (dfs(i, j + len - k, k) && dfs(i + k, j, len - k)) {
                memo[i][j][len] = true;
                return true;
            }
