class Solution {
    public boolean isScramble(String s1, String s2) {
        int n = s1.length();
        if (n != s2.length()) return false;
        if (s1.equals(s2)) return true;

        // Quick anagram check
        int[] cnt = new int[26];
        for (int i = 0; i < n; i++) {
            cnt[s1.charAt(i) - 'a']++;
            cnt[s2.charAt(i) - 'a']--;
        }
        for (int c : cnt) {
            if (c != 0) return false;
        }

        // dp[len][i][j] = true if s1[i..i+len) is a scramble of s2[j..j+len)
        boolean[][][] dp = new boolean[n + 1][n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                dp[1][i][j] = s1.charAt(i) == s2.charAt(j);
            }
        }

        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len <= n; i++) {
                for (int j = 0; j + len <= n; j++) {
                    boolean res = false;
                    for (int k = 1; k < len && !res; k++) {
                        // No swap: left with left, right with right
                        if (dp[k][i][j] && dp[len - k][i + k][j + k]) {
                            res = true;
                        }
                        // Swap: left of s1 with right of s2, right of s1 with left of s2
                        else if (dp[k][i][j + len - k] && dp[len - k][i + k][j]) {
                            res = true;
                        }
                    }
                    dp[len][i][j] = res;
                }
            }
        }

        return dp[n][0][0];
    }
}

