        // Advance left pointer past products that no longer match the current prefix
        while (left <= right && (products[left].length <= i || products[left][i] !== c)) {
            left++;
        }
        // Retreat right pointer past products that no longer match the current prefix
        while (left <= right && (products[right].length <= i || products[right][i] !== c)) {
            right--;
        }
        // Collect up to 3 lexicographically smallest matches (products are sorted)
        const suggestions: string[] = [];
        for (let j = left; j <= right && suggestions.length < 3; j++) {
            suggestions.push(products[j]);
        }
        res.push(suggestions);
    }

    return res;
}

