class Solution {
    public List<List<String>> suggestedProducts(String[] products, String searchWord) {
        Arrays.sort(products);
        List<List<String>> res = new ArrayList<>();
        int left = 0, right = products.length - 1;

        for (int i = 0; i < searchWord.length(); i++) {
            char c = searchWord.charAt(i);

            while (left <= right && (products[left].length() <= i || products[left].charAt(i) != c)) left++;
            while (left <= right && (products[right].length() <= i || products[right].charAt(i) != c)) right--;

            List<String> curr = new ArrayList<>();
            for (int j = left; j <= right && j < left + 3; j++) {
                curr.add(products[j]);
            }
            res.add(curr);
        }

        return res;
    }
}

import java.util.*;

class Solution {
    public List<List<String>> suggestedProducts(String[] products, String searchWord) {
        String[] sorted = products.clone();
        Arrays.sort(sorted);

        List<List<String>> result = new ArrayList<>();
        int start = 0;
        StringBuilder prefix = new StringBuilder();

        for (int i = 0; i < searchWord.length(); i++) {
            prefix.append(searchWord.charAt(i));
            String p = prefix.toString();

            while (start < sorted.length && !sorted[start].startsWith(p)) {
                start++;
            }

            List<String> suggestions = new ArrayList<>();
            for (int j = start; j < sorted.length && suggestions.size() < 3; j++) {
                if (sorted[j].startsWith(p)) {
                    suggestions.add(sorted[j]);
                } else {
                    break;
                }
            }

            result.add(suggestions);
        }

        return result;
    }
}

import java.util.*;

class Solution {
    public List<List<String>> suggestedProducts(String[] products, String searchWord) {
        Arrays.sort(products);

        List<List<String>> result = new ArrayList<>();
        StringBuilder prefix = new StringBuilder();
        int start = 0;

        for (char c : searchWord.toCharArray()) {
            prefix.append(c);
            String currentPrefix = prefix.toString();

            start = lowerBound(products, currentPrefix, start);

            List<String> suggestions = new ArrayList<>();
            for (int i = start; i < products.length && suggestions.size() < 3; i++) {
                if (products[i].startsWith(currentPrefix)) {
                    suggestions.add(products[i]);
                } else {
                    break;
                }
            }

            result.add(suggestions);
        }

        return result;
    }

    private int lowerBound(String[] products, String target, int left) {
        int right = products.length;

        while (left < right) {
            int mid = left + (right - left) / 2;

            if (products[mid].compareTo(target) < 0) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        return left;
    }
}

