            const num = heap.peek();
            const cnt = delayed.get(num) || 0;
            if (cnt === 0) break;
            delayed.set(num, cnt - 1);
            if (cnt - 1 === 0) delayed.delete(num);
            heap.pop();
        }
    }

    function balance() {
        prune(lo);
        prune(hi);
        if (loSize > hiSize + 1) {
            hi.push(lo.pop());
            loSize--;
            hiSize++;
            prune(lo);
        } else if (hiSize > loSize) {
            lo.push(hi.pop());
            hiSize--;
            loSize++;
            prune(hi);
        }
    }

    function add(num) {
        prune(lo);
        prune(hi);
        if (loSize === 0 || num <= lo.peek()) {
            lo.push(num);
            loSize++;
        } else {
            hi.push(num);
            hiSize++;
        }
        balance();
    }

    function remove(num) {
        prune(lo);
        prune(hi);
        delayed.set(num, (delayed.get(num) || 0) + 1);
        if (num <= lo.peek()) {
            loSize--;
        } else {
            hiSize--;
        }
        prune(lo);
        prune(hi);
        balance();
    }

    function getMedian() {
        prune(lo);
        prune(hi);
        if (k % 2 === 1) {
            return lo.peek();
        } else {
            return (lo.peek() + hi.peek()) / 2;
        }
    }

    const n = nums.length;
    const medians = [];
    for (let i = 0; i < n; i++) {
        add(nums[i]);
        if (i >= k - 1) {
            medians.push(getMedian());
            remove(nums[i - k + 1]);
        }
    }
    return medians;
};

