            large.push(small.pop());
            smallSize--;
            largeSize++;
            prune(small);
        } else if (smallSize < largeSize) {
            small.push(large.pop());
            smallSize++;
            largeSize--;
            prune(large);
        }
    };

    const add = (num) => {
        if (small.size() === 0 || num <= small.peek()) {
            small.push(num);
            smallSize++;
        } else {
            large.push(num);
            largeSize++;
