        delayed.set(num, (delayed.get(num) || 0) + 1);

        if (num <= small.peek()) {
            smallSize--;

            if (num === small.peek()) {
                prune(small);
            }
        } else {
            largeSize--;

            if (large.size() > 0 && num === large.peek()) {
                prune(large);
            }
        }

        balance();
    };

    const getMedian = () => {
        prune(small);
        prune(large);

        if (k % 2 === 1) {
