    for (let i = k; i < nums.length; i++) {
        add(nums[i]);
        remove(nums[i - k]);
        result.push(getMedian());
    }

    return result;
};

function medianSlidingWindow(nums: number[], k: number): number[] {
    const n = nums.length;
    const unique = [...new Set(nums)].sort((a, b) => a - b);
    const m = unique.length;
    const valToRank = new Map<number, number>();
    for (let i = 0; i < m; i++) {
        valToRank.set(unique[i], i + 1);
    }
    const tree = new Array(m + 1).fill(0);
    const update = (i: number, delta: number) => {
        while (i <= m) {
            tree[i] += delta;
            i += i & -i;
        }
    };
    const query = (i: number): number => {
        let sum = 0;
        while (i > 0) {
            sum += tree[i];
            i -= i & -i;
        }
        return sum;
    };
    const findKth = (kth: number): number => {
        let lo = 1, hi = m;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (query(mid) >= kth) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        return unique[lo - 1];
    };
    const getMedian = (): number => {
        if (k % 2 === 1) {
            return findKth((k + 1) / 2);
        } else {
            const a = findKth(k / 2);
            const b = findKth(k / 2 + 1);
            return (a + b) / 2;
        }
    };
    const result: number[] = [];
    for (let i = 0; i < k; i++) {
        update(valToRank.get(nums[i])!, 1);
    }
    result.push(getMedian());
    for (let i = k; i < n; i++) {
        update(valToRank.get(nums[i - k])!, -1);
        update(valToRank.get(nums[i])!, 1);
        result.push(getMedian());
    }
    return result;
