    function prune(heap: Item[]): void {
        while (heap.length > 0 && deleted.has(heap[0].id)) {
            deleted.delete(heap[0].id);
            pop(heap, heap === low ? maxBefore : minBefore);
        }
    }

    let lowSize = 0;
    let highSize = 0;

    function rebalance(): void {
        prune(low);
        prune(high);

        while (lowSize > highSize + 1) {
            const item = pop(low, maxBefore);
            push(high, item, minBefore);
            side[item.id] = 1;
            lowSize--;
            highSize++;
            prune(low);
