        while (lowSize < highSize) {
            const item = pop(high, minBefore);
            push(low, item, maxBefore);
            side[item.id] = 0;
            highSize--;
            lowSize++;
            prune(high);
        }
    }

    function add(value: number, id: number): void {
        prune(low);

        if (low.length === 0 || value <= low[0].v) {
            push(low, { v: value, id }, maxBefore);
            side[id] = 0;
            lowSize++;
        } else {
            push(high, { v: value, id }, minBefore);
            side[id] = 1;
            highSize++;
        }

        rebalance();
    }

    function remove(id: number): void {
        deleted.add(id);

        if (side[id] === 0) {
            lowSize--;
        } else {
            highSize--;
        }

        prune(low);
        prune(high);
        rebalance();
    }

    for (let i = 0; i < k; i++) {
        add(nums[i], i);
    }

    const result: number[] = [];

    function getMedian(): number {
        prune(low);
        prune(high);

        if (k % 2 === 1) {
            return low[0].v;
        }
        return (low[0].v + high[0].v) / 2;
    }

    result.push(getMedian());

    for (let i = k; i < nums.length; i++) {
        remove(i - k);
        add(nums[i], i);
        result.push(getMedian());
    }

    return result;
};

function medianSlidingWindow(nums: number[], k: number): number[] {
    const n = nums.length;
    const sorted = Array.from(new Set(nums)).sort((a, b) => a - b);
    const m = sorted.length;
    const idx = new Map<number, number>();
    for (let i = 0; i < m; i++) idx.set(sorted[i], i + 1);
    const tree = new Int32Array(m + 1);
    const update = (i: number, d: number) => {
        for (; i <= m; i += i & -i) tree[i] += d;
    };
    let LOG = 1;
    while (LOG * 2 <= m) LOG *= 2;
    const kth = (t: number): number => {
        let pos = 0;
        let rem = t;
        for (let step = LOG; step > 0; step >>= 1) {
            if (pos + step <= m && tree[pos + step] < rem) {
                pos += step;
                rem -= tree[pos];
            }
        }
        return sorted[pos];
    };
    const res: number[] = [];
    for (let i = 0; i < n; i++) {
        update(idx.get(nums[i])!, 1);
        if (i >= k) update(idx.get(nums[i - k])!, -1);
        if (i >= k - 1) {
            if (k % 2 === 1) {
                res.push(kth((k + 1) / 2));
            } else {
                res.push((kth(k / 2) + kth(k / 2 + 1)) / 2);
            }
        }
    }
    return res;
};

function medianSlidingWindow(nums: number[], k: number): number[] {
    class DualHeap {
        small: MaxHeap;
        large: MinHeap;
        delayed: Map<number, number>;
        smallSize: number = 0;
        largeSize: number = 0;

        constructor(private k: number) {
            this.small = new MaxHeap();
            this.large = new MinHeap();
            this.delayed = new Map();
        }

        prune(heap: MaxHeap | MinHeap): void {
            while (heap.size() > 0) {
                const num = heap.peek()!;
                const count = this.delayed.get(num);
                if (count === undefined) break;
                if (count === 1) this.delayed.delete(num);
                else this.delayed.set(num, count - 1);
                heap.pop();
            }
        }

        makeBalance(): void {
            if (this.smallSize > this.largeSize + 1) {
                this.large.push(this.small.pop()!);
                this.smallSize--;
                this.largeSize++;
                this.prune(this.small);
            } else if (this.smallSize < this.largeSize) {
                this.small.push(this.large.pop()!);
                this.smallSize++;
                this.largeSize--;
                this.prune(this.large);
            }
        }

        insert(num: number): void {
            if (this.small.size() === 0 || num <= this.small.peek()!) {
                this.small.push(num);
                this.smallSize++;
            } else {
                this.large.push(num);
                this.largeSize++;
            }
            this.makeBalance();
        }

        erase(num: number): void {
            this.delayed.set(num, (this.delayed.get(num) || 0) + 1);
            if (num <= this.small.peek()!) {
                this.smallSize--;
                if (num === this.small.peek()) this.prune(this.small);
            } else {
                this.largeSize--;
                if (this.large.size() > 0 && num === this.large.peek()) this.prune(this.large);
            }
            this.makeBalance();
        }

        getMedian(): number {
            if (this.k % 2 === 1) return this.small.peek()!;
            return (this.small.peek()! + this.large.peek()!) / 2;
        }
    }

    class MaxHeap {
        private data: number[] = [];
        size(): number { return this.data.length; }
        peek(): number | undefined { return this.data[0]; }
        push(val: number): void {
            this.data.push(val);
            this.bubbleUp(this.data.length - 1);
        }
        pop(): number | undefined {
            if (this.data.length === 0) return undefined;
            const top = this.data[0];
            const last = this.data.pop()!;
            if (this.data.length > 0) {
                this.data[0] = last;
                this.bubbleDown(0);
            }
            return top;
        }
        private bubbleUp(i: number): void {
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (this.data[p] >= this.data[i]) break;
                [this.data[p], this.data[i]] = [this.data[i], this.data[p]];
                i = p;
            }
        }
        private bubbleDown(i: number): void {
            const n = this.data.length;
            while (true) {
                let largest = i;
                const l = i * 2 + 1, r = i * 2 + 2;
                if (l < n && this.data[l] > this.data[largest]) largest = l;
                if (r < n && this.data[r] > this.data[largest]) largest = r;
                if (largest === i) break;
                [this.data[i], this.data[largest]] = [this.data[largest], this.data[i]];
                i = largest;
            }
        }
    }

    class MinHeap {
        private data: number[] = [];
        size(): number { return this.data.length; }
        peek(): number | undefined { return this.data[0]; }
        push(val: number): void {
            this.data.push(val);
            this.bubbleUp(this.data.length - 1);
        }
        pop(): number | undefined {
            if (this.data.length === 0) return undefined;
            const top = this.data[0];
            const last = this.data.pop()!;
            if (this.data.length > 0) {
                this.data[0] = last;
                this.bubbleDown(0);
            }
            return top;
        }
        private bubbleUp(i: number): void {
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (this.data[p] <= this.data[i]) break;
                [this.data[p], this.data[i]] = [this.data[i], this.data[p]];
                i = p;
            }
        }
        private bubbleDown(i: number): void {
            const n = this.data.length;
            while (true) {
                let smallest = i;
                const l = i * 2 + 1, r = i * 2 + 2;
                if (l < n && this.data[l] < this.data[smallest]) smallest = l;
                if (r < n && this.data[r] < this.data[smallest]) smallest = r;
                if (smallest === i) break;
                [this.data[i], this.data[smallest]] = [this.data[smallest], this.data[i]];
                i = smallest;
            }
        }
    }

    const dh = new DualHeap(k);
    const ans: number[] = [];

    for (let i = 0; i < nums.length; i++) {
        dh.insert(nums[i]);
        if (i >= k) dh.erase(nums[i - k]);
        if (i >= k - 1) ans.push(dh.getMedian());
    }

    return ans;
};

function medianSlidingWindow(nums: number[], k: number): number[] {
    const vals = Array.from(new Set(nums)).sort((a, b) => a - b);
    const m = vals.length;
    const index = new Map<number, number>();
    for (let i = 0; i < m; i++) index.set(vals[i], i + 1);

    const comp = nums.map(v => index.get(v)!);
    const bit = new Int32Array(m + 1);

    const add = (i: number, delta: number): void => {
        while (i <= m) {
            bit[i] += delta;
            i += i & -i;
        }
    };

    const kth = (order: number): number => {
        let pos = 0;
        let step = 1;
        while ((step << 1) <= m) step <<= 1;

        for (let d = step; d > 0; d >>= 1) {
            const next = pos + d;
            if (next <= m && bit[next] < order) {
                pos = next;
                order -= bit[next];
            }
        }

        return vals[pos];
    };

    const result: number[] = [];

    for (let i = 0; i < nums.length; i++) {
        add(comp[i], 1);

        if (i >= k) {
            add(comp[i - k], -1);
        }

        if (i >= k - 1) {
            if (k & 1) {
                result.push(kth((k + 1) >> 1));
            } else {
                const a = kth(k >> 1);
                const b = kth((k >> 1) + 1);
                result.push((a + b) / 2);
            }
        }
    }

    return result;
}

function medianSlidingWindow(nums: number[], k: number): number[] {
    // Coordinate compression preserves numeric ordering.
    const values = Array.from(new Set(nums)).sort((a, b) => a - b);
    const ranks = new Map<number, number>();
    for (let i = 0; i < values.length; i++) {
        ranks.set(values[i], i + 1);
    }

    const size = values.length;
    const tree = new Int32Array(size + 1);

    function update(index: number, delta: number): void {
        while (index <= size) {
            tree[index] += delta;
            index += index & -index;
        }
    }

    let highestBit = 1;
    while (highestBit * 2 <= size) {
        highestBit *= 2;
    }

    // Find the value at the given 1-based position in the current window.
    function select(order: number): number {
        let index = 0;
        for (let bit = highestBit; bit > 0; bit = Math.floor(bit / 2)) {
            const next = index + bit;
            if (next <= size && tree[next] < order) {
                index = next;
                order -= tree[next];
            }
        }
        return values[index];
    }

    const result: number[] = [];
    const lowerOrder = Math.floor((k + 1) / 2);
    const upperOrder = Math.floor(k / 2) + 1;

    for (let i = 0; i < nums.length; i++) {
        update(ranks.get(nums[i])!, 1);

        if (i >= k) {
            update(ranks.get(nums[i - k])!, -1);
        }

        if (i >= k - 1) {
            const lower = select(lowerOrder);
            result.push(
                k % 2 === 1 ? lower : (lower + select(upperOrder)) / 2
            );
        }
    }

    return result;
};

function medianSlidingWindow(nums: number[], k: number): number[] {
    const n = nums.length;
    const sorted = [...nums].sort((a, b) => a - b);
    const unique: number[] = [];
    for (let i = 0; i < n; i++) {
        if (i === 0 || sorted[i] !== sorted[i - 1]) unique.push(sorted[i]);
    }
    const m = unique.length;
    const posOf = new Map<number, number>();
    for (let i = 0; i < m; i++) posOf.set(unique[i], i);
    const ranks = new Int32Array(n);
    for (let i = 0; i < n; i++) ranks[i] = posOf.get(nums[i])!;

    const tree = new Int32Array(m + 1);
    const add = (i: number, delta: number): void => {
        for (; i <= m; i += i & (-i)) tree[i] += delta;
    };
    let LOG = 1;
    while ((1 << LOG) <= m) LOG++;
    const kth = (rank: number): number => {
        let pos = 0;
        let rem = rank;
        for (let pw = 1 << LOG; pw > 0; pw >>= 1) {
            const nxt = pos + pw;
            if (nxt <= m && tree[nxt] < rem) {
                pos = nxt;
                rem -= tree[nxt];
            }
        }
        return unique[pos];
    };

    const loRank = ((k - 1) >> 1) + 1;
    const hiRank = (k >> 1) + 1;

    for (let i = 0; i < k; i++) add(ranks[i] + 1, 1);

    const res: number[] = new Array(n - k + 1);
    for (let i = 0; i + k <= n; i++) {
        const a = kth(loRank);
        const b = loRank === hiRank ? a : kth(hiRank);
        res[i] = (a + b) / 2;
        if (i + k < n) {
            add(ranks[i] + 1, -1);
            add(ranks[i + k] + 1, 1);
        }
    }
    return res;
}

function medianSlidingWindow(nums: number[], k: number): number[] {
    const n = nums.length;
    const sorted = Array.from(new Set(nums)).sort((a, b) => a - b);
    const m = sorted.length;
    const idx = new Map<number, number>();
    for (let i = 0; i < m; i++) idx.set(sorted[i], i + 1);
    const tree = new Int32Array(m + 1);
    const add = (i: number, d: number): void => {
        for (; i <= m; i += i & -i) tree[i] += d;
    };
    let LOG = 0;
    while ((1 << (LOG + 1)) <= m) LOG++;
    const kth = (r: number): number => {
        let pos = 0;
        for (let b = LOG; b >= 0; b--) {
            const np = pos + (1 << b);
            if (np <= m && tree[np] < r) {
                pos = np;
                r -= tree[np];
            }
        }
        return sorted[pos];
    };
    const res: number[] = [];
    for (let i = 0; i < k; i++) add(idx.get(nums[i])!, 1);
    const odd = (k & 1) === 1;
    for (let i = k; ; i++) {
        if (odd) {
            res.push(kth((k + 1) >> 1));
        } else {
            const a = kth(k >> 1);
            const b = kth((k >> 1) + 1);
            res.push((a + b) / 2);
        }
        if (i >= n) break;
        add(idx.get(nums[i])!, 1);
        add(idx.get(nums[i - k])!, -1);
    }
    return res;
};

function medianSlidingWindow(nums: number[], k: number): number[] {
    const sorted = nums.slice().sort((a, b) => a - b);
    const values: number[] = [];

    for (const value of sorted) {
        if (values.length === 0 || values[values.length - 1] !== value) {
            values.push(value);
        }
    }

    const indices = new Map<number, number>();
    for (let i = 0; i < values.length; i++) {
        indices.set(values[i], i + 1);
    }

    const tree = new Int32Array(values.length + 1);

    const update = (index: number, delta: number): void => {
        while (index < tree.length) {
            tree[index] += delta;
            index += index & -index;
        }
    };

    const kth = (rank: number): number => {
        let index = 0;
        let step = 1;

        while (step * 2 <= values.length) {
            step *= 2;
        }

        while (step > 0) {
            const next = index + step;
            if (next <= values.length && tree[next] < rank) {
                index = next;
                rank -= tree[next];
            }
            step = Math.floor(step / 2);
        }

        return values[index];
    };

    const result: number[] = [];
    const leftRank = Math.floor((k + 1) / 2);
    const rightRank = Math.floor((k + 2) / 2);

    for (let i = 0; i < nums.length; i++) {
        update(indices.get(nums[i])!, 1);

        if (i >= k) {
            update(indices.get(nums[i - k])!, -1);
        }

        if (i >= k - 1) {
            result.push((kth(leftRank) + kth(rightRank)) / 2);
        }
    }

    return result;
};

function medianSlidingWindow(nums: number[], k: number): number[] {
    class Fenwick {
        size: number;
        tree: number[];

        constructor(size: number) {
            this.size = size;
            this.tree = new Array(size + 1).fill(0);
        }

        add(index: number, delta: number): void {
            for (let i = index + 1; i <= this.size; i += i & -i) {
                this.tree[i] += delta;
            }
        }

        kth(order: number): number {
            let idx = 0;
            let bit = 1;

            while ((bit << 1) <= this.size) bit <<= 1;

            for (let step = bit; step > 0; step >>= 1) {
                const next = idx + step;
                if (next <= this.size && this.tree[next] < order) {
                    idx = next;
                    order -= this.tree[next];
                }
            }

            return idx;
        }
    }

    const sorted = nums.slice().sort((a, b) => a - b);
    const values: number[] = [];

    for (const num of sorted) {
        if (values.length === 0 || values[values.length - 1] !== num) {
            values.push(num);
        }
    }

    const indexMap = new Map<number, number>();
    for (let i = 0; i < values.length; i++) {
        indexMap.set(values[i], i);
    }

    const fenwick = new Fenwick(values.length);
    const result: number[] = [];

    for (let i = 0; i < nums.length; i++) {
        fenwick.add(indexMap.get(nums[i])!, 1);

        if (i >= k) {
            fenwick.add(indexMap.get(nums[i - k])!, -1);
        }

        if (i >= k - 1) {
            if (k % 2 === 1) {
                const midIndex = fenwick.kth(Math.floor(k / 2) + 1);
                result.push(values[midIndex]);
            } else {
                const leftIndex = fenwick.kth(k / 2);
                const rightIndex = fenwick.kth(k / 2 + 1);
                result.push((values[leftIndex] + values[rightIndex]) / 2);
            }
        }
    }

    return result;
};

class Solution {
public:
    vector<double> medianSlidingWindow(vector<int>& nums, int k) {
        multiset<int> w(nums.begin(), nums.begin() + k);
        auto mid = next(w.begin(), k / 2);
        vector<double> res;
        for (int i = k;; i++) {
            double m = ((double)*mid + (double)*prev(mid, 1 - k % 2)) / 2.0;
            res.push_back(m);
            if (i == (int)nums.size()) break;
            w.insert(nums[i]);
            if (nums[i] < *mid) --mid;
            if (nums[i - k] <= *mid) ++mid;
            w.erase(w.lower_bound(nums[i - k]));
        }
        return res;
    }
};

class Solution {
public:
    vector<double> medianSlidingWindow(vector<int>& nums, int k) {
        multiset<int> lower, upper;

        auto rebalance = [&]() {
            while (lower.size() > upper.size() + 1) {
                auto it = prev(lower.end());
                upper.insert(*it);
                lower.erase(it);
            }
            while (lower.size() < upper.size()) {
                auto it = upper.begin();
                lower.insert(*it);
                upper.erase(it);
            }
        };

        auto insertValue = [&](int value) {
            if (lower.empty() || value <= *lower.rbegin()) {
                lower.insert(value);
            } else {
                upper.insert(value);
            }
            rebalance();
        };

        auto eraseValue = [&](int value) {
            auto it = lower.find(value);
            if (it != lower.end()) {
                lower.erase(it);
            } else {
                upper.erase(upper.find(value));
            }
            rebalance();
        };

        auto getMedian = [&]() -> double {
            if (k % 2 == 1) {
                return static_cast<double>(*lower.rbegin());
            }
            long long left = *lower.rbegin();
            long long right = *upper.begin();
            return (left + right) / 2.0;
        };

        for (int i = 0; i < k; ++i) {
            insertValue(nums[i]);
        }

        vector<double> medians;
        medians.reserve(nums.size() - k + 1);
        medians.push_back(getMedian());

        for (int i = k; i < static_cast<int>(nums.size()); ++i) {
            eraseValue(nums[i - k]);
            insertValue(nums[i]);
            medians.push_back(getMedian());
        }

        return medians;
    }
};

