        vector<double> res;
        int n = nums.size();
        multiset<long long> window(nums.begin(), nums.begin() + k);
        auto mid = next(window.begin(), k / 2);
        for (int i = k;; i++) {
            if (k % 2 == 1) {
                res.push_back((double)*mid);
            } else {
                res.push_back(((double)*mid + (double)*prev(mid)) / 2.0);
            }
            if (i >= n) break;
            // insert new element
            window.insert((long long)nums[i]);
            if ((long long)nums[i] < *mid) {
                mid--;
            }
            // remove old element
            long long out = nums[i - k];
            if (out <= *mid) {
                mid++;
            }
            window.erase(window.lower_bound(out));
        }
        return res;
    }
};

