class Solution {
    public double[] medianSlidingWindow(int[] nums, int k) {
        DualHeap dh = new DualHeap(k);
        double[] ans = new double[nums.length - k + 1];

        for (int i = 0; i < k; i++) dh.insert(nums[i]);
        ans[0] = dh.getMedian();

        for (int i = k; i < nums.length; i++) {
            dh.insert(nums[i]);
            dh.erase(nums[i - k]);
            ans[i - k + 1] = dh.getMedian();
        }
        return ans;
    }

    static class DualHeap {
        PriorityQueue<Integer> small; // max heap
        PriorityQueue<Integer> large; // min heap
        Map<Integer, Integer> delayed;
        int smallSize, largeSize, k;

        DualHeap(int k) {
            this.k = k;
            small = new PriorityQueue<>(Collections.reverseOrder());
            large = new PriorityQueue<>();
            delayed = new HashMap<>();
        }

        void insert(int num) {
            if (small.isEmpty() || num <= small.peek()) {
                small.offer(num);
                smallSize++;
            } else {
                large.offer(num);
                largeSize++;
            }
            makeBalance();
        }

        void erase(int num) {
            delayed.put(num, delayed.getOrDefault(num, 0) + 1);
            if (!small.isEmpty() && num <= small.peek()) {
                smallSize--;
                if (num == small.peek()) prune(small);
            } else {
                largeSize--;
                if (!large.isEmpty() && num == large.peek()) prune(large);
            }
            makeBalance();
        }

        double getMedian() {
            if ((k & 1) == 1) return (double) small.peek();
            return ((double) small.peek() + (double) large.peek()) / 2.0;
        }

        void makeBalance() {
            if (smallSize > largeSize + 1) {
                large.offer(small.poll());
                smallSize--;
                largeSize++;
                prune(small);
            } else if (smallSize < largeSize) {
                small.offer(large.poll());
                largeSize--;
                smallSize++;
                prune(large);
            }
            prune(small);
            prune(large);
        }

        void prune(PriorityQueue<Integer> heap) {
            while (!heap.isEmpty()) {
                int num = heap.peek();
                Integer cnt = delayed.get(num);
                if (cnt == null || cnt == 0) break;
                delayed.put(num, cnt - 1);
                if (delayed.get(num) == 0) delayed.remove(num);
                heap.poll();
            }
        }
    }
}

