import java.util.TreeMap;

class Solution {
    private final TreeMap<Integer, Integer> lower = new TreeMap<>();
    private final TreeMap<Integer, Integer> upper = new TreeMap<>();
    private int lowerSize;
    private int upperSize;

    public double[] medianSlidingWindow(int[] nums, int k) {
        lower.clear();
        upper.clear();
        lowerSize = 0;
        upperSize = 0;

        double[] medians = new double[nums.length - k + 1];

        for (int i = 0; i < k; i++) {
            add(nums[i]);
        }

        for (int left = 0; left + k <= nums.length; left++) {
            medians[left] = getMedian(k);

            if (left + k < nums.length) {
                remove(nums[left]);
                add(nums[left + k]);
            }
        }

        return medians;
    }

    private void add(int value) {
        if (lower.isEmpty() || value <= lower.lastKey()) {
            addToMap(lower, value);
            lowerSize++;
        } else {
            addToMap(upper, value);
            upperSize++;
        }
        rebalance();
    }

    private void remove(int value) {
        if (lower.containsKey(value)) {
            removeFromMap(lower, value);
            lowerSize--;
        } else {
            removeFromMap(upper, value);
            upperSize--;
        }
        rebalance();
    }

    private void rebalance() {
        int totalSize = lowerSize + upperSize;
        int targetLowerSize = (totalSize + 1) / 2;

        while (lowerSize > targetLowerSize) {
            int value = lower.lastKey();
            removeFromMap(lower, value);
            lowerSize--;
            addToMap(upper, value);
            upperSize++;
        }

        while (lowerSize < targetLowerSize) {
            int value = upper.firstKey();
            removeFromMap(upper, value);
            upperSize--;
            addToMap(lower, value);
            lowerSize++;
        }
    }

    private double getMedian(int k) {
        if ((k & 1) == 1) {
            return lower.lastKey();
        }
        return ((double) lower.lastKey() + (double) upper.firstKey()) / 2.0;
    }

    private void addToMap(TreeMap<Integer, Integer> map, int value) {
        map.put(value, map.getOrDefault(value, 0) + 1);
    }

    private void removeFromMap(TreeMap<Integer, Integer> map, int value) {
        int count = map.get(value);
        if (count == 1) {
            map.remove(value);
        } else {
            map.put(value, count - 1);
        }
    }
}

import java.util.*;

class Solution {
    public double[] medianSlidingWindow(int[] nums, int k) {
        final int[] a = nums;
        Comparator<Integer> cmp = (x, y) -> a[x] != a[y] ? Integer.compare(a[x], a[y]) : Integer.compare(x, y);
        TreeSet<Integer> lo = new TreeSet<>(cmp);
        TreeSet<Integer> hi = new TreeSet<>(cmp);
        int n = nums.length;
        double[] res = new double[n - k + 1];
        for (int i = 0; i < n; i++) {
            if (i >= k) {
                int r = i - k;
                if (lo.contains(r)) lo.remove(r);
                else hi.remove(r);
                rebalance(lo, hi);
            }
            if (lo.isEmpty() || cmp.compare(i, lo.last()) <= 0) lo.add(i);
            else hi.add(i);
            rebalance(lo, hi);
            if (i >= k - 1) {
                if (k % 2 == 1) res[i - k + 1] = nums[lo.last()];
                else res[i - k + 1] = ((double) nums[lo.last()] + (double) nums[hi.first()]) / 2.0;
            }
        }
        return res;
    }

    private void rebalance(TreeSet<Integer> lo, TreeSet<Integer> hi) {
        int target = (lo.size() + hi.size() + 1) / 2;
        while (lo.size() > target) {
            hi.add(lo.pollLast());
        }
        while (lo.size() < target) {
            lo.add(hi.pollFirst());
        }
    }
}

import java.util.TreeMap;

class Solution {
    public double[] medianSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        double[] ans = new double[n - k + 1];
        TreeMap<Integer, Integer> left = new TreeMap<>();   // smaller half; max = lastKey()
        TreeMap<Integer, Integer> right = new TreeMap<>();  // larger half; min = firstKey()
        int[] size = new int[2]; // size[0] = left size, size[1] = right size

        for (int i = 0; i < k; i++) {
            add(nums[i], left, right, size);
        }
        ans[0] = median(left, right, size);
        for (int i = k; i < n; i++) {
            add(nums[i], left, right, size);
            remove(nums[i - k], left, right, size);
            ans[i - k + 1] = median(left, right, size);
        }
        return ans;
    }

    private static void add(int v, TreeMap<Integer, Integer> left, TreeMap<Integer, Integer> right, int[] size) {
        if (size[0] == 0 || v <= left.lastKey()) {
            insert(left, v);
            size[0]++;
        } else {
            insert(right, v);
            size[1]++;
        }
        rebalance(left, right, size);
    }

    private static void remove(int v, TreeMap<Integer, Integer> left, TreeMap<Integer, Integer> right, int[] size) {
        if (v <= left.lastKey()) {
            erase(left, v);
            size[0]--;
        } else {
            erase(right, v);
            size[1]--;
        }
        rebalance(left, right, size);
    }

    private static void rebalance(TreeMap<Integer, Integer> left, TreeMap<Integer, Integer> right, int[] size) {
        if (size[0] > size[1] + 1) {
            int v = left.lastKey();
            erase(left, v);
            size[0]--;
            insert(right, v);
            size[1]++;
        } else if (size[0] < size[1]) {
            int v = right.firstKey();
            erase(right, v);
            size[1]--;
            insert(left, v);
            size[0]++;
        }
    }

    private static double median(TreeMap<Integer, Integer> left, TreeMap<Integer, Integer> right, int[] size) {
        if (((size[0] + size[1]) & 1) == 1) {
            return left.lastKey();
        }
        return ((double) left.lastKey() + right.firstKey()) / 2.0;
    }

    private static void insert(TreeMap<Integer, Integer> m, int v) {
        m.merge(v, 1, Integer::sum);
    }

    private static void erase(TreeMap<Integer, Integer> m, int v) {
        int c = m.get(v) - 1;
        if (c == 0) {
            m.remove(v);
        } else {
            m.put(v, c);
        }
    }
}

import java.util.TreeMap;

class Solution {
    private final TreeMap<Integer, Integer> low = new TreeMap<>();
    private final TreeMap<Integer, Integer> high = new TreeMap<>();
    private int lowSize;
    private int highSize;

    public double[] medianSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        double[] result = new double[n - k + 1];

        for (int i = 0; i < k; i++) {
            add(nums[i]);
        }

        result[0] = median();

        for (int i = k; i < n; i++) {
            remove(nums[i - k]);
            add(nums[i]);
            result[i - k + 1] = median();
        }

        return result;
    }

    private void add(int value) {
        if (low.isEmpty() || value <= low.lastKey()) {
            increment(low, value);
            lowSize++;
        } else {
            increment(high, value);
            highSize++;
        }
        rebalance();
    }

    private void remove(int value) {
        if (!low.isEmpty() && value <= low.lastKey()) {
            decrement(low, value);
            lowSize--;
        } else {
            decrement(high, value);
            highSize--;
        }
        rebalance();
    }

    private void rebalance() {
        while (lowSize > highSize + 1) {
            int value = low.lastKey();
            decrement(low, value);
            lowSize--;
            increment(high, value);
            highSize++;
        }

        while (lowSize < highSize) {
            int value = high.firstKey();
            decrement(high, value);
            highSize--;
            increment(low, value);
            lowSize++;
        }
    }

    private double median() {
        if ((lowSize + highSize) % 2 == 1) {
            return low.lastKey();
        }
        return ((double) low.lastKey() + (double) high.firstKey()) / 2.0;
    }

    private void increment(TreeMap<Integer, Integer> map, int value) {
        map.put(value, map.getOrDefault(value, 0) + 1);
    }

    private void decrement(TreeMap<Integer, Integer> map, int value) {
        int count = map.get(value);
        if (count == 1) {
            map.remove(value);
        } else {
            map.put(value, count - 1);
        }
    }
}

