class Solution {
    public int[][] spiralMatrixIII(int rows, int cols, int rStart, int cStart) {
        int total = rows * cols;
        int[][] result = new int[total][2];
        int count = 0;
        int r = rStart;
        int c = cStart;

        result[count][0] = r;
        result[count][1] = c;
        count++;

        int[][] directions = {
            {0, 1},
            {1, 0},
            {0, -1},
            {-1, 0}
        };

        int stepLength = 1;
        int direction = 0;

        while (count < total) {
            for (int repeat = 0; repeat < 2 && count < total; repeat++) {
                int dr = directions[direction][0];
                int dc = directions[direction][1];

                for (int step = 0; step < stepLength; step++) {
                    r += dr;
                    c += dc;

                    if (r >= 0 && r < rows && c >= 0 && c < cols) {
                        result[count][0] = r;
                        result[count][1] = c;
                        count++;

                        if (count == total) {
                            break;
                        }
                    }
                }

                direction = (direction + 1) % 4;
                if (repeat == 1) {
                    stepLength++;
                }
            }
        }

        return result;
    }
}

