var minStickers = function(stickers, target) {
    const tLen = target.length;
    const codes = new Array(tLen);
    for (let i = 0; i < tLen; i++) codes[i] = target.charCodeAt(i) - 97;
    const inTarget = new Array(26).fill(false);
    for (const c of codes) inTarget[c] = true;

    // Count only letters that appear in target; dedupe identical stickers
    const countMap = new Map();
    for (const s of stickers) {
        const cnt = new Array(26).fill(0);
        for (let i = 0; i < s.length; i++) {
            const c = s.charCodeAt(i) - 97;
            if (inTarget[c]) cnt[c]++;
        }
        countMap.set(cnt.join(','), cnt);
    }
    const unique = [...countMap.values()];

    // Remove stickers dominated componentwise by another (distinct) sticker
    const useful = unique.filter((a, i) =>
        !unique.some((b, j) => i !== j && b.every((v, k) => v >= a[k]))
    );

    const memo = new Map();

    const dfs = (mask) => {
        if (mask === 0) return 0;
        const cached = memo.get(mask);
        if (cached !== undefined) return cached;

        // first still-needed position
        let first = 0;
        while ((mask & (1 << first)) === 0) first++;
        const need = codes[first];

        let best = Infinity;
        for (const cnt of useful) {
            if (cnt[need] === 0) continue;
            const avail = cnt.slice();
            let next = mask;
            for (let i = first; i < tLen; i++) {
                const bit = 1 << i;
                if ((next & bit) && avail[codes[i]] > 0) {
                    avail[codes[i]]--;
                    next ^= bit;
                }
            }
            const rest = dfs(next);
            if (rest !== -1 && rest + 1 < best) best = rest + 1;
        }

        const ans = best === Infinity ? -1 : best;
        memo.set(mask, ans);
        return ans;
    };

    return dfs((1 << tLen) - 1);
};

/**
 * @param {string[]} stickers
 * @param {string} target
 * @return {number}
 */
var minStickers = function(stickers, target) {
    const m = target.length;
    const targetMask = (1 << m) - 1;

    // Filter stickers to only contain characters present in target
    const targetCharSet = new Set(target);
    const filteredStickers = [];
    for (const sticker of stickers) {
        let s = '';
        for (const ch of sticker) {
            if (targetCharSet.has(ch)) {
                s += ch;
            }
        }
        if (s.length > 0) {
            filteredStickers.push(s);
        }
    }

    // Group stickers by the characters they contain
    const stickersByChar = Array.from({ length: 26 }, () => []);
    for (const s of filteredStickers) {
        const seen = new Set();
        for (const ch of s) {
            const idx = ch.charCodeAt(0) - 97;
            if (!seen.has(idx)) {
                seen.add(idx);
                stickersByChar[idx].push(s);
            }
        }
    }

    const dist = new Int32Array(1 << m).fill(-1);
    const queue = new Int32Array(1 << m);
    let head = 0;
    let tail = 0;

    dist[0] = 0;
    queue[tail++] = 0;

    while (head < tail) {
        const mask = queue[head++];

        if (mask === targetMask) {
            return dist[mask];
        }

        // Find the first unset bit
        let firstUnset = 0;
        while ((mask & (1 << firstUnset)) !== 0) {
            firstUnset++;
        }

        const requiredCharIdx = target.charCodeAt(firstUnset) - 97;
        const availableStickers = stickersByChar[requiredCharIdx];

        for (let i = 0; i < availableStickers.length; i++) {
            const sticker = availableStickers[i];
            let nextMask = mask;

            for (let c = 0; c < sticker.length; c++) {
                const ch = sticker[c];
                for (let j = 0; j < m; j++) {
                    if ((nextMask & (1 << j)) === 0 && target[j] === ch) {
                        nextMask |= (1 << j);
                        break;
                    }
                }
            }

            if (dist[nextMask] === -1) {
                dist[nextMask] = dist[mask] + 1;
                if (nextMask === targetMask) {
                    return dist[nextMask];
                }
                queue[tail++] = nextMask;
            }
        }
    }

    return -1;
};

/**
 * @param {string[]} stickers
 * @param {string} target
 * @return {number}
 */
var minStickers = function(stickers, target) {
    const m = target.length;
    const full = (1 << m) - 1;

    // Quick check: every target letter must be present in at least one sticker
    const hasLetter = new Array(26).fill(false);
    for (const s of stickers) {
        for (let i = 0; i < s.length; i++) {
            hasLetter[s.charCodeAt(i) - 97] = true;
        }
    }
    for (let i = 0; i < m; i++) {
        if (!hasLetter[target.charCodeAt(i) - 97]) return -1;
    }

    // Map target letters to indices
    const letterIndex = new Map();
    for (let i = 0; i < m; i++) {
        if (!letterIndex.has(target[i])) {
            letterIndex.set(target[i], letterIndex.size);
        }
    }
    const d = letterIndex.size;
    const targetIndices = new Array(m);
    for (let i = 0; i < m; i++) {
        targetIndices[i] = letterIndex.get(target[i]);
    }

    // Preprocess stickers: count only letters that appear in target
    const stickerCounts = [];
    for (const s of stickers) {
        const counts = new Array(d).fill(0);
        let useful = false;
        for (let i = 0; i < s.length; i++) {
            const ch = s[i];
            if (letterIndex.has(ch)) {
                counts[letterIndex.get(ch)]++;
                useful = true;
            }
        }
        if (useful) {
            stickerCounts.push(counts);
        }
    }

    // BFS over bitmask of covered target positions
    const dist = new Int32Array(1 << m).fill(-1);
    dist[0] = 0;
    const queue = [0];
    let head = 0;
    const avail = new Array(d);

    while (head < queue.length) {
        const mask = queue[head++];
        const curDist = dist[mask];
        if (mask === full) return curDist;

        for (const counts of stickerCounts) {
            // Copy counts to avail
            for (let j = 0; j < d; j++) {
                avail[j] = counts[j];
            }
            let newMask = mask;
            for (let i = 0; i < m; i++) {
                if ((newMask & (1 << i)) === 0) {
                    const idx = targetIndices[i];
                    if (avail[idx] > 0) {
                        avail[idx]--;
                        newMask |= (1 << i);
                    }
                }
            }
            if (newMask !== mask && dist[newMask] === -1) {
                if (newMask === full) return curDist + 1;
                dist[newMask] = curDist + 1;
                queue.push(newMask);
            }
        }
    }

    return -1;
};

/**
 * @param {string[]} stickers
 * @param {string} target
 * @return {number}
 */
var minStickers = function(stickers, target) {
    const n = target.length;
    const full = (1 << n) - 1;
    const t = [];
    for (let i = 0; i < n; i++) t.push(target.charCodeAt(i) - 97);
    const cnts = stickers.map(s => {
        const c = new Array(26).fill(0);
        for (let i = 0; i < s.length; i++) {
            const k = s.charCodeAt(i) - 97;
            if (k >= 0 && k < 26) c[k]++;
        }
        return c;
    });
    const dp = new Array(full + 1).fill(Infinity);
    dp[0] = 0;
    for (let mask = 0; mask < full; mask++) {
        if (dp[mask] === Infinity) continue;
        let i = 0;
        while (mask & (1 << i)) i++;
        for (const c of cnts) {
            if (t[i] < 0 || t[i] >= 26 || c[t[i]] === 0) continue;
            const cc = c.slice();
            let nm = mask;
            for (let j = i; j < n; j++) {
                if (nm & (1 << j)) continue;
                if (cc[t[j]] > 0) {
                    cc[t[j]]--;
                    nm |= (1 << j);
                }
            }
            if (dp[mask] + 1 < dp[nm]) dp[nm] = dp[mask] + 1;
        }
    }
    return dp[full] === Infinity ? -1 : dp[full];
};

/**
 * @param {string[]} stickers
 * @param {string} target
 * @return {number}
 */
var minStickers = function(stickers, target) {
    const n = target.length;
    const stickerCounts = stickers.map(s => {
        const cnt = new Array(26).fill(0);
        for (const c of s) cnt[c.charCodeAt(0) - 97]++;
        return cnt;
    });

    const memo = new Map();

    const dp = (remaining) => {
        if (remaining === "") return 0;
        if (memo.has(remaining)) return memo.get(remaining);

        const targetCount = new Array(26).fill(0);
        for (const c of remaining) targetCount[c.charCodeAt(0) - 97]++;

        let best = Infinity;
        for (const sc of stickerCounts) {
            // optimization: sticker must help cover first remaining char
            if (sc[remaining.charCodeAt(0) - 97] === 0) continue;

            let next = "";
            for (let i = 0; i < 26; i++) {
                const need = targetCount[i] - sc[i];
                if (need > 0) {
                    next += String.fromCharCode(97 + i).repeat(need);
                }
            }
            const res = dp(next);
            if (res !== -1) best = Math.min(best, res + 1);
        }

        const result = best === Infinity ? -1 : best;
        memo.set(remaining, result);
        return result;
    };

    return dp(target);
};

