class Solution {
public:
    int minStickers(vector<string>& stickers, string target) {
        int m = target.size();
        int full = (1 << m) - 1;
        int n = stickers.size();

        vector<array<int, 26>> cnt(n);
        for (int i = 0; i < n; ++i) {
            cnt[i].fill(0);
            for (char c : stickers[i]) {
                cnt[i][c - 'a']++;
            }
