class Solution {
public:
    int minStickers(vector<string>& stickers, string target) {
        int n = target.size();
        int full = (1 << n) - 1;

        // Letter counts per sticker; discard stickers sharing no letter with target.
        vector<array<int, 26>> sts;
        for (const string& s : stickers) {
            array<int, 26> c{};
            for (char ch : s) c[ch - 'a']++;
            bool useful = false;
            for (int i = 0; i < n; i++) {
                if (c[target[i] - 'a'] > 0) { useful = true; break; }
            }
            if (useful) sts.push_back(c);
        }

        sort(sts.begin(), sts.end());
        sts.erase(unique(sts.begin(), sts.end()), sts.end());

        // Remove stickers dominated by another sticker (componentwise counts).
        vector<array<int, 26>> keep;
        for (int i = 0; i < (int)sts.size(); i++) {
            bool dominated = false;
            for (int j = 0; j < (int)sts.size() && !dominated; j++) {
                if (i == j) continue;
                bool covers = true;
                for (int c = 0; c < 26; c++) {
                    if (sts[j][c] < sts[i][c]) { covers = false; break; }
                }
                if (covers) dominated = true;
            }
            if (!dominated) keep.push_back(sts[i]);
        }

        const int INF = INT_MAX;
        vector<int> dp(full + 1, INF);
        dp[full] = 0;
        for (int mask = full - 1; mask >= 0; mask--) {
            int idx = 0;
            while (mask & (1 << idx)) idx++;          // first uncovered position
            int need = target[idx] - 'a';
            int best = INF;
            for (const auto& sc : keep) {
                if (sc[need] == 0) continue;          // must help cover position idx
                array<int, 26> avail = sc;
                int nm = mask;
                for (int i = 0; i < n; i++) {
                    if (!(nm & (1 << i))) {
                        int ch = target[i] - 'a';
                        if (avail[ch] > 0) {
                            avail[ch]--;
                            nm |= (1 << i);
                        }
                    }
                }
                if (dp[nm] != INF && dp[nm] + 1 < best) best = dp[nm] + 1;
            }
            dp[mask] = best;
        }

        return dp[0] == INF ? -1 : dp[0];
    }
};

