class Solution {
    public int minStickers(String[] stickers, String target) {
        int n = stickers.length;
        int[][] cnt = new int[n][26];
        for (int i = 0; i < n; i++) {
            for (char c : stickers[i].toCharArray()) cnt[i][c - 'a']++;
        }

        int m = target.length();
        int full = (1 << m) - 1;
        int[] memo = new int[1 << m];
        Arrays.fill(memo, -2);
        memo[full] = 0;

        return dfs(0, target, cnt, memo, full);
    }

    private int dfs(int mask, String target, int[][] stickers, int[] memo, int full) {
        if (memo[mask] != -2) return memo[mask];

        int m = target.length();
        int best = Integer.MAX_VALUE;

        for (int[] sticker : stickers) {
            int[] avail = Arrays.copyOf(sticker, 26);
            int nextMask = mask;

            for (int i = 0; i < m; i++) {
                if (((nextMask >> i) & 1) == 1) continue;
                int ch = target.charAt(i) - 'a';
                if (avail[ch] > 0) {
                    avail[ch]--;
                    nextMask |= (1 << i);
                }
            }

            if (nextMask != mask) {
                int sub = dfs(nextMask, target, stickers, memo, full);
                if (sub != -1) best = Math.min(best, 1 + sub);
            }
        }

        memo[mask] = (best == Integer.MAX_VALUE) ? -1 : best;
        return memo[mask];
    }
}

