class Solution {
    public int minStickers(String[] stickers, String target) {
        int n = target.length();
        if (n == 0) return 0;

        // Compact distinct letters of target to indices 0..d-1
        int[] charToIdx = new int[26];
        for (int i = 0; i < 26; i++) charToIdx[i] = -1;
        int[] posLetter = new int[n];
        int d = 0;
        for (int i = 0; i < n; i++) {
            int c = target.charAt(i) - 'a';
            if (charToIdx[c] < 0) charToIdx[c] = d++;
            posLetter[i] = charToIdx[c];
        }
        int[] letterMask = new int[d];
        for (int i = 0; i < n; i++) letterMask[posLetter[i]] |= 1 << i;

        // Per-sticker counts of target letters only
        int[][] raw = new int[stickers.length][];
        int m = 0;
        for (String s : stickers) {
            int[] cnt = new int[d];
            boolean useful = false;
            for (int i = 0; i < s.length(); i++) {
                int k = charToIdx[s.charAt(i) - 'a'];
                if (k >= 0) { cnt[k]++; useful = true; }
            }
            if (useful) raw[m++] = cnt;
        }

        // Impossible if some target letter appears on no sticker
        for (int k = 0; k < d; k++) {
            boolean has = false;
            for (int i = 0; i < m; i++) {
                if (raw[i][k] > 0) { has = true; break; }
            }
            if (!has) return -1;
        }

        // Drop stickers dominated componentwise by another (equal counts dominate,
        // so duplicates collapse to a single survivor)
        boolean[] dropped = new boolean[m];
        for (int i = 0; i < m; i++) {
            if (dropped[i]) continue;
            for (int j = 0; j < m; j++) {
                if (j == i || dropped[j]) continue;
                boolean ge = true;
                for (int k = 0; k < d; k++) {
                    if (raw[j][k] < raw[i][k]) { ge = false; break; }
                }
                if (ge) { dropped[i] = true; break; }
            }
        }
        int numKept = 0;
        for (int i = 0; i < m; i++) if (!dropped[i]) numKept++;
        int[][] st = new int[numKept][];
        int idx = 0;
        for (int i = 0; i < m; i++) if (!dropped[i]) st[idx++] = raw[i];

        // For each target letter, indices of kept stickers supplying it
        int[][] byLetter = new int[d][];
        int[] sz = new int[d];
        for (int i = 0; i < numKept; i++)
            for (int k = 0; k < d; k++) if (st[i][k] > 0) sz[k]++;
        for (int k = 0; k < d; k++) byLetter[k] = new int[sz[k]];
        int[] fp = new int[d];
        for (int i = 0; i < numKept; i++)
            for (int k = 0; k < d; k++) if (st[i][k] > 0) byLetter[k][fp[k]++] = i;

        // BFS over bitmasks of still-unsatisfied target positions
        int total = 1 << n;
        int full = total - 1;
        int[] dist = new int[total];
        for (int i = 0; i < total; i++) dist[i] = -1;
        dist[full] = 0;
        int[] queue = new int[total];
        int head = 0, tail = 0;
        queue[tail++] = full;
        while (head < tail) {
            int cur = queue[head++];
            int nd = dist[cur] + 1;
            int k0 = posLetter[Integer.numberOfTrailingZeros(cur)];
            int[] cand = byLetter[k0];
            for (int q = 0; q < cand.length; q++) {
                int[] sc = st[cand[q]];
                int nm = cur;
                for (int k = 0; k < d; k++) {
                    int cap = sc[k];
                    if (cap == 0) continue;
                    int x = cur & letterMask[k];
                    int t = Integer.bitCount(x);
                    if (t > cap) t = cap;
                    while (t-- > 0) {
                        nm &= ~(x & -x);
                        x &= x - 1;
                    }
                }
                if (nm != cur && dist[nm] == -1) {
                    dist[nm] = nd;
                    if (nm == 0) return nd;
                    queue[tail++] = nm;
                }
            }
        }
        return -1;
    }
}

import java.util.*;

class Solution {
    private int[][] stickerCounts;
    private Map<String, Integer> memo;

    public int minStickers(String[] stickers, String target) {
        int n = stickers.length;
        stickerCounts = new int[n][26];
        boolean[] available = new boolean[26];

        for (int i = 0; i < n; i++) {
            for (char c : stickers[i].toCharArray()) {
                stickerCounts[i][c - 'a']++;
                available[c - 'a'] = true;
            }
        }

        for (char c : target.toCharArray()) {
            if (!available[c - 'a']) {
                return -1;
            }
        }

        char[] chars = target.toCharArray();
        Arrays.sort(chars);
        target = new String(chars);

        memo = new HashMap<>();
        memo.put("", 0);

        return dfs(target);
    }

    private int dfs(String target) {
        if (memo.containsKey(target)) {
            return memo.get(target);
        }

        int[] need = new int[26];
        for (char c : target.toCharArray()) {
            need[c - 'a']++;
        }

        int firstChar = target.charAt(0) - 'a';
        int result = Integer.MAX_VALUE;

        for (int[] sticker : stickerCounts) {
            if (sticker[firstChar] == 0) {
                continue;
            }

            StringBuilder nextTarget = new StringBuilder();

            for (int i = 0; i < 26; i++) {
                int remaining = need[i] - sticker[i];
                for (int j = 0; j < remaining; j++) {
                    nextTarget.append((char) ('a' + i));
                }
            }

            int subResult = dfs(nextTarget.toString());

            if (subResult != -1) {
                result = Math.min(result, 1 + subResult);
            }
        }

        int answer = result == Integer.MAX_VALUE ? -1 : result;
        memo.put(target, answer);
        return answer;
    }
}

class Solution {
    public int minStickers(String[] stickers, String target) {
        int m = target.length();
        int total = 1 << m;
        int INF = 1000;

        int[] dp = new int[total];
        for (int i = 0; i < total; i++) {
            dp[i] = INF;
        }
        dp[0] = 0;

        int n = stickers.length;
        int[][] counts = new int[n][26];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < stickers[i].length(); j++) {
                counts[i][stickers[i].charAt(j) - 'a']++;
            }
        }

        int[] cnt = new int[26];

        for (int mask = 0; mask < total; mask++) {
            if (dp[mask] == INF) continue;

            int first = 0;
            while (first < m && (mask & (1 << first)) != 0) {
                first++;
            }
            if (first == m) continue;

            int need = target.charAt(first) - 'a';

            for (int s = 0; s < n; s++) {
                if (counts[s][need] == 0) continue;

                System.arraycopy(counts[s], 0, cnt, 0, 26);
                int newMask = mask;

                for (int j = 0; j < m; j++) {
                    if ((newMask & (1 << j)) == 0) {
                        int c = target.charAt(j) - 'a';
                        if (cnt[c] > 0) {
                            cnt[c]--;
                            newMask |= (1 << j);
                        }
                    }
                }

                if (dp[newMask] > dp[mask] + 1) {
                    dp[newMask] = dp[mask] + 1;
                }
            }
        }

        return dp[total - 1] == INF ? -1 : dp[total - 1];
    }
}

