class StreamChecker {
    struct Node {
        int ch[26]{};
        int fail = 0;
        bool isWord = false;
        bool hasWord = false;
    };
    vector<Node> trie;
    int cur = 0;

public:
    StreamChecker(vector<string>& words) {
        size_t need = 1;
        for (const string& w : words) need += w.size();
        trie.reserve(need);
        trie.emplace_back();  // root = index 0

        for (const string& w : words) {
            int c = 0;
            for (char letter : w) {
                int x = letter - 'a';
                if (!trie[c].ch[x]) {
                    trie[c].ch[x] = (int)trie.size();
                    trie.emplace_back();
                }
                c = trie[c].ch[x];
            }
            trie[c].isWord = true;
        }

        // BFS: build failure links, materialize goto automaton, propagate hasWord.
        queue<int> q;
        for (int x = 0; x < 26; ++x)
            if (trie[0].ch[x]) q.push(trie[0].ch[x]);  // fail = 0 by default

        while (!q.empty()) {
            int u = q.front(); q.pop();
            trie[u].hasWord = trie[u].isWord || trie[trie[u].fail].hasWord;
            for (int x = 0; x < 26; ++x) {
                int v = trie[u].ch[x];
                if (v) {
                    trie[v].fail = trie[trie[u].fail].ch[x];
                    q.push(v);
                } else {
                    trie[u].ch[x] = trie[trie[u].fail].ch[x];
                }
            }
        }
    }

    bool query(char letter) {
        cur = trie[cur].ch[letter - 'a'];
        return trie[cur].hasWord;
    }
};

