/**
 * @param {number} n
 * @param {number} firstPlayer
 * @param {number} secondPlayer
 * @return {number[]}
 */
var earliestAndLatest = function(n, firstPlayer, secondPlayer) {
    const memo = new Map();
    const dp = (n, f, s) => {
        if (f + s === n + 1) return [1, 1];
        if (f + s > n + 1) {
            const nf = n + 1 - s;
            const ns = n + 1 - f;
            f = nf; s = ns;
        }
        const key = n * 10000 + f * 100 + s;
        if (memo.has(key)) return memo.get(key);
        let earliest = Infinity, latest = -Infinity;
        const half = Math.floor((n + 1) / 2);
        if (s <= half) {
            for (let i = 0; i < f; i++) {
                for (let j = 0; j < s - f; j++) {
                    const [x, y] = dp(half, i + 1, i + j + 2);
                    if (x < earliest) earliest = x;
                    if (y > latest) latest = y;
                }
            }
        } else {
            const sp = n + 1 - s;
            const mid = Math.floor((n - 2 * sp + 1) / 2);
            for (let i = 0; i < f; i++) {
                for (let j = 0; j < sp - f; j++) {
                    const [x, y] = dp(half, i + 1, i + j + mid + 2);
                    if (x < earliest) earliest = x;
                    if (y > latest) latest = y;
                }
            }
        }
        const res = [earliest + 1, latest + 1];
        memo.set(key, res);
        return res;
    };
    return dp(n, firstPlayer, secondPlayer);
};

var earliestAndLatest = function(n, firstPlayer, secondPlayer) {
    const memo = new Map();
    function f(n, a, b) {
        if (a + b === n + 1) return [1, 1];
        const key = n * 10000 + a * 100 + b;
        if (memo.has(key)) return memo.get(key);
        const half = Math.floor(n / 2);
        let mn = Infinity, mx = -Infinity;
        const total = 1 << half;
        for (let mask = 0; mask < total; mask++) {
            let cnt = 0, na = 0, nb = 0;
            for (let p = 1; p <= n; p++) {
                let surv;
                if (n % 2 === 1 && p === half + 1) {
                    surv = true;
                } else {
                    const i = p <= half ? p : n + 1 - p;
                    const left = p <= half;
                    // pair i: positions i and n+1-i
                    const li = i, ri = n + 1 - i;
                    let winnerLeft;
                    if (li === a || li === b) winnerLeft = true;
                    else if (ri === a || ri === b) winnerLeft = false;
                    else winnerLeft = ((mask >> (i - 1)) & 1) === 1;
                    surv = left ? winnerLeft : !winnerLeft;
                }
                if (surv) {
                    cnt++;
                    if (p === a) na = cnt;
                    if (p === b) nb = cnt;
                }
            }
            const r = f(cnt, na, nb);
            if (r[0] + 1 < mn) mn = r[0] + 1;
            if (r[1] + 1 > mx) mx = r[1] + 1;
        }
        const res = [mn, mx];
        memo.set(key, res);
        return res;
    }
    return f(n, firstPlayer, secondPlayer);
};

/**
 * @param {number} n
 * @param {number} firstPlayer
 * @param {number} secondPlayer
 * @return {number[]}
 */
var earliestAndLatest = function(n, firstPlayer, secondPlayer) {
    const memo = new Map();

    const dfs = (size, a, b) => {
        if (a + b === size + 1) return [1, 1];

        const key = size + "," + a + "," + b;
        if (memo.has(key)) return memo.get(key);

        const nextSize = Math.ceil(size / 2);
        let states = new Set();
        states.add("0,0");

        const contrib = (pos) => {
            if (pos < a) return [1, 0];
            if (pos > a && pos < b) return [0, 1];
            return [0, 0];
        };

        const applyOptions = (options) => {
            const nextStates = new Set();

            for (const state of states) {
                const [x, y] = state.split(",").map(Number);

                for (const [dx, dy] of options) {
                    nextStates.add((x + dx) + "," + (y + dy));
                }
            }

            states = nextStates;
        };

        for (let i = 1; i <= Math.floor(size / 2); i++) {
            const j = size + 1 - i;

            if (i === a || j === a || i === b || j === b) {
                applyOptions([[0, 0]]);
            } else {
                applyOptions([contrib(i), contrib(j)]);
            }
        }

        if (size % 2 === 1) {
            const mid = Math.floor(size / 2) + 1;
            applyOptions([contrib(mid)]);
        }

        let earliest = Infinity;
        let latest = -Infinity;

        for (const state of states) {
            const [x, y] = state.split(",").map(Number);
            const nextA = x + 1;
            const nextB = x + y + 2;

            const [e, l] = dfs(nextSize, nextA, nextB);
            earliest = Math.min(earliest, e + 1);
            latest = Math.max(latest, l + 1);
        }

        const result = [earliest, latest];
        memo.set(key, result);
        return result;
    };

    return dfs(n, firstPlayer, secondPlayer);
};

