var earliestAndLatest = function(n, firstPlayer, secondPlayer) {
    const memo = new Map();

    function dfs(n, i, j) {
        if (i > j) { const t = i; i = j; j = t; }
        if (i + j === n + 1) return [1, 1];
        if (i + j > n + 1) {
            const ni = n + 1 - j;
            j = n + 1 - i;
            i = ni;
        }
        const key = (n << 10) | (i << 5) | j;
        const cached = memo.get(key);
        if (cached !== undefined) return cached;

        const half = n >> 1;
        const nextN = half + (n & 1);

        let cMin, cMax;
        if (j <= half) {
            cMin = 0;
            cMax = j - i - 1;
        } else {
            const internal = Math.max(0, half - (n + 1 - j));
            const freeY = n - i - j;
            const mid = (n % 2 === 1 && half + 1 < j) ? 1 : 0;
            cMin = internal + mid;
            cMax = internal + freeY + mid;
        }

        let earliest = Infinity;
        let latest = -Infinity;
        for (let l = 0; l < i; l++) {
            for (let c = cMin; c <= cMax; c++) {
                const sub = dfs(nextN, 1 + l, 2 + l + c);
                if (sub[0] < earliest) earliest = sub[0];
                if (sub[1] > latest) latest = sub[1];
            }
        }
        const ans = [earliest + 1, latest + 1];
        memo.set(key, ans);
        return ans;
    }

    return dfs(n, firstPlayer, secondPlayer);
};

