    const memo = new Map<string, number[]>();
    const BASE = 32;

    const solve = (curN: number, fPos: number, sPos: number): number[] => {
        if (fPos + sPos === curN + 1) {
            return [1, 1];
        }

        if (fPos + sPos > curN + 1) {
            const newF = curN + 1 - sPos;
            const newS = curN + 1 - fPos;
            fPos = newF;
            sPos = newS;
        }

        const key = `${curN},${fPos},${sPos}`;
        const cached = memo.get(key);
        if (cached !== undefined) {
            return cached;
        }

        const nextN = Math.ceil(curN / 2);
        const half = Math.floor(curN / 2);

        const contribution = (pos: number): number => {
            if (pos < fPos) return BASE;
            if (pos > fPos && pos < sPos) return 1;
            return 0;
        };

        let states = new Set<number>();
        states.add(0);

        for (let left = 1; left <= half; left++) {
            const right = curN + 1 - left;
            const options = new Set<number>();

            if (left === fPos || right === fPos || left === sPos || right === sPos) {
                options.add(0);
            } else {
                options.add(contribution(left));
                options.add(contribution(right));
            }

            const nextStates = new Set<number>();

            for (const state of states) {
                const x = Math.floor(state / BASE);
                const y = state % BASE;

                for (const opt of options) {
                    const addX = Math.floor(opt / BASE);
                    const addY = opt % BASE;
                    nextStates.add((x + addX) * BASE + y + addY);
                }
            }

            states = nextStates;
        }

        if (curN % 2 === 1) {
            const mid = Math.floor(curN / 2) + 1;

            if (mid !== fPos && mid !== sPos) {
                const add = contribution(mid);
                const addX = Math.floor(add / BASE);
                const addY = add % BASE;

                const nextStates = new Set<number>();

                for (const state of states) {
                    const x = Math.floor(state / BASE);
                    const y = state % BASE;
                    nextStates.add((x + addX) * BASE + y + addY);
                }

                states = nextStates;
            }
        }

        let earliest = Number.POSITIVE_INFINITY;
        let latest = 0;

        for (const state of states) {
            const beforeFirst = Math.floor(state / BASE);
            const betweenPlayers = state % BASE;

            const nextF = beforeFirst + 1;
            const nextS = beforeFirst + betweenPlayers + 2;

            const [subEarliest, subLatest] = solve(nextN, nextF, nextS);

            earliest = Math.min(earliest, subEarliest + 1);
            latest = Math.max(latest, subLatest + 1);
        }

        const result = [earliest, latest];
        memo.set(key, result);
        return result;
    };

    return solve(n, firstPlayer, secondPlayer);
};

function earliestAndLatest(n: number, firstPlayer: number, secondPlayer: number): number[] {
    const memo = new Map<string, number[]>();
    const BASE = 32;

    function dfs(m: number, a: number, b: number): number[] {
        if (a + b === m + 1) {
            return [1, 1];
        }

        const key = `${m},${a},${b}`;
        const cached = memo.get(key);
        if (cached !== undefined) {
            return cached;
        }

        let states = new Set<number>([0]);

        const category = (position: number): number => {
            if (position < a) return BASE;
            if (position > a && position < b) return 1;
            return 0;
        };

        const processMatch = (left: number, right?: number): void => {
            let deltas: number[];

            if (right === undefined) {
                deltas = [category(left)];
            } else if (left === a || right === a || left === b || right === b) {
                deltas = [0];
            } else {
                deltas = [category(left), category(right)];
            }

            const nextStates = new Set<number>();
            for (const state of states) {
                for (const delta of deltas) {
                    nextStates.add(state + delta);
                }
            }
            states = nextStates;
        };

        for (let left = 1; left <= Math.floor(m / 2); left++) {
            processMatch(left, m + 1 - left);
        }

        if (m % 2 === 1) {
            processMatch(Math.floor(m / 2) + 1);
        }

        const nextSize = Math.ceil(m / 2);
        let earliest = Infinity;
        let latest = -Infinity;

        for (const state of states) {
            const beforeA = Math.floor(state / BASE);
            const between = state % BASE;
            const nextA = beforeA + 1;
            const nextB = beforeA + between + 2;

            const [childEarliest, childLatest] = dfs(nextSize, nextA, nextB);
            earliest = Math.min(earliest, childEarliest + 1);
            latest = Math.max(latest, childLatest + 1);
        }

        const result = [earliest, latest];
        memo.set(key, result);
        return result;
    }

    return dfs(n, firstPlayer, secondPlayer);
};

function earliestAndLatest(n: number, firstPlayer: number, secondPlayer: number): number[] {
    const memo = new Map<number, number[]>();

    function encode(nn: number, a: number, b: number): number {
        return (nn << 10) | (a << 5) | b;
    }

    function getG(pos: number, a: number, b: number): number {
        if (pos === a || pos === b) return -1;
        if (pos < a) return 0;
        if (pos < b) return 1;
        return 2;
    }

    function getPossibles(nn: number, a: number, b: number): number[][] {
        const set = new Set<number>();
        let fl = 0, fm = 0, fr = 0;
        const frees: number[][] = [];
        const half = Math.floor(nn / 2);
        for (let i = 1; i <= half; i++) {
            const j = nn + 1 - i;
            const gi = getG(i, a, b);
            const gj = getG(j, a, b);
            if (gi === -1 || gj === -1) continue;
            frees.push([gi, gj]);
        }
        if (nn % 2 === 1) {
            const midp = (nn + 1) / 2;
            const g = getG(midp, a, b);
            if (g === 0) fl++;
            else if (g === 1) fm++;
            else if (g === 2) fr++;
        }
        function dfs(idx: number, cl: number, cm: number, cr: number) {
            if (idx === frees.length) {
                const na = cl + 1;
                const nb = cl + cm + 2;
                set.add(na * 32 + nb);
                return;
            }
            const [g1, g2] = frees[idx];
            dfs(idx + 1, cl + (g1 === 0 ? 1 : 0), cm + (g1 === 1 ? 1 : 0), cr + (g1 === 2 ? 1 : 0));
            dfs(idx + 1, cl + (g2 === 0 ? 1 : 0), cm + (g2 === 1 ? 1 : 0), cr + (g2 === 2 ? 1 : 0));
        }
        dfs(0, fl, fm, fr);
        const res: number[][] = [];
        for (const code of set) {
            res.push([Math.floor(code / 32), code % 32]);
        }
        return res;
    }

    function dp(nn: number, a: number, b: number): number[] {
        if (a > b) {
            const tmp = a;
            a = b;
            b = tmp;
        }
        const key = encode(nn, a, b);
        if (memo.has(key)) return memo.get(key)!;
        if (a + b === nn + 1) {
            const r = [1, 1];
            memo.set(key, r);
            return r;
        }
        const possibles = getPossibles(nn, a, b);
        let minR = Infinity;
        let maxR = -Infinity;
        const nextN = (nn + 1) >> 1;
        for (const [na, nb] of possibles) {
            const [e, l] = dp(nextN, na, nb);
            minR = Math.min(minR, e);
            maxR = Math.max(maxR, l);
        }
        const res = [minR + 1, maxR + 1];
        memo.set(key, res);
        return res;
    }

    return dp(n, firstPlayer, secondPlayer);
}

function earliestAndLatest(n: number, firstPlayer: number, secondPlayer: number): number[] {
    const memo = new Map<string, number[]>();

    function solve(size: number, first: number, second: number): number[] {
        if (first + second === size + 1) {
            return [1, 1];
        }

        // Reflect the row to merge symmetric states.
        if (first + second > size + 1) {
            [first, second] = [size + 1 - second, size + 1 - first];
        }

        const key = `${size},${first},${second}`;
        const cached = memo.get(key);
        if (cached !== undefined) {
            return cached;
        }

        const nextSize = Math.ceil(size / 2);
        const stride = nextSize + 1;

        // Encode counts of advancing players before first and before second.
        let states = new Set<number>([0]);

        for (let left = 1, right = size; left <= right; left++, right--) {
            let winners: number[];

            if (left === first || right === first) {
                winners = [first];
            } else if (left === second || right === second) {
                winners = [second];
            } else if (left === right) {
                winners = [left];
            } else {
                winners = [left, right];
            }

            const nextStates = new Set<number>();
            for (const winner of winners) {
                const increment =
                    (winner < first ? stride : 0) +
                    (winner < second ? 1 : 0);

                for (const state of states) {
                    nextStates.add(state + increment);
                }
            }
            states = nextStates;
        }

        let earliest = Infinity;
        let latest = 0;

        for (const state of states) {
            const nextFirst = Math.floor(state / stride) + 1;
            const nextSecond = (state % stride) + 1;
            const result = solve(nextSize, nextFirst, nextSecond);

            earliest = Math.min(earliest, result[0] + 1);
            latest = Math.max(latest, result[1] + 1);
        }

        const result = [earliest, latest];
        memo.set(key, result);
        return result;
    }

    return solve(n, firstPlayer, secondPlayer);
};

