    const memo = new Map<number, number[]>();

    function dp(m: number, l: number, r: number): number[] {
        if (l + r === m + 1) return [1, 1];
        if (l + r > m + 1) {
            const nl = m + 1 - r;
            const nr = m + 1 - l;
            l = nl; r = nr;
        }
        const key = m * 10000 + l * 100 + r;
        if (memo.has(key)) return memo.get(key)!;
        let mn = Infinity, mx = -Infinity;
        const nm = Math.floor((m + 1) / 2);
        let jLo: number, jHi: number;
        if (2 * r <= m + 1) {
            jLo = 0;
            jHi = r - l - 1;
        } else {
            const fixed = Math.floor((2 * r - m - 1) / 2);
            const free = m - r - l;
            jLo = fixed;
            jHi = fixed + free;
        }
        for (let i = 0; i < l; i++) {
            for (let j = jLo; j <= jHi; j++) {
                const res = dp(nm, i + 1, i + j + 2);
                if (res[0] + 1 < mn) mn = res[0] + 1;
                if (res[1] + 1 > mx) mx = res[1] + 1;
            }
        }
        const ans = [mn, mx];
        memo.set(key, ans);
        return ans;
    }

    return dp(n, firstPlayer, secondPlayer);
};

