    const solve = (m: number, i: number, j: number): [number, number] => {
        if (i + j === m + 1) return [1, 1];
        const key = (m * 32 + i) * 32 + j;
        const cached = memo.get(key);
        if (cached !== undefined) return cached;

        const pairs = m >> 1;
        const hasMid = (m & 1) === 1;
        const mid = (m + 1) >> 1;
        const mNext = pairs + (hasMid ? 1 : 0);

        let fixedBefore = 0, fixedBetween = 0, p = 0, q = 0, r = 0;

        for (let k = 1; k <= pairs; k++) {
            const lo = k;
            const hi = m + 1 - k;
            if (lo === i || hi === i) continue; // firstPlayer's pair: she survives
            if (lo === j || hi === j) continue; // secondPlayer's pair: he survives
            const lc = lo < i ? 0 : lo < j ? 1 : 2; // 0 = before F, 1 = between, 2 = after S
            const hc = hi < i ? 0 : hi < j ? 1 : 2;
            if (lc === 0 && hc === 0) fixedBefore++;
            else if (lc === 1 && hc === 1) fixedBetween++;
            else if (lc === 0 && hc === 1) p++;      // choose before or between
            else if (lc === 0 && hc === 2) q++;      // choose before or after
            else if (lc === 1 && hc === 2) r++;      // choose between or after
        }

        if (hasMid && mid !== i && mid !== j) {
            if (mid < i) fixedBefore++;
            else if (mid < j) fixedBetween++;
        }

        let minR = Infinity;
        let maxR = 0;
        for (let a = 0; a <= p; a++) {
            for (let b = 0; b <= q; b++) {
                for (let c = 0; c <= r; c++) {
                    const before = fixedBefore + a + b;
                    const between = fixedBetween + (p - a) + c;
