            if ((a === firstPlayer && b === secondPlayer) ||
                (a === secondPlayer && b === firstPlayer)) {
                const res = [round, round];
                memo.set(key, res);
                return res;
            }
        }

        let earliest = Infinity;
        let latest = -Infinity;

        const pairs: [number, number][] = [];
        for (let i = 0; i < Math.floor(m / 2); i++) {
            pairs.push([cur[i], cur[m - 1 - i]]);
        }
        const mid = m % 2 === 1 ? cur[Math.floor(m / 2)] : -1;

        function choose(idx: number, winners: number[]) {
            if (idx === pairs.length) {
                const next = winners.slice();
                if (mid !== -1) next.push(mid);
                next.sort((a, b) => a - b);

                const [e, l] = dfs(next, round + 1);
                if (e < earliest) earliest = e;
                if (l > latest) latest = l;
                return;
            }

            const [a, b] = pairs[idx];

            if (a === firstPlayer || b === firstPlayer) {
                winners.push(firstPlayer);
                choose(idx + 1, winners);
                winners.pop();
            } else if (a === secondPlayer || b === secondPlayer) {
                winners.push(secondPlayer);
                choose(idx + 1, winners);
                winners.pop();
            } else {
                winners.push(a);
                choose(idx + 1, winners);
                winners.pop();

                winners.push(b);
                choose(idx + 1, winners);
                winners.pop();
            }
        }

        choose(0, []);

        const res = [earliest, latest];
        memo.set(key, res);
        return res;
    }

    return dfs(players, 1);
}

function earliestAndLatest(n: number, firstPlayer: number, secondPlayer: number): number[] {
    const memo = new Map<number, [number, number]>();
    const dp = (m: number, f: number, s: number): [number, number] => {
        if (f + s === m + 1) return [1, 1];
        const key = m * 10000 + f * 100 + s;
        const cached = memo.get(key);
        if (cached) return cached;
        let best = Infinity, worst = -Infinity;
        const half = Math.floor(m / 2);
        const nm = Math.ceil(m / 2);
        const rec = (i: number, cf: number, cs: number) => {
            if (i > half) {
                if (m % 2 === 1) {
                    const mid = (m + 1) / 2;
                    if (mid < f) cf++;
                    if (mid < s) cs++;
                }
                const r = dp(nm, cf + 1, cs + 1);
                if (r[0] + 1 < best) best = r[0] + 1;
                if (r[1] + 1 > worst) worst = r[1] + 1;
                return;
            }
            const j = m + 1 - i;
            const forced = (i === f || i === s) ? i : (j === f || j === s) ? j : -1;
            if (forced !== -1) {
                rec(i + 1, cf + (forced < f ? 1 : 0), cs + (forced < s ? 1 : 0));
            } else {
                rec(i + 1, cf + (i < f ? 1 : 0), cs + (i < s ? 1 : 0));
                rec(i + 1, cf + (j < f ? 1 : 0), cs + (j < s ? 1 : 0));
            }
        };
        rec(1, 0, 0);
        const res: [number, number] = [best, worst];
        memo.set(key, res);
        return res;
    };
    return dp(n, firstPlayer, secondPlayer);
};

class Solution {
public:
    vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        map<int, pair<int, int>> memo;
        auto dfs = [&](auto&& self, int nn, int aa, int bb) -> pair<int, int> {
            if (aa > bb) swap(aa, bb);
            int key = nn * 1024 + aa * 32 + bb;
            if (memo.count(key)) return memo[key];
            if (aa + bb == nn + 1) return memo[key] = {1, 1};
            vector<pair<int, int>> free_pairs;
            for (int i = 1; i <= nn / 2; ++i) {
                int l = i, r = nn + 1 - i;
                if (l != aa && l != bb && r != aa && r != bb) {
                    free_pairs.emplace_back(l, r);
                }
            }
            int mid = (nn % 2 == 1) ? (nn + 1) / 2 : -1;
            int f = free_pairs.size();
            set<pair<int, int>> poss;
            for (int mask = 0; mask < (1 << f); ++mask) {
                vector<int> adv{aa, bb};
                if (mid != -1 && mid != aa && mid != bb) adv.push_back(mid);
                for (int k = 0; k < f; ++k) {
                    int l = free_pairs[k].first, r = free_pairs[k].second;
                    if (mask & (1 << k)) adv.push_back(l);
                    else adv.push_back(r);
                }
                sort(adv.begin(), adv.end());
                int na = 0, nb = 0;
                for (int i = 0; i < (int)adv.size(); ++i) {
                    if (adv[i] == aa) na = i + 1;
                    if (adv[i] == bb) nb = i + 1;
                }
                poss.insert({na, nb});
            }
            int emin = 100, emax = 0;
            int nxt = (nn + 1) / 2;
            for (auto& pr : poss) {
                auto [mn, mx] = self(self, nxt, pr.first, pr.second);
                emin = min(emin, mn + 1);
                emax = max(emax, mx + 1);
            }
            return memo[key] = {emin, emax};
        };
        auto ans = dfs(dfs, n, firstPlayer, secondPlayer);
        return {ans.first, ans.second};
    }
};

class Solution {
public:
    int memoE[30][30][30], memoL[30][30][30];
    bool vis[30][30][30];

    pair<int,int> dfs(int m, int a, int b) {
        if (a + b == m - 1) return {1, 1};
        if (vis[m][a][b]) return {memoE[m][a][b], memoL[m][a][b]};
        vis[m][a][b] = true;
        int half = m / 2;
        int best = INT_MAX, worst = 0;
        int nm = (m + 1) / 2;
        for (int mask = 0; mask < (1 << half); mask++) {
            bool alive[30] = {false};
            if (m % 2 == 1) alive[m / 2] = true;
            for (int i = 0; i < half; i++) {
                int j = m - 1 - i;
                if (i == a || i == b) alive[i] = true;
                else if (j == a || j == b) alive[j] = true;
                else if (mask >> i & 1) alive[i] = true;
                else alive[j] = true;
            }
            int na = 0, nb = 0;
            for (int k = 0; k < a; k++) if (alive[k]) na++;
            for (int k = 0; k < b; k++) if (alive[k]) nb++;
            auto r = dfs(nm, na, nb);
            best = min(best, r.first + 1);
            worst = max(worst, r.second + 1);
        }
        memoE[m][a][b] = best;
        memoL[m][a][b] = worst;
        return {best, worst};
    }

    vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memset(vis, 0, sizeof(vis));
        auto r = dfs(n, firstPlayer - 1, secondPlayer - 1);
        return {r.first, r.second};
    }
};

class Solution {
    int earliest[29][29][29];
    int latest[29][29][29];

    pair<int, int> solve(int n, int firstPlayer, int secondPlayer) {
        int reflectedFirst = n + 1 - secondPlayer;
        int reflectedSecond = n + 1 - firstPlayer;

        if (reflectedFirst < firstPlayer) {
            firstPlayer = reflectedFirst;
            secondPlayer = reflectedSecond;
        }

        if (firstPlayer + secondPlayer == n + 1) {
            return {1, 1};
        }

        if (earliest[n][firstPlayer][secondPlayer] != 0) {
            return {
                earliest[n][firstPlayer][secondPlayer],
                latest[n][firstPlayer][secondPlayer]
            };
        }

        vector<vector<int>> options;

        for (int left = 1; left <= n / 2; ++left) {
            int right = n + 1 - left;

            if (left == firstPlayer || right == firstPlayer) {
                options.push_back({firstPlayer});
            } else if (left == secondPlayer || right == secondPlayer) {
                options.push_back({secondPlayer});
            } else {
                options.push_back({left, right});
            }
        }

        if (n % 2 == 1) {
            options.push_back({n / 2 + 1});
        }

        unordered_set<int> nextStates;

        function<void(int, int, int)> generate = [&](int index, int beforeFirst, int beforeSecond) {
            if (index == static_cast<int>(options.size())) {
                int nextFirst = beforeFirst + 1;
                int nextSecond = beforeSecond + 1;
                nextStates.insert(nextFirst * 32 + nextSecond);
                return;
            }

            for (int winner : options[index]) {
                generate(
                    index + 1,
                    beforeFirst + (winner < firstPlayer),
                    beforeSecond + (winner < secondPlayer)
                );
            }
        };

        generate(0, 0, 0);

        int nextN = (n + 1) / 2;
        int minRound = INT_MAX;
        int maxRound = 0;

        for (int state : nextStates) {
            int nextFirst = state / 32;
            int nextSecond = state % 32;

            auto result = solve(nextN, nextFirst, nextSecond);
            minRound = min(minRound, result.first + 1);
            maxRound = max(maxRound, result.second + 1);
        }

        earliest[n][firstPlayer][secondPlayer] = minRound;
        latest[n][firstPlayer][secondPlayer] = maxRound;

        return {minRound, maxRound};
    }

public:
    vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memset(earliest, 0, sizeof(earliest));
        memset(latest, 0, sizeof(latest));

        auto result = solve(n, firstPlayer, secondPlayer);
        return {result.first, result.second};
    }
};

class Solution {
public:
    int mn[30][30][30], mx[30][30][30];
    void solve(int n, int l, int r) {
        if (mn[n][l][r]) return;
        if (l + r == n + 1) { mn[n][l][r] = mx[n][l][r] = 1; return; }
        if (l > n + 1 - r) { int nl = n + 1 - r, nr = n + 1 - l; l = nl; r = nr; }
        int half = (n + 1) / 2;
        int lo = 1000, hi = 0;
        if (r <= n / 2) {
            // both in left half
            for (int i = 0; i < l; i++) {
                for (int j = 0; j < r - l; j++) {
                    int nl = i + 1, nr = i + j + 2;
                    if (nr > half) continue;
                    solve(half, nl, nr);
                    lo = min(lo, mn[half][nl][nr]);
                    hi = max(hi, mx[half][nl][nr]);
                }
            }
        } else {
            // r in right half, l in left half, l < n+1-r
            int rm = n + 1 - r; // mirror position of r
            int mid = (n - 2 * rm) / 2; // players strictly between rm and r region... computing count between
            // players between l and rm (exclusive): rm - l - 1 ; then players between rm and r that pair among themselves: (r - rm - 1)/2 rounded
            int between = rm - l - 1;
            int inner = (r - rm - 1 + 1) / 2; // number of survivors from the middle segment (fixed)
            for (int i = 0; i < l; i++) {
                for (int j = 0; j <= between; j++) {
                    int nl = i + 1, nr = i + j + 1 + inner + 1;
                    if (nr > half) continue;
                    solve(half, nl, nr);
                    lo = min(lo, mn[half][nl][nr]);
                    hi = max(hi, mx[half][nl][nr]);
                }
            }
            (void)mid;
        }
        mn[n][l][r] = lo + 1;
        mx[n][l][r] = hi + 1;
        // store mirrored as well
        int ml = n + 1 - r, mr = n + 1 - l;
        mn[n][ml][mr] = lo + 1;
        mx[n][ml][mr] = hi + 1;
    }
    vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memset(mn, 0, sizeof(mn));
        memset(mx, 0, sizeof(mx));
        solve(n, firstPlayer, secondPlayer);
        return {mn[n][firstPlayer][secondPlayer], mx[n][firstPlayer][secondPlayer]};
    }
};

