class Solution {
    int n;
    int f, s;
    unordered_map<int, pair<int,int>> memo;

    pair<int,int> dfs(int mask) {
        auto it = memo.find(mask);
        if (it != memo.end()) return it->second;

        int ps[30];
        int m = 0;
        for (int i = 0; i < n; ++i)
            if ((mask >> i) & 1) ps[m++] = i + 1;

        // If the two best players are paired this round, they compete now.
        for (int i = 0, j = m - 1; i < j; ++i, --j) {
            int a = ps[i], b = ps[j];
            if ((a == f && b == s) || (a == s && b == f)) {
                memo[mask] = make_pair(1, 1);
                return memo[mask];
            }
        }

        int half = m / 2;
        int midBit = (m & 1) ? (1 << (ps[half] - 1)) : 0;

        // Enumerate all possible sets of winners for this round.
        vector<int> nexts;
        nexts.push_back(0);
        for (int i = 0; i < half; ++i) {
            int a = ps[i], b = ps[m - 1 - i];
            vector<int> nn;
            if (a == f || a == s) {
                int bit = 1 << (a - 1);
                for (int v : nexts) nn.push_back(v | bit);
            } else if (b == f || b == s) {
                int bit = 1 << (b - 1);
                for (int v : nexts) nn.push_back(v | bit);
            } else {
                int ba = 1 << (a - 1);
                int bb = 1 << (b - 1);
                for (int v : nexts) {
                    nn.push_back(v | ba);
                    nn.push_back(v | bb);
                }
            }
            nexts.swap(nn);
        }
        if (midBit != 0)
            for (int &v : nexts) v |= midBit;

        int mn = INT_MAX, mx = INT_MIN;
        for (int nm : nexts) {
            pair<int,int> r = dfs(nm);
            if (r.first + 1 < mn) mn = r.first + 1;
            if (r.second + 1 > mx) mx = r.second + 1;
        }
        memo[mask] = make_pair(mn, mx);
        return memo[mask];
    }

public:
    vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        this->n = n;
        f = firstPlayer;
        s = secondPlayer;
        memo.clear();
        pair<int,int> r = dfs((1 << n) - 1);
        return vector<int>{r.first, r.second};
    }
};

class Solution {
    int memo_min[30][30][30];
    int memo_max[30][30][30];

    pair<int, int> dfs(int n, int f, int s) {
        if (f + s == n + 1) {
            return {1, 1};
        }

        if (f + s > n + 1) {
            int nf = n + 1 - s;
            int ns = n + 1 - f;
            f = nf;
            s = ns;
        }

        if (memo_min[n][f][s] != 0) {
            return {memo_min[n][f][s], memo_max[n][f][s]};
        }

        int mid = (s <= n / 2) ? s : (n - s + 1);
        int K = (s <= n / 2) ? 0 : (2 * s - n - 1) / 2;
        int next_n = (n + 1) / 2;

        int min_round = 100, max_round = 0;

        for (int c1 = 0; c1 <= f - 1; ++c1) {
            for (int c2 = 0; c2 <= mid - 1 - f; ++c2) {
                int next_f = c1 + 1;
                int next_s = next_f + c2 + 1 + K;
                auto [cur_min, cur_max] = dfs(next_n, next_f, next_s);
                min_round = min(min_round, 1 + cur_min);
                max_round = max(max_round, 1 + cur_max);
            }
        }

        memo_min[n][f][s] = min_round;
        memo_max[n][f][s] = max_round;
        return {min_round, max_round};
    }

public:
    vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        auto [earliest, latest] = dfs(n, firstPlayer, secondPlayer);
        return {earliest, latest};
    }
};

