class Solution {
    pair<int, int> memo[29][29][29];

    pair<int, int> solve(int n, int a, int b) {
        if (a + b == n + 1) return {1, 1};

        if (memo[n][a][b].first != 0) {
            return memo[n][a][b];
        }

        bool possible[30][30] = {};
        possible[0][0] = true;

        auto addWinner = [](pair<int, int> state, int winner, int a, int b) {
            state.first += (winner < a);
            state.second += (winner < b);
            return state;
        };

        for (int i = 1; i <= n / 2; ++i) {
            int j = n + 1 - i;
            bool nextPossible[30][30] = {};

            for (int x = 0; x < 30; ++x) {
                for (int y = 0; y < 30; ++y) {
                    if (!possible[x][y]) continue;

                    if (i == a || j == a) {
                        auto state = addWinner({x, y}, a, a, b);
                        nextPossible[state.first][state.second] = true;
                    } else if (i == b || j == b) {
                        auto state = addWinner({x, y}, b, a, b);
                        nextPossible[state.first][state.second] = true;
                    } else {
                        auto state1 = addWinner({x, y}, i, a, b);
                        auto state2 = addWinner({x, y}, j, a, b);
                        nextPossible[state1.first][state1.second] = true;
                        nextPossible[state2.first][state2.second] = true;
                    }
                }
            }

            memcpy(possible, nextPossible, sizeof(possible));
        }

        if (n % 2 == 1) {
            int middle = (n + 1) / 2;
            bool nextPossible[30][30] = {};

            for (int x = 0; x < 30; ++x) {
                for (int y = 0; y < 30; ++y) {
                    if (!possible[x][y]) continue;
                    auto state = addWinner({x, y}, middle, a, b);
                    nextPossible[state.first][state.second] = true;
                }
            }

            memcpy(possible, nextPossible, sizeof(possible));
        }

        int nextN = (n + 1) / 2;
        int earliest = INT_MAX;
        int latest = 0;

        for (int x = 0; x < 30; ++x) {
            for (int y = 0; y < 30; ++y) {
                if (!possible[x][y]) continue;

                int nextA = x + 1;
                int nextB = y + 1;
                auto result = solve(nextN, nextA, nextB);

                earliest = min(earliest, result.first + 1);
                latest = max(latest, result.second + 1);
            }
        }

        return memo[n][a][b] = {earliest, latest};
    }

public:
    vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memset(memo, 0, sizeof(memo));
        auto result = solve(n, firstPlayer, secondPlayer);
        return {result.first, result.second};
    }
};

class Solution {
public:
    int mn[29][29][29], mx[29][29][29];
    bool vis[29][29][29];
    void solve(int n, int f, int s) {
        if (vis[n][f][s]) return;
        vis[n][f][s] = true;
        if (f + s == n + 1) {
            mn[n][f][s] = 1;
            mx[n][f][s] = 1;
            return;
        }
        int best = 1000, worst = 0;
        int pairs = n / 2;
        for (int mask = 0; mask < (1 << pairs); mask++) {
            bool ok = true;
            vector<int> alive(n + 2, 0);
            for (int i = 1; i <= pairs; i++) {
                int a = i, b = n + 1 - i;
                int w;
                bool bit = (mask >> (i - 1)) & 1;
                if (a == f || a == s) w = a;
                else if (b == f || b == s) w = b;
                else w = bit ? a : b;
                // skip redundant masks for forced pairs
                if ((a == f || a == s || b == f || b == s) && bit) { ok = false; break; }
                alive[w] = 1;
            }
            if (!ok) continue;
            if (n % 2) alive[(n + 1) / 2] = 1;
            int cnt = 0, nf = 0, ns = 0;
            for (int p = 1; p <= n; p++) {
                if (alive[p]) {
                    cnt++;
                    if (p == f) nf = cnt;
                    if (p == s) ns = cnt;
                }
            }
            solve(cnt, nf, ns);
            best = min(best, mn[cnt][nf][ns] + 1);
            worst = max(worst, mx[cnt][nf][ns] + 1);
        }
        mn[n][f][s] = best;
        mx[n][f][s] = worst;
    }
    vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memset(vis, 0, sizeof(vis));
        solve(n, firstPlayer, secondPlayer);
        return {mn[n][firstPlayer][secondPlayer], mx[n][firstPlayer][secondPlayer]};
    }
};

class Solution {
    private java.util.Map<Integer, int[]> memo;
    private int f1, f2;

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memo = new java.util.HashMap<>();
        f1 = firstPlayer - 1;
        f2 = secondPlayer - 1;
        return dfs((1 << n) - 1);
    }

    private int[] dfs(int mask) {
        int[] cached = memo.get(mask);
        if (cached != null) return cached;

        int k = Integer.bitCount(mask);
        int[] players = new int[k];
        for (int p = 0, i = 0; p < 28; p++) {
            if ((mask & (1 << p)) != 0) players[i++] = p;
        }

        int pos1 = -1, pos2 = -1;
        for (int i = 0; i < k; i++) {
            if (players[i] == f1) pos1 = i;
            else if (players[i] == f2) pos2 = i;
        }

        if (pos1 + pos2 == k - 1) {
            int[] res = {1, 1};
            memo.put(mask, res);
            return res;
        }

        int base = 0;
        int[] pa = new int[14];
        int[] pb = new int[14];
        int f = 0;
        for (int i = 0; i < k / 2; i++) {
            int a = players[i];
            int b = players[k - 1 - i];
            if (a == f1 || a == f2) {
                base |= 1 << a;
            } else if (b == f1 || b == f2) {
                base |= 1 << b;
            } else {
                pa[f] = a;
                pb[f] = b;
                f++;
            }
        }
        if ((k & 1) == 1) base |= 1 << players[k / 2];

        int earliest = Integer.MAX_VALUE;
        int latest = Integer.MIN_VALUE;
        int limit = 1 << f;
        for (int choice = 0; choice < limit; choice++) {
            int next = base;
            for (int i = 0; i < f; i++) {
                next |= 1 << (((choice >> i) & 1) == 0 ? pa[i] : pb[i]);
            }
            int[] child = dfs(next);
            if (child[0] < earliest) earliest = child[0];
            if (child[1] > latest) latest = child[1];
        }

        int[] res = {earliest + 1, latest + 1};
        memo.put(mask, res);
        return res;
    }
}

class Solution {
    private int[][][][] memo;

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memo = new int[n + 1][n + 1][n + 1][];
        return dp(n, firstPlayer, secondPlayer);
    }

    private int[] dp(int n, int l, int r) {
        if (l + r == n + 1) return new int[]{1, 1};
        if (l + r > n + 1) {
            int nl = n + 1 - r;
            int nr = n + 1 - l;
            l = nl;
            r = nr;
        }
        if (memo[n][l][r] != null) return memo[n][l][r];
        int half = (n + 1) / 2;
        int mn = Integer.MAX_VALUE, mx = Integer.MIN_VALUE;
        if (r <= n / 2) {
            for (int i = 0; i < l; i++) {
                for (int j = 0; j < r - l; j++) {
                    int[] res = dp(half, i + 1, i + j + 2);
                    mn = Math.min(mn, res[0] + 1);
                    mx = Math.max(mx, res[1] + 1);
                }
            }
        } else {
            int m = n + 1 - r;
            int fixed = (r - m) / 2;
            for (int i = 0; i < l; i++) {
                for (int j = 0; j < m - l; j++) {
                    int[] res = dp(half, i + 1, i + 1 + j + fixed + 1);
                    mn = Math.min(mn, res[0] + 1);
                    mx = Math.max(mx, res[1] + 1);
                }
            }
        }
        memo[n][l][r] = new int[]{mn, mx};
        return memo[n][l][r];
    }
}

class Solution {
    private int[][][] minMemo = new int[29][29][29];
    private int[][][] maxMemo = new int[29][29][29];

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        return dfs(n, firstPlayer, secondPlayer);
    }

    private int[] dfs(int n, int a, int b) {
        if (a + b == n + 1) {
            return new int[]{1, 1};
        }

        if (minMemo[n][a][b] != 0) {
            return new int[]{minMemo[n][a][b], maxMemo[n][a][b]};
        }

        int earliest = Integer.MAX_VALUE;
        int latest = 0;

        int pairCount = n / 2;
        int totalMasks = 1 << pairCount;

        for (int mask = 0; mask < totalMasks; mask++) {
            int lessThanA = 0;
            int lessThanB = 0;

            for (int i = 0; i < pairCount; i++) {
                int left = i + 1;
                int right = n - i;

                int winner;
                if (left == a || right == a) {
                    winner = a;
                } else if (left == b || right == b) {
                    winner = b;
                } else {
                    winner = ((mask & (1 << i)) == 0) ? left : right;
                }

                if (winner < a) {
                    lessThanA++;
                }
                if (winner < b) {
                    lessThanB++;
                }
            }

            if ((n & 1) == 1) {
                int middle = (n + 1) / 2;
                if (middle < a) {
                    lessThanA++;
                }
                if (middle < b) {
                    lessThanB++;
                }
            }

            int nextA = lessThanA + 1;
            int nextB = lessThanB + 1;

            int[] result = dfs((n + 1) / 2, nextA, nextB);
            earliest = Math.min(earliest, result[0] + 1);
            latest = Math.max(latest, result[1] + 1);
        }

        minMemo[n][a][b] = earliest;
        maxMemo[n][a][b] = latest;

        return new int[]{earliest, latest};
    }
}

class Solution {
    private int[][][][] dp;

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        int left = firstPlayer - 1;
        int mid = secondPlayer - firstPlayer - 1;
        int right = n - secondPlayer;
        dp = new int[29][29][29][2];
        return dfs(left, mid, right);
    }

    private int[] dfs(int left, int mid, int right) {
        if (dp[left][mid][right][0] != 0) {
            return new int[]{dp[left][mid][right][0], dp[left][mid][right][1]};
        }
        if (left == right) {
            dp[left][mid][right][0] = 1;
            dp[left][mid][right][1] = 1;
            return new int[]{1, 1};
        }
        int total = left + mid + right + 2;
        int[] types = new int[total];
        int idx = 0;
        for (int i = 0; i < left; i++) types[idx++] = 0;
        types[idx++] = 1;
        for (int i = 0; i < mid; i++) types[idx++] = 2;
        types[idx++] = 3;
        for (int i = 0; i < right; i++) types[idx++] = 4;
        java.util.List<int[]> frees = new java.util.ArrayList<>();
        int initL = 0, initM = 0, initR = 0;
        for (int i = 0; i < total / 2; i++) {
            int t1 = types[i];
            int t2 = types[total - 1 - i];
            boolean spec1 = t1 == 1 || t1 == 3;
            boolean spec2 = t2 == 1 || t2 == 3;
            if (!spec1 && !spec2) {
                frees.add(new int[]{t1, t2});
            }
        }
        if (total % 2 == 1) {
            int t = types[total / 2];
            if (t == 0) initL++;
            else if (t == 2) initM++;
            else if (t == 4) initR++;
        }
        int k = frees.size();
        int minR = Integer.MAX_VALUE;
        int maxR = 0;
        for (int mask = 0; mask < (1 << k); mask++) {
            int cl = initL, cm = initM, cr = initR;
            for (int j = 0; j < k; j++) {
                int[] p = frees.get(j);
                int t = ((mask & (1 << j)) == 0) ? p[0] : p[1];
                if (t == 0) cl++;
                else if (t == 2) cm++;
                else if (t == 4) cr++;
            }
            int[] sub = dfs(cl, cm, cr);
            minR = Math.min(minR, 1 + sub[0]);
            maxR = Math.max(maxR, 1 + sub[1]);
        }
        dp[left][mid][right][0] = minR;
        dp[left][mid][right][1] = maxR;
        return new int[]{minR, maxR};
    }
}

class Solution {
    private final int[][][] earliest = new int[29][29][29];
    private final int[][][] latest = new int[29][29][29];

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        return solve(n, firstPlayer, secondPlayer);
    }

    private int[] solve(int n, int a, int b) {
        if (a + b == n + 1) {
            return new int[]{1, 1};
        }

        if (earliest[n][a][b] != 0) {
            return new int[]{earliest[n][a][b], latest[n][a][b]};
        }

        int[] result = {Integer.MAX_VALUE, Integer.MIN_VALUE};
        enumerate(n, a, b, 1, 0, 0, result);

        earliest[n][a][b] = result[0];
        latest[n][a][b] = result[1];
        return result;
    }

    private void enumerate(int n, int a, int b, int match,
                           int beforeA, int beforeB, int[] result) {
        int pairs = n / 2;

        if (match > pairs) {
            if ((n & 1) == 1) {
                int middle = pairs + 1;
                if (middle < a) beforeA++;
                if (middle < b) beforeB++;
            }

            int nextA = beforeA + 1;
            int nextB = beforeB + 1;
            int[] next = solve((n + 1) / 2, nextA, nextB);

            result[0] = Math.min(result[0], next[0] + 1);
            result[1] = Math.max(result[1], next[1] + 1);
            return;
        }

        int left = match;
        int right = n + 1 - match;

        if (left == a || right == a) {
            advance(n, a, b, match, beforeA, beforeB, result, a);
        } else if (left == b || right == b) {
            advance(n, a, b, match, beforeA, beforeB, result, b);
        } else {
            advance(n, a, b, match, beforeA, beforeB, result, left);
            advance(n, a, b, match, beforeA, beforeB, result, right);
        }
    }

    private void advance(int n, int a, int b, int match,
                         int beforeA, int beforeB, int[] result, int winner) {
        enumerate(
            n, a, b, match + 1,
            beforeA + (winner < a ? 1 : 0),
            beforeB + (winner < b ? 1 : 0),
            result
        );
    }
}

class Solution {
    int[][][] memoMin = new int[29][29][29];
    int[][][] memoMax = new int[29][29][29];

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        int[] r = solve(n, firstPlayer, secondPlayer);
        return r;
    }

    private int[] solve(int n, int a, int b) {
        if (a + b == n + 1) return new int[]{1, 1};
        if (memoMin[n][a][b] != 0) return new int[]{memoMin[n][a][b], memoMax[n][a][b]};
        int half = n / 2;
        int[] fi = new int[half], fj = new int[half];
        int k = 0;
        boolean[] fixedAlive = new boolean[n + 2];
        for (int i = 1; i <= half; i++) {
            int j = n + 1 - i;
            if (i == a || i == b) fixedAlive[i] = true;
            else if (j == a || j == b) fixedAlive[j] = true;
            else { fi[k] = i; fj[k] = j; k++; }
        }
        if (n % 2 == 1) fixedAlive[(n + 1) / 2] = true;
        int m = (n + 1) / 2;
        int best = Integer.MAX_VALUE, worst = Integer.MIN_VALUE;
        boolean[] alive = new boolean[n + 2];
        for (int mask = 0; mask < (1 << k); mask++) {
            for (int x = 1; x <= n; x++) alive[x] = fixedAlive[x];
            for (int t = 0; t < k; t++) {
                if (((mask >> t) & 1) == 1) alive[fi[t]] = true;
                else alive[fj[t]] = true;
            }
            int na = 0, nb = 0, cnt = 0;
            for (int x = 1; x <= n; x++) {
                if (alive[x]) {
                    cnt++;
                    if (x == a) na = cnt;
                    if (x == b) nb = cnt;
                }
            }
            int[] r = solve(m, na, nb);
            best = Math.min(best, r[0] + 1);
            worst = Math.max(worst, r[1] + 1);
        }
        memoMin[n][a][b] = best;
        memoMax[n][a][b] = worst;
        return new int[]{best, worst};
    }
}

class Solution {
    private int[][][] minDp;
    private int[][][] maxDp;

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        minDp = new int[n + 1][n + 1][n + 1];
        maxDp = new int[n + 1][n + 1][n + 1];

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= n; k++) {
                    minDp[i][j][k] = -1;
                    maxDp[i][j][k] = -1;
                }
            }
        }

        return dfs(n, firstPlayer, secondPlayer);
    }

    private int[] dfs(int m, int a, int b) {
        if (a + b == m + 1) {
            return new int[]{1, 1};
        }

        if (minDp[m][a][b] != -1) {
            return new int[]{minDp[m][a][b], maxDp[m][a][b]};
        }

        int pairs = m / 2;
        int nextM = (m + 1) / 2;
        int mn = Integer.MAX_VALUE;
        int mx = Integer.MIN_VALUE;
        int masks = 1 << pairs;

        for (int mask = 0; mask < masks; mask++) {
            int winners = 0;

            for (int i = 1; i <= pairs; i++) {
                int opp = m + 1 - i;
                int winner;

                if (i == a || opp == a) {
                    winner = a;
                } else if (i == b || opp == b) {
                    winner = b;
                } else {
                    winner = ((mask >> (i - 1)) & 1) == 0 ? i : opp;
                }

                winners |= 1 << winner;
            }

            if ((m & 1) == 1) {
                winners |= 1 << ((m + 1) / 2);
            }

            int na = Integer.bitCount(winners & ((1 << a) - 1)) + 1;
            int nb = Integer.bitCount(winners & ((1 << b) - 1)) + 1;

            int[] res = dfs(nextM, na, nb);
            mn = Math.min(mn, res[0] + 1);
            mx = Math.max(mx, res[1] + 1);
        }

        minDp[m][a][b] = mn;
        maxDp[m][a][b] = mx;
        return new int[]{mn, mx};
    }
}

import java.util.*;

class Solution {
    private Map<Integer, int[]> memo;

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memo = new HashMap<>();
        return solve(n, firstPlayer, secondPlayer);
    }

    private int[] solve(int n, int first, int second) {
        if (first + second == n + 1) {
            return new int[]{1, 1};
        }

        int key = (n << 10) | (first << 5) | second;
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        Set<Integer> nextStates = new HashSet<>();
        generateNextStates(1, n, first, second, 0, 0, nextStates);

        int nextN = (n + 1) / 2;
        int earliest = Integer.MAX_VALUE;
        int latest = Integer.MIN_VALUE;

        for (int state : nextStates) {
            int nextFirst = state >> 5;
            int nextSecond = state & 31;

            int[] result = solve(nextN, nextFirst, nextSecond);
            earliest = Math.min(earliest, result[0] + 1);
            latest = Math.max(latest, result[1] + 1);
        }

        int[] answer = new int[]{earliest, latest};
        memo.put(key, answer);
        return answer;
    }

    private void generateNextStates(
            int pairIndex,
            int n,
            int first,
            int second,
            int beforeFirst,
            int beforeSecond,
            Set<Integer> nextStates
    ) {
        int half = n / 2;

        if (pairIndex > half) {
            if (n % 2 == 1) {
                int middle = half + 1;
                if (middle < first) beforeFirst++;
                if (middle < second) beforeSecond++;
            }

            int nextFirst = beforeFirst + 1;
            int nextSecond = beforeSecond + 1;
            nextStates.add((nextFirst << 5) | nextSecond);
            return;
        }

        int left = pairIndex;
        int right = n + 1 - pairIndex;

        if (left == first || right == first) {
            addWinner(pairIndex, n, first, second, beforeFirst, beforeSecond, nextStates, first);
        } else if (left == second || right == second) {
            addWinner(pairIndex, n, first, second, beforeFirst, beforeSecond, nextStates, second);
        } else {
            addWinner(pairIndex, n, first, second, beforeFirst, beforeSecond, nextStates, left);
            addWinner(pairIndex, n, first, second, beforeFirst, beforeSecond, nextStates, right);
        }
    }

    private void addWinner(
            int pairIndex,
            int n,
            int first,
            int second,
            int beforeFirst,
            int beforeSecond,
            Set<Integer> nextStates,
            int winner
    ) {
        if (winner < first) beforeFirst++;
        if (winner < second) beforeSecond++;

        generateNextStates(
                pairIndex + 1,
                n,
                first,
                second,
                beforeFirst,
                beforeSecond,
                nextStates
        );
    }
}

import java.util.*;

class Solution {
    Map<String, int[]> memo = new HashMap<>();

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        return solve(n, firstPlayer, secondPlayer);
    }

    int[] solve(int n, int f, int s) {
        if (f > s) { int t = f; f = s; s = t; }
        // by symmetry: position f from front <-> mirror
        if (f - 1 > n - s) {
            int nf = n + 1 - s;
            int ns = n + 1 - f;
            f = nf; s = ns;
        }
        String key = n + "," + f + "," + s;
        if (memo.containsKey(key)) return memo.get(key);

        if (f + s == n + 1) {
            int[] res = new int[]{1, 1};
            memo.put(key, res);
            return res;
        }

        int minR = Integer.MAX_VALUE, maxR = Integer.MIN_VALUE;
        int half = n / 2;
        // enumerate outcomes of the pairs on the left half (positions 1..half)
        // for each pair (i, n+1-i), one survives
        // f and s must survive. Their new positions determined by how many below survive.
        // recurse over choices
        int[] r = enumerate(n, f, s, 1, new ArrayList<>());
        minR = r[0]; maxR = r[1];
        memo.put(key, r);
        return r;
    }

    // survivors: list of surviving original positions (from left perspective)
    int[] enumerate(int n, int f, int s, int i, List<Integer> survivors) {
        int half = n / 2;
        if (i > half) {
            // middle player advances if odd
            List<Integer> all = new ArrayList<>(survivors);
            if (n % 2 == 1) all.add(half + 1);
            Collections.sort(all);
            int newN = all.size();
            int nf = all.indexOf(f) + 1;
            int ns = all.indexOf(s) + 1;
            int[] sub = solve(newN, nf, ns);
            return new int[]{sub[0] + 1, sub[1] + 1};
        }
        int j = n + 1 - i;
        List<Integer> choices = new ArrayList<>();
        if (i == f || i == s) {
            choices.add(i);
        } else if (j == f || j == s) {
            choices.add(j);
        } else {
            choices.add(i);
            choices.add(j);
        }
        int minR = Integer.MAX_VALUE, maxR = Integer.MIN_VALUE;
        for (int c : choices) {
            List<Integer> next = new ArrayList<>(survivors);
            next.add(c);
            int[] r = enumerate(n, f, s, i + 1, next);
            minR = Math.min(minR, r[0]);
            maxR = Math.max(maxR, r[1]);
        }
        return new int[]{minR, maxR};
    }
}

class Solution {
    private int[][][][] memo;

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memo = new int[n + 1][n + 1][n + 1][];
        return solve(n, firstPlayer, secondPlayer);
    }

    private int[] solve(int n, int first, int second) {
        if (first + second == n + 1) {
            return new int[]{1, 1};
        }

        // Reflect the row to merge symmetric states.
        if (first + second > n + 1) {
            int reflectedFirst = n + 1 - second;
            second = n + 1 - first;
            first = reflectedFirst;
        }

        if (memo[n][first][second] != null) {
            return memo[n][first][second];
        }

        int nextN = (n + 1) / 2;

        // reachable[a][b]: a winners precede first, b winners precede second.
        boolean[][] reachable = new boolean[nextN + 1][nextN + 1];
        reachable[0][0] = true;
        int processed = 0;

        for (int left = 1, right = n; left <= right; left++, right--) {
            int[] possibleWinners;
            if (left == first || left == second || left == right) {
                possibleWinners = new int[]{left};
            } else if (right == first || right == second) {
                possibleWinners = new int[]{right};
            } else {
                possibleWinners = new int[]{left, right};
            }

            boolean[][] next = new boolean[nextN + 1][nextN + 1];
            for (int winner : possibleWinners) {
                int beforeFirst = winner < first ? 1 : 0;
                int beforeSecond = winner < second ? 1 : 0;

                for (int a = 0; a <= processed; a++) {
                    for (int b = a; b <= processed; b++) {
                        if (reachable[a][b]) {
                            next[a + beforeFirst][b + beforeSecond] = true;
                        }
                    }
                }
            }

            reachable = next;
            processed++;
        }

        int earliest = Integer.MAX_VALUE;
        int latest = 0;

        for (int a = 0; a < nextN; a++) {
            for (int b = a + 1; b < nextN; b++) {
                if (reachable[a][b]) {
                    int[] result = solve(nextN, a + 1, b + 1);
                    earliest = Math.min(earliest, result[0] + 1);
                    latest = Math.max(latest, result[1] + 1);
                }
            }
        }

        return memo[n][first][second] = new int[]{earliest, latest};
    }
}

class Solution {
    int[][] memo = new int[32 * 32 * 32][];

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        return solve(n, firstPlayer, secondPlayer);
    }

    int[] solve(int n, int f, int s) {
        if (f + s == n + 1) return new int[]{1, 1};
        int key = n * 1024 + f * 32 + s;
        if (memo[key] != null) return memo[key];
        int m = n / 2;
        int mn = Integer.MAX_VALUE, mx = Integer.MIN_VALUE;
        for (int mask = 0; mask < (1 << m); mask++) {
            boolean[] surv = new boolean[n + 2];
            for (int i = 1; i <= m; i++) {
                int a = i, b = n + 1 - i;
                if (a == f || a == s) surv[a] = true;
                else if (b == f || b == s) surv[b] = true;
                else if (((mask >> (i - 1)) & 1) == 1) surv[a] = true;
                else surv[b] = true;
            }
            if (n % 2 == 1) surv[m + 1] = true;
            int cnt = 0, nf = 0, ns = 0;
            for (int p = 1; p <= n; p++) {
                if (surv[p]) {
                    cnt++;
                    if (p == f) nf = cnt;
                    if (p == s) ns = cnt;
                }
            }
            int[] r = solve(cnt, nf, ns);
            mn = Math.min(mn, r[0] + 1);
            mx = Math.max(mx, r[1] + 1);
        }
        return memo[key] = new int[]{mn, mx};
    }
}

