        int m = mat.size();
        vector<pair<int, int>> rows;
        rows.reserve(m);

        for (int i = 0; i < m; i++) {
            const vector<int>& row = mat[i];
            int lo = 0, hi = row.size();
            // Binary search for the first 0; lo ends as the count of 1's
            while (lo < hi) {
                int mid = lo + (hi - lo) / 2;
                if (row[mid] == 1) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            rows.push_back({lo, i});
        }

        sort(rows.begin(), rows.end());

        vector<int> result;
        result.reserve(k);
        for (int i = 0; i < k; i++) {
            result.push_back(rows[i].second);
        }
        return result;
    }
};

