var getCoprimes = function(nums, edges) {
    const n = nums.length;
    const MAX = 50;

    const gcd = (a, b) => {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };

    const cop = Array.from({ length: MAX + 1 }, () => new Array(MAX + 1).fill(false));
    for (let i = 1; i <= MAX; i++) {
        for (let j = 1; j <= MAX; j++) {
            cop[i][j] = gcd(i, j) === 1;
        }
    }

    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    const ans = new Array(n).fill(-1);
    const last = new Array(MAX + 1).fill(-1);
    const depth = new Array(n).fill(0);

    const stack = [[0, -1, 0, 0, -1]];

    while (stack.length > 0) {
        const ev = stack.pop();
        const u = ev[0];
        const p = ev[1];
        const d = ev[2];
        const state = ev[3];

        if (state === 0) {
            const val = nums[u];
            let best = -1;
            let bestDepth = -1;

            for (let v = 1; v <= MAX; v++) {
                const idx = last[v];
                if (idx !== -1 && cop[val][v]) {
                    const dep = depth[idx];
                    if (dep > bestDepth) {
                        bestDepth = dep;
                        best = idx;
                    }
                }
            }

            ans[u] = best;
            depth[u] = d;

            const prev = last[val];
            stack.push([u, p, d, 1, prev]);
            last[val] = u;

            const neighbors = adj[u];
            for (let i = 0; i < neighbors.length; i++) {
                const nei = neighbors[i];
                if (nei !== p) {
                    stack.push([nei, u, d + 1, 0, -1]);
                }
            }
        } else {
            const prev = ev[4];
            last[nums[u]] = prev;
        }
    }

    return ans;
};

var getCoprimes = function(nums, edges) {
    const n = nums.length;
    const gcd = (a, b) => { while (b) { [a, b] = [b, a % b]; } return a; };
    const cop = [];
    for (let i = 0; i <= 50; i++) {
        cop.push([]);
        for (let j = 1; j <= 50; j++) if (i > 0 && gcd(i, j) === 1) cop[i].push(j);
    }
    const deg = new Int32Array(n + 1);
    for (const [a, b] of edges) { deg[a]++; deg[b]++; }
    const head = new Int32Array(n + 1);
    for (let i = 0; i < n; i++) head[i + 1] = head[i] + deg[i];
    const pos = head.slice(0, n);
    const adj = new Int32Array(2 * (n - 1));
    for (const [a, b] of edges) { adj[pos[a]++] = b; adj[pos[b]++] = a; }
    const stNode = [], stDepth = [];
    for (let v = 0; v <= 50; v++) { stNode.push([]); stDepth.push([]); }
    const ans = new Array(n).fill(-1);
    const stack = new Int32Array(n), idx = new Int32Array(n), par = new Int32Array(n).fill(-1);
    const depth = new Int32Array(n);
    let sp = 0;
    stack[sp++] = 0;
    idx[0] = -1;
    while (sp > 0) {
        const u = stack[sp - 1];
        if (idx[u] === -1) {
            let best = -1, bd = -1;
            for (const v of cop[nums[u]]) {
                const s = stDepth[v];
                if (s.length && s[s.length - 1] > bd) {
                    bd = s[s.length - 1];
                    best = stNode[v][s.length - 1];
                }
            }
            ans[u] = best;
            stNode[nums[u]].push(u);
            stDepth[nums[u]].push(depth[u]);
            idx[u] = head[u];
        }
        if (idx[u] < head[u + 1]) {
            const w = adj[idx[u]++];
            if (w === par[u]) continue;
            par[w] = u;
            depth[w] = depth[u] + 1;
            idx[w] = -1;
            stack[sp++] = w;
        } else {
            stNode[nums[u]].pop();
            stDepth[nums[u]].pop();
            sp--;
        }
    }
    return ans;
};

