    const stacks = Array.from({ length: 51 }, () => []); // each: array of [node, depth]
    const depth = new Array(n).fill(0);
    const parent = new Array(n).fill(-1);
    // iterative DFS with enter/exit
    const stack = [[0, false]];
    while (stack.length) {
        const [node, exiting] = stack.pop();
        const val = nums[node];
        if (exiting) {
            stacks[val].pop();
            continue;
        }
        // compute answer
        let bestDepth = -1, best = -1;
        for (const c of coprimes[val]) {
            const st = stacks[c];
            if (st.length) {
                const [an, d] = st[st.length - 1];
                if (d > bestDepth) { bestDepth = d; best = an; }
            }
        }
        ans[node] = best;
        stacks[val].push([node, depth[node]]);
        stack.push([node, true]);
        for (const nb of adj[node]) {
            if (nb !== parent[node]) {
                parent[nb] = node;
                depth[nb] = depth[node] + 1;
                stack.push([nb, false]);
            }
        }
    }
    return ans;
