            depth[v] = depth[u] + 1;
            enter(v);
            st.push(v);
        } else {
            stackNode[nums[u]] = prevNode[u];
            stackDepth[nums[u]] = prevDepth[u];
            st.pop();
        }
    }
    return ans;
};

function getCoprimes(nums: number[], edges: number[][]): number[] {
    const n = nums.length;
    const adj: number[][] = Array.from({ length: n }, () => []);

    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    const gcd = (a: number, b: number): number => {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };

    const coprimes: number[][] = Array.from({ length: 51 }, () => []);
    for (let a = 1; a <= 50; a++) {
        for (let b = 1; b <= 50; b++) {
            if (gcd(a, b) === 1) {
                coprimes[a].push(b);
            }
        }
    }

    const ans: number[] = new Array(n).fill(-1);
    const depth: number[] = new Array(n).fill(0);
    const last: number[] = new Array(51).fill(-1);

    const stack: [number, number, number, number][] = [[0, -1, 0, -1]];

    while (stack.length > 0) {
        const [u, parent, state, oldLast] = stack.pop()!;
        const value = nums[u];

        if (state === 0) {
            if (parent !== -1) {
                depth[u] = depth[parent] + 1;
            }

            let best = -1;
            let bestDepth = -1;

            for (const x of coprimes[value]) {
                const idx = last[x];
                if (idx !== -1 && depth[idx] > bestDepth) {
                    bestDepth = depth[idx];
                    best = idx;
                }
            }

            ans[u] = best;

            const previous = last[value];
            last[value] = u;

            stack.push([u, parent, 1, previous]);

            for (const next of adj[u]) {
                if (next !== parent) {
                    stack.push([next, u, 0, -1]);
                }
            }
        } else {
            last[value] = oldLast;
        }
    }

    return ans;
}

function getCoprimes(nums: number[], edges: number[][]): number[] {
    const n = nums.length;
    const adj: number[][] = Array.from({ length: n }, () => []);
    for (const [a, b] of edges) {
        adj[a].push(b);
