    }
    const gcd = (a: number, b: number): number => {
        while (b !== 0) {
            const t = b;
            b = a % b;
            a = t;
        }
        return a;
    };
    const lastNode: number[] = new Array(51).fill(-1);
    const lastDepth: number[] = new Array(51).fill(-1);
    const oldNode: number[] = new Array(n);
    const oldDepth: number[] = new Array(n);
    const ans: number[] = new Array(n).fill(-1);
    const stack: number[][] = [[0, -1, 0, 0]];
    while (stack.length > 0) {
        const [u, p, d, stage] = stack.pop()!;
        const val = nums[u];
        if (stage === 0) {
            let bestD = -1;
            let best = -1;
            for (let v = 1; v <= 50; v++) {
                if (lastDepth[v] > bestD && gcd(val, v) === 1) {
                    bestD = lastDepth[v];
                    best = lastNode[v];
                }
            }
            ans[u] = best;
            oldNode[u] = lastNode[val];
            oldDepth[u] = lastDepth[val];
            lastNode[val] = u;
            lastDepth[val] = d;
            stack.push([u, p, d, 1]);
            const ch = adj[u];
            for (let i = ch.length - 1; i >= 0; i--) {
                const nei = ch[i];
                if (nei !== p) {
                    stack.push([nei, u, d + 1, 0]);
                }
            }
        } else {
            lastNode[val] = oldNode[u];
