        for (int i = 1; i <= 50; i++)
            for (int j = 1; j <= 50; j++)
                cop[i][j] = (__gcd(i, j) == 1);
        vector<vector<pair<int,int>>> st(51); // value -> stack of (node, depth)
        vector<int> ans(n, -1);
        vector<int> depth(n, 0), parent(n, -1), idx(n, 0);
        // iterative DFS
        vector<int> stack;
        stack.push_back(0);
        parent[0] = -1;
        depth[0] = 0;
        // on entering node
        auto enter = [&](int u) {
            int best = -1, bestDepth = -1;
            for (int v = 1; v <= 50; v++) {
                if (cop[nums[u]][v] && !st[v].empty()) {
                    auto& p = st[v].back();
                    if (p.second > bestDepth) {
                        bestDepth = p.second;
                        best = p.first;
                    }
                }
            }
            ans[u] = best;
            st[nums[u]].push_back({u, depth[u]});
        };
        enter(0);
        while (!stack.empty()) {
            int u = stack.back();
            if (idx[u] < (int)adj[u].size()) {
                int v = adj[u][idx[u]++];
                if (v == parent[u]) continue;
                parent[v] = u;
                depth[v] = depth[u] + 1;
                enter(v);
                stack.push_back(v);
            } else {
                st[nums[u]].pop_back();
                stack.pop_back();
            }
        }
        return ans;
    }
};

