class Solution {
    public int[] getCoprimes(int[] nums, int[][] edges) {
        int n = nums.length;

        boolean[][] coprime = new boolean[51][51];
        for (int a = 1; a <= 50; a++) {
            for (int b = a; b <= 50; b++) {
                int x = a, y = b;
                while (y != 0) {
                    int remainder = x % y;
                    x = y;
                    y = remainder;
                }
                coprime[a][b] = coprime[b][a] = (x == 1);
            }
        }

        // Neighbors of u occupy adjacency[offset[u] ... offset[u + 1]).
        int[] offset = new int[n + 1];
        for (int[] edge : edges) {
            offset[edge[0] + 1]++;
            offset[edge[1] + 1]++;
        }
        for (int i = 1; i <= n; i++) {
            offset[i] += offset[i - 1];
        }

        int[] cursor = offset.clone();
        int[] adjacency = new int[2 * edges.length];
        for (int[] edge : edges) {
            adjacency[cursor[edge[0]]++] = edge[1];
            adjacency[cursor[edge[1]]++] = edge[0];
        }

        int[] answer = new int[n];
        int[] parent = new int[n];
        int[] depth = new int[n];
        int[] previous = new int[n];
        int[] latest = new int[51];
        java.util.Arrays.fill(latest, -1);
        parent[0] = -1;

        // Nonnegative events enter a node; ~node events leave it.
        int[] stack = new int[2 * n];
        int size = 0;
        stack[size++] = 0;

        while (size > 0) {
            int event = stack[--size];

            if (event < 0) {
                int node = ~event;
                latest[nums[node]] = previous[node];
                continue;
            }

            int node = event;
            int value = nums[node];
            int closest = -1;
            int bestDepth = -1;

            for (int v = 1; v <= 50; v++) {
                int ancestor = latest[v];
                if (ancestor != -1 && coprime[value][v]
                        && depth[ancestor] > bestDepth) {
                    closest = ancestor;
                    bestDepth = depth[ancestor];
                }
            }
            answer[node] = closest;

            previous[node] = latest[value];
            latest[value] = node;
            stack[size++] = ~node;

            for (int i = offset[node]; i < offset[node + 1]; i++) {
                int child = adjacency[i];
                if (child != parent[node]) {
                    parent[child] = node;
                    depth[child] = depth[node] + 1;
                    stack[size++] = child;
                }
            }
        }

        return answer;
    }
}

