                maxDepth = lastDepth[v];
                bestNode = lastNode[v];
            }
        }
        ans[u] = bestNode;

        int prevNode = lastNode[val];
        int prevDepth = lastDepth[val];
        lastNode[val] = u;
        lastDepth[val] = depth;

        for (int e = head[u]; e != -1; e = next[e]) {
            int v = to[e];
            if (v != p) {
                dfs(v, u, depth + 1);
            }
        }

        lastNode[val] = prevNode;
        lastDepth[val] = prevDepth;
    }
}

class Solution {
    public int[] getCoprimes(int[] nums, int[][] edges) {
        int n = nums.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        boolean[][] coprime = new boolean[51][51];
        for (int i = 1; i <= 50; i++) {
            for (int j = 1; j <= 50; j++) {
                coprime[i][j] = gcd(i, j) == 1;
            }
        }
        Deque<int[]>[] last = new ArrayDeque[51];
        for (int i = 1; i <= 50; i++) last[i] = new ArrayDeque<>();
        int[] ans = new int[n];
        Arrays.fill(ans, -1);
        dfs(0, -1, 0, nums, adj, coprime, last, ans);
        return ans;
    }

    private void dfs(int u, int parent, int depth, int[] nums, List<Integer>[] adj,
                     boolean[][] coprime, Deque<int[]>[] last, int[] ans) {
        int val = nums[u];
        int bestDepth = -1;
        int bestNode = -1;
        for (int v = 1; v <= 50; v++) {
            if (coprime[val][v] && !last[v].isEmpty()) {
                int[] top = last[v].peekLast();
                if (top[1] > bestDepth) {
                    bestDepth = top[1];
                    bestNode = top[0];
                }
            }
        }
        ans[u] = bestNode;
        last[val].addLast(new int[]{u, depth});
        for (int nei : adj[u]) {
            if (nei != parent) {
                dfs(nei, u, depth + 1, nums, adj, coprime, last, ans);
            }
        }
        last[val].removeLast();
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
}

class Solution {
    public int[] getCoprimes(int[] nums, int[][] edges) {
        int n = nums.length;

        int[] head = new int[n];
        for (int i = 0; i < n; i++) {
            head[i] = -1;
        }

        int m = edges.length;
        int[] to = new int[2 * m];
        int[] next = new int[2 * m];
        int idx = 0;

        for (int[] e : edges) {
            int u = e[0], v = e[1];

            to[idx] = v;
            next[idx] = head[u];
            head[u] = idx++;

            to[idx] = u;
            next[idx] = head[v];
            head[v] = idx++;
        }

        boolean[][] coprime = new boolean[51][51];
        for (int i = 1; i <= 50; i++) {
            for (int j = 1; j <= 50; j++) {
                coprime[i][j] = gcd(i, j) == 1;
            }
        }

        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            ans[i] = -1;
        }

        int[] depth = new int[n];
        int[] last = new int[51];
        for (int i = 0; i <= 50; i++) {
            last[i] = -1;
        }

        int[] prev = new int[n];

        int capacity = 2 * n + 5;
        int[] stackNode = new int[capacity];
        int[] stackParent = new int[capacity];
        int[] stackState = new int[capacity];

        int top = 0;
        stackNode[top] = 0;
        stackParent[top] = -1;
        stackState[top] = 0;
        top++;

        while (top > 0) {
            top--;
            int node = stackNode[top];
            int parent = stackParent[top];
            int state = stackState[top];

            if (state == 0) {
                int val = nums[node];

                int best = -1;
                int bestDepth = -1;

                for (int g = 1; g <= 50; g++) {
                    if (last[g] != -1 && coprime[val][g]) {
                        int cand = last[g];
                        if (depth[cand] > bestDepth) {
                            bestDepth = depth[cand];
                            best = cand;
                        }
                    }
                }

                ans[node] = best;

                prev[node] = last[val];
                last[val] = node;

                stackNode[top] = node;
                stackParent[top] = parent;
                stackState[top] = 1;
                top++;

                for (int e = head[node]; e != -1; e = next[e]) {
                    int nei = to[e];
                    if (nei == parent) {
                        continue;
                    }

                    depth[nei] = depth[node] + 1;

                    stackNode[top] = nei;
                    stackParent[top] = node;
                    stackState[top] = 0;
                    top++;
                }
            } else {
                int val = nums[node];
                last[val] = prev[node];
            }
        }

        return ans;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

import java.util.*;

class Solution {
    public int[] getCoprimes(int[] nums, int[][] edges) {
        int n = nums.length;
        List<Integer>[] adj = new List[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }

        // Precompute lists of values coprime with each value 1..50
        List<Integer>[] cop = new List[51];
        for (int a = 1; a <= 50; a++) {
            cop[a] = new ArrayList<>();
            for (int b = 1; b <= 50; b++) {
                if (gcd(a, b) == 1) cop[a].add(b);
            }
        }

        // For each value, a stack of ancestor node indices on current path (top = deepest)
        Deque<Integer>[] stacks = new Deque[51];
        for (int v = 1; v <= 50; v++) stacks[v] = new ArrayDeque<>();

        int[] ans = new int[n];
        int[] depth = new int[n];
        int[] parent = new int[n];
        Arrays.fill(parent, -1);

        // Iterative DFS: enter marker = node id, exit marker = node id + n
        Deque<Integer> st = new ArrayDeque<>();
        st.push(0);
        while (!st.isEmpty()) {
            int cur = st.pop();
            if (cur >= n) {
                // exit node (cur - n): remove from its value's stack
                stacks[nums[cur - n]].pop();
                continue;
            }
            int node = cur;
            int val = nums[node];
            int best = -1, bestDepth = -1;
            for (int v : cop[val]) {
                Deque<Integer> s = stacks[v];
                if (!s.isEmpty()) {
                    int cand = s.peek();
                    if (depth[cand] > bestDepth) {
                        bestDepth = depth[cand];
                        best = cand;
                    }
                }
            }
            ans[node] = best;
            stacks[val].push(node);
            st.push(node + n); // exit marker processed after subtree
            int p = parent[node];
            int d = depth[node] + 1;
            for (int nxt : adj[node]) {
                if (nxt != p) {
                    parent[nxt] = node;
                    depth[nxt] = d;
                    st.push(nxt);
                }
            }
        }
        return ans;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

