/**
 * @param {number} n
 * @param {number[]} leftChild
 * @param {number[]} rightChild
 * @return {boolean}
 */
var validateBinaryTreeNodes = function(n, leftChild, rightChild) {
    const indeg = new Int32Array(n);
    for (let i = 0; i < n; i++) {
        if (leftChild[i] !== -1) {
            if (++indeg[leftChild[i]] > 1) return false;
        }
        if (rightChild[i] !== -1) {
            if (++indeg[rightChild[i]] > 1) return false;
        }
    }
    let root = -1;
    for (let i = 0; i < n; i++) {
        if (indeg[i] === 0) {
            if (root !== -1) return false;
            root = i;
        }
    }
    if (root === -1) return false;
    const visited = new Uint8Array(n);
    const stack = [root];
    visited[root] = 1;
    let count = 0;
    while (stack.length) {
        const u = stack.pop();
        count++;
        for (const c of [leftChild[u], rightChild[u]]) {
            if (c !== -1) {
                if (visited[c]) return false;
                visited[c] = 1;
                stack.push(c);
            }
        }
    }
    return count === n;
};

/**
 * @param {number} n
 * @param {number[]} leftChild
 * @param {number[]} rightChild
 * @return {boolean}
 */
var validateBinaryTreeNodes = function(n, leftChild, rightChild) {
    const indegree = new Array(n).fill(0);

    // Check every node has at most one parent
    for (let i = 0; i < n; i++) {
        if (leftChild[i] !== -1 && ++indegree[leftChild[i]] > 1) return false;
        if (rightChild[i] !== -1 && ++indegree[rightChild[i]] > 1) return false;
    }

    // Find the unique root (exactly one node with in-degree 0)
    let root = -1;
    for (let i = 0; i < n; i++) {
        if (indegree[i] === 0) {
            if (root !== -1) return false; // more than one root
            root = i;
        }
    }
    if (root === -1) return false; // no root -> cycle exists

    // BFS from root, ensure all nodes are reachable
    const visited = new Array(n).fill(false);
    const queue = [root];
    visited[root] = true;
    let head = 0;
    let count = 0;

    while (head < queue.length) {
        const node = queue[head++];
        count++;

        const l = leftChild[node];
        const r = rightChild[node];

        if (l !== -1) {
            if (visited[l]) return false;
            visited[l] = true;
            queue.push(l);
        }
        if (r !== -1) {
            if (visited[r]) return false;
            visited[r] = true;
            queue.push(r);
        }
    }

    return count === n;
};

