class Solution {
public:
    bool validateBinaryTreeNodes(int n, vector<int>& leftChild, vector<int>& rightChild) {
        vector<int> indegree(n, 0);

        // Check each node has at most one parent
        for (int i = 0; i < n; ++i) {
            if (leftChild[i] != -1 && ++indegree[leftChild[i]] > 1) return false;
            if (rightChild[i] != -1 && ++indegree[rightChild[i]] > 1) return false;
        }

        // Find the unique root (node with no parent)
        int root = -1;
        for (int i = 0; i < n; ++i) {
            if (indegree[i] == 0) {
                if (root != -1) return false; // more than one root -> forest
                root = i;
            }
        }
        if (root == -1) return false; // no root -> cycle covering all nodes

        // BFS from root, ensure all nodes are reachable (no disconnected cycles)
        vector<bool> visited(n, false);
        queue<int> q;
        q.push(root);
        visited[root] = true;
        int count = 0;

        while (!q.empty()) {
            int node = q.front();
            q.pop();
            ++count;

            int children[2] = {leftChild[node], rightChild[node]};
            for (int child : children) {
                if (child != -1) {
                    if (visited[child]) return false; // cycle detected
                    visited[child] = true;
                    q.push(child);
                }
            }
        }

        return count == n;
    }
};

