    if (n > 10) return false;
    const used = new Array(10).fill(false);
    const dfs = (i, sum) => {
        if (i === n) return sum === 0;
        for (let d = 0; d < 10; d++) {
            if (used[d]) continue;
            if (d === 0 && nz[i]) continue;
            used[d] = true;
            if (dfs(i + 1, sum + cs[i] * d)) {
                used[d] = false;
                return true;
            }
            used[d] = false;
        }
        return false;
    };
    return dfs(0, 0);
