var isSolvable = function(words, result) {
    const leading = Array(26).fill(false);
    const seen = Array(26).fill(false);
    let unique = 0;
    let maxWordLen = 0;

    const mark = (s) => {
        for (let i = 0; i < s.length; i++) {
            const c = s.charCodeAt(i) - 65;
            if (!seen[c]) {
                seen[c] = true;
                unique++;
            }
        }
    };

    for (const word of words) {
        maxWordLen = Math.max(maxWordLen, word.length);
        if (word.length > 1) leading[word.charCodeAt(0) - 65] = true;
        mark(word);
    }

    if (result.length > 1) leading[result.charCodeAt(0) - 65] = true;
    mark(result);

    if (unique > 10) return false;
    if (result.length < maxWordLen || result.length > maxWordLen + 1) return false;

    const revWords = words.map(word => {
        const arr = [];
        for (let i = word.length - 1; i >= 0; i--) {
            arr.push(word.charCodeAt(i) - 65);
        }
        return arr;
    });

    const revResult = [];
    for (let i = result.length - 1; i >= 0; i--) {
        revResult.push(result.charCodeAt(i) - 65);
    }

    const assigned = Array(26).fill(-1);
    const used = Array(10).fill(false);
    const maxLen = result.length;

    const dfs = (col, row, sum) => {
        if (col === maxLen) {
            return sum === 0;
        }

        if (row < revWords.length) {
            if (col >= revWords[row].length) {
                return dfs(col, row + 1, sum);
            }

            const ch = revWords[row][col];

            if (assigned[ch] !== -1) {
                return dfs(col, row + 1, sum + assigned[ch]);
            }

            for (let digit = 0; digit <= 9; digit++) {
                if (used[digit]) continue;
                if (digit === 0 && leading[ch]) continue;

                assigned[ch] = digit;
                used[digit] = true;

                if (dfs(col, row + 1, sum + digit)) return true;

                assigned[ch] = -1;
                used[digit] = false;
            }

            return false;
        }

        const target = sum % 10;
        const ch = revResult[col];

        if (assigned[ch] !== -1) {
            if (assigned[ch] !== target) return false;
            return dfs(col + 1, 0, Math.floor(sum / 10));
        }

        if (used[target]) return false;
        if (target === 0 && leading[ch]) return false;

        assigned[ch] = target;
        used[target] = true;

        if (dfs(col + 1, 0, Math.floor(sum / 10))) return true;

        assigned[ch] = -1;
        used[target] = false;

        return false;
    };

    return dfs(0, 0, 0);
