        maxWordLen = Math.max(maxWordLen, w.length);
    }
    if (result.length > maxWordLen + 1) return false;

    const cannotBeZero = new Set();
    for (const w of words) {
        if (w.length > 1) cannotBeZero.add(w[0]);
    }
    if (result.length > 1) cannotBeZero.add(result[0]);

    // Reverse strings so index 0 is least significant digit
    const revWords = words.map(w => w.split('').reverse().join(''));
    const revResult = result.split('').reverse().join('');

    const charToDigit = new Map();
    const usedDigits = new Array(10).fill(false);

    function dfs(col, wordIdx, sum) {
        if (col === revResult.length) {
            return sum === 0;
        }

        if (wordIdx < revWords.length) {
            const word = revWords[wordIdx];
            if (col >= word.length) {
                return dfs(col, wordIdx + 1, sum);
            }
            const ch = word[col];
            if (charToDigit.has(ch)) {
                return dfs(col, wordIdx + 1, sum + charToDigit.get(ch));
            } else {
                const startDigit = cannotBeZero.has(ch) ? 1 : 0;
                for (let d = startDigit; d <= 9; d++) {
                    if (!usedDigits[d]) {
                        usedDigits[d] = true;
                        charToDigit.set(ch, d);
                        if (dfs(col, wordIdx + 1, sum + d)) return true;
                        charToDigit.delete(ch);
                        usedDigits[d] = false;
                    }
                }
                return false;
            }
        }

        // wordIdx === revWords.length, match with revResult[col]
        const targetDigit = sum % 10;
        const carry = Math.floor(sum / 10);
        const ch = revResult[col];

        if (charToDigit.has(ch)) {
            if (charToDigit.get(ch) === targetDigit) {
                return dfs(col + 1, 0, carry);
            }
            return false;
        } else {
            if (usedDigits[targetDigit]) return false;
            if (targetDigit === 0 && cannotBeZero.has(ch)) return false;

            usedDigits[targetDigit] = true;
            charToDigit.set(ch, targetDigit);
            if (dfs(col + 1, 0, carry)) return true;
            charToDigit.delete(ch);
            usedDigits[targetDigit] = false;
            return false;
        }
    }

    return dfs(0, 0, 0);
