 */
var isSolvable = function(words, result) {
    const all = [...words, result];
    if (result.length > Math.max(...words.map(w => w.length)) + 1) return false;
    // leading chars (can't be zero)
    const leading = new Set();
    for (const w of all) {
        if (w.length > 1) leading.add(w[0]);
    }
    const maxLen = result.length;
    // check no word longer than result
    for (const w of words) if (w.length > result.length) return false;

    const assigned = {}; // char -> digit
    const used = new Array(10).fill(false);

    // we process columns from rightmost (index 0 from right)
    // words contribute +, result contributes -

    function solve(col, pos, carry) {
        // col: which column (0 = rightmost)
        // pos: which word index within this column
        if (col === maxLen) {
            return carry === 0;
        }
        if (pos === all.length) {
            // sum of this column
            // compute: sum of words digits - result digit + carry should balance
            // actually we accumulate
            return false; // shouldn't reach, handled in solveColumn
        }
        return false;
    }

    // Better: iterate column, accumulate sum
    function solveColumn(col, idx, sum) {
        if (col === maxLen) {
            return sum === 0;
        }
        if (idx === all.length) {
            // last element is result; sum already includes words added and result subtracted
            // determine carry
            if (sum % 10 !== 0) return false;
            return solveColumn(col + 1, 0, Math.floor(sum / 10));
        }
        const word = all[idx];
        const sign = (idx === all.length - 1) ? -1 : 1;
        if (col >= word.length) {
            return solveColumn(col, idx + 1, sum);
        }
        const ch = word[word.length - 1 - col];
        if (ch in assigned) {
            return solveColumn(col, idx + 1, sum + sign * assigned[ch]);
        } else {
            for (let d = 0; d <= 9; d++) {
                if (used[d]) continue;
                if (d === 0 && leading.has(ch)) continue;
                used[d] = true;
                assigned[ch] = d;
                if (solveColumn(col, idx + 1, sum + sign * d)) {
                    used[d] = false;
                    delete assigned[ch];
                    return true;
                }
                used[d] = false;
                delete assigned[ch];
            }
            return false;
        }
    }

    return solveColumn(0, 0, 0);
};

function isSolvable(words: string[], result: string): boolean {
    const length = result.length;
    const columns: number[][] = Array.from({ length }, () => []);
    const leading = new Uint8Array(26);
    const digits = new Int8Array(26).fill(-1);

    let maxWordLength = 0;

    for (const word of words) {
        if (word.length > length) return false;
        maxWordLength = Math.max(maxWordLength, word.length);

        if (word.length > 1) {
            leading[word.charCodeAt(0) - 65] = 1;
        }

        for (let column = 0; column < word.length; column++) {
            columns[column].push(word.charCodeAt(word.length - 1 - column) - 65);
        }
