    const reversedWords: number[][] = words.map(word => {
        const arr: number[] = [];
        for (let i = word.length - 1; i >= 0; i--) {
            arr.push(word.charCodeAt(i) - 65);
        }
        return arr;
    });

    const reversedResult: number[] = [];
    for (let i = result.length - 1; i >= 0; i--) {
        reversedResult.push(result.charCodeAt(i) - 65);
    }

    const letterToDigit: number[] = new Array(26).fill(-1);
    const usedDigit: boolean[] = new Array(10).fill(false);

    const dfs = (col: number, row: number, sum: number): boolean => {
        if (col === result.length) {
            return sum === 0;
        }

        if (row === words.length) {
            const digit = sum % 10;
            const carry = Math.floor(sum / 10);
            const resultChar = reversedResult[col];
            const assigned = letterToDigit[resultChar];

            if (assigned !== -1) {
                if (assigned !== digit) return false;
                return dfs(col + 1, 0, carry);
            }

            if (usedDigit[digit]) return false;
            if (digit === 0 && nonZero[resultChar]) return false;

            letterToDigit[resultChar] = digit;
            usedDigit[digit] = true;

            if (dfs(col + 1, 0, carry)) return true;

            letterToDigit[resultChar] = -1;
            usedDigit[digit] = false;

            return false;
        }

        if (col >= reversedWords[row].length) {
            return dfs(col, row + 1, sum);
        }

        const ch = reversedWords[row][col];
        const assigned = letterToDigit[ch];

        if (assigned !== -1) {
            return dfs(col, row + 1, sum + assigned);
        }

        for (let digit = 0; digit <= 9; digit++) {
            if (usedDigit[digit]) continue;
            if (digit === 0 && nonZero[ch]) continue;

            letterToDigit[ch] = digit;
            usedDigit[digit] = true;

            if (dfs(col, row + 1, sum + digit)) return true;

            letterToDigit[ch] = -1;
            usedDigit[digit] = false;
        }

        return false;
    };

    return dfs(0, 0, 0);
};

function isSolvable(words: string[], result: string): boolean {
    if (result.length > 0 && words.some(w => w.length > result.length)) return false;

    const allWords = [...words, result];
    const maxLen = result.length;

    // leading chars can't be zero
    const nonZero = new Set<string>();
    for (const w of allWords) {
        if (w.length > 1) nonZero.add(w[0]);
    }

    const charToDigit = new Map<string, number>();
    const usedDigits = new Array(10).fill(false);

    // dfs over columns from rightmost
    function dfs(col: number, rowIndex: number, carry: number): boolean {
        if (col === maxLen) {
            return carry === 0;
        }
        if (rowIndex === words.length) {
            // process result char at this column
            const rlen = result.length;
            const rChar = col < rlen ? result[rlen - 1 - col] : null;
            // sum so far is carry; we need to determine result digit
            const targetDigit = carry % 10;
            const newCarry = Math.floor(carry / 10);
            if (rChar === null) {
                // result has no char here; must have digit 0 effectively, but nothing to assign
                if (targetDigit !== 0) return false;
                return dfs(col + 1, 0, newCarry);
            }
            if (charToDigit.has(rChar)) {
                if (charToDigit.get(rChar) !== targetDigit) return false;
                return dfs(col + 1, 0, newCarry);
            } else {
                if (usedDigits[targetDigit]) return false;
                if (targetDigit === 0 && nonZero.has(rChar)) return false;
                charToDigit.set(rChar, targetDigit);
                usedDigits[targetDigit] = true;
                const res = dfs(col + 1, 0, newCarry);
                charToDigit.delete(rChar);
                usedDigits[targetDigit] = false;
                return res;
            }
        }
        // process words[rowIndex] at this column
        const w = words[rowIndex];
        if (col >= w.length) {
            return dfs(col, rowIndex + 1, carry);
        }
        const c = w[w.length - 1 - col];
        if (charToDigit.has(c)) {
            return dfs(col, rowIndex + 1, carry + charToDigit.get(c)!);
        } else {
            for (let d = 0; d <= 9; d++) {
                if (usedDigits[d]) continue;
                if (d === 0 && nonZero.has(c)) continue;
                charToDigit.set(c, d);
                usedDigits[d] = true;
                if (dfs(col, rowIndex + 1, carry + d)) {
                    charToDigit.delete(c);
                    usedDigits[d] = false;
                    return true;
                }
                charToDigit.delete(c);
                usedDigits[d] = false;
            }
            return false;
        }
    }

    return dfs(0, 0, 0);
};

function isSolvable(words: string[], result: string): boolean {
    const mapping = new Array<number>(26).fill(-1);
    const leading = new Array<boolean>(26).fill(false);
    const seen = new Set<string>();

    let maxLength = 0;

    for (const word of words) {
        maxLength = Math.max(maxLength, word.length);
        if (word.length > 1) {
            leading[word.charCodeAt(0) - 65] = true;
        }
        for (const char of word) seen.add(char);
    }

    if (result.length > 1) {
        leading[result.charCodeAt(0) - 65] = true;
    }
    for (const char of result) seen.add(char);

    if (seen.size > 10) return false;
    if (result.length < maxLength || result.length > maxLength + 1) {
        return false;
    }

    let usedMask = 0;

    const dfs = (column: number, row: number, sum: number): boolean => {
        if (column === result.length) {
            return sum === 0;
        }

        if (row < words.length) {
            const word = words[row];

            if (column >= word.length) {
                return dfs(column, row + 1, sum);
            }

            const letter = word.charCodeAt(word.length - 1 - column) - 65;
            const assignedDigit = mapping[letter];

            if (assignedDigit !== -1) {
                return dfs(column, row + 1, sum + assignedDigit);
            }

            for (let digit = 0; digit <= 9; digit++) {
                const bit = 1 << digit;

                if ((usedMask & bit) !== 0) continue;
                if (digit === 0 && leading[letter]) continue;

                mapping[letter] = digit;
                usedMask |= bit;

                if (dfs(column, row + 1, sum + digit)) return true;

                mapping[letter] = -1;
                usedMask &= ~bit;
            }

            return false;
        }

        const resultLetter =
            result.charCodeAt(result.length - 1 - column) - 65;
        const requiredDigit = sum % 10;
        const carry = Math.floor(sum / 10);
        const assignedDigit = mapping[resultLetter];

        if (assignedDigit !== -1) {
            if (assignedDigit !== requiredDigit) return false;
            return dfs(column + 1, 0, carry);
        }

        const bit = 1 << requiredDigit;

        if ((usedMask & bit) !== 0) return false;
        if (requiredDigit === 0 && leading[resultLetter]) return false;

        mapping[resultLetter] = requiredDigit;
        usedMask |= bit;

        if (dfs(column + 1, 0, carry)) return true;

        mapping[resultLetter] = -1;
        usedMask &= ~bit;

        return false;
    };

    return dfs(0, 0, 0);
};

function isSolvable(words: string[], result: string): boolean {
    const maxLen = result.length;
    for (const w of words) {
        if (w.length > maxLen) return false;
    }

    const cannotBeZero = new Uint8Array(26);
    for (const w of words) {
        if (w.length > 1) {
            cannotBeZero[w.charCodeAt(0) - 65] = 1;
        }
    }
    if (result.length > 1) {
        cannotBeZero[result.charCodeAt(0) - 65] = 1;
    }

    const charToDigit = new Int8Array(26).fill(-1);
    const digitUsed = new Uint8Array(10);

    function backtrack(col: number, wordIdx: number, sum: number): boolean {
        if (col === maxLen) {
            return sum === 0;
        }

        if (wordIdx < words.length) {
            const w = words[wordIdx];
            if (col >= w.length) {
                return backtrack(col, wordIdx + 1, sum);
            }

            const c = w.charCodeAt(w.length - 1 - col) - 65;
            if (charToDigit[c] !== -1) {
                return backtrack(col, wordIdx + 1, sum + charToDigit[c]);
            }

            const startDigit = cannotBeZero[c] ? 1 : 0;
            for (let d = startDigit; d <= 9; d++) {
                if (!digitUsed[d]) {
                    digitUsed[d] = 1;
                    charToDigit[c] = d;
                    if (backtrack(col, wordIdx + 1, sum + d)) {
                        return true;
                    }
                    charToDigit[c] = -1;
                    digitUsed[d] = 0;
                }
            }
            return false;
        }

        const c = result.charCodeAt(result.length - 1 - col) - 65;
        const expectedDigit = sum % 10;
        const nextCarry = Math.floor(sum / 10);

        if (charToDigit[c] !== -1) {
            if (charToDigit[c] === expectedDigit) {
                return backtrack(col + 1, 0, nextCarry);
            }
            return false;
        }

        if (expectedDigit === 0 && cannotBeZero[c]) {
            return false;
        }

        if (!digitUsed[expectedDigit]) {
            digitUsed[expectedDigit] = 1;
            charToDigit[c] = expectedDigit;
            if (backtrack(col + 1, 0, nextCarry)) {
                return true;
            }
            charToDigit[c] = -1;
            digitUsed[expectedDigit] = 0;
        }

        return false;
    }

    return backtrack(0, 0, 0);
}

function isSolvable(words: string[], result: string): boolean {
    const nonZero = new Set<string>();
    for (const w of words) {
        if (w.length > 1) nonZero.add(w[0]);
    }
    if (result.length > 1) nonZero.add(result[0]);

    const reWords = words.map(w => w.split('').reverse());
    const reResult = result.split('').reverse();
    const maxLen = Math.max(reResult.length, ...reWords.map(w => w.length));

    const assign = new Array<number>(26).fill(-1);
    const used = new Array<boolean>(10).fill(false);

    function dfs(pos: number, wIdx: number, sum: number): boolean {
        if (pos === maxLen) {
            return sum === 0;
        }
        if (wIdx < reWords.length) {
            const word = reWords[wIdx];
            if (pos >= word.length) {
                return dfs(pos, wIdx + 1, sum);
            }
            const ch = word[pos];
            const c = ch.charCodeAt(0) - 65;
            if (assign[c] !== -1) {
                return dfs(pos, wIdx + 1, sum + assign[c]);
            }
            for (let d = 0; d <= 9; d++) {
                if (used[d] || (d === 0 && nonZero.has(ch))) continue;
                assign[c] = d;
                used[d] = true;
                if (dfs(pos, wIdx + 1, sum + d)) return true;
                assign[c] = -1;
                used[d] = false;
            }
            return false;
        } else {
            const digit = sum % 10;
            const nextSum = Math.floor(sum / 10);
            if (pos >= reResult.length) {
                if (digit !== 0) return false;
                return dfs(pos + 1, 0, nextSum);
            }
            const ch = reResult[pos];
            const c = ch.charCodeAt(0) - 65;
            if (assign[c] !== -1) {
                if (assign[c] !== digit) return false;
                return dfs(pos + 1, 0, nextSum);
            }
            if (used[digit] || (digit === 0 && nonZero.has(ch))) return false;
            assign[c] = digit;
            used[digit] = true;
            const ok = dfs(pos + 1, 0, nextSum);
            assign[c] = -1;
            used[digit] = false;
            return ok;
        }
    }

    return dfs(0, 0, 0);
}

function isSolvable(words: string[], result: string): boolean {
    for (const w of words) {
        if (w.length > result.length) return false;
    }
    const weight: Map<string, number> = new Map();
    const nonzero: Set<string> = new Set();
    const addWord = (w: string, sign: number) => {
        let p = 1;
        for (let i = w.length - 1; i >= 0; i--) {
            const c = w[i];
            weight.set(c, (weight.get(c) || 0) + sign * p);
            p *= 10;
        }
        if (w.length > 1) nonzero.add(w[0]);
    };
    for (const w of words) addWord(w, 1);
    addWord(result, -1);

    const chars = Array.from(weight.keys());
    chars.sort((a, b) => Math.abs(weight.get(b)!) - Math.abs(weight.get(a)!));
    const n = chars.length;
    const ws: number[] = chars.map(c => weight.get(c)!);
    const nz: boolean[] = chars.map(c => nonzero.has(c));

    const maxRem: number[] = new Array(n + 1).fill(0);
    const minRem: number[] = new Array(n + 1).fill(0);
    for (let i = n - 1; i >= 0; i--) {
        maxRem[i] = maxRem[i + 1] + (ws[i] > 0 ? 9 * ws[i] : 0);
        minRem[i] = minRem[i + 1] + (ws[i] < 0 ? 9 * ws[i] : 0);
    }

    const dfs = (idx: number, sum: number, used: number): boolean => {
        if (idx === n) return sum === 0;
        if (sum + minRem[idx] > 0 || sum + maxRem[idx] < 0) return false;
        for (let d = 0; d <= 9; d++) {
            if (used & (1 << d)) continue;
            if (d === 0 && nz[idx]) continue;
            if (dfs(idx + 1, sum + ws[idx] * d, used | (1 << d))) return true;
        }
        return false;
    };

    return dfs(0, 0, 0);
};

#include <vector>
#include <string>
#include <algorithm>

using namespace std;

class Solution {
    int assigned[128];
    bool used[10];
    bool cannot_be_zero[128];
    vector<string> w;
    string res;

    bool dfs(int col, int row, int sum) {
        if (col == res.length()) {
            return sum == 0;
        }

        if (row == w.size()) {
            int rem = sum % 10;
            char c = res[col];
            if (assigned[c] != -1) {
                if (assigned[c] != rem) return false;
                return dfs(col + 1, 0, sum / 10);
            } else {
                if (used[rem]) return false;
                if (rem == 0 && cannot_be_zero[c]) return false;
                assigned[c] = rem;
                used[rem] = true;
                bool ok = dfs(col + 1, 0, sum / 10);
                assigned[c] = -1;
                used[rem] = false;
                return ok;
            }
        }

        if (col >= w[row].length()) {
            return dfs(col, row + 1, sum);
        }

        char c = w[row][col];
        if (assigned[c] != -1) {
            return dfs(col, row + 1, sum + assigned[c]);
        }

        for (int d = 0; d <= 9; ++d) {
            if (used[d]) continue;
            if (d == 0 && cannot_be_zero[c]) continue;

            assigned[c] = d;
            used[d] = true;
            if (dfs(col, row + 1, sum + d)) return true;
            assigned[c] = -1;
            used[d] = false;
        }

        return false;
    }

public:
    bool isSolvable(vector<string>& words, string result) {
        fill(assigned, assigned + 128, -1);
        fill(used, used + 10, false);
        fill(cannot_be_zero, cannot_be_zero + 128, false);

        int max_len = 0;
        for (const string& word : words) {
            max_len = max(max_len, (int)word.length());
            if (word.length() > 1) {
                cannot_be_zero[word[0]] = true;
            }
        }

        if (result.length() > 1) {
            cannot_be_zero[result[0]] = true;
        }

        if (result.length() < max_len || result.length() > max_len + 1) {
            return false;
        }

        w = words;
        res = result;

        for (string& word : w) {
            reverse(word.begin(), word.end());
        }
        reverse(res.begin(), res.end());

        return dfs(0, 0, 0);
    }
};

class Solution {
public:
    vector<string> w;
    string r;
    int mp[26];
    bool used[10];
    bool lead[26];
    int n;

    bool dfs(int col, int row, int sum) {
        int rl = r.size();
        if (col == rl) return sum == 0;
        if (row < n) {
            const string& s = w[row];
            int len = s.size();
            if (col >= len) return dfs(col, row + 1, sum);
            int c = s[len - 1 - col] - 'A';
            if (mp[c] >= 0) return dfs(col, row + 1, sum + mp[c]);
            for (int d = 0; d < 10; d++) {
                if (used[d]) continue;
                if (d == 0 && lead[c]) continue;
                used[d] = true; mp[c] = d;
                if (dfs(col, row + 1, sum + d)) return true;
                used[d] = false; mp[c] = -1;
            }
            return false;
        }
        int c = r[rl - 1 - col] - 'A';
        int d = sum % 10;
        if (mp[c] >= 0) {
            if (mp[c] != d) return false;
            return dfs(col + 1, 0, sum / 10);
        }
        if (used[d]) return false;
        if (d == 0 && lead[c]) return false;
        used[d] = true; mp[c] = d;
        if (dfs(col + 1, 0, sum / 10)) return true;
        used[d] = false; mp[c] = -1;
        return false;
    }

    bool isSolvable(vector<string>& words, string result) {
        auto clean = [](const string& s) {
            string t;
            for (char ch : s) if (ch >= 'A' && ch <= 'Z') t += ch;
            return t;
        };
        w.clear();
        for (auto& s : words) w.push_back(clean(s));
        r = clean(result);
        n = w.size();
        for (auto& s : w) if (s.size() > r.size()) return false;
        memset(mp, -1, sizeof(mp));
        memset(used, 0, sizeof(used));
        memset(lead, 0, sizeof(lead));
        for (auto& s : w) if (s.size() > 1) lead[s[0] - 'A'] = true;
        if (r.size() > 1) lead[r[0] - 'A'] = true;
        return dfs(0, 0, 0);
    }
};

#include <bits/stdc++.h>
using namespace std;

class Solution {
    vector<string> wlist;
    string res;
    int R;
    int mp[26];
    bool used[10];
    bool leading[26];

    bool assign(int pos, int carry, vector<char>& letters, int idx) {
        if (idx == (int)letters.size()) {
            int sum = carry;
            for (const string& w : wlist) {
                if (pos < (int)w.size()) {
                    sum += mp[w[w.size() - 1 - pos] - 'A'];
                }
            }
            int rd = mp[res[R - 1 - pos] - 'A'];
            if (sum % 10 != rd) return false;
            return dfs(pos + 1, sum / 10);
        }

        char c = letters[idx];
        int ci = c - 'A';
        if (mp[ci] != -1) {
            return assign(pos, carry, letters, idx + 1);
        }

        for (int d = 0; d <= 9; ++d) {
            if (used[d]) continue;
            if (d == 0 && leading[ci]) continue;

            mp[ci] = d;
            used[d] = true;

            if (assign(pos, carry, letters, idx + 1)) return true;

            used[d] = false;
            mp[ci] = -1;
        }

        return false;
    }

    bool dfs(int pos, int carry) {
        if (pos == R) return carry == 0;

        vector<char> letters;
        bool seen[26] = {false};

        for (const string& w : wlist) {
            if (pos < (int)w.size()) {
                char c = w[w.size() - 1 - pos];
                if (!seen[c - 'A']) {
                    seen[c - 'A'] = true;
                    letters.push_back(c);
                }
            }
        }

        char rc = res[R - 1 - pos];
        if (!seen[rc - 'A']) {
            seen[rc - 'A'] = true;
            letters.push_back(rc);
        }

        return assign(pos, carry, letters, 0);
    }

public:
    bool isSolvable(vector<string>& words, string result) {
        wlist = words;
        res = result;
        R = result.size();

        fill(mp, mp + 26, -1);
        fill(used, used + 10, false);
        fill(leading, leading + 26, false);

        for (const string& w : words) {
            if ((int)w.size() > R) return false;
            if (w.size() > 1) leading[w[0] - 'A'] = true;
        }

        if (R > 1) leading[res[0] - 'A'] = true;

        return dfs(0, 0);
    }
};

class Solution {
public:
    vector<long long> w;
    vector<bool> nz;
    int n;
    bool dfs(int i, int used, long long sum) {
        if (i == n) return sum == 0;
        for (int d = 0; d < 10; d++) {
            if (used & (1 << d)) continue;
            if (d == 0 && nz[i]) continue;
            if (dfs(i + 1, used | (1 << d), sum + w[i] * d)) return true;
        }
        return false;
    }
    bool isSolvable(vector<string>& words, string result) {
        long long wt[26] = {0};
        bool nzero[26] = {false};
        bool present[26] = {false};
        auto process = [&](const string& s, int sign) {
            string t;
            for (char c : s) if (c >= 'A' && c <= 'Z') t += c;
            long long p = 1;
            for (int i = (int)t.size() - 1; i >= 0; i--) {
                wt[t[i] - 'A'] += sign * p;
                present[t[i] - 'A'] = true;
                p *= 10;
            }
            if (t.size() > 1) nzero[t[0] - 'A'] = true;
        };
        for (auto& s : words) process(s, 1);
        process(result, -1);
        for (int i = 0; i < 26; i++) {
            if (present[i]) {
                w.push_back(wt[i]);
                nz.push_back(nzero[i]);
            }
        }
        n = w.size();
        if (n > 10) return false;
        return dfs(0, 0, 0);
    }
};

#include <algorithm>
#include <string>
#include <vector>
using namespace std;

class Solution {
public:
    bool isSolvable(vector<string>& words, string result) {
        int digit[26];
        fill(digit, digit + 26, -1);

        bool leading[26] = {};
        for (const string& word : words) {
            if (word.size() > result.size()) return false;
            if (word.size() > 1) leading[word.front() - 'A'] = true;
        }
        if (result.size() > 1) leading[result.front() - 'A'] = true;

        int used = 0;
        int n = static_cast<int>(words.size());
        int columns = static_cast<int>(result.size());

        // Process columns from right to left, accumulating digits and carry.
        auto dfs = [&](auto&& self, int col, int row, int sum) -> bool {
            if (col == columns) return sum == 0;

            if (row < n) {
                const string& word = words[row];
                if (col >= static_cast<int>(word.size())) {
                    return self(self, col, row + 1, sum);
                }

                int ch = word[word.size() - 1 - col] - 'A';
                if (digit[ch] != -1) {
                    return self(self, col, row + 1, sum + digit[ch]);
                }

                for (int d = 0; d <= 9; ++d) {
                    if ((used & (1 << d)) || (d == 0 && leading[ch])) {
                        continue;
                    }

                    digit[ch] = d;
                    used |= 1 << d;
                    bool solved = self(self, col, row + 1, sum + d);
                    used &= ~(1 << d);
                    digit[ch] = -1;

                    if (solved) return true;
                }
                return false;
            }

            // The result digit is forced by the current column sum.
            int ch = result[columns - 1 - col] - 'A';
            int d = sum % 10;
            int carry = sum / 10;

            if (digit[ch] != -1) {
                return digit[ch] == d &&
                       self(self, col + 1, 0, carry);
            }

            if ((used & (1 << d)) || (d == 0 && leading[ch])) {
                return false;
            }

            digit[ch] = d;
            used |= 1 << d;
            bool solved = self(self, col + 1, 0, carry);
            used &= ~(1 << d);
            digit[ch] = -1;
            return solved;
        };

        return dfs(dfs, 0, 0, 0);
    }
};

class Solution {
public:
    vector<string> w;
    string res;
    int mp[26];
    bool used[10];
    bool nonzero[26];
    int maxLen;

    bool dfs(int col, int idx, int carry) {
        if (col == maxLen) {
            return carry == 0;
        }
        if (idx == (int)w.size()) {
            // handle result digit at this column
            int sum = carry;
            for (auto& s : w) {
                if (col < (int)s.size()) sum += mp[s[s.size() - 1 - col] - 'A'];
            }
            int d = sum % 10;
            int c = sum / 10;
            char ch = res[res.size() - 1 - col];
            int ci = ch - 'A';
            if (mp[ci] != -1) {
                if (mp[ci] != d) return false;
                return dfs(col + 1, 0, c);
            } else {
                if (used[d]) return false;
                if (d == 0 && nonzero[ci]) return false;
                mp[ci] = d;
                used[d] = true;
                bool ok = dfs(col + 1, 0, c);
                mp[ci] = -1;
                used[d] = false;
                return ok;
            }
        }
        const string& s = w[idx];
        if (col >= (int)s.size()) return dfs(col, idx + 1, carry);
        int ci = s[s.size() - 1 - col] - 'A';
        if (mp[ci] != -1) return dfs(col, idx + 1, carry);
        for (int d = 0; d <= 9; d++) {
            if (used[d]) continue;
            if (d == 0 && nonzero[ci]) continue;
            mp[ci] = d;
            used[d] = true;
            if (dfs(col, idx + 1, carry)) {
                mp[ci] = -1;
                used[d] = false;
                return true;
            }
            mp[ci] = -1;
            used[d] = false;
        }
        return false;
    }

    bool isSolvable(vector<string>& words, string result) {
        w = words;
        res = result;
        maxLen = res.size();
        for (auto& s : w) {
            if ((int)s.size() > maxLen) return false;
        }
        memset(mp, -1, sizeof(mp));
        memset(used, 0, sizeof(used));
        memset(nonzero, 0, sizeof(nonzero));
        for (auto& s : w) {
            if (s.size() > 1) nonzero[s[0] - 'A'] = true;
        }
        if (res.size() > 1) nonzero[res[0] - 'A'] = true;
        return dfs(0, 0, 0);
    }
};

