class Solution {
public:
    bool isSolvable(vector<string>& words, string result) {
        int maxLength = 0;
        bool leading[26] = {};
        bool present[26] = {};

        for (const string& word : words) {
            maxLength = max(maxLength, (int)word.size());
            if (word.size() > 1) leading[word[0] - 'A'] = true;
            for (char c : word) present[c - 'A'] = true;
        }

        if (result.size() > 1) leading[result[0] - 'A'] = true;
        for (char c : result) present[c - 'A'] = true;

        int distinct = 0;
        for (bool exists : present) distinct += exists;

        if (distinct > 10 ||
            (int)result.size() < maxLength ||
            (int)result.size() > maxLength + 1) {
            return false;
        }

        int value[26];
        fill(begin(value), end(value), -1);
        bool used[10] = {};

        function<bool(int, int, int)> dfs =
            [&](int column, int row, int sum) -> bool {
                if (column == (int)result.size()) {
                    return sum == 0;
                }

                if (row < (int)words.size()) {
                    const string& word = words[row];

                    if (column >= (int)word.size()) {
                        return dfs(column, row + 1, sum);
                    }

                    int index = (int)word.size() - 1 - column;
                    int letter = word[index] - 'A';

                    if (value[letter] != -1) {
                        return dfs(column, row + 1, sum + value[letter]);
                    }

                    for (int digit = 0; digit <= 9; ++digit) {
                        if (used[digit] || (digit == 0 && leading[letter])) {
                            continue;
                        }

                        value[letter] = digit;
                        used[digit] = true;

                        if (dfs(column, row + 1, sum + digit)) {
                            return true;
                        }

                        value[letter] = -1;
                        used[digit] = false;
                    }

                    return false;
                }

                int requiredDigit = sum % 10;
                int carry = sum / 10;
                int resultIndex = (int)result.size() - 1 - column;
                int letter = result[resultIndex] - 'A';

                if (value[letter] != -1) {
                    if (value[letter] != requiredDigit) return false;
                    return dfs(column + 1, 0, carry);
                }

                if (used[requiredDigit] ||
                    (requiredDigit == 0 && leading[letter])) {
                    return false;
                }

                value[letter] = requiredDigit;
                used[requiredDigit] = true;

                if (dfs(column + 1, 0, carry)) {
                    return true;
                }

                value[letter] = -1;
                used[requiredDigit] = false;
                return false;
            };

        return dfs(0, 0, 0);
    }
};

class Solution {
public:
    bool isSolvable(vector<string>& words, string result) {
        int maxLen = 0;
        for (auto &w : words) maxLen = max(maxLen, (int)w.size());
        if ((int)result.size() < maxLen || (int)result.size() > maxLen + 1) return false;

        vector<long long> coef(26, 0);
        vector<bool> seen(26, false), noZero(26, false);

        long long p10[8];
        p10[0] = 1;
        for (int i = 1; i < 8; i++) p10[i] = p10[i - 1] * 10;

        for (string &w : words) {
            if (w.size() > 1) noZero[w[0] - 'A'] = true;
            for (int i = 0; i < (int)w.size(); i++) {
                int c = w[w.size() - 1 - i] - 'A';
                seen[c] = true;
                coef[c] += p10[i];
            }
        }

        if (result.size() > 1) noZero[result[0] - 'A'] = true;
        for (int i = 0; i < (int)result.size(); i++) {
            int c = result[result.size() - 1 - i] - 'A';
            seen[c] = true;
            coef[c] -= p10[i];
        }

        vector<int> chars;
        int leadingCount = 0;
        for (int i = 0; i < 26; i++) {
            if (seen[i]) {
                chars.push_back(i);
                if (noZero[i]) leadingCount++;
            }
        }

        if (chars.size() > 10) return false;
        if (leadingCount > 9) return false;

        sort(chars.begin(), chars.end(), [&](int a, int b) {
            return llabs(coef[a]) > llabs(coef[b]);
        });

        vector<bool> used(10, false);
        int n = chars.size();

        function<bool(int, long long)> dfs = [&](int idx, long long sum) -> bool {
            if (idx == n) return sum == 0;

            long long low = 0, high = 0;
            int minDigit = -1, maxDigit = -1;
            for (int d = 0; d <= 9; d++) {
                if (!used[d]) {
                    minDigit = d;
                    break;
                }
            }
            for (int d = 9; d >= 0; d--) {
                if (!used[d]) {
                    maxDigit = d;
                    break;
                }
            }

            for (int i = idx; i < n; i++) {
                long long c = coef[chars[i]];
                if (c > 0) {
                    low += c * minDigit;
                    high += c * maxDigit;
                } else {
                    low += c * maxDigit;
                    high += c * minDigit;
                }
            }

            if (sum + low > 0 || sum + high < 0) return false;

            int ch = chars[idx];
            for (int d = 0; d <= 9; d++) {
                if (used[d]) continue;
                if (d == 0 && noZero[ch]) continue;

                used[d] = true;
                if (dfs(idx + 1, sum + coef[ch] * d)) return true;
                used[d] = false;
            }

            return false;
        };

        return dfs(0, 0);
    }
};

class Solution {
public:
    bool isSolvable(vector<string>& words, string result) {
        bool seen[26] = {};
        vector<bool> leading(26, false);
        vector<char> letters;
        auto add = [&](const string& s) {
            if (s.size() > 1) leading[s[0] - 'A'] = true;
            for (char c : s) {
                if (!seen[c - 'A']) {
                    seen[c - 'A'] = true;
                    letters.push_back(c);
                }
            }
        };
        for (auto& w : words) add(w);
        add(result);
        vector<int> assign(26, -1);
        vector<bool> used(10, false);
        return dfs(0, letters, assign, used, leading, words, result);
    }
private:
    bool dfs(int pos, vector<char>& letters, vector<int>& assign, vector<bool>& used, vector<bool>& leading, vector<string>& words, string& result) {
        if (pos == (int)letters.size()) {
            long long sum = 0;
            for (auto& w : words) {
                long long num = 0;
                for (char c : w) {
                    num = num * 10 + assign[c - 'A'];
                }
                sum += num;
            }
            long long res = 0;
            for (char c : result) {
                res = res * 10 + assign[c - 'A'];
            }
            return sum == res;
        }
        char ch = letters[pos];
        int idx = ch - 'A';
        for (int d = 0; d <= 9; ++d) {
            if (used[d]) continue;
            if (d == 0 && leading[idx]) continue;
            used[d] = true;
            assign[idx] = d;
            if (dfs(pos + 1, letters, assign, used, leading, words, result)) return true;
            used[d] = false;
        }
        return false;
    }
};

class Solution {
    private String[] w;
    private String r;
    private int[] map = new int[26];
    private boolean[] used = new boolean[10];
    private boolean[] nonZero = new boolean[26];

    public boolean isSolvable(String[] words, String result) {
        for (String s : words) if (s.length() > result.length()) return false;
        w = new String[words.length];
        for (int i = 0; i < words.length; i++) {
            w[i] = new StringBuilder(words[i]).reverse().toString();
            if (words[i].length() > 1) nonZero[words[i].charAt(0) - 'A'] = true;
        }
        r = new StringBuilder(result).reverse().toString();
        if (result.length() > 1) nonZero[result.charAt(0) - 'A'] = true;
        java.util.Arrays.fill(map, -1);
        return dfs(0, 0, 0);
    }

    private boolean dfs(int col, int idx, int sum) {
        if (col == r.length()) return sum == 0;
        if (idx == w.length) {
            int d = sum % 10;
            int c = r.charAt(col) - 'A';
            if (map[c] != -1) {
                return map[c] == d && dfs(col + 1, 0, sum / 10);
            }
            if (used[d]) return false;
            if (d == 0 && nonZero[c]) return false;
            map[c] = d;
            used[d] = true;
            boolean ok = dfs(col + 1, 0, sum / 10);
            map[c] = -1;
            used[d] = false;
            return ok;
        }
        String word = w[idx];
        if (col >= word.length()) return dfs(col, idx + 1, sum);
        int c = word.charAt(col) - 'A';
        if (map[c] != -1) return dfs(col, idx + 1, sum + map[c]);
        for (int d = 0; d <= 9; d++) {
            if (used[d]) continue;
            if (d == 0 && nonZero[c]) continue;
            map[c] = d;
            used[d] = true;
            if (dfs(col, idx + 1, sum + d)) {
                map[c] = -1;
                used[d] = false;
                return true;
            }
            map[c] = -1;
            used[d] = false;
        }
        return false;
    }
}

class Solution {
    private String[] words;
    private String result;
    private int[] map;
    private boolean[] used;
    private boolean[] nonZero;

    public boolean isSolvable(String[] words, String result) {
        this.words = words;
        this.result = result;
        this.map = new int[26];
        this.used = new boolean[10];
        this.nonZero = new boolean[26];

        for (int i = 0; i < 26; i++) {
            map[i] = -1;
        }

        boolean[] seen = new boolean[26];
        int unique = 0;
        int maxWordLen = 0;

        for (String word : words) {
            maxWordLen = Math.max(maxWordLen, word.length());

            if (word.length() > 1) {
                nonZero[word.charAt(0) - 'A'] = true;
            }

            for (char c : word.toCharArray()) {
                int idx = c - 'A';
                if (!seen[idx]) {
                    seen[idx] = true;
                    unique++;
                }
            }
        }

        if (result.length() > 1) {
            nonZero[result.charAt(0) - 'A'] = true;
        }

        for (char c : result.toCharArray()) {
            int idx = c - 'A';
            if (!seen[idx]) {
                seen[idx] = true;
                unique++;
            }
        }

        if (unique > 10) {
            return false;
        }

        if (maxWordLen > result.length()) {
            return false;
        }

        if (result.length() > maxWordLen + 1) {
            return false;
        }

        return dfs(0, 0, 0);
    }

    private boolean dfs(int col, int row, int sum) {
        if (col == result.length()) {
            return sum == 0;
        }

        if (row < words.length) {
            String word = words[row];

            if (col >= word.length()) {
                return dfs(col, row + 1, sum);
            }

            char c = word.charAt(word.length() - 1 - col);
            int idx = c - 'A';

            if (map[idx] != -1) {
                return dfs(col, row + 1, sum + map[idx]);
            }

            for (int digit = 0; digit <= 9; digit++) {
                if (used[digit]) {
                    continue;
                }

                if (digit == 0 && nonZero[idx]) {
                    continue;
                }

                map[idx] = digit;
                used[digit] = true;

                if (dfs(col, row + 1, sum + digit)) {
                    return true;
                }

                used[digit] = false;
                map[idx] = -1;
            }

            return false;
        }

        char c = result.charAt(result.length() - 1 - col);
        int idx = c - 'A';
        int digit = sum % 10;
        int carry = sum / 10;

        if (map[idx] != -1) {
            if (map[idx] != digit) {
                return false;
            }
            return dfs(col + 1, 0, carry);
        }

        if (used[digit]) {
            return false;
        }

        if (digit == 0 && nonZero[idx]) {
            return false;
        }

        map[idx] = digit;
        used[digit] = true;

        if (dfs(col + 1, 0, carry)) {
            return true;
        }

        used[digit] = false;
        map[idx] = -1;

        return false;
    }
}

class Solution {
    private String[] words;
    private String result;
    private int[] mapping;
    private boolean[] used;
    private boolean[] leading;

    public boolean isSolvable(String[] words, String result) {
        this.words = words;
        this.result = result;
        this.mapping = new int[26];
        this.used = new boolean[10];
        this.leading = new boolean[26];

        java.util.Arrays.fill(mapping, -1);

        boolean[] present = new boolean[26];
        int unique = 0;
        int maxWordLength = 0;

        for (String word : words) {
            maxWordLength = Math.max(maxWordLength, word.length());
            if (word.length() > 1) {
                leading[word.charAt(0) - 'A'] = true;
            }
            for (int i = 0; i < word.length(); i++) {
                int letter = word.charAt(i) - 'A';
                if (!present[letter]) {
                    present[letter] = true;
                    unique++;
                }
            }
        }

        if (result.length() > 1) {
            leading[result.charAt(0) - 'A'] = true;
        }
        for (int i = 0; i < result.length(); i++) {
            int letter = result.charAt(i) - 'A';
            if (!present[letter]) {
                present[letter] = true;
                unique++;
            }
        }

        if (unique > 10
                || result.length() < maxWordLength
                || result.length() > maxWordLength + 1) {
            return false;
        }

        return solveColumn(0, 0, 0);
    }

    private boolean solveColumn(int column, int wordIndex, int sum) {
        if (column == result.length()) {
            return sum == 0;
        }

        if (wordIndex < words.length) {
            String word = words[wordIndex];
            int position = word.length() - 1 - column;

            if (position < 0) {
                return solveColumn(column, wordIndex + 1, sum);
            }

            int letter = word.charAt(position) - 'A';

            if (mapping[letter] != -1) {
                return solveColumn(column, wordIndex + 1,
                        sum + mapping[letter]);
            }

            for (int digit = 0; digit <= 9; digit++) {
                if (used[digit] || (digit == 0 && leading[letter])) {
                    continue;
                }

                mapping[letter] = digit;
                used[digit] = true;

                if (solveColumn(column, wordIndex + 1, sum + digit)) {
                    return true;
                }

                mapping[letter] = -1;
                used[digit] = false;
            }

            return false;
        }

        int resultPosition = result.length() - 1 - column;
        int resultLetter = result.charAt(resultPosition) - 'A';
        int requiredDigit = sum % 10;
        int carry = sum / 10;

        if (mapping[resultLetter] != -1) {
            if (mapping[resultLetter] != requiredDigit) {
                return false;
            }
            return solveColumn(column + 1, 0, carry);
        }

        if (used[requiredDigit]
                || (requiredDigit == 0 && leading[resultLetter])) {
            return false;
        }

        mapping[resultLetter] = requiredDigit;
        used[requiredDigit] = true;

        if (solveColumn(column + 1, 0, carry)) {
            return true;
        }

        mapping[resultLetter] = -1;
        used[requiredDigit] = false;
        return false;
    }
}

class Solution {
    private String[] ws;
    private String res;
    private int[] map = new int[26];
    private boolean[] used = new boolean[10];
    private int n;

    public boolean isSolvable(String[] words, String result) {
        n = words.length;
        ws = new String[n];
        res = result.trim();
        for (int i = 0; i < n; i++) {
            ws[i] = words[i].trim();
            if (ws[i].length() > res.length()) return false;
        }
        java.util.Arrays.fill(map, -1);
        return dfs(0, 0, 0);
    }

    private boolean dfs(int col, int row, int sum) {
        if (col == res.length()) return sum == 0;
        if (row < n) {
            String w = ws[row];
            int len = w.length();
            if (col >= len) return dfs(col, row + 1, sum);
            int c = w.charAt(len - 1 - col) - 'A';
            if (map[c] >= 0) {
                if (len > 1 && col == len - 1 && map[c] == 0) return false;
                return dfs(col, row + 1, sum + map[c]);
            }
            int start = (len > 1 && col == len - 1) ? 1 : 0;
            for (int d = start; d < 10; d++) {
                if (used[d]) continue;
                used[d] = true;
                map[c] = d;
                if (dfs(col, row + 1, sum + d)) return true;
                map[c] = -1;
                used[d] = false;
            }
            return false;
        } else {
            int len = res.length();
            int digit = sum % 10;
            int c = res.charAt(len - 1 - col) - 'A';
            boolean lead = len > 1 && col == len - 1;
            if (map[c] >= 0) {
                if (map[c] != digit) return false;
                if (lead && digit == 0) return false;
                return dfs(col + 1, 0, sum / 10);
            }
            if (used[digit]) return false;
            if (lead && digit == 0) return false;
            used[digit] = true;
            map[c] = digit;
            if (dfs(col + 1, 0, sum / 10)) return true;
            map[c] = -1;
            used[digit] = false;
            return false;
        }
    }
}

class Solution {
    public boolean isSolvable(String[] words, String result) {
        long[] coeff = new long[26];
        boolean[] present = new boolean[26];
        boolean[] noZero = new boolean[26];

        for (String w : words) {
            long pow = 1;
            for (int i = w.length() - 1; i >= 0; i--) {
                int c = w.charAt(i) - 'A';
                coeff[c] += pow;
                present[c] = true;
                pow *= 10;
            }
            if (w.length() > 1) noZero[w.charAt(0) - 'A'] = true;
        }

        long pow = 1;
        for (int i = result.length() - 1; i >= 0; i--) {
            int c = result.charAt(i) - 'A';
            coeff[c] -= pow;
            present[c] = true;
            pow *= 10;
        }
        if (result.length() > 1) noZero[result.charAt(0) - 'A'] = true;

        int n = 0;
        for (int c = 0; c < 26; c++) if (present[c]) n++;
        if (n > 10) return false;

        int[] ch = new int[n];
        long[] cf = new long[n];
        boolean[] lead = new boolean[n];
        int idx = 0;
        for (int c = 0; c < 26; c++) {
            if (present[c]) {
                ch[idx] = c;
                cf[idx] = coeff[c];
                lead[idx] = noZero[c];
                idx++;
            }
        }

        for (int i = 1; i < n; i++) {
            int ci = ch[i];
            long fi = cf[i];
            boolean li = lead[i];
            int j = i - 1;
            while (j >= 0 && Math.abs(cf[j]) < Math.abs(fi)) {
                ch[j + 1] = ch[j];
                cf[j + 1] = cf[j];
                lead[j + 1] = lead[j];
                j--;
            }
            ch[j + 1] = ci;
            cf[j + 1] = fi;
            lead[j + 1] = li;
        }

        long[] sufMax = new long[n + 1];
        long[] sufMin = new long[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            long v = cf[i];
            sufMax[i] = sufMax[i + 1] + (v > 0 ? v * 9 : 0);
            sufMin[i] = sufMin[i + 1] + (v < 0 ? v * 9 : 0);
        }

        return dfs(ch, cf, lead, sufMax, sufMin, new boolean[10], 0, 0L);
    }

    private boolean dfs(int[] ch, long[] cf, boolean[] lead, long[] sufMax, long[] sufMin,
                        boolean[] used, int i, long sum) {
        if (i == ch.length) {
            return sum == 0;
        }
        long c = cf[i];
        for (int d = 0; d <= 9; d++) {
            if (used[d]) continue;
            if (d == 0 && lead[i]) continue;
            long s = sum + c * d;
            if (s + sufMax[i + 1] < 0 || s + sufMin[i + 1] > 0) continue;
            used[d] = true;
            if (dfs(ch, cf, lead, sufMax, sufMin, used, i + 1, s)) return true;
            used[d] = false;
        }
        return false;
    }
}

class Solution {
    private int[] charToDigit;
    private boolean[] digitUsed;
    private boolean[] cannotBeZero;
    private String[] words;
    private String result;

    public boolean isSolvable(String[] words, String result) {
        this.words = words;
        this.result = result;
        this.charToDigit = new int[26];
        this.digitUsed = new boolean[10];
        this.cannotBeZero = new boolean[26];

        for (int i = 0; i < 26; i++) {
            charToDigit[i] = -1;
        }

        int maxWordLen = 0;
        for (String w : words) {
            maxWordLen = Math.max(maxWordLen, w.length());
            if (w.length() > 1) {
                cannotBeZero[w.charAt(0) - 'A'] = true;
            }
        }

        if (result.length() > 1) {
            cannotBeZero[result.charAt(0) - 'A'] = true;
        }

        // Result cannot be shorter than any word, nor longer than maxWordLen + 1
        if (result.length() < maxWordLen || result.length() > maxWordLen + 1) {
            return false;
        }

        return backtrack(0, 0, 0, 0);
    }

    private boolean backtrack(int col, int wordIdx, int sum, int carry) {
        if (col == result.length()) {
            return carry == 0;
        }

        if (wordIdx < words.length) {
            String word = words[wordIdx];
            if (col >= word.length()) {
                return backtrack(col, wordIdx + 1, sum, carry);
            }

            char c = word.charAt(word.length() - 1 - col);
            int cIdx = c - 'A';

            if (charToDigit[cIdx] != -1) {
                return backtrack(col, wordIdx + 1, sum + charToDigit[cIdx], carry);
            } else {
                int startDigit = cannotBeZero[cIdx] ? 1 : 0;
                for (int d = startDigit; d <= 9; d++) {
                    if (!digitUsed[d]) {
                        charToDigit[cIdx] = d;
                        digitUsed[d] = true;

                        if (backtrack(col, wordIdx + 1, sum + d, carry)) {
                            return true;
                        }

                        charToDigit[cIdx] = -1;
                        digitUsed[d] = false;
                    }
                }
                return false;
            }
        }

        // Now process the result character for column `col`
        int total = sum + carry;
        int expectedDigit = total % 10;
        int nextCarry = total / 10;

        char resChar = result.charAt(result.length() - 1 - col);
        int resCharIdx = resChar - 'A';

        if (charToDigit[resCharIdx] != -1) {
            if (charToDigit[resCharIdx] == expectedDigit) {
                return backtrack(col + 1, 0, 0, nextCarry);
            }
            return false;
        } else {
            if (!digitUsed[expectedDigit]) {
                if (expectedDigit == 0 && cannotBeZero[resCharIdx]) {
                    return false;
                }
                charToDigit[resCharIdx] = expectedDigit;
                digitUsed[expectedDigit] = true;

                if (backtrack(col + 1, 0, 0, nextCarry)) {
                    return true;
                }

                charToDigit[resCharIdx] = -1;
                digitUsed[expectedDigit] = false;
            }
            return false;
        }
    }
}

class Solution {
    public boolean isSolvable(String[] words, String result) {
        int maxLen = 0;
        for (String w : words) {
            maxLen = Math.max(maxLen, w.length());
        }
        if (maxLen > result.length() || result.length() > maxLen + 1) {
            return false;
        }
        boolean[] lead = new boolean[26];
        for (String w : words) {
            if (w.length() > 1) {
                lead[w.charAt(0) - 'A'] = true;
            }
        }
        if (result.length() > 1) {
            lead[result.charAt(0) - 'A'] = true;
        }
        int[] mp = new int[26];
        for (int i = 0; i < 26; i++) {
            mp[i] = -1;
        }
        boolean[] used = new boolean[10];
        return dfs(words, result, lead, mp, used, 0, 0, 0);
    }

    private boolean dfs(String[] words, String result, boolean[] lead, int[] mp, boolean[] used, int pos, int idx, int curSum) {
        if (pos == result.length()) {
            return curSum == 0;
        }
        if (idx == words.length) {
            char c = result.charAt(result.length() - 1 - pos);
            int need = curSum % 10;
            int ncarry = curSum / 10;
            if (mp[c - 'A'] != -1) {
                if (mp[c - 'A'] != need) {
                    return false;
                }
                return dfs(words, result, lead, mp, used, pos + 1, 0, ncarry);
            } else {
                if (used[need] || (need == 0 && lead[c - 'A'])) {
                    return false;
                }
                mp[c - 'A'] = need;
                used[need] = true;
                boolean res = dfs(words, result, lead, mp, used, pos + 1, 0, ncarry);
                mp[c - 'A'] = -1;
                used[need] = false;
                return res;
            }
        }
        String word = words[idx];
        if (word.length() <= pos) {
            return dfs(words, result, lead, mp, used, pos, idx + 1, curSum);
        }
        char c = word.charAt(word.length() - 1 - pos);
        if (mp[c - 'A'] != -1) {
            return dfs(words, result, lead, mp, used, pos, idx + 1, curSum + mp[c - 'A']);
        } else {
            for (int d = 0; d <= 9; d++) {
                if (used[d] || (d == 0 && lead[c - 'A'])) {
                    continue;
                }
                mp[c - 'A'] = d;
                used[d] = true;
                if (dfs(words, result, lead, mp, used, pos, idx + 1, curSum + d)) {
                    return true;
                }
                mp[c - 'A'] = -1;
                used[d] = false;
            }
            return false;
        }
    }
}

class Solution {
    private String[] words;
    private String result;
    private int[] digit;
    private boolean[] used;
    private boolean[] nonZero;

    public boolean isSolvable(String[] words, String result) {
        this.words = words;
        this.result = result;
        digit = new int[26];
        java.util.Arrays.fill(digit, -1);
        used = new boolean[10];
        nonZero = new boolean[26];

        int maxLength = 0;
        for (String word : words) {
            maxLength = Math.max(maxLength, word.length());
            if (word.length() > 1) {
                nonZero[word.charAt(0) - 'A'] = true;
            }
        }

        if (result.length() < maxLength || result.length() > maxLength + 1) {
            return false;
        }
        if (result.length() > 1) {
            nonZero[result.charAt(0) - 'A'] = true;
        }

        return search(0, 0, 0);
    }

    // Process each column from right to left, carrying its sum forward.
    private boolean search(int column, int row, int sum) {
        if (column == result.length()) {
            return sum == 0;
        }

        if (row < words.length) {
            String word = words[row];
            if (column >= word.length()) {
                return search(column, row + 1, sum);
            }

            int letter = word.charAt(word.length() - 1 - column) - 'A';
            if (digit[letter] != -1) {
                return search(column, row + 1, sum + digit[letter]);
            }

            for (int d = 0; d <= 9; d++) {
                if (used[d] || (d == 0 && nonZero[letter])) {
                    continue;
                }

                digit[letter] = d;
                used[d] = true;

                if (search(column, row + 1, sum + d)) {
                    return true;
                }

                used[d] = false;
                digit[letter] = -1;
            }
            return false;
        }

        int letter = result.charAt(result.length() - 1 - column) - 'A';
        int required = sum % 10;
        int carry = sum / 10;

        if (digit[letter] != -1) {
            return digit[letter] == required && search(column + 1, 0, carry);
        }

        if (used[required] || (required == 0 && nonZero[letter])) {
            return false;
        }

        digit[letter] = required;
        used[required] = true;

        if (search(column + 1, 0, carry)) {
            return true;
        }

        used[required] = false;
        digit[letter] = -1;
        return false;
    }
}

class Solution {
    private String[] words;
    private String result;
    private int maxLen;
    private int[] digit;
    private boolean[] used;
    private boolean[] leading;

    public boolean isSolvable(String[] words, String result) {
        this.words = words;
        this.result = result;
        this.maxLen = result.length();
        this.digit = new int[26];
        this.used = new boolean[10];
        this.leading = new boolean[26];

        java.util.Arrays.fill(digit, -1);

        for (String word : words) {
            maxLen = Math.max(maxLen, word.length());
            if (word.length() > 1) {
                leading[word.charAt(0) - 'A'] = true;
            }
        }

        if (result.length() > 1) {
            leading[result.charAt(0) - 'A'] = true;
        }

        return dfs(0, 0, 0);
    }

    private boolean dfs(int column, int index, int sum) {
        if (column == maxLen) {
            return sum == 0;
        }

        if (index < words.length) {
            String word = words[index];

            if (column >= word.length()) {
                return dfs(column, index + 1, sum);
            }

            int c = word.charAt(word.length() - 1 - column) - 'A';

            if (digit[c] != -1) {
                return dfs(column, index + 1, sum + digit[c]);
            }

            for (int d = 0; d <= 9; d++) {
                if (used[d] || (d == 0 && leading[c])) {
                    continue;
                }

                digit[c] = d;
                used[d] = true;

                if (dfs(column, index + 1, sum + d)) {
                    return true;
                }

                digit[c] = -1;
                used[d] = false;
            }

            return false;
        }

        int required = sum % 10;
        int nextCarry = sum / 10;

        if (column >= result.length()) {
            return required == 0 && dfs(column + 1, 0, nextCarry);
        }

        int c = result.charAt(result.length() - 1 - column) - 'A';

        if (digit[c] != -1) {
            return digit[c] == required
                    && dfs(column + 1, 0, nextCarry);
        }

        if (used[required] || (required == 0 && leading[c])) {
            return false;
        }

        digit[c] = required;
        used[required] = true;

        if (dfs(column + 1, 0, nextCarry)) {
            return true;
        }

        digit[c] = -1;
        used[required] = false;
        return false;
    }
}

class Solution {
    long[] w = new long[26];
    int[] letters;
    boolean[] lead = new boolean[26];
    int n;

    public boolean isSolvable(String[] words, String result) {
        boolean[] present = new boolean[26];
        for (String s : words) {
            s = s.trim();
            long p = 1;
            for (int i = s.length() - 1; i >= 0; i--) {
                int c = s.charAt(i) - 'A';
                w[c] += p;
                p *= 10;
                present[c] = true;
            }
            if (s.length() > 1) lead[s.charAt(0) - 'A'] = true;
        }
        String s = result.trim();
        long p = 1;
        for (int i = s.length() - 1; i >= 0; i--) {
            int c = s.charAt(i) - 'A';
            w[c] -= p;
            p *= 10;
            present[c] = true;
        }
        if (s.length() > 1) lead[s.charAt(0) - 'A'] = true;
        int cnt = 0;
        for (int i = 0; i < 26; i++) if (present[i]) cnt++;
        letters = new int[cnt];
        int k = 0;
        for (int i = 0; i < 26; i++) if (present[i]) letters[k++] = i;
        n = cnt;
        return dfs(0, 0, 0);
    }

    boolean dfs(int idx, long sum, int mask) {
        if (idx == n) return sum == 0;
        int c = letters[idx];
        for (int d = 0; d < 10; d++) {
            if ((mask & (1 << d)) != 0) continue;
            if (d == 0 && lead[c]) continue;
            if (dfs(idx + 1, sum + w[c] * d, mask | (1 << d))) return true;
        }
        return false;
    }
}

