                Set<String> temp = beginFrontier;
                beginFrontier = endFrontier;
                endFrontier = temp;
            }

            Set<String> nextFrontier = new HashSet<>();

            for (String word : beginFrontier) {
                char[] letters = word.toCharArray();

                for (int i = 0; i < letters.length; i++) {
                    char original = letters[i];

                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == original) {
                            continue;
                        }

                        letters[i] = c;
                        String nextWord = new String(letters);

                        if (endFrontier.contains(nextWord)) {
                            return length + 1;
                        }

                        if (dictionary.remove(nextWord)) {
                            nextFrontier.add(nextWord);
                        }
                    }

                    letters[i] = original;
                }
            }

            beginFrontier = nextFrontier;
            length++;
        }

        return 0;
    }
}

class Solution {
    public int ladderLength(String beginWord, String endWord, List<String> wordList) {
        Set<String> wordSet = new HashSet<>(wordList);
        if (!wordSet.contains(endWord)) {
            return 0;
        }
        Queue<String> queue = new LinkedList<>();
        queue.offer(beginWord);
        wordSet.remove(beginWord);
        int length = 1;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                String word = queue.poll();
                if (word.equals(endWord)) {
                    return length;
                }
                char[] chars = word.toCharArray();
                for (int j = 0; j < chars.length; j++) {
                    char original = chars[j];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == original) {
                            continue;
                        }
                        chars[j] = c;
                        String newWord = new String(chars);
                        if (wordSet.contains(newWord)) {
                            queue.offer(newWord);
                            wordSet.remove(newWord);
                        }
                    }
                    chars[j] = original;
                }
            }
            length++;
        }
        return 0;
    }
}

